const sidebarSectionByView = Object.freeze({
  campaigns: "gos",
  "strategic-qr": "offer",
  communications: "offer",
  "smart-catalogs": "offer",
  inventory: "offer",
  "reward-passes": "offer",
  leads: "operate",
  sales: "operate",
  validator: "operate",
  redemptions: "optimize",
  affiliates: "optimize",
  dashboard: "gos",
  channels: "gos",
  competition: "gos",
  branches: "operate",
  missions: "optimize",
  recycling: "optimize",
  account: "admin",
  admin: "admin",
});
navButtons.forEach((button) => {
  const copy = button.querySelector(":scope > span:not(.material-symbols-outlined):not(.feature-tier-badge)");
  const label = String(copy?.querySelector("strong")?.textContent || copy?.textContent || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!label) return;
  if (!button.getAttribute("aria-label")) button.setAttribute("aria-label", label);
  if (!button.getAttribute("title")) button.setAttribute("title", label);
});

function setSidebarAccordionSection(sectionKey, options = {}) {
  const allowCollapse = Boolean(options.allowCollapse);
  const target = sidebarNavSections.find((section) => section.dataset.sidebarSection === sectionKey);
  if (!target) return;
  const shouldCloseTarget = allowCollapse && target.classList.contains("is-open");
  sidebarNavSections.forEach((section) => {
    const isTarget = section === target;
    const isOpen = isTarget && !shouldCloseTarget;
    section.classList.toggle("is-open", isOpen);
    section.classList.toggle("is-current", isTarget);
    const toggle = section.querySelector("[data-sidebar-group-toggle]");
    if (toggle) {
      toggle.setAttribute("aria-expanded", String(isOpen));
      if (isTarget) toggle.setAttribute("aria-current", "page");
      else toggle.removeAttribute("aria-current");
    }
  });
}

function syncSidebarAccordionWithActiveNav(view = state.currentView) {
  const currentSectionKey = sidebarSectionByView[view] || "";
  sidebarNavSections.forEach((section) => {
    const isCurrent = section.dataset.sidebarSection === currentSectionKey;
    section.classList.toggle("is-current", isCurrent);
    const toggle = section.querySelector("[data-sidebar-group-toggle]");
    if (toggle) {
      if (isCurrent) toggle.setAttribute("aria-current", "page");
      else toggle.removeAttribute("aria-current");
    }
  });
  if (currentSectionKey) {
    setSidebarAccordionSection(currentSectionKey);
    return;
  }
  if (view === "rms-machine") {
    // The icon-only machine view still needs a usable first menu group.
    setSidebarAccordionSection("offer");
    return;
  }
  if (!sidebarNavSections.some((section) => section.classList.contains("is-open"))) {
    setSidebarAccordionSection("operate");
  }
}

const ACCOUNT_SCREEN_COPY = Object.freeze({
  profile: {
    title: "Tu empresa",
    subtitle: "Mantén clara la identidad con la que Qori opera y representa tu negocio.",
  },
  channels: {
    title: "Canales oficiales",
    subtitle: "Conecta correo y WhatsApp, valida cada envío y protege la confianza de tu audiencia.",
  },
  billing: {
    title: "Recargas",
    subtitle: "Compra tickets, revisa tu saldo y administra el plan del portal.",
  },
  assets: {
    title: "Activos digitales",
    subtitle: "Administra logo, marco QR y archivos para entregar a tus clientes.",
  },
  security: {
    title: "Seguridad",
    subtitle: "Actualiza la contraseña de acceso a tu cuenta.",
  },
  admin: {
    title: "Administración",
    subtitle: "Gestiona usuarios y permisos del equipo con acceso al portal.",
  },
});

const ACCOUNT_SECTION_SCREEN = Object.freeze({
  accountSectionCompany: "profile",
  accountSectionChannels: "channels",
  accountSectionSecurity: "security",
  accountSectionData: "billing",
  accountSectionBilling: "billing",
  accountSectionAssets: "assets",
  accountSectionUsers: "admin",
});

const ACCOUNT_SCREEN_SECTION = Object.freeze({
  profile: "accountSectionCompany",
  channels: "accountSectionChannels",
  assets: "accountSectionAssets",
  admin: "accountSectionUsers",
  billing: "accountSectionData",
  security: "accountSectionSecurity",
});

function normalizeAccountScreen(screen = "") {
  return ACCOUNT_SCREEN_COPY[screen] ? screen : "profile";
}

function accountScreenFromHash() {
  const sectionId = String(window.location.hash || "").replace(/^#/, "");
  return ACCOUNT_SECTION_SCREEN[sectionId] || "";
}

function accountSidebarScreen(screen = "") {
  const normalized = normalizeAccountScreen(screen);
  return ["admin", "channels", "security"].includes(normalized) ? "profile" : normalized;
}

function syncAccountNavigationState(screen = "") {
  const normalized = normalizeAccountScreen(screen);
  const currentSectionId = ACCOUNT_SCREEN_SECTION[normalized] || ACCOUNT_SCREEN_SECTION.profile;
  document.querySelectorAll(".account-admin-nav a[href^='#accountSection']").forEach((link) => {
    const sectionId = String(link.getAttribute("href") || "").replace(/^#/, "");
    const isCurrent = sectionId === currentSectionId;
    link.classList.toggle("is-active", isCurrent);
    if (isCurrent) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
  const sidebarScreen = accountSidebarScreen(normalized);
  navButtons
    .filter((button) => button.dataset.view === "account")
    .forEach((button) => {
      const isCurrent = button.dataset.accountScreen === sidebarScreen;
      button.classList.toggle("active", isCurrent);
      button.dataset.sidebarCurrentMatch = isCurrent ? "true" : "false";
      if (isCurrent) button.setAttribute("aria-current", "page");
      else button.removeAttribute("aria-current");
    });
}

function applyAccountScreen() {
  if (!state.accountHashApplied) {
    const screenFromHash = accountScreenFromHash();
    if (screenFromHash) state.accountScreen = screenFromHash;
    state.accountHashApplied = true;
  }
  const screen = normalizeAccountScreen(state.accountScreen);
  state.accountScreen = screen;
  const copy = ACCOUNT_SCREEN_COPY[screen];
  document.querySelectorAll('[data-view="account"] [data-account-screen]').forEach((node) => {
    const supportedScreens = String(node.dataset.accountScreen || "").split(/\s+/).filter(Boolean);
    node.classList.toggle("account-screen-hidden", !supportedScreens.includes(screen));
  });
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-profile", screen === "profile");
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-channels", screen === "channels");
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-billing", screen === "billing");
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-assets", screen === "assets");
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-security", screen === "security");
  document.querySelector('[data-view="account"]')?.classList.toggle("account-screen-admin", screen === "admin");
  const title = document.getElementById("accountViewTitle");
  const subtitle = document.getElementById("accountViewSubtitle");
  if (title) title.textContent = copy.title;
  if (subtitle) subtitle.textContent = copy.subtitle;
  syncAccountNavigationState(screen);
}

function openAccountSection(screen = "") {
  const normalized = normalizeAccountScreen(screen);
  state.accountScreen = normalized;
  state.accountHashApplied = true;
  const sectionId = ACCOUNT_SCREEN_SECTION[normalized];
  if (sectionId && window.location.hash !== `#${sectionId}`) {
    window.history.replaceState(window.history.state, "", `#${sectionId}`);
  }
  setView("account");
  applyAccountScreen();
}

