function renderAccountView() {
  ensureAccountAdminUxStyles();
  const business = state.businessProfile || {};
  const user = business.current_user || session?.user || {};
  const subscription = state.subscription || {};
  const plan = subscription.plan || {};
  const credit = state.qrCreditAccount || {};
  const qrBalance = Number(credit.qr_balance || 0);
  const availableQr = qrBalance.toLocaleString("es-CO");

  setAccountText(accountBusinessName, business.name);
  setAccountText(accountBusinessNit, business.nit);
  setAccountText(accountBusinessSlug, business.slug);
  setAccountText(accountBusinessContact, business.contact_name || business.contact_email);
  setAccountText(accountBusinessPhone, business.phone);
  setAccountText(accountUserName, user.full_name);
  setAccountText(accountUserEmail, user.email);
  setAccountText(accountUserRole, accountRoleLabel(user.role));
  setAccountText(accountUserBusiness, business.name || user.business_id);
  setAccountText(accountUserId, user.id);
  setAccountText(accountPlanName, plan.name || plan.code);
  setAccountText(accountType, plan.category === "ticket_base" ? "Portal Base" : plan.category === "growth_temporal" ? "Growth temporal" : (plan.billing_period === "monthly" ? "Suscripcion mensual" : plan.category));
  setAccountText(accountPlanStatus, subscriptionAccessLabel(plan));
  setAccountText(accountQrAvailable, availableQr, "0");
  setAccountText(accountQrUsed, Number(credit.qr_used_total || subscription.usage?.monthly_qr?.used || 0).toLocaleString("es-CO"), "0");
  setAccountText(accountQrCourtesy, Number(credit.qr_courtesy_total || 0).toLocaleString("es-CO"), "0");
  renderCommercialDeal();
  renderBusinessUsers();
  renderSubscriptionRenewal();
  renderQrCreditShop();
  renderSubscriptionPricing();
  renderDigitalAssets();

  if (accountNameInput) accountNameInput.value = business.name || "";
  if (accountSloganInput) accountSloganInput.value = business.slogan || business.settings?.slogan || business.settings?.tagline || "";
  if (accountNitInput) accountNitInput.value = business.nit || "";
  if (accountContactInput) accountContactInput.value = business.contact_name || "";
  if (accountEmailInput) accountEmailInput.value = business.contact_email || "";
  if (accountCommunicationSenderNameInput) accountCommunicationSenderNameInput.value = business.communication_sender_name || business.name || "";
  if (accountCommunicationSenderEmailInput) accountCommunicationSenderEmailInput.value = business.communication_sender_email || "";
  if (accountCommunicationTestEmailInput && !accountCommunicationTestEmailInput.value) accountCommunicationTestEmailInput.value = business.contact_email || user.email || "";
  renderCommunicationEmailConnection();
  renderCommunicationWhatsAppConnection();
  if (accountPhoneInput) accountPhoneInput.value = business.phone || "";
  if (accountWebsiteInput) accountWebsiteInput.value = business.website || "";
  if (accountCityInput) accountCityInput.value = business.city || "";
  if (accountAddressInput) accountAddressInput.value = business.address || "";
  const affiliatePoints = business.affiliate_points || state.affiliatePointRules || {};
  if (accountAffiliatePointAmountInput) accountAffiliatePointAmountInput.value = String(affiliatePoints.point_amount_cop || 1000);
  if (accountAffiliatePointRateInput) accountAffiliatePointRateInput.value = String(affiliatePoints.referral_rate || 1);
  if (accountAffiliatePointRoundingInput) accountAffiliatePointRoundingInput.value = affiliatePoints.referral_rounding || "floor";
  if (accountAffiliateReferralRegistrationPointsInput) accountAffiliateReferralRegistrationPointsInput.value = String(affiliatePoints.referral_registration_points || 0);
  if (accountAffiliateReferralPurchasePointsInput) accountAffiliateReferralPurchasePointsInput.value = String(affiliatePoints.referral_purchase_points || 0);
  const riskRecovery = rmsRiskRecoveryAuthorizations(business.rms_risk_recovery_authorizations);
  if (accountRiskDiscountEnabledInput) accountRiskDiscountEnabledInput.checked = riskRecovery.discount.enabled;
  if (accountRiskDiscountMaxInput) accountRiskDiscountMaxInput.value = riskRecovery.discount.max_percent ? String(riskRecovery.discount.max_percent) : "";
  if (accountRiskTwoForOneEnabledInput) accountRiskTwoForOneEnabledInput.checked = riskRecovery.two_for_one.enabled;
  if (accountRiskTwoForOneLabelInput) accountRiskTwoForOneLabelInput.value = riskRecovery.two_for_one.label || "";
  if (accountRiskGiftEnabledInput) accountRiskGiftEnabledInput.checked = riskRecovery.gift.enabled;
  if (accountRiskGiftLabelInput) accountRiskGiftLabelInput.value = riskRecovery.gift.label || "";
  renderAccountRiskCustomBenefits(riskRecovery.benefits);

  const logo = business.logo_data_url || "";
  if (accountLogoPreview) {
    accountLogoPreview.innerHTML = logo
      ? `<img src="${escapeHtml(logo)}" alt="Logo del negocio">`
      : '<span class="material-symbols-outlined">storefront</span>';
  }
  if (accountLogoTitle) {
    accountLogoTitle.textContent = logo ? "Logo cargado" : "Sin logo cargado";
  }
  if (accountLogoRemoveButton) {
    accountLogoRemoveButton.disabled = !logo;
  }

  const ticketFrame = business.ticket_frame_data_url || business.settings?.ticket_frame_data_url || "";
  if (accountTicketFramePreview) {
    accountTicketFramePreview.innerHTML = ticketFrame
      ? `<img src="${escapeHtml(ticketFrame)}" alt="Marco de tickets QR">`
      : '<span class="material-symbols-outlined">crop_free</span>';
  }
  if (accountTicketFrameTitle) {
    accountTicketFrameTitle.textContent = ticketFrame ? "Marco cargado" : "Sin marco cargado";
  }
  if (accountTicketFrameRemoveButton) {
    accountTicketFrameRemoveButton.disabled = !ticketFrame;
  }
  applyAccountScreen();
  syncAccountPermissionControls();
}

function renderCommunicationEmailConnection() {
  const connection = state.communicationEmailConnection || {};
  const ready = Boolean(connection.ready);
  const hasKey = Boolean(connection.api_key_configured);
  const usingPlatformSender = Boolean(connection.using_platform_sender);
  if (usingPlatformSender) {
    if (accountCommunicationSenderEmailInput) accountCommunicationSenderEmailInput.value = connection.sender_email || "contacto@marketgamesqr.com";
    if (accountCommunicationSenderNameInput && !accountCommunicationSenderNameInput.value.trim()) accountCommunicationSenderNameInput.value = connection.sender_name || "MarketGames QR";
  }
  if (accountCommunicationConnectionStatus) {
    accountCommunicationConnectionStatus.textContent = ready ? (usingPlatformSender ? "Lista · MarketGames" : "Lista para prueba") : (hasKey ? "Falta remitente" : "Sin conectar");
    accountCommunicationConnectionStatus.className = `status-chip ${ready ? "ok" : "pending"}`;
  }
  if (accountCommunicationConnectionHelp) {
    accountCommunicationConnectionHelp.textContent = usingPlatformSender
      ? "Esta cuenta interna usa el remitente verificado contacto@marketgamesqr.com y la conexión central de MarketGames. Las demás cuentas deben conectar su propio dominio y clave de Resend."
      : "Déjala vacía para conservar la clave ya conectada. Para reemplazarla, pega una nueva y guarda.";
  }
  if (accountCommunicationDisconnectButton) accountCommunicationDisconnectButton.disabled = !hasKey || usingPlatformSender;
  if (accountCommunicationTestButton) accountCommunicationTestButton.disabled = !ready;
}

async function loadCommunicationEmailConnection(options = {}) {
  if (!session?.user?.business_id || (state.communicationEmailConnectionLoaded && !options.force)) return state.communicationEmailConnection;
  const data = await api("/api/business/communications/email-connection", { headers: authHeaders() });
  state.communicationEmailConnection = data || null;
  state.communicationEmailConnectionLoaded = true;
  return state.communicationEmailConnection;
}

let portalEmailRouteResolver = null;

function closePortalEmailRouteModal(choice = "cancel") {
  const modal = document.getElementById("portalEmailRouteModal");
  modal?.classList.add("hidden");
  modal?.setAttribute("aria-hidden", "true");
  const resolve = portalEmailRouteResolver;
  portalEmailRouteResolver = null;
  resolve?.(choice);
}

function askPortalEmailRoute() {
  const modal = document.getElementById("portalEmailRouteModal");
  if (!modal) return Promise.resolve("external");
  if (portalEmailRouteResolver) closePortalEmailRouteModal("cancel");
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  window.setTimeout(() => modal.querySelector('[data-portal-email-route="external"]')?.focus(), 0);
  return new Promise((resolve) => { portalEmailRouteResolver = resolve; });
}

function openPortalEmailSettings() {
  closePortalEmailRouteModal("configure");
  document.querySelector('.nav-item[data-view="account"][data-account-screen="profile"]')?.click();
  window.setTimeout(() => document.getElementById("accountSectionEmail")?.scrollIntoView({ behavior: "smooth", block: "start" }), 120);
}

async function portalEmailDeliveryRoute(options = {}) {
  let connection = null;
  try {
    connection = await loadCommunicationEmailConnection({ force: options.force !== false });
  } catch (_error) {
    state.communicationEmailConnectionLoaded = false;
  }
  if (connection?.ready) return "qori";
  const choice = await askPortalEmailRoute();
  if (choice === "configure") openPortalEmailSettings();
  return choice;
}

function openExternalEmailDraft({ to = [], bcc = [], subject = "", body = "" } = {}) {
  const direct = (Array.isArray(to) ? to : [to]).map((email) => String(email || "").trim()).filter(Boolean);
  const blind = (Array.isArray(bcc) ? bcc : [bcc]).map((email) => String(email || "").trim()).filter(Boolean);
  const params = new URLSearchParams();
  if (blind.length) params.set("bcc", blind.join(","));
  if (subject) params.set("subject", subject);
  if (body) params.set("body", body);
  const url = `mailto:${direct.map(encodeURIComponent).join(",")}${params.toString() ? `?${params.toString()}` : ""}`;
  window.location.href = url;
  return true;
}

function portalEmailRecipient(item = {}) {
  const email = String(item.email || item.recipient_email || "").trim();
  const sourceId = item.source_id || item.id || crypto.randomUUID();
  const registered = Boolean(item.source_id || item.id);
  return {
    source_id: sourceId,
    source_type: registered ? String(item.source_type || "PLAYER").toUpperCase() : "DIRECT_EMAIL",
    ...(registered ? {} : { recipient_email: email, recipient_name: String(item.name || "Contacto").trim() || "Contacto" }),
  };
}

async function sendPortalEmailFromQori({ recipients = [], subject = "", body = "", actionUrl = null, title = "Correo desde Qori", metadata = {}, activationId = null } = {}) {
  const validRecipients = recipients.filter((item) => String(item?.email || item?.recipient_email || "").trim());
  if (!validRecipients.length) throw new Error("No hay destinatarios con correo válido para este envío.");
  const created = await api("/api/business/communications", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({
      title: String(title || subject || "Correo desde Qori").slice(0, 180),
      communication_type: "EMAIL",
      status: "READY",
      activation_id: activationId || null,
      subject,
      email_body: body,
      action_url: actionUrl || null,
      metadata: { source: "portal_email_router", ...metadata },
    }),
  });
  const communicationId = created.communication?.id;
  if (!communicationId) throw new Error("Qori no pudo preparar el correo.");
  const delivery = await api(`/api/business/communications/${encodeURIComponent(communicationId)}/send`, {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({
      recipients: validRecipients.map(portalEmailRecipient),
      consent_confirmed: true,
      idempotency_key: crypto.randomUUID(),
    }),
  });
  if (!Number(delivery?.results?.sent || 0)) {
    throw new Error(delivery?.results?.failure_reasons?.[0]?.message || "Qori no pudo enviar el correo. Revisa la conexión de Resend.");
  }
  return delivery;
}

document.getElementById("portalEmailRouteModal")?.addEventListener("click", (event) => {
  const control = event.target.closest("[data-portal-email-route]");
  if (!control) return;
  const choice = control.dataset.portalEmailRoute || "cancel";
  closePortalEmailRouteModal(choice);
});

window.portalEmailDeliveryRoute = portalEmailDeliveryRoute;
window.openExternalEmailDraft = openExternalEmailDraft;
window.sendPortalEmailFromQori = sendPortalEmailFromQori;
window.loadCommunicationEmailConnection = loadCommunicationEmailConnection;

function communicationWhatsAppTemplateParameters(value) {
  return String(value || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean);
}

function renderCommunicationWhatsAppTemplateOptions(select = accountWhatsAppTestTemplateInput, selected = "") {
  if (!select) return;
  const templates = Array.isArray(state.communicationWhatsAppTemplates) ? state.communicationWhatsAppTemplates : [];
  select.innerHTML = `<option value="">${templates.length ? "Elige una plantilla aprobada" : "Guarda la conexión y carga tus plantillas"}</option>${templates.map((template) => `<option value="${escapeHtml(template.name)}" data-language="${escapeHtml(template.language || "es_CO")}" data-variables="${Number(template.variable_count || 0)}">${escapeHtml(template.name)} · ${escapeHtml(template.language || "es_CO")}${Number(template.variable_count || 0) ? ` · ${Number(template.variable_count)} variable(s)` : ""}</option>`).join("")}`;
  select.value = selected || "";
  updateCommunicationWhatsAppTestParameters();
}

function updateCommunicationWhatsAppTestParameters() {
  const selected = accountWhatsAppTestTemplateInput?.selectedOptions?.[0];
  const variableCount = Number(selected?.dataset.variables || 0);
  const selectedTemplate = Boolean(accountWhatsAppTestTemplateInput?.value);
  if (!selectedTemplate) {
    accountWhatsAppTestParametersField?.classList.remove("hidden");
    if (accountWhatsAppTestParametersLabel) accountWhatsAppTestParametersLabel.textContent = "Variables de prueba (una por línea)";
    return;
  }
  if (!variableCount) {
    if (accountWhatsAppTestParametersInput) accountWhatsAppTestParametersInput.value = "";
    accountWhatsAppTestParametersField?.classList.add("hidden");
    return;
  }
  accountWhatsAppTestParametersField?.classList.remove("hidden");
  if (accountWhatsAppTestParametersLabel) accountWhatsAppTestParametersLabel.textContent = variableCount === 1 ? "Dato de prueba para {{1}}" : `${variableCount} datos de prueba, una línea por variable`;
}

function renderCommunicationWhatsAppConnection() {
  const connection = state.communicationWhatsAppConnection || {};
  const ready = Boolean(connection.ready);
  const hasToken = Boolean(connection.access_token_configured);
  if (accountWhatsAppBusinessAccountIdInput) accountWhatsAppBusinessAccountIdInput.value = connection.business_account_id || "";
  if (accountWhatsAppPhoneNumberIdInput) accountWhatsAppPhoneNumberIdInput.value = connection.phone_number_id || "";
  if (accountWhatsAppWebhookUrlInput) accountWhatsAppWebhookUrlInput.value = connection.webhook_callback_url || "";
  if (accountWhatsAppWebhookVerifyTokenInput) accountWhatsAppWebhookVerifyTokenInput.value = connection.webhook_verify_token || "";
  if (accountWhatsAppConnectionStatus) {
    accountWhatsAppConnectionStatus.textContent = ready ? "Lista para prueba" : (hasToken ? "Faltan IDs" : "Sin conectar");
    accountWhatsAppConnectionStatus.className = `status-chip ${ready ? "ok" : "pending"}`;
  }
  if (accountWhatsAppDisconnectButton) accountWhatsAppDisconnectButton.disabled = !hasToken;
  if (accountWhatsAppLoadTemplatesButton) accountWhatsAppLoadTemplatesButton.disabled = !ready;
  if (accountWhatsAppTestButton) accountWhatsAppTestButton.disabled = !ready;
  renderCommunicationWhatsAppTemplateOptions();
}

async function loadCommunicationWhatsAppConnection(options = {}) {
  if (!session?.user?.business_id || (state.communicationWhatsAppConnectionLoaded && !options.force)) return state.communicationWhatsAppConnection;
  const data = await api("/api/business/communications/whatsapp-connection", { headers: authHeaders() });
  state.communicationWhatsAppConnection = data || null;
  state.communicationWhatsAppConnectionLoaded = true;
  return state.communicationWhatsAppConnection;
}

async function loadCommunicationWhatsAppTemplates() {
  if (!state.communicationWhatsAppConnection?.ready) throw new Error("Primero guarda el token, el ID de cuenta y el ID de número de WhatsApp Business.");
  setButtonLoading(accountWhatsAppLoadTemplatesButton, true, "Cargando...");
  try {
    const data = await api("/api/business/communications/whatsapp-connection/templates", { headers: authHeaders() });
    state.communicationWhatsAppTemplates = data.templates || [];
    renderCommunicationWhatsAppConnection();
    setInlineMessage(accountWhatsAppConnectionMessage, state.communicationWhatsAppTemplates.length ? `${state.communicationWhatsAppTemplates.length} plantilla(s) aprobada(s) lista(s). Ahora prueba una antes de lanzar.` : "No hay plantillas aprobadas todavía. Créala en WhatsApp Manager y vuelve a cargar.", state.communicationWhatsAppTemplates.length ? "success" : "error");
    return state.communicationWhatsAppTemplates;
  } catch (error) {
    setInlineMessage(accountWhatsAppConnectionMessage, error.message || "No se pudieron cargar las plantillas de Meta.", "error");
    throw error;
  } finally { setButtonLoading(accountWhatsAppLoadTemplatesButton, false); }
}

async function saveCommunicationWhatsAppConnection({ removeAccessToken = false } = {}) {
  const businessAccountId = optionalInputValue(accountWhatsAppBusinessAccountIdInput);
  const phoneNumberId = optionalInputValue(accountWhatsAppPhoneNumberIdInput);
  const accessToken = String(accountWhatsAppAccessTokenInput?.value || "").trim();
  if (!businessAccountId || !phoneNumberId) { setInlineMessage(accountWhatsAppConnectionMessage, "Completa el ID de cuenta de WhatsApp Business y el ID del número. Ambos aparecen en Meta for Developers.", "error"); return null; }
  if (!removeAccessToken && !accessToken && !state.communicationWhatsAppConnection?.access_token_configured) { setInlineMessage(accountWhatsAppConnectionMessage, "Pega el token de usuario del sistema de Meta para completar la conexión.", "error"); return null; }
  setButtonLoading(accountWhatsAppConnectButton, true, "Guardando...");
  try {
    const data = await api("/api/business/communications/whatsapp-connection", { method: "PATCH", headers: authHeaders(), body: JSON.stringify({ business_account_id: businessAccountId, phone_number_id: phoneNumberId, access_token: removeAccessToken ? "" : accessToken, remove_access_token: removeAccessToken }) });
    state.communicationWhatsAppConnection = data;
    state.communicationWhatsAppConnectionLoaded = true;
    if (accountWhatsAppAccessTokenInput) accountWhatsAppAccessTokenInput.value = "";
    renderCommunicationWhatsAppConnection();
    setInlineMessage(accountWhatsAppConnectionMessage, removeAccessToken ? "Conexión eliminada. No se enviarán campañas por WhatsApp hasta conectar un token nuevo." : "Conexión guardada. Carga una plantilla aprobada y envía una prueba antes de lanzar.", "success");
    return data;
  } catch (error) {
    setInlineMessage(accountWhatsAppConnectionMessage, error.message || "No se pudo guardar la conexión de WhatsApp.", "error");
    return null;
  } finally { setButtonLoading(accountWhatsAppConnectButton, false); }
}

async function testCommunicationWhatsAppConnection() {
  const phone = optionalInputValue(accountWhatsAppTestPhoneInput);
  const selected = accountWhatsAppTestTemplateInput?.selectedOptions?.[0];
  const templateName = accountWhatsAppTestTemplateInput?.value || "";
  if (!phone || !templateName) { setInlineMessage(accountWhatsAppConnectionMessage, "Elige una plantilla aprobada y escribe el número que recibirá la prueba.", "error"); return; }
  if (!accountWhatsAppTestConsentInput?.checked) { setInlineMessage(accountWhatsAppConnectionMessage, "Confirma el consentimiento del número de prueba antes de enviar.", "error"); return; }
  setButtonLoading(accountWhatsAppTestButton, true, "Enviando...");
  try {
    const data = await api("/api/business/communications/whatsapp-connection/test", { method: "POST", headers: authHeaders(), body: JSON.stringify({ recipient_phone: phone, template_name: templateName, language_code: selected?.dataset.language || "es_CO", body_parameters: communicationWhatsAppTemplateParameters(accountWhatsAppTestParametersInput?.value), consent_confirmed: true }) });
    setInlineMessage(accountWhatsAppConnectionMessage, `Meta aceptó la prueba para ${data.recipient_phone}. Revisa el WhatsApp de ese número.`, "success");
    showFeedback("La prueba fue aceptada por WhatsApp Business.", "success", { title: "Conexión de WhatsApp" });
  } catch (error) { setInlineMessage(accountWhatsAppConnectionMessage, error.message || "La prueba no pudo enviarse.", "error"); }
  finally { setButtonLoading(accountWhatsAppTestButton, false); }
}

async function copyWhatsAppWebhookValue(input, label) {
  const value = String(input?.value || "").trim();
  if (!value) { setInlineMessage(accountWhatsAppConnectionMessage, "Aún no pudimos cargar este valor. Actualiza Cuenta e inténtalo de nuevo.", "error"); return; }
  try { await navigator.clipboard.writeText(value); }
  catch { window.prompt(`Copia ${label}`, value); }
  setInlineMessage(accountWhatsAppConnectionMessage, `${label} copiado. Pégalo sin espacios adicionales en Meta.`, "success");
}

