    setImportantStyle(entry, "border-radius", "12px");
    setImportantStyle(entry, "box-shadow", "0 14px 30px rgba(1, 34, 104, .42), 0 0 0 3px rgba(105, 221, 255, .18), inset 0 1px 0 rgba(255, 255, 255, .22)");
