function renderRevenuePulseStrip(summary = {}, dashboard = {}, path = []) {
  if (!revenuePulseStrip) return;
  const observedSalesCount = toNumber(summary.observed_sales_count ?? summary.direct_sales_count);
  const observedRevenue = toNumber(summary.observed_revenue ?? summary.attributed_revenue);
  const activeQr = toNumber(dashboard.summary?.active_qr);
  const openAgenda = (state.leadAgenda || []).filter((item) => String(item.agenda_status || "OPEN").toUpperCase() === "OPEN").length;
  const totalLeads = toNumber(summary.total_leads || 0);
  const totalRedeemed = toNumber(summary.total_qr_redeemed || 0);
  const avgTicket = observedSalesCount ? observedRevenue / observedSalesCount : 0;
  const cards = [
    { icon: "paid", label: "Revenue medido", value: money(observedRevenue), meta: `${observedSalesCount.toLocaleString("es-CO")} ventas · ticket ${money(avgTicket)}`, tone: "rgba(7, 89, 214, .14)" },
    { icon: "group_add", label: "Materia prima", value: totalLeads.toLocaleString("es-CO"), meta: "leads y contactos capturados", tone: "rgba(59, 130, 246, .14)" },
    { icon: "confirmation_number", label: "Tickets activos", value: activeQr.toLocaleString("es-CO"), meta: `${totalRedeemed.toLocaleString("es-CO")} redenciones registradas`, tone: "rgba(168, 85, 247, .14)" },
    { icon: "event_available", label: "Trabajo pendiente", value: openAgenda.toLocaleString("es-CO"), meta: `${path.filter((step) => Number(step.count || 0) > 0).length} etapas con actividad`, tone: "rgba(245, 158, 11, .16)" },
  ];
  revenuePulseStrip.innerHTML = cards.map((card) => `
    <article class="revenue-pulse-card" style="--pulse:${escapeHtml(card.tone)}">
      <span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(card.icon)}</span>
      <small>${escapeHtml(card.label)}</small>
      <strong>${escapeHtml(card.value)}</strong>
      <small>${escapeHtml(card.meta)}</small>
    </article>
  `).join("");
}

function renderRevenueDecisionDeck(summary = {}, dashboard = {}) {
  if (!revenueDecisionDeck) return;
  const leads = toNumber(summary.total_leads);
  const activeQr = toNumber(dashboard.summary?.active_qr);
  const redeemed = toNumber(summary.total_qr_redeemed);
  const sales = toNumber(summary.observed_sales_count ?? summary.direct_sales_count);
  const openAgenda = (state.leadAgenda || []).filter((item) => !["DONE", "CLOSED", "COMPLETED", "CANCELLED"].includes(String(item.status || item.agenda_status || "").toUpperCase())).length;
  // La inversión configurada es una base comercial acumulada; se etiqueta
  // explícitamente para no presentarla como si fuera gasto diario del corte.
  const economics = dashboardCommercialEconomics();
  const signals = [];

  if (!leads) {
    signals.push({ tone: "is-priority", icon: "person_add", label: "Entrada comercial", value: "Sin leads", detail: "Aún no hay contactos para convertir. Crea una fuente de entrada antes de medir rendimiento.", route: "campaigns", cta: "Crear entrada" });
  } else if (!openAgenda) {
    signals.push({ tone: "is-priority", icon: "event_available", label: "Seguimiento", value: "Sin tareas", detail: `${leads.toLocaleString("es-CO")} contactos no tienen una próxima acción visible.`, route: "agenda", cta: "Crear seguimiento" });
  } else {
    signals.push({ tone: "is-healthy", icon: "event_note", label: "Seguimiento", value: openAgenda.toLocaleString("es-CO"), detail: `${leads.toLocaleString("es-CO")} leads registrados · tareas abiertas para mover la conversación.`, route: "agenda", cta: "Ver agenda" });
  }

  if (activeQr && !redeemed) {
    signals.push({ tone: "is-priority", icon: "confirmation_number", label: "Activación", value: `${activeQr.toLocaleString("es-CO")} activos`, detail: "Hay beneficios vigentes sin redención registrada. Revisa entrega, vigencia y recordatorio.", route: "strategic-qr", cta: "Revisar tickets" });
  } else {
    signals.push({ tone: "is-neutral", icon: "qr_code_scanner", label: "Activación", value: redeemed.toLocaleString("es-CO"), detail: activeQr ? `${activeQr.toLocaleString("es-CO")} tickets siguen activos para impulsar la siguiente visita.` : "Sin tickets activos pendientes de revisión.", route: "redemptions", cta: "Ver redenciones" });
  }

  if (redeemed > sales) {
    signals.push({ tone: "is-priority", icon: "point_of_sale", label: "Conversión", value: `${redeemed - sales} por revisar`, detail: "La señal de redención supera las ventas registradas. Confirma cuáles visitas terminaron en compra.", route: "sales", cta: "Registrar ventas" });
  } else {
    signals.push({ tone: "is-healthy", icon: "paid", label: "Conversión", value: sales.toLocaleString("es-CO"), detail: sales ? "Ventas reales disponibles para calcular ticket promedio y retorno." : "Aún no hay ventas registradas en este período.", route: "sales", cta: "Ver ventas" });
  }

  const economicsSignal = economics.investment > 0
    ? { tone: "is-neutral", icon: "account_balance_wallet", label: "Base económica", value: money(economics.investment), detail: `${economics.sourceLabel}. ROI y CAC usan inversión registrada, no estimaciones inventadas.`, route: "channels", cta: "Ver inversión" }
    : { tone: "is-priority", icon: "account_balance_wallet", label: "Base económica", value: "Sin inversión", detail: "Registra la inversión de campaña o canal para habilitar un ROI y CAC confiables.", route: "channels", cta: "Registrar inversión" };
  signals.push(economicsSignal);

  revenueDecisionDeck.innerHTML = `
    <header>
      <div><span class="mono-label">Diagnóstico operativo</span><h3>Qué está frenando o moviendo el revenue</h3><p>Son señales de trabajo: abre la acción correspondiente y conserva la trazabilidad en Qori.</p></div>
      <span class="revenue-decision-deck-key"><i></i>Acciones priorizadas</span>
    </header>
    <div class="revenue-decision-grid">
      ${signals.map((signal) => `
        <article class="${escapeHtml(signal.tone)}">
          <span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(signal.icon)}</span>
          <div><small>${escapeHtml(signal.label)}</small><strong>${escapeHtml(signal.value)}</strong><p>${escapeHtml(signal.detail)}</p></div>
          <button class="ghost-button compact" type="button" data-revenue-decision-route="${escapeHtml(signal.route)}">${escapeHtml(signal.cta)}<span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></button>
        </article>
      `).join("")}
    </div>`;
  revenueDecisionDeck.querySelectorAll("[data-revenue-decision-route]").forEach((button) => {
    button.addEventListener("click", () => navigateRevenueRoute(button.dataset.revenueDecisionRoute));
  });
}

function renderRevenueWorkspace() {
  ensureRevenueCenterUxStyles();
  const summary = state.summary || {};
  const dashboard = state.dashboard || {};
  const observedSalesCount = toNumber(summary.observed_sales_count ?? summary.direct_sales_count);
  const observedRevenue = toNumber(summary.observed_revenue ?? summary.attributed_revenue);
  const activeQr = toNumber(dashboard.summary?.active_qr);
  const openAgenda = (state.leadAgenda || []).filter((item) => String(item.agenda_status || "OPEN").toUpperCase() === "OPEN").length;
  const activeMissions = toNumber(state.missions?.metrics?.active_seasons || 0);
  const path = [
    { key: "capture", label: "Capturar", count: summary.total_leads || 0, meta: "leads nuevos", action: "Crear QR", target: "campaigns" },
    { key: "gamify", label: "Gamificar", count: activeMissions || state.leadCaptureActivations?.length || 0, meta: "dinámicas activas", action: "Crear dinámica", target: "missions" },
    { key: "qualify", label: "Calificar", count: state.leadCrmPagination?.total || summary.total_leads || 0, meta: "contactos procesables", action: "Ver contactos", target: "contacts" },
    { key: "agenda", label: "Agendar", count: openAgenda, meta: "tareas abiertas", action: "Ver agenda", target: "agenda" },
    { key: "redeem", label: "Redimir", count: summary.total_qr_redeemed || 0, meta: `${activeQr} tickets activos`, action: "Validar ticket", target: "validator" },
    { key: "sell", label: "Vender", count: observedSalesCount, meta: money(observedRevenue), action: "Registrar venta", target: "sales" },
    { key: "loyalty", label: "Fidelizar", count: summary.referral_sales_count || state.rewardPasses?.length || 0, meta: "recompra / referido", action: "Activar recompra", target: "reward-passes" },
  ];
  renderRevenuePulseStrip(summary, dashboard, path);
  renderRevenueDecisionDeck(summary, dashboard);
  if (revenuePathGuide) {
    revenuePathGuide.innerHTML = path.map((step, index) => `
      <article class="revenue-path-step ${Number(step.count || 0) > 0 ? "is-active" : ""}">
        <span>${index + 1}</span>
        <strong>${escapeHtml(step.label)}</strong>
        <p>${Number(step.count || 0).toLocaleString("es-CO")} ${escapeHtml(step.meta)}</p>
        <button type="button" data-revenue-route="${escapeHtml(step.target)}">${escapeHtml(step.action)}</button>
      </article>
    `).join("");
    revenuePathGuide.querySelectorAll("[data-revenue-route]").forEach((button) => {
      button.addEventListener("click", () => navigateRevenueRoute(button.dataset.revenueRoute));
    });
  }
  renderNextBestAction(path);
  const totalActivity = path.reduce((acc, step) => acc + Number(step.count || 0), 0);
  revenueOnboarding?.classList.toggle("hidden", totalActivity > 0);
}

function nextBestRevenueAction(path = []) {
  const summary = state.summary || {};
  const dashboard = state.dashboard || {};
  const leads = toNumber(summary.total_leads || 0);
  const openAgenda = (state.leadAgenda || []).filter((item) => String(item.agenda_status || "OPEN").toUpperCase() === "OPEN").length;
  const redeemed = toNumber(summary.total_qr_redeemed || 0);
  const observedSalesCount = toNumber(summary.observed_sales_count ?? summary.direct_sales_count);
  const activeQr = toNumber(dashboard.summary?.active_qr || 0);
  if (!leads) return { title: "Crear una entrada de clientes", description: "Aún no hay materia prima comercial. Crea QR, campaña, dinámica o importa contactos para alimentar la Máquina RMS.", cta: "Crear acción de revenue", objective: "capture", route: "wizard" };
  if (leads && !openAgenda) return { title: "Crear seguimiento en agenda", description: "Ya hay leads o contactos, pero necesitan una orden de trabajo: WhatsApp, llamada, redención, venta o recompra.", cta: "Crear tarea de conversión", objective: "agenda", route: "wizard" };
  if (activeQr > 0 && redeemed === 0) return { title: "Recordar tickets activos", description: "Hay tickets vivos sin redención suficiente. Usa agenda o WhatsApp para empujar visita y validación.", cta: "Revisar tickets", objective: "validate", route: "validator" };
  if (redeemed > observedSalesCount) return { title: "Registrar ventas pendientes", description: "Hay redenciones que deben conectarse con ventas para medir revenue real.", cta: "Registrar venta", objective: "sales", route: "sales" };
  if (!state.missions?.metrics?.active_seasons) return { title: "Crear dinámica semanal", description: "Una misión, ranking o racha mantiene vivo al cliente después de la captura.", cta: "Crear dinámica", objective: "gamify", route: "missions" };
  return { title: "Operar la Máquina RMS", description: "Procesa oportunidades por prioridad y convierte cada lead en una siguiente acción medible.", cta: "Ver Máquina RMS", objective: "agenda", route: "rms-machine" };
}

function renderNextBestAction(path = []) {
  if (!nextBestActionCard) return;
  const action = nextBestRevenueAction(path);
  const activeSteps = path.filter((step) => Number(step.count || 0) > 0);
  const primaryActive = activeSteps[0]?.label || "Inicio";
  const lastActive = activeSteps[activeSteps.length - 1]?.label || "Sin actividad";
  nextBestActionCard.innerHTML = `
    <div class="revenue-action-head">
      <span class="material-symbols-outlined revenue-action-icon" aria-hidden="true">bolt</span>
      <div>
        <span class="mono-label">Siguiente acción recomendada</span>
        <h3>${escapeHtml(action.title)}</h3>
      </div>
    </div>
    <p>${escapeHtml(action.description)}</p>
    <div class="revenue-action-chips" aria-label="Contexto de revenue">
      <span>Entrada: ${escapeHtml(primaryActive)}</span>
      <span>Última etapa: ${escapeHtml(lastActive)}</span>
      <span>${activeSteps.length || 0} etapas activas</span>
    </div>
    <button class="solid-button" type="button" data-next-revenue-action="${escapeHtml(action.route)}" data-revenue-objective="${escapeHtml(action.objective)}">${escapeHtml(action.cta)}</button>
  `;
  nextBestActionCard.querySelector("[data-next-revenue-action]")?.addEventListener("click", (event) => {
    const route = event.currentTarget.dataset.nextRevenueAction;
    if (route === "wizard") {
      openRevenueActionWizard(event.currentTarget.dataset.revenueObjective || "capture");
      return;
    }
    navigateRevenueRoute(route);
  });
}

function navigateRevenueRoute(route = "") {
  const target = String(route || "");
  if (target === "agenda") {
    setContactCenterTab("agenda");
    setView("leads");
    return;
  }
  if (target === "contacts") {
    setContactCenterTab("directory");
    setView("leads");
    return;
  }
  if (target === "sales") {
    setView("sales");
    return;
  }
  if (target === "validator") {
    setView("validator");
    return;
  }
  setView(target || "rms-machine");
}

function updateRevenueActionToolOptions() {
  const config = revenueActionConfig(revenueActionObjectiveInput?.value || "capture");
  if (revenueActionToolInput) {
    revenueActionToolInput.innerHTML = config.tools.map((tool) => `<option value="${escapeHtml(tool)}">${escapeHtml(tool)}</option>`).join("");
  }
  if (revenueActionTaskInput) revenueActionTaskInput.value = config.task;
  if (revenueActionCoverageInput) revenueActionCoverageInput.value = config.coverage || revenueActionCoverageInput.value;
  renderRevenueActionSummary();
}

function openRevenueActionWizard(objective = "capture") {
  if (revenueActionObjectiveInput) revenueActionObjectiveInput.value = REVENUE_ACTION_OPTIONS[objective] ? objective : "capture";
  if (revenueActionDueInput && !revenueActionDueInput.value) {
    revenueActionDueInput.value = datetimeLocalValue(new Date(Date.now() + 86400000));
  }
  updateRevenueActionToolOptions();
  if (revenueActionWizardMessage) revenueActionWizardMessage.textContent = "";
  revenueActionWizardModal?.classList.remove("hidden");
}

function closeRevenueActionWizard() {
  revenueActionWizardModal?.classList.add("hidden");
}

function revenueSelectLabel(input) {
  return input?.selectedOptions?.[0]?.textContent || input?.value || "";
}

function renderRevenueActionSummary() {
  if (!revenueActionSummary) return;
  const objective = revenueSelectLabel(revenueActionObjectiveInput);
  const tool = revenueSelectLabel(revenueActionToolInput);
  const segment = revenueSelectLabel(revenueActionSegmentInput);
  const coverage = revenueSelectLabel(revenueActionCoverageInput);
  const task = revenueSelectLabel(revenueActionTaskInput);
  revenueActionSummary.innerHTML = `
    <span class="mono-label">Confirmación</span>
    <h4>Acción de revenue lista para agenda</h4>
    <p>Objetivo: ${escapeHtml(objective)} · Herramienta: ${escapeHtml(tool)} · Segmento: ${escapeHtml(segment)} · Cobertura: ${escapeHtml(coverage)} · Agenda: ${escapeHtml(task)}</p>
    <small>Métrica esperada: clientes capturados, tickets/redenciones, tareas ejecutadas y revenue atribuido.</small>
  `;
}

async function submitRevenueActionWizard(event) {
  event.preventDefault();
  const objective = revenueActionObjectiveInput?.value || "capture";
  const config = revenueActionConfig(objective);
  const payload = {
    source_type: "MARKETING",
    note_type: "follow_up",
    next_action: revenueActionTaskInput?.value || config.task,
    note: `Acción de revenue: ${revenueSelectLabel(revenueActionObjectiveInput)} con ${revenueSelectLabel(revenueActionToolInput)}. Segmento: ${revenueSelectLabel(revenueActionSegmentInput)}. Cobertura: ${revenueSelectLabel(revenueActionCoverageInput)}.`,
    reminder_at: revenueActionDueInput?.value ? new Date(revenueActionDueInput.value).toISOString() : new Date(Date.now() + 86400000).toISOString(),
    agenda_priority: ["capture", "validate", "sales"].includes(objective) ? "HIGH" : "MEDIUM",
    checklist: [
      { label: "Activar herramienta seleccionada", done: false },
      { label: "Capturar o seleccionar clientes", done: false },
      { label: "Registrar resultado comercial", done: false },
    ],
    metadata: {
      source_module: "revenue_workspace",
      source_flow: "revenue_action_wizard",
      objective,
      tool: revenueActionToolInput?.value || "",
      segment: revenueActionSegmentInput?.value || "",
      coverage: revenueActionCoverageInput?.value || "",
      route: config.route,
    },
  };
  try {
    if (revenueActionWizardMessage) revenueActionWizardMessage.textContent = "Creando tarea en agenda...";
    await api("/api/business/leads/agenda", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify(payload),
    });
    state.leadAgendaLoaded = false;
    closeRevenueActionWizard();
    showFeedback("Acción de revenue creada. Quedó como tarea en la agenda operativa.", "success", { title: "Centro de Revenue" });
    navigateRevenueRoute(config.route);
  } catch (error) {
    if (revenueActionWizardMessage) revenueActionWizardMessage.textContent = error.message || "No se pudo crear la acción.";
    showFeedback(error.message || "No se pudo crear la acción de revenue.", "error", { title: "Centro de Revenue" });
  }
}

function navigatePortalShortcut(target = "") {
  const shortcut = String(target || "").trim();
  if (!shortcut) return;
  if (shortcut === "rms-stations") {
    setView("rms-machine");
    return;
  }
  const contactTabs = {
    agenda: "agenda",
    contacts: "directory",
    sales: "sales",
  };
  if (contactTabs[shortcut]) {
    setContactCenterTab(contactTabs[shortcut]);
    setView(shortcut === "sales" ? "sales" : "leads");
    return;
  }
  const viewMap = {
    dashboard: "dashboard",
    campaigns: "campaigns",
    "strategic-qr": "strategic-qr",
    missions: "missions",
    "smart-catalogs": "smart-catalogs",
    "rms-machine": "rms-machine",
    "reward-passes": "reward-passes",
    validator: "validator",
    redemptions: "redemptions",
    affiliates: "affiliates",
    inventory: "inventory",
    branches: "branches",
    competition: "competition",
    account: "account",
    admin: "admin",
  };
  if (viewMap[shortcut]) setView(viewMap[shortcut]);
}

function focusRmsMachineStations(options = {}) {
  state.rmsStationScreenOpen = false;
  state.rmsStationPhase = "";
  state.rmsMachineFilters.phase = "";
  state.rmsMachineSelectedIds = [];
  state.rmsMachineInspectorId = "";
  if (rmsMachinePhaseFilter) rmsMachinePhaseFilter.value = "";
  document.getElementById("rmsMachineTutorial")?.classList.remove("is-open");
  renderRmsMachineView();
  const delay = Number.isFinite(options.delay) ? options.delay : 120;
  const behavior = options.behavior || "smooth";
  window.setTimeout(() => {
    const target = rmsStageBoard || rmsStationWorkspace;
    target?.scrollIntoView({ behavior, block: "start" });
  }, delay);
}

function smartCatalogSelectedCatalog() {
  return (state.smartCatalogs || []).find((catalog) => catalog.id === state.smartCatalogSelectedCatalogId) || state.smartCatalogs?.[0] || null;
}

function smartCatalogPublicUrl(catalog) {
  if (!catalog) return "";
  return catalog.public_url || `${window.location.origin}/c/${encodeURIComponent(catalog.slug || "")}`;
}

function smartCatalogStatusLabel(status) {
  const labels = {
    ACTIVE: "Activo",
    DRAFT: "Borrador",
    PAUSED: "Pausado",
    ARCHIVED: "Archivado",
    INTENT_CREATED: "Intención",
    CONTACTED: "Contactado",
    WON: "Vendido",
    LOST: "Perdido",
    POST_SALE_SENT: "Postventa enviada",
    AVAILABLE: "Disponible",
    LIMITED: "Limitado",
    OUT_OF_STOCK: "Agotado",
    HIDDEN: "Oculto",
  };
  return labels[status] || status || "-";
}

function smartCatalogStatusClass(status) {
  if (["ACTIVE", "WON", "POST_SALE_SENT", "AVAILABLE"].includes(status)) return "ok";
  if (["DRAFT", "PAUSED", "INTENT_CREATED", "CONTACTED", "LIMITED"].includes(status)) return "pending";
  return "danger";
}

function smartCatalogMetricValue(value, type = "number") {
  if (type === "money") return money(value || 0);
  if (type === "rate") return `${Number(value || 0).toLocaleString("es-CO")}%`;
  return Number(value || 0).toLocaleString("es-CO");
}

function smartCatalogFormPayload(form) {
  const data = new FormData(form);
  const payload = Object.fromEntries(data.entries());
  Object.keys(payload).forEach((key) => {
    if (payload[key] === "") payload[key] = null;
  });
  return payload;
}

function splitSmartCatalogList(value = "") {
  return String(value || "")
    .split(/[\n,;]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 12);
}

function smartCatalogProductBenefits(product = {}) {
  return Array.isArray(product.benefits) ? product.benefits.filter(Boolean) : [];
}

function smartCatalogProductFormField(name) {
  return smartCatalogProductForm?.querySelector(`[name="${name}"]`) || null;
}

function syncSmartCatalogProductImagePreview(source = smartCatalogProductImageUrlInput?.value) {
  const imageSource = String(source || "").trim();
  if (!smartCatalogProductImagePreview || !smartCatalogProductImagePreviewImage) return;
  smartCatalogProductImagePreview.classList.toggle("hidden", !imageSource);
  if (!imageSource) {
    smartCatalogProductImagePreviewImage.removeAttribute("src");
    if (smartCatalogProductImagePreviewLabel) smartCatalogProductImagePreviewLabel.textContent = "";
    return;
  }
  smartCatalogProductImagePreviewImage.src = imageSource;
  if (smartCatalogProductImagePreviewLabel) {
    smartCatalogProductImagePreviewLabel.textContent = imageSource.startsWith("data:image/")
      ? "Imagen subida desde este equipo"
      : "Imagen desde URL";
  }
}

async function uploadSmartCatalogProductImage(file) {
  if (!file || !smartCatalogProductImageUrlInput) return;
  try {
    setInlineMessage(smartCatalogProductMessage, "Preparando imagen...", "info");
    const dataUrl = await readFileAsDataUrl(file, 1024 * 1024, ["image/png", "image/jpeg", "image/webp", "image/gif"]);
    smartCatalogProductImageUrlInput.value = dataUrl;
    syncSmartCatalogProductImagePreview(dataUrl);
    setInlineMessage(smartCatalogProductMessage, "Imagen lista para guardar con la oferta.", "success");
  } catch (error) {
    if (smartCatalogProductImageFileInput) smartCatalogProductImageFileInput.value = "";
    setInlineMessage(smartCatalogProductMessage, error.message || "No se pudo cargar la imagen.", "error");
  }
}

function applySmartCatalogInventoryProductToForm(options = {}) {
  const select = document.getElementById("smartCatalogInventoryProductSelect");
  const product = findInventoryProduct(select?.value || "");
  if (!product || !smartCatalogProductForm) return;
  const setField = (name, value) => {
    const field = smartCatalogProductFormField(name);
    if (!field || value === undefined || value === null || value === "") return;
    if (options.overwrite || !String(field.value || "").trim()) field.value = value;
  };
  setField("name", product.name);
  setField("short_description", product.description || product.short_description || product.notes);
  setField("category", product.category);
  setField("price", product.unit_price || product.price || product.sale_price);
  setField("image_url", product.image_url || product.image);
  syncSmartCatalogProductImagePreview();
}

function prepareSmartCatalogProductPayload(payload = {}) {
  const selectedInventoryProduct = findInventoryProduct(payload.inventory_product_id || "");
  if (selectedInventoryProduct) {
    payload.inventory_product_id = selectedInventoryProduct.id;
    payload.name = payload.name || selectedInventoryProduct.name;
    payload.short_description = payload.short_description || selectedInventoryProduct.description || selectedInventoryProduct.short_description || selectedInventoryProduct.notes || "";
    payload.category = payload.category || selectedInventoryProduct.category || "";
    payload.price = payload.price || selectedInventoryProduct.unit_price || selectedInventoryProduct.price || selectedInventoryProduct.sale_price || "";
    payload.image_url = payload.image_url || selectedInventoryProduct.image_url || selectedInventoryProduct.image || "";
  } else if (!payload.inventory_product_id || payload.inventory_product_id === OPEN_PRODUCT_VALUE) {
    delete payload.inventory_product_id;
  } else if (String(payload.inventory_product_id || "").startsWith("inventory:")) {
    payload.inventory_product_id = String(payload.inventory_product_id).slice("inventory:".length);
  }
  const benefits = splitSmartCatalogList(payload.benefits_text);
  if (payload.seasonal_benefit) benefits.unshift(String(payload.seasonal_benefit).trim());
  payload.benefits = Array.from(new Set(benefits));
  payload.tags = splitSmartCatalogList(payload.tags_text);
  payload.metadata = {
    ...(payload.metadata && typeof payload.metadata === "object" ? payload.metadata : {}),
    season_name: payload.season_name || null,
    seasonal_benefit: payload.seasonal_benefit || null,
    created_from: "smart_catalog_product_form",
  };
  delete payload.benefits_text;
  delete payload.tags_text;
  delete payload.season_name;
  delete payload.seasonal_benefit;
  return payload;
}

