function validatorScrollTo(selector = "") {
  const target = document.querySelector(selector);
  if (!target) return;
  target.scrollIntoView({ behavior: "smooth", block: "start" });
  const focusTarget = target.matches("input, select, textarea, button") ? target : target.querySelector("input, select, textarea, button");
  window.setTimeout(() => focusTarget?.focus({ preventScroll: true }), 260);
}

function ensureValidatorQrUx() {
  const view = document.querySelector('.view-section[data-view="validator"]');
  if (!view) return;
  if (!view.querySelector(".validator-operator-hero")) {
    view.querySelector(":scope > .view-head")?.insertAdjacentHTML("afterend", `
      <section class="validator-operator-hero" aria-label="Flujo operativo del Validador QR">
        <div class="validator-hero-copy">
          <span class="mono-label">Operación en caja</span>
          <h3>Valida el ticket, redime el beneficio y registra la venta sin perder el hilo.</h3>
          <p>Esta pantalla está organizada para atención física: primero captura el QR, luego confirma el estado, redime y cierra la venta atribuida.</p>
        </div>
        <div class="validator-operator-flow">
          <article class="validator-operator-step"><span>1</span><strong>Escanear</strong><small>Cámara o token manual.</small></article>
          <article class="validator-operator-step"><span>2</span><strong>Confirmar</strong><small>Cliente, beneficio y vigencia.</small></article>
          <article class="validator-operator-step"><span>3</span><strong>Redimir</strong><small>Bloquea doble uso del ticket.</small></article>
          <article class="validator-operator-step"><span>4</span><strong>Vender</strong><small>Factura y revenue atribuido.</small></article>
        </div>
      </section>
      <section class="validator-quick-actions" aria-label="Acciones rápidas del validador">
        <button class="validator-quick-action" type="button" data-validator-quick="camera"><span class="material-symbols-outlined">qr_code_scanner</span><span><strong>Escanear con cámara</strong><small>Abre el lector visual.</small></span></button>
        <button class="validator-quick-action" type="button" data-validator-quick="manual"><span class="material-symbols-outlined">keyboard</span><span><strong>Pegar token</strong><small>Validación manual rápida.</small></span></button>
        <button class="validator-quick-action" type="button" data-validator-quick="result"><span class="material-symbols-outlined">fact_check</span><span><strong>Ver resultado</strong><small>Datos del ticket y cliente.</small></span></button>
        <button class="validator-quick-action" type="button" data-validator-quick="sale"><span class="material-symbols-outlined">point_of_sale</span><span><strong>Registrar venta</strong><small>Cierra revenue atribuido.</small></span></button>
      </section>
    `);
  }
  if (!view.dataset.validatorQrUxBound) {
    view.dataset.validatorQrUxBound = "true";
    view.addEventListener("click", (event) => {
      const action = event.target.closest("[data-validator-quick]")?.dataset.validatorQuick;
      if (!action) return;
      event.preventDefault();
      if (action === "camera") {
        validatorScrollTo(".validator-scanner-shell");
        return;
      }
      if (action === "manual") {
        validatorScrollTo("#validatorQrTokenInput");
        return;
      }
      if (action === "result") {
        validatorScrollTo("#validatorResultTitle");
        return;
      }
      if (action === "history") {
        validatorScrollTo("#validatorHistorySection");
      }
    });
  }
}

async function loadValidatorHistory() {
  if (!session?.token) return;

  const businessId = session.user?.business_id;
  if (!businessId) {
    validatorHistoryTable.innerHTML = '<tr><td colspan="7">Asigna un negocio al administrador para consultar su historial.</td></tr>';
    validatorHistoryCards.innerHTML = '<article class="validator-history-empty">Selecciona un negocio para cargar operaciones.</article>';
    return;
  }

  const scopeKey = businessScopeKey();
  try {
    const data = await api(`/api/businesses/${businessId}/validator-history?limit=160`, {
      method: "GET",
      headers: authHeaders(),
    });
    if (!isCurrentBusinessScope(scopeKey)) return;
    state.validatorHistory = data.history || [];
    state.validatorHistorySummary = data.summary || null;
    state.validatorHistoryGate = data.gate || null;
    renderValidatorHistory();
  } catch (error) {
    if (!isCurrentBusinessScope(scopeKey)) return;
    validatorHistoryTable.innerHTML = `<tr><td colspan="7">${escapeHtml(error.message)}</td></tr>`;
    validatorHistoryCards.innerHTML = `<article class="validator-history-empty">${escapeHtml(error.message)}</article>`;
  }
}

function renderValidatorBranchOptions() {
  if (!validatorBranchOptions) return;
  validatorBranchOptions.innerHTML = (state.businessBranches || [])
    .filter((branch) => branch.is_active !== false)
    .map((branch) => `<option value="${escapeHtml(branch.name || "")}"></option>`)
    .join("");
}

async function renderValidatorView() {
  ensureValidatorQrUx();
  loadInventoryProducts({ quiet: true }).then(() => {
    if (state.validatorRedemptionMode === "PURCHASE") {
      renderValidatorPurchaseItems();
      calculateValidatorCheckoutPreview();
    }
  }).catch(() => {});
  if (!state.businessBranchesLoaded && !state.businessBranchesLoading && session?.user?.business_id && hasPlanFeature("multi_branch")) {
    loadBusinessBranches({ quiet: true }).then(renderValidatorBranchOptions).catch(() => {});
  } else {
    renderValidatorBranchOptions();
  }
  if (!window.isSecureContext) {
    validatorCameraStatus.textContent = "Origen inseguro";
    validatorScannerHint.textContent = `La camara solo funciona en HTTPS o localhost. ${await validatorCameraDiagnostic()}. Usa el ingreso manual.`;
  } else if (!validatorCanUseCameraScanner()) {
    validatorCameraStatus.textContent = "Sin soporte";
    validatorScannerHint.textContent = `La camara no esta disponible en este navegador. ${await validatorCameraDiagnostic()}. Usa el ingreso manual.`;
  } else if (!validatorCanUseBarcodeDetector() && validatorCanUseJsQr()) {
    validatorCameraStatus.textContent = "Modo compatible";
    validatorScannerHint.textContent = `Tu navegador no tiene BarcodeDetector, pero si puede usar la camara cuando el sitio se abre en HTTPS o localhost. ${await validatorCameraDiagnostic()}.`;
  } else {
    validatorCameraStatus.textContent = "Lista";
    validatorScannerHint.textContent = `Escaner listo. ${await validatorCameraDiagnostic()}.`;
  }

  if (!state.validatorLastValidation) {
    setValidatorResult("neutral", "Esperando ticket", "Escanea o pega un ticket para consultar la base de datos.");
    setValidatorOperationState("idle", null);
  }

  loadValidatorHistory();
}

function strategicMetricCard(label, value, accent = "default") {
  return `
    <article class="surface-card kpi-card strategic-ticket-kpi-card">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong class="kpi-value ${accent}">${escapeHtml(value)}</strong>
    </article>
  `;
}

function strategicBatchStatusClass(status) {
  return ["ACTIVE", "REDEEMED"].includes(String(status || "").toUpperCase()) ? "ok" : "pending";
}

