function customerSaleIdempotencyKey() {
  if (!state.customerSaleIdempotencyKey) {
    const randomPart = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    state.customerSaleIdempotencyKey = `sales-module:${session?.user?.business_id || "business"}:${randomPart}`;
  }
  return state.customerSaleIdempotencyKey;
}

function affiliatePurchaseIdempotencyKey() {
  if (!state.affiliatePurchaseIdempotencyKey) {
    const randomPart = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    state.affiliatePurchaseIdempotencyKey = `affiliate-purchase:${session?.user?.business_id || "business"}:${randomPart}`;
  }
  return state.affiliatePurchaseIdempotencyKey;
}

async function submitCustomerAcquisitionSale(event) {
  event.preventDefault();
  const submitButton = customerAcquisitionForm.querySelector("button[type='submit']");
  if (!resolveCustomerBeforeSaleSubmit()) return;
  if (!hasCustomerIdentityForSale()) {
    setInlineMessage(customerAcquisitionMessage, "Identifica el cliente antes de registrar la venta: selecciona uno existente o escribe nombre, telefono, correo o cedula.", "error");
    customerAcquisitionNameInput?.focus();
    return;
  }
  const products = customerSaleProductsPayload();
  const saleTotal = products.reduce((sum, product) => sum + Number(product.line_total || 0), 0);
  if (!products.length || saleTotal <= 0) {
    setInlineMessage(customerAcquisitionMessage, "Agrega al menos un producto con precio para registrar la venta.", "error");
    return;
  }
  const productSummary = customerSaleProductSummary(products);
  const acquisitionChannel = acquisitionChannelSelection("customer-sale");
  const metadata = {
    products,
    sale_entry: "sales_module",
    customer_lookup: customerAcquisitionCustomerLookupInput?.value?.trim() || null,
  };
  setButtonLoading(submitButton, true, "Registrando...");
  setSalesCustomerStatus("Registrando venta", "Estamos guardando cliente, productos y atribucion comercial.", "success", "sync");
  setInlineMessage(customerAcquisitionMessage, "Registrando venta real y medio de llegada...", "info");
  try {
    const data = await api("/api/business/customer-acquisition-sales", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        idempotency_key: customerSaleIdempotencyKey(),
        sale_amount: saleTotal,
        campaign_id: customerAcquisitionCampaignInput?.value || null,
        branch_id: customerAcquisitionBranchInput?.value || null,
        currency: customerAcquisitionCurrencyInput.value.trim() || "COP",
        payment_method: customerAcquisitionPaymentMethodInput?.value || null,
        product_name: productSummary || null,
        customer_name: customerAcquisitionNameInput.value.trim() || null,
        customer_document_id: customerAcquisitionDocumentInput.value.trim() || null,
        customer_phone: customerAcquisitionPhoneInput.value.trim() || null,
        customer_email: customerAcquisitionEmailInput.value.trim() || null,
        acquisition_source: customerAcquisitionSourceInput.value,
        ...acquisitionChannel,
        referred_affiliate_id: null,
        notes: customerAcquisitionNotesInput.value.trim() || null,
        metadata,
      }),
    });
    const savedMetadata = saleMetadata(data.sale || {});
    const autoCreatedCount = Array.isArray(savedMetadata.auto_created_products) ? savedMetadata.auto_created_products.length : 0;
    const productSyncMessage = autoCreatedCount
      ? ` ${autoCreatedCount} producto${autoCreatedCount === 1 ? "" : "s"} nuevo${autoCreatedCount === 1 ? "" : "s"} quedó${autoCreatedCount === 1 ? "" : "aron"} creado${autoCreatedCount === 1 ? "" : "s"} en Productos.`
      : "";
    const customerCreatedMessage = data.customer?.created
      ? ` ${data.customer.name || "El comprador"} también quedó creado como contacto cliente.`
      : "";
    const message = data.duplicate
      ? "Esta venta ya estaba registrada. Conservamos el registro original sin duplicar cliente, productos ni puntos."
      : `Venta registrada con su medio de llegada.${customerCreatedMessage}${productSyncMessage}`;
    setInlineMessage(customerAcquisitionMessage, message, "success");
    state.customerSaleIdempotencyKey = "";
    customerAcquisitionForm.reset();
    if (customerAcquisitionAffiliateInput) customerAcquisitionAffiliateInput.dataset.autoSelectedAffiliateId = "";
    customerAcquisitionCurrencyInput.value = "COP";
    renderCustomerAcquisitionBranchOptions();
    setSalesCustomerStatus("Cliente nuevo / manual", "Formulario listo para registrar otra venta.", "success", "task_alt");
    state.customerSaleItems = [defaultCustomerSaleItem()];
    renderCustomerAcquisitionCampaignOptions();
    renderCustomerSaleItems();
    await loadInventoryProducts({ force: true, quiet: true });
    renderInventoryProductOptions();
    await Promise.all([
      loadContactFeedData({ force: true, quiet: true }),
      loadLeadCrmData({ force: true, quiet: true }),
      loadAcquisitionChannels({ force: true, quiet: true }),
      loadChannelEfforts({ force: true, quiet: true }),
      loadAttributedSalesView({ quiet: true }),
    ]);
    renderSalesCustomerOptions();
    renderAcquisitionChannelDatalist();
    if (state.currentView === "channels") renderAcquisitionChannelsView();
    await refreshLiveBusinessData();
    if (state.currentView === "branches") renderBranchesView();
    setView("sales");
    closeSalesCreatePanel({ scroll: true });
    showFeedback(message, "success", { title: "Venta registrada" });
  } catch (error) {
    setSalesCustomerStatus("No se pudo registrar", error.message, "error", "error");
    setInlineMessage(customerAcquisitionMessage, error.message, "error");
    showFeedback(error.message, "error", { title: "No se pudo registrar" });
  } finally {
    setButtonLoading(submitButton, false);
  }
}

function normalizeInventoryLookup(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLocaleLowerCase("es-CO")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

function rmsProductSearchMatches(product = {}, query = "") {
  const tokens = normalizeInventoryLookup(query).split(/\s+/).filter(Boolean);
  if (!tokens.length) return true;
  const searchable = normalizeInventoryLookup([
    product.name,
    product.category,
    product.sku,
    product.barcode,
    product.brand,
    product.description,
    product.unit_label,
  ].filter(Boolean).join(" "));
  return tokens.every((token) => searchable.includes(token));
}

const OPEN_PRODUCT_VALUE = "__OPEN_PRODUCT__";

function productSalePayload(product, quantity = 1, unitPrice = null) {
  if (!product) return null;
  const safeQuantity = Math.max(1, Number(quantity || 1));
  const safeUnitPrice = Math.max(0, Number(unitPrice ?? product.unit_price ?? 0));
  return {
    inventory_product_id: product.id,
    name: product.name,
    sku: product.sku || null,
    barcode: product.barcode || null,
    quantity: safeQuantity,
    unit_price: safeUnitPrice,
    line_total: safeQuantity * safeUnitPrice,
  };
}

function activeInventoryProducts() {
  return (state.inventoryProducts || []).filter((item) => item.status !== "ARCHIVED");
}

function inventoryProductSelectValue(product = {}) {
  return product?.id ? `inventory:${product.id}` : "";
}

function findInventoryProductById(productId) {
  if (!productId) return null;
  return (state.inventoryProducts || []).find((product) => String(product.id) === String(productId)) || null;
}

function findInventoryProduct(value) {
  const raw = String(value || "").trim();
  if (raw.startsWith("inventory:")) {
    return findInventoryProductById(raw.slice("inventory:".length));
  }
  const needle = normalizeInventoryLookup(raw);
  if (!needle) return null;
  return (state.inventoryProducts || []).find((product) => {
    const candidates = [product.name, product.sku, product.barcode, inventoryProductLabel(product)].map(normalizeInventoryLookup);
    return candidates.includes(needle);
  }) || null;
}

function inventoryProductLabel(product = {}) {
  const refs = [product.sku, product.barcode].filter(Boolean).join(" / ");
  return refs ? `${product.name} - ${refs}` : product.name;
}

function productOpenInputFor(productInput) {
  if (!productInput) return null;
  const openInputId = productInput.dataset?.openProductInput;
  if (openInputId) return document.getElementById(openInputId);
  const row = productInput.closest?.("[data-sale-item-index], [data-affiliate-purchase-row], label");
  return row?.querySelector?.("[data-open-product-input]") || null;
}

function productInputRawValue(productInput) {
  if (!productInput) return "";
  if (productInput.value === OPEN_PRODUCT_VALUE) {
    return String(productOpenInputFor(productInput)?.value || "").trim();
  }
  const product = findInventoryProduct(productInput.value);
  return String(product?.name || productInput.value || "").trim();
}

function productSelectSelectionForValue(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (raw === OPEN_PRODUCT_VALUE || raw.startsWith("inventory:")) return raw;
  const product = findInventoryProduct(raw);
  return product ? inventoryProductSelectValue(product) : OPEN_PRODUCT_VALUE;
}

function inventoryProductSelectOptions(selectedValue = "", options = {}) {
  const selected = String(selectedValue || "");
  const placeholder = options.placeholder || "Sin producto especifico";
  const openLabel = options.openLabel || "Producto abierto / no esta en Productos";
  const option = (value, label) => `<option value="${escapeHtml(value)}" ${selected === value ? "selected" : ""}>${escapeHtml(label)}</option>`;
  return [
    option("", placeholder),
    ...activeInventoryProducts().map((product) => {
      const stock = product.stock_quantity !== undefined && product.stock_quantity !== null ? ` · stock ${Number(product.stock_quantity || 0).toLocaleString("es-CO")}` : "";
      return option(inventoryProductSelectValue(product), `${inventoryProductLabel(product)} · ${money(product.unit_price || 0)}${stock}`);
    }),
    option(OPEN_PRODUCT_VALUE, openLabel),
  ].join("");
}

function syncProductOpenInput(productInput) {
  const openInput = productOpenInputFor(productInput);
  if (!openInput) return;
  const isOpen = productInput?.value === OPEN_PRODUCT_VALUE;
  openInput.classList.toggle("hidden", !isOpen);
  openInput.disabled = !isOpen || Boolean(productInput?.disabled);
  openInput.required = Boolean(isOpen && productInput?.required);
}

function setProductInputValue(productInput, value = "") {
  if (!productInput) return;
  const raw = String(value || "").trim();
  const openInput = productOpenInputFor(productInput);
  const selected = productSelectSelectionForValue(raw);
  if (productInput.tagName === "SELECT" && !Array.from(productInput.options || []).some((option) => option.value === selected)) {
    productInput.innerHTML = inventoryProductSelectOptions(selected, {
      placeholder: productInput.dataset.placeholder || "Sin producto especifico",
      openLabel: productInput.dataset.openLabel || "Producto abierto / no esta en Productos",
    });
  }
  productInput.value = selected;
  if (openInput) {
    openInput.value = selected === OPEN_PRODUCT_VALUE ? raw : "";
  }
  syncProductOpenInput(productInput);
}

function renderProductSelect(productInput) {
  if (!productInput) return;
  const openInput = productOpenInputFor(productInput);
  const currentRaw = productInputRawValue(productInput) || openInput?.value || "";
  const selected = productSelectSelectionForValue(productInput.value || currentRaw);
  if (selected === OPEN_PRODUCT_VALUE && openInput && currentRaw) openInput.value = currentRaw;
  productInput.innerHTML = inventoryProductSelectOptions(selected, {
    placeholder: productInput.dataset.placeholder || "Sin producto especifico",
    openLabel: productInput.dataset.openLabel || "Producto abierto / no esta en Productos",
  });
  productInput.value = selected;
  syncProductOpenInput(productInput);
}

function renderInventoryProductOptions() {
  document.querySelectorAll("[data-product-select]").forEach((select) => renderProductSelect(select));
}

async function loadInventoryProductCategories(options = {}) {
  if (state.inventoryTaxonomyLoaded && !options.force) {
    return { categories: state.inventoryCategories, subcategories: state.inventorySubcategories };
  }
  if (state.inventoryTaxonomyLoading && !options.force) return state.inventoryTaxonomyLoading;
  const scopeKey = businessScopeKey();
  const request = Promise.all([
    api("/api/business/inventory/categories", { headers: authHeaders(), planGate: false }),
    api("/api/business/inventory/subcategories", { headers: authHeaders(), planGate: false }),
  ]).then(([categoriesData, subcategoriesData]) => {
    if (!isCurrentBusinessScope(scopeKey)) return { categories: state.inventoryCategories, subcategories: state.inventorySubcategories };
    state.inventoryCategories = Array.isArray(categoriesData.categories) ? categoriesData.categories : [];
    state.inventorySubcategories = Array.isArray(subcategoriesData.subcategories) ? subcategoriesData.subcategories : [];
    state.inventoryTaxonomyLoaded = true;
    renderInventoryTaxonomyOptions();
    return { categories: state.inventoryCategories, subcategories: state.inventorySubcategories };
  }).finally(() => {
    if (isCurrentBusinessScope(scopeKey)) state.inventoryTaxonomyLoading = null;
  });
  state.inventoryTaxonomyLoading = request;
  return request;
}

async function loadInventoryTaxonomy(options = {}) {
  const core = await loadInventoryProductCategories(options);
  const [brandsData, unitsData, taxBasesData, healthyTaxesData] = await Promise.all([
    apiSafe("/api/business/inventory/catalog/brands", { headers: authHeaders() }, { brands: [] }),
    apiSafe("/api/business/inventory/catalog/units", { headers: authHeaders() }, { units: [] }),
    apiSafe("/api/business/inventory/catalog/tax-bases", { headers: authHeaders() }, { tax_bases: [] }),
    apiSafe("/api/business/inventory/catalog/healthy-taxes", { headers: authHeaders() }, { healthy_taxes: [] }),
  ]);
  state.inventoryBrands = Array.isArray(brandsData.brands) ? brandsData.brands : [];
  state.inventoryUnits = Array.isArray(unitsData.units) ? unitsData.units : [];
  state.inventoryTaxBases = Array.isArray(taxBasesData.tax_bases) ? taxBasesData.tax_bases : [];
  state.inventoryHealthyTaxes = Array.isArray(healthyTaxesData.healthy_taxes) ? healthyTaxesData.healthy_taxes : [];
  state.inventoryTaxonomyLoaded = true;
  renderInventoryTaxonomyOptions();
  return core;
}

function inventoryTaxRate(classification = "EXEMPT") {
  return { EXEMPT: 0, EXCLUDED: 0, VAT_0: 0, VAT_5: 0.05, VAT_8: 0.08, VAT_11: 0.11, VAT_19: 0.19 }[classification] || 0;
}

function inventoryTaxRateLabel(rate, fallback = "No aplica") {
  const value = Number(rate);
  return Number.isFinite(value) ? `${Math.round(value * 10000) / 100}%` : fallback;
}

function inventoryBaseVatLabel(product = {}) {
  const fallback = { EXEMPT: "Exento", VAT_0: "0%", VAT_5: "5%", VAT_8: "8%", VAT_11: "11%", VAT_19: "19%" }[product.tax_classification] || "Exento";
  if (!product.tax_base_name) return fallback;
  const rate = inventoryTaxRateLabel(product.tax_base_rate, fallback);
  return `${product.tax_base_name} · ${rate}`;
}

function inventoryHealthyTaxLabel(product = {}) {
  if (!product.healthy_tax_name) return "No aplica";
  return `${product.healthy_tax_name} · ${inventoryTaxRateLabel(product.healthy_tax_rate, "0%")}`;
}

function renderInventorySellingPrice() {
  if (!inventoryUnitPriceInput) return;
  const base = Math.max(0, Number(inventoryPriceBeforeTaxInput?.value || 0));
  const taxBase = (state.inventoryTaxBases || []).find((item) => String(item.id) === String(inventoryTaxClassificationInput?.value || ""));
  const healthyTax = (state.inventoryHealthyTaxes || []).find((item) => String(item.id) === String(inventoryHealthyTaxInput?.value || ""));
  const iva = taxBase ? Number(taxBase.rate || 0) : inventoryTaxRate(inventoryTaxClassificationInput?.value);
  const healthy = Number(healthyTax?.rate || 0);
  const total = Math.round((base * (1 + iva + healthy) + Number.EPSILON) * 100) / 100;
  inventoryUnitPriceInput.value = String(total);
  const cost = Math.max(0, Number(inventoryCostPriceInput?.value || 0));
  if (inventoryUtilityInput) inventoryUtilityInput.value = String(Math.round((base - cost + Number.EPSILON) * 100) / 100);
  if (inventoryMarginInput) inventoryMarginInput.value = base > 0 ? `${Math.round((((base - cost) / base) * 100 + Number.EPSILON) * 100) / 100}%` : "0%";
}

function renderInventoryTaxonomyOptions() {
  const categories = state.inventoryCategories || [];
  const selectedCategory = inventoryCategoryInput?.value || "";
  const categoryOptions = [
    '<option value="">Selecciona una categoría</option>',
    ...categories.map((category) => `<option value="${escapeHtml(category.id)}">${escapeHtml(`${category.name} · ${category.internal_id}`)}</option>`),
  ].join("");
  if (inventoryCategoryInput) {
    inventoryCategoryInput.innerHTML = categoryOptions;
    inventoryCategoryInput.value = categories.some((category) => category.id === selectedCategory) ? selectedCategory : "";
  }
  if (inventorySubcategoryCategoryInput) {
    const selected = inventorySubcategoryCategoryInput.value || "";
    inventorySubcategoryCategoryInput.innerHTML = categoryOptions;
    inventorySubcategoryCategoryInput.value = categories.some((category) => category.id === selected) ? selected : "";
  }
  const selectOptions = (items, placeholder, selectedValue = "") => [
    `<option value="">${escapeHtml(placeholder)}</option>`,
    ...(items || []).map((item) => `<option value="${escapeHtml(item.id)}" ${String(item.id) === String(selectedValue) ? "selected" : ""}>${escapeHtml(`${item.name} · ${item.internal_id}`)}</option>`),
  ].join("");
  if (inventoryBrandInput) inventoryBrandInput.innerHTML = selectOptions(state.inventoryBrands, "Sin marca", inventoryBrandInput.value);
  if (inventoryUnitLabelInput) inventoryUnitLabelInput.innerHTML = selectOptions(state.inventoryUnits, "Selecciona unidad de medida", inventoryUnitLabelInput.value);
  if (inventoryTaxClassificationInput) inventoryTaxClassificationInput.innerHTML = selectOptions(state.inventoryTaxBases, "Selecciona IVA base", inventoryTaxClassificationInput.value);
  if (inventoryHealthyTaxInput) inventoryHealthyTaxInput.innerHTML = selectOptions(state.inventoryHealthyTaxes, "No aplica", inventoryHealthyTaxInput.value);
  renderInventorySubcategoryOptions();
  renderInventoryTaxonomyList();
}

function renderInventorySubcategoryOptions() {
  if (!inventorySubcategoryInput) return;
  const categoryId = inventoryCategoryInput?.value || "";
  const selected = inventorySubcategoryInput.value || "";
  const available = (state.inventorySubcategories || []).filter((subcategory) => !categoryId || subcategory.category_id === categoryId);
  inventorySubcategoryInput.innerHTML = [
    '<option value="">Sin subcategoría</option>',
    ...available.map((subcategory) => `<option value="${escapeHtml(subcategory.id)}">${escapeHtml(`${subcategory.name} · ${subcategory.internal_id}`)}</option>`),
  ].join("");
  inventorySubcategoryInput.value = available.some((subcategory) => subcategory.id === selected) ? selected : "";
}

function renderInventoryTaxonomyList() {
  if (!inventoryTaxonomyList) return;
  const categories = state.inventoryCategories || [];
  if (!categories.length) {
    inventoryTaxonomyList.innerHTML = '<p class="empty-state compact">Aún no hay categorías. Crea la primera para poder registrar productos.</p>';
    return;
  }
  inventoryTaxonomyList.innerHTML = categories.map((category) => {
    const subcategories = (state.inventorySubcategories || []).filter((item) => item.category_id === category.id);
    return `<article><strong>${escapeHtml(category.name)}</strong><small>${escapeHtml(category.internal_id)} · ${Number(category.products_count || 0)} producto(s)</small><div>${subcategories.length ? subcategories.map((item) => `<span class="pill muted">${escapeHtml(item.name)} · ${escapeHtml(item.internal_id)}</span>`).join("") : '<small>Sin subcategorías</small>'}</div></article>`;
  }).join("");
}

async function loadInventoryProducts(options = {}) {
  if (state.inventoryLoaded && !options.force) return state.inventoryProducts;
  const scopeKey = businessScopeKey();
  // Una carga iniciada para otra sesión no puede bloquear el catálogo de la
  // empresa actual. Sin este corte, Asignación podía quedar en “Cargando el
  // catálogo” después de entrar al portal o cambiar de empresa.
  if (state.inventoryLoading && !options.force && state.inventoryLoadingScope === scopeKey) return state.inventoryLoading;
  if (state.inventoryLoading && state.inventoryLoadingScope !== scopeKey) {
    state.inventoryLoading = null;
    state.inventoryLoadingScope = "";
  }
  if (!options.quiet && inventoryTable) {
    inventoryTable.innerHTML = '<tr><td colspan="7">Cargando productos...</td></tr>';
  }
  state.inventoryLoadError = "";
  const request = (async () => {
    try {
      const data = await api("/api/business/inventory/products?limit=500", { headers: authHeaders(), planGate: false });
      if (!isCurrentBusinessScope(scopeKey)) return state.inventoryProducts;
      state.inventoryProducts = Array.isArray(data.products) ? data.products : [];
    } catch (error) {
      if (!isCurrentBusinessScope(scopeKey)) return state.inventoryProducts;
      state.inventoryProducts = [];
      state.inventoryLoadError = error.message || "No se pudo cargar el catálogo de productos.";
    } finally {
      if (isCurrentBusinessScope(scopeKey)) {
        state.inventoryLoaded = true;
        renderInventoryProductOptions();
      }
      if (state.inventoryLoading === request) {
        state.inventoryLoading = null;
        state.inventoryLoadingScope = "";
      }
    }
    if (isCurrentBusinessScope(scopeKey)) {
      loadInventoryTaxonomy({ quiet: true }).catch(() => {});
    }
    return state.inventoryProducts;
  })();
  state.inventoryLoading = request;
  state.inventoryLoadingScope = scopeKey;
  return request;
}

function filteredInventoryProducts() {
  const needle = normalizeInventoryLookup(state.inventorySearch);
  const products = state.inventoryProducts || [];
  const mode = state.inventoryQuickFilter || "all";
  const categoryId = String(state.inventoryCategoryFilter || "");
  return products.filter((product) => {
    const stock = Number(product.stock_quantity || 0);
    const minStock = Number(product.min_stock_quantity || 0);
    const status = product.status || "ACTIVE";
    const matchesNeedle = !needle || [product.internal_id, product.name, product.sku, product.barcode, product.category, product.category_name, product.subcategory_name, product.brand]
      .some((value) => normalizeInventoryLookup(value).includes(needle));
    const matchesCategory = !categoryId || String(product.category_id || "") === categoryId;
    const matchesMode = mode === "all"
      || (mode === "active" && status === "ACTIVE")
      || (mode === "low_stock" && status === "ACTIVE" && stock <= minStock)
      || (mode === "without_code" && !product.sku && !product.barcode)
      || (mode === "archived" && status === "ARCHIVED");
    return matchesNeedle && matchesCategory && matchesMode;
  });
}

function inventoryKpis(products = state.inventoryProducts || []) {
  const active = products.filter((item) => item.status === "ACTIVE");
  const stockUnits = active.reduce((sum, item) => sum + Number(item.stock_quantity || 0), 0);
  const inventoryValue = active.reduce((sum, item) => sum + (Number(item.stock_quantity || 0) * Number(item.unit_price || 0)), 0);
  const lowStock = active.filter((item) => Number(item.stock_quantity || 0) <= Number(item.min_stock_quantity || 0)).length;
  return [
    { label: "Productos activos", value: active.length.toLocaleString("es-CO"), meta: "Disponibles para venta" },
    { label: "Unidades en stock", value: stockUnits.toLocaleString("es-CO"), meta: "Suma de productos" },
    { label: "Valor venta productos", value: money(inventoryValue), meta: "Stock x precio venta" },
    { label: "Stock bajo", value: lowStock.toLocaleString("es-CO"), meta: "Requieren reposicion" },
  ];
}

