function inventoryCsvParse(text = "") {
  const source = String(text || "").replace(/^\uFEFF/, "");
  const firstLine = source.split(/\r?\n/, 1)[0] || "";
  const delimiter = (firstLine.match(/;/g) || []).length > (firstLine.match(/,/g) || []).length ? ";" : ",";
  const rows = [];
  let row = [];
  let cell = "";
  let inQuotes = false;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];
    if (char === '"' && inQuotes && next === '"') {
      cell += '"';
      index += 1;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === delimiter && !inQuotes) {
      row.push(cell.trim());
      cell = "";
    } else if ((char === "\n" || char === "\r") && !inQuotes) {
      if (char === "\r" && next === "\n") index += 1;
      row.push(cell.trim());
      if (row.some(Boolean)) rows.push(row);
      row = [];
      cell = "";
    } else {
      cell += char;
    }
  }
  row.push(cell.trim());
  if (row.some(Boolean)) rows.push(row);
  return rows;
}

function inventoryCsvNumber(value, fallback = 0, commaMode = "AUTO") {
  const raw = String(value ?? "").trim().replace(/[^0-9,.-]/g, "");
  if (!raw) return fallback;
  const mode = ["THOUSANDS", "DECIMAL", "AUTO"].includes(commaMode) ? commaMode : "AUTO";
  const normalized = mode === "THOUSANDS"
    ? raw.replace(/,/g, "")
    : mode === "DECIMAL"
      ? (raw.includes(",") ? raw.replace(/\./g, "").replace(/,/g, ".") : raw)
      : raw.includes(",") && raw.includes(".")
        ? (raw.lastIndexOf(".") > raw.lastIndexOf(",") ? raw.replace(/,/g, "") : raw.replace(/\./g, "").replace(",", "."))
        : raw.includes(",")
          ? raw.replace(",", ".")
          : (/^-?\d{1,3}(\.\d{3})+$/.test(raw) ? raw.replace(/\./g, "") : raw);
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function inventoryCsvOptional(value) {
  const normalized = String(value ?? "").trim();
  return normalized || null;
}

function inventoryCsvStatus(value = "") {
  const status = normalizeCsvHeader(value);
  if (["inactive", "inactivo"].includes(status)) return "INACTIVE";
  if (["archived", "archivado"].includes(status)) return "ARCHIVED";
  return "ACTIVE";
}

function inventoryCsvTaxClassification(value = "") {
  const normalized = String(value || "").trim().toUpperCase().replace(/\s+/g, "");
  if (["5", "5%", "VAT_5", "IVA_5"].includes(normalized)) return "VAT_5";
  if (["8", "8%", "VAT_8", "IVA_8"].includes(normalized)) return "VAT_8";
  if (["19", "19%", "VAT_19", "IVA_19"].includes(normalized)) return "VAT_19";
  if (["EXCLUIDO", "EXCLUDED"].includes(normalized)) return "EXCLUDED";
  return "EXEMPT";
}

function inventoryProductsFromCsv(text = "", options = {}) {
  const commaMode = options.commaMode || "AUTO";
  const rows = inventoryCsvParse(text);
  if (rows.length < 2) return [];
  const headers = rows[0].map(normalizeCsvHeader);
  return rows.slice(1).map((cells, rowIndex) => {
    const record = {};
    headers.forEach((header, index) => { if (header) record[header] = cells[index] || ""; });
    const name = csvCell(record, ["nombre", "name", "producto", "product"]);
    return {
      row_number: rowIndex + 2,
      internal_id: csvCell(record, ["id_producto", "product_id", "internal_id", "id"]),
      name,
      barcode: inventoryCsvOptional(csvCell(record, ["codigo_barras", "codigo_de_barras", "barcode"])),
      sku: inventoryCsvOptional(csvCell(record, ["sku", "referencia", "codigo"])),
      category_internal_id: inventoryCsvOptional(csvCell(record, ["categoria_id", "category_id", "category_internal_id"])),
      category: inventoryCsvOptional(csvCell(record, ["categoria", "category", "nombre_categoria", "category_name"])),
      subcategory_internal_id: inventoryCsvOptional(csvCell(record, ["subcategoria_id", "subcategory_id", "subcategory_internal_id"])),
      subcategory: inventoryCsvOptional(csvCell(record, ["subcategoria", "subcategory", "nombre_subcategoria", "subcategory_name"])),
      brand: inventoryCsvOptional(csvCell(record, ["marca", "brand"])),
      tax_base: inventoryCsvOptional(csvCell(record, ["iva_base", "iva", "tax_base", "tax"])),
      healthy_tax: inventoryCsvOptional(csvCell(record, ["impuesto_saludable", "healthy_tax"])),
      tax_classification: inventoryCsvTaxClassification(csvCell(record, ["iva_base", "iva", "tax", "tax_classification"])),
      price_before_tax: inventoryCsvNumber(csvCell(record, ["precio_base", "precio_antes_iva", "price_before_tax", "precio_venta", "precio", "unit_price", "sale_price"]), 0, commaMode),
      unit_price: 0,
      cost_price: csvCell(record, ["costo_producto", "costo", "cost", "cost_price"]) ? inventoryCsvNumber(csvCell(record, ["costo_producto", "costo", "cost", "cost_price"]), 0, commaMode) : null,
      currency: (csvCell(record, ["moneda", "currency"]) || "COP").toUpperCase(),
      stock_quantity: inventoryCsvNumber(csvCell(record, ["stock", "cantidad", "stock_quantity"]), 0, commaMode),
      min_stock_quantity: inventoryCsvNumber(csvCell(record, ["stock_minimo", "min_stock", "min_stock_quantity"]), 0, commaMode),
      unit_label: csvCell(record, ["unidad_de_medida", "unidad", "unidad_medida", "unit", "unit_label"]) || "Unidad",
      status: inventoryCsvStatus(csvCell(record, ["estado", "status"])),
      description: inventoryCsvOptional(csvCell(record, ["descripcion", "description", "detalle"])),
    };
  }).filter((product) => product.name || product.sku || product.barcode);
}

function downloadInventoryCsvTemplate() {
  const csv = [
    "ID Producto,nombre,categoria,subcategoria,codigo_barras,sku,marca,iva_base,impuesto_saludable,precio_base,Costo Producto,moneda,stock,stock_minimo,Unidad de Medida,estado,descripcion",
    "PRD-001,Producto de ejemplo,Ropa,Camisas,770000000001,SKU-001,Marca creada,19%,No Aplica,\"25,000.00\",\"12,000.00\",COP,10,2,Unidad,ACTIVE,Descripcion opcional",
  ].join("\n");
  const link = document.createElement("a");
  link.href = URL.createObjectURL(new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8" }));
  link.download = "plantilla-productos-qori.csv";
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(link.href), 500);
}

async function importInventoryProductsCsv(event) {
  event?.preventDefault();
  const file = inventoryCsvFileInput?.files?.[0];
  if (!file) {
    setInlineMessage(inventoryCsvImportMessage, "Selecciona un archivo CSV.", "error");
    return;
  }
  try {
    const commaMode = inventoryCsvCommaModeInput?.value || "THOUSANDS";
    const products = inventoryProductsFromCsv(await file.text(), { commaMode });
    const incomplete = products.filter((product) => !product.internal_id || !product.name || (!product.category_internal_id && !product.category));
    if (!products.length || incomplete.length) {
      throw new Error("Cada fila necesita ID de producto, nombre y una categoría existente (ID interno o nombre). Descarga la plantilla si necesitas la estructura exacta.");
    }
    setButtonLoading(inventoryCsvImportSubmitButton, true, "Importando...");
    const commaDescription = commaMode === "DECIMAL" ? "coma decimal" : commaMode === "THOUSANDS" ? "coma de miles" : "detección automática";
    setInlineMessage(inventoryCsvImportMessage, `Validando ${products.length.toLocaleString("es-CO")} producto(s) con ${commaDescription}...`, "info");
    const result = await api("/api/business/inventory/products/import-csv", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({ products }),
    });
    state.inventoryLoaded = false;
    await loadInventoryProducts({ force: true, quiet: true });
    renderInventoryProductOptions();
    renderInventoryView();
    const message = `${Number(result.imported || 0).toLocaleString("es-CO")} producto(s) importado(s) correctamente.`;
    setInlineMessage(inventoryCsvImportMessage, message, "success");
    showFeedback(message, "success", { title: "Inventario actualizado" });
    window.setTimeout(closeInventoryCsvImportModal, 650);
  } catch (error) {
    setInlineMessage(inventoryCsvImportMessage, error.message || "No se pudo importar el CSV.", "error");
    showFeedback(error.message || "No se pudo importar el CSV.", "error", { title: "Productos" });
  } finally {
    setButtonLoading(inventoryCsvImportSubmitButton, false);
  }
}

async function submitInventoryProduct(event) {
  event.preventDefault();
  const productId = inventoryProductIdInput?.value || "";
  const payload = inventoryFormPayload();
  if (!payload.internal_id || !payload.name || !payload.category_id || payload.price_before_tax < 0) {
    setInlineMessage(inventoryMessage, "Completa ID interno, nombre, categoría y precio antes de IVA.", "error");
    return;
  }
  setButtonLoading(inventorySaveButton, true, productId ? "Actualizando..." : "Guardando...");
  setInlineMessage(inventoryMessage, "Guardando producto...", "info");
  try {
    const data = await api(productId ? `/api/business/inventory/products/${productId}` : "/api/business/inventory/products", {
      method: productId ? "PATCH" : "POST",
      headers: authHeaders(),
      body: JSON.stringify(payload),
    });
    const saved = data.product;
    state.inventoryProducts = [
      saved,
      ...(state.inventoryProducts || []).filter((item) => item.id !== saved.id),
    ];
    state.inventoryLoaded = true;
    resetInventoryForm();
    renderInventoryProductOptions();
    setInlineMessage(inventoryMessage, "Producto guardado correctamente.", "success");
    closeInventoryProductModal();
    renderInventoryView();
    showFeedback("Producto guardado.", "success", { title: "Productos" });
  } catch (error) {
    setInlineMessage(inventoryMessage, error.message, "error");
    showFeedback(error.message, "error", { title: "No se pudo guardar" });
  } finally {
    setButtonLoading(inventorySaveButton, false);
  }
}

async function archiveInventoryProduct(productId) {
  const product = (state.inventoryProducts || []).find((item) => item.id === productId);
  if (!product) return;
  if (product.has_sales) {
    showFeedback("No se puede eliminar porque este producto tiene ventas o movimientos asociados.", "error", { title: "Productos" });
    return;
  }
  const reason = window.prompt(`Eliminar ${product.name}. Solo es posible porque no tiene ventas ni movimientos. Motivo obligatorio:`);
  if (!String(reason || "").trim()) return;
  try {
    await api(`/api/business/inventory/products/${productId}`, {
      method: "DELETE",
      headers: authHeaders(),
      body: JSON.stringify({ reason: String(reason).trim() }),
    });
    state.inventoryProducts = (state.inventoryProducts || []).filter((item) => item.id !== productId);
    renderInventoryProductOptions();
    renderInventoryView();
    showFeedback("Producto eliminado.", "success", { title: "Productos" });
  } catch (error) {
    showFeedback(error.message, "error", { title: "No se pudo archivar" });
  }
}

async function loadCompetitionProducts(options = {}) {
  if (!session?.user?.business_id) {
    state.competitionProducts = [];
    state.competitionCompetitors = [];
    state.competitionFindings = [];
    state.competitionCampaigns = [];
    state.competitionEvents = [];
    state.competitionTasks = [];
    state.competitionLoaded = true;
    state.competitionLoading = false;
    return [];
  }
  if (state.competitionLoaded && !options.force) return state.competitionProducts;
  if (state.competitionLoading) return state.competitionProducts;
  if (!options.quiet && competitionTable) competitionTable.innerHTML = '<tr><td colspan="9">Cargando radar competitivo...</td></tr>';
  state.competitionLoading = true;
  const scopeKey = businessScopeKey();
  try {
    const [competitorsData, productsData, findingsData, campaignsData, eventsData, tasksData] = await Promise.all([
      apiSafe("/api/business/competitors?limit=500", { headers: authHeaders() }, { competitors: [] }),
      apiSafe("/api/business/competitor-products?limit=500", { headers: authHeaders() }, { products: [] }),
      apiSafe("/api/business/competitor-findings?limit=500", { headers: authHeaders() }, { findings: [] }),
      apiSafe("/api/business/competitor-campaigns?limit=500", { headers: authHeaders() }, { campaigns: [] }),
      apiSafe("/api/business/competitor-events?limit=500", { headers: authHeaders() }, { events: [] }),
      apiSafe("/api/business/competitor-tasks?limit=500", { headers: authHeaders() }, { tasks: [] }),
    ]);
    if (!isCurrentBusinessScope(scopeKey)) return state.competitionProducts;
    state.competitionCompetitors = Array.isArray(competitorsData.competitors) ? competitorsData.competitors : [];
    state.competitionProducts = Array.isArray(productsData.products) ? productsData.products : [];
    state.competitionFindings = Array.isArray(findingsData.findings) ? findingsData.findings : [];
    state.competitionCampaigns = Array.isArray(campaignsData.campaigns) ? campaignsData.campaigns : [];
    state.competitionEvents = Array.isArray(eventsData.events) ? eventsData.events : [];
    state.competitionTasks = Array.isArray(tasksData.tasks) ? tasksData.tasks : [];
    state.competitionLoaded = true;
    renderCompetitionSelectOptions();
    return state.competitionProducts;
  } finally {
    if (isCurrentBusinessScope(scopeKey)) state.competitionLoading = false;
  }
}

function setCompetitionTab(tab = "competitors") {
  state.competitionTab = tab || "competitors";
  competitionTabs.forEach((button) => button.classList.toggle("active", button.dataset.competitionTab === state.competitionTab));
  competitionPanels.forEach((panel) => panel.classList.toggle("hidden", panel.dataset.competitionPanel !== state.competitionTab));
}

function setCompetitionProductView(view = "competitor") {
  state.competitionProductView = view === "product" ? "product" : "competitor";
  competitionProductViewTabs.forEach((button) => button.classList.toggle("active", button.dataset.competitionProductView === state.competitionProductView));
  competitionProductViewPanels.forEach((panel) => panel.classList.toggle("hidden", panel.dataset.competitionProductViewPanel !== state.competitionProductView));
}

