function buildTimelineSeries() {
  const report = state.selectedReport || {};
  const leadBuckets = (state.selectedLeads || []).reduce((acc, item) => {
    const date = item.created_at?.slice(0, 10);
    if (date) acc[date] = (acc[date] || 0) + 1;
    return acc;
  }, {});
  const salesBuckets = (report.sales_by_day || []).reduce((acc, item) => {
    if (item.date) acc[item.date] = toNumber(item.sales);
    return acc;
  }, {});
  const redemptionBuckets = (report.redemptions_by_day || []).reduce((acc, item) => {
    if (item.date) acc[item.date] = toNumber(item.count);
    return acc;
  }, {});
  const dates = Array.from(new Set([
    ...Object.keys(leadBuckets),
    ...Object.keys(salesBuckets),
    ...Object.keys(redemptionBuckets),
  ])).sort();

  return filterByDate(
    dates.map((date) => ({
      date,
      label: formatDateShort(date),
      leads: leadBuckets[date] || 0,
      sales: salesBuckets[date] || 0,
      redemptions: redemptionBuckets[date] || 0,
    })),
    ["date"]
  );
}

function commercialChipClass(status = "") {
  const value = String(status || "").toUpperCase();
  if (["VIP", "BUYER", "RECURRENT", "CONVERTED"].includes(value)) return "ok";
  if (["INTERESTED", "FOLLOW_UP", "CONTACTED"].includes(value)) return "warning";
  if (["INACTIVE", "LOST"].includes(value)) return "danger";
  return "pending";
}

function leadBadges(item = {}) {
  const digitalAssetOrigin = String(item.channel || "").toLowerCase().includes("descarga de activo digital");
  return [
    digitalAssetOrigin ? "Activo digital" : "",
    leadDirectoryIsCustomer(item) ? "Comprador" : "",
    item.active_tickets > 0 ? "Ticket activo" : "",
    item.expired_tickets > 0 ? "Ticket vencido" : "",
    item.inactive_tickets > 0 ? "Ticket no activo" : "",
    item.redeemed_tickets > 0 ? "Redimio" : "",
    item.source_type === "MANUAL" ? "Manual" : "",
  ].filter(Boolean);
}

function leadOriginText(item = {}) {
  const parts = [];
  const channel = String(item.channel || "").trim();
  const campaign = String(item.campaign_name || "").trim();
  const asset = String(item.top_interest || "").trim();
  const jobTitle = String(item.metadata?.manual_job_title || "").trim();
  const importance = String(item.metadata?.manual_importance_reason || "").trim();
  const isDigitalAsset = channel.toLowerCase().includes("descarga de activo digital");
  if (channel) parts.push(channel);
  if (jobTitle) parts.push(`Cargo: ${jobTitle}`);
  if (importance) parts.push(`Clave: ${importance}`);
  if (isDigitalAsset && asset) parts.push(`Activo: ${asset}`);
  if (campaign) parts.push(`Campaña: ${campaign}`);
  return parts.filter((value, index, array) => value && array.indexOf(value) === index).join(" · ") || "Sin origen";
}

function leadTicketInventoryParts(item = {}) {
  return [
    Number(item.active_tickets || 0) ? `${Number(item.active_tickets || 0)} activos` : "",
    Number(item.expired_tickets || 0) ? `${Number(item.expired_tickets || 0)} expirados` : "",
    Number(item.inactive_tickets || 0) ? `${Number(item.inactive_tickets || 0)} no activos` : "",
    Number(item.redeemed_tickets || 0) ? `${Number(item.redeemed_tickets || 0)} redimidos` : "",
  ].filter(Boolean);
}

function leadTicketInventoryText(item = {}) {
  return leadTicketInventoryParts(item).join(" | ") || "Sin tickets";
}

function leadDirectoryMetadata(item = {}) {
  return item.metadata && typeof item.metadata === "object" ? item.metadata : {};
}

function leadDirectoryIsCustomer(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  return metadata.customer_import_declared === true
    || String(metadata.customer_import_declared || "").toLowerCase() === "true"
    || Number(item.purchase_count || item.sales_count || item.purchases_count || 0) > 0
    || Number(item.total_spent || item.sales_total || item.purchase_total || item.sale_amount || 0) > 0
    || Boolean(item.last_purchase_at || item.last_sale_at);
}

function leadDirectoryHasCommercialPotential(item = {}) {
  if (leadDirectoryIsCustomer(item)) return false;
  const metadata = leadDirectoryMetadata(item);
  const status = String(item.commercial_status || item.status || metadata.commercial_status || "").toUpperCase();
  if (["LOST", "DELETED"].includes(status)) return false;
  return Number(item.active_tickets || 0) > 0
    || Number(item.redeemed_tickets || 0) > 0
    || Number(item.activation_count || item.activations_count || 0) > 0
    || Number(item.games_played || item.score_total || item.attention_score || 0) > 0
    || ["HIGH", "MEDIUM"].includes(String(item.care_priority || "").toUpperCase())
    || ["INTERESTED", "FOLLOW_UP", "CONTACTED", "NEW"].includes(status)
    || String(item.source_type || "").toUpperCase() === "MANUAL"
    || Boolean(item.phone || item.email || item.document_id)
    || Boolean(item.campaign_id || item.campaign_name || leadDirectoryCampaign(item) !== "Sin campaña")
    || Boolean(item.channel || item.source || item.attribution_source || metadata.manual_source)
    || Boolean(item.interest || item.top_interest || item.favorite_product || item.purchase_intent || metadata.manual_importance_reason);
}

function leadDirectoryChannel(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  return String(
    item.channel
      || item.attribution_source
      || item.source
      || metadata.manual_source
      || metadata.attribution_source
      || item.source_type
      || "Sin canal"
  ).trim() || "Sin canal";
}

function leadDirectoryCampaign(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  return String(
    item.campaign_name
      || item.attribution_subject
      || metadata.campaign_name
      || metadata.source_campaign
      || metadata.attribution_subject
      || "Sin campaña"
  ).trim() || "Sin campaña";
}

function leadDirectoryContactLine(item = {}) {
  return [item.phone, item.email, item.document_id]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .join(" · ") || "Sin contacto básico";
}

function leadDirectoryActivationCount(item = {}) {
  return Number(item.activation_count || item.activations_count || 0);
}

function leadDirectorySalesSummary(item = {}) {
  const purchaseCount = Number(item.purchase_count || item.sales_count || item.purchases_count || 0);
  const totalSpent = Number(item.total_spent || item.sales_total || item.purchase_total || item.sale_amount || 0);
  const avgTicket = Number(item.avg_ticket || 0);
  const topProduct = String(item.top_product || item.product_name || item.favorite_product || "").trim();
  const topCategory = String(item.top_category || item.product_category || "").trim();
  const lastPurchase = item.last_purchase_at || item.last_sale_at || null;
  if (!purchaseCount && !totalSpent && !lastPurchase) {
    return {
      hasSales: false,
      label: "Sin ventas relacionadas",
      detail: "Aún no hay venta asociada a este contacto.",
      meta: "",
    };
  }
  const displayPurchaseCount = purchaseCount || (lastPurchase ? 1 : 0);
  return {
    hasSales: true,
    label: `${displayPurchaseCount.toLocaleString("es-CO")} venta(s) · ${money(totalSpent)}`,
    detail: [
      topProduct ? `Producto: ${topProduct}` : "",
      topCategory ? `Categoría: ${topCategory}` : "",
      avgTicket ? `Ticket prom.: ${money(avgTicket)}` : "",
    ].filter(Boolean).join(" · ") || "Ventas registradas en el CRM.",
    meta: lastPurchase ? `Última venta ${formatDateShort(lastPurchase)}` : "Sin fecha de última venta",
  };
}

// Debe declararse antes del directorio y del progreso: ambos se inicializan al cargar app.js.
const RMS_FLOW_ORDER = Object.freeze([
  "recoleccion", "alimentacion", "curaduria", "clasificacion", "procesamiento",
  "accion_correctiva", "control_anti_fuga", "cierre", "postventa", "inteligencia",
]);
const RMS_FLOW_INDEX = Object.freeze(Object.fromEntries(RMS_FLOW_ORDER.map((key, index) => [key, index])));
const RMS_FLOW_NEXT_PHASE = Object.freeze({
  recoleccion: "alimentacion", alimentacion: "curaduria", curaduria: "clasificacion",
  clasificacion: "procesamiento", procesamiento: "accion_correctiva", accion_correctiva: "control_anti_fuga",
  control_anti_fuga: "cierre", cierre: "postventa",
});
const RMS_QUALITY_CONTROL_KEYS = ["preprocesamiento", "revenue_generado"];

function rmsFlowIndex(phase = "") {
  return RMS_FLOW_INDEX[phase] ?? Number.MAX_SAFE_INTEGER;
}

function rmsNextPrimaryPhase(phase = "") {
  const start = rmsFlowIndex(phase);
  return RMS_FLOW_ORDER.slice(start + 1).find((key) => !RMS_QUALITY_CONTROL_KEYS.includes(key)) || "";
}

const LEAD_DIRECTORY_RMS_STATIONS = {
  recoleccion: { label: "Estación 01 · Recolección", short: "01 Recolección" },
  alimentacion: { label: "Estación 02 · Alimentación", short: "02 Alimentación" },
  curaduria: { label: "Estación 03 · Curaduría", short: "03 Curaduría" },
  clasificacion: { label: "Estación 04 · Activación 1", short: "04 Activación 1" },
  preprocesamiento: { label: "Tablero auxiliar · Control de calidad 1", short: "Control calidad 1" },
  procesamiento: { label: "Estación 05 · Evaluación", short: "05 Evaluación" },
  accion_correctiva: { label: "Estación 06 · Negociación", short: "06 Negociación" },
  control_anti_fuga: { label: "Estación 07 · Riesgos de fuga", short: "07 Riesgos fuga" },
  cierre: { label: "Estación 08 · Ventas atribuidas", short: "08 Ventas atribuidas" },
  revenue_generado: { label: "Tablero auxiliar · Control de calidad 2", short: "Control calidad 2" },
  postventa: { label: "Estación 09 · Valorización Clientes", short: "09 Valorización" },
  inteligencia: { label: "Estación 10 · Inteligencia GOS", short: "10 Inteligencia GOS" },
};

function leadDirectoryStationInfo(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  const rawPhase = String(
    item.rms_phase
      || item.stage
      || item.rms_stage
      || metadata.rms_phase
      || metadata.stage
      || ""
  ).trim();
  const key = rawPhase.toLowerCase();
  const station = LEAD_DIRECTORY_RMS_STATIONS[key];
  if (station) {
    return {
      key,
      label: station.label,
      short: station.short,
      updated_at: item.rms_phase_updated_at || metadata.rms_phase_updated_at || item.updated_at || item.last_interaction_at || null,
      assigned: true,
    };
  }
  return {
    key: "",
    label: "Sin estación asignada",
    short: "Sin estación",
    updated_at: null,
    assigned: false,
  };
}

function leadDirectoryAffiliateLabel(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  const affiliateValue = item.is_affiliate
    || item.affiliate_id
    || item.affiliate_status
    || item.affiliate_code
    || metadata.is_affiliate
    || metadata.affiliate_id
    || metadata.affiliate_status
    || metadata.affiliate_code;
  return affiliateValue ? "Afiliado" : "No afiliado";
}

function leadDirectorySort(a = {}, b = {}) {
  return Number(b.purchase_count || 0) - Number(a.purchase_count || 0)
    || Number(b.attention_score || 0) - Number(a.attention_score || 0)
    || new Date(b.last_interaction_at || b.updated_at || b.created_at || 0) - new Date(a.last_interaction_at || a.updated_at || a.created_at || 0);
}

function leadDirectoryPriorityScore(item = {}) {
  const value = String(item.care_priority || item.priority || "").toUpperCase();
  if (value === "HIGH") return 3;
  if (value === "MEDIUM") return 2;
  if (value === "LOW") return 1;
  return 0;
}

function leadDirectoryComparableDate(item = {}) {
  return new Date(item.last_interaction_at || item.last_purchase_at || item.last_sale_at || item.updated_at || item.created_at || 0).getTime() || 0;
}

function leadDirectoryNormalize(value = "") {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function leadDirectorySearchHaystack(item = {}) {
  const metadata = leadDirectoryMetadata(item);
  return [
    item.name,
    item.phone,
    item.email,
    item.document_id,
    item.id,
    item.commercial_status,
    item.care_priority,
    item.care_priority_label,
    item.recommended_action,
    item.top_interest,
    item.favorite_product,
    item.purchase_intent,
    item.product_name,
    item.top_product,
    item.top_category,
    leadDirectoryChannel(item),
    leadDirectoryCampaign(item),
    leadDirectoryContactLine(item),
    leadOriginText(item),
    leadTicketInventoryText(item),
    leadDirectoryStationInfo(item).label,
    metadata.manual_job_title,
    metadata.manual_source,
    metadata.manual_importance_reason,
    metadata.commercial_owner_name,
    metadata.commercial_owner_email,
  ].filter(Boolean).join(" ");
}

function leadDirectoryMatchesSearch(item = {}, search = "") {
  const term = leadDirectoryNormalize(search);
  if (!term) return true;
  return leadDirectoryNormalize(leadDirectorySearchHaystack(item)).includes(term);
}

function leadDirectoryMatchesSignal(item = {}, signal = "") {
  const value = String(signal || "");
  if (!value) return true;
  const station = leadDirectoryStationInfo(item);
  const purchaseCount = Number(item.purchase_count || item.sales_count || item.purchases_count || 0);
  const revenue = Number(item.total_spent || item.sales_total || item.purchase_total || item.sale_amount || 0);
  if (value === "active_tickets") return Number(item.active_tickets || 0) > 0;
  if (value === "ticket_issues") return Number(item.expired_tickets || 0) > 0 || Number(item.inactive_tickets || 0) > 0;
  if (value === "activations") return leadDirectoryActivationCount(item) > 0;
  if (value === "without_contact") return !String(item.phone || "").trim() && !String(item.email || "").trim();
  if (value === "manual") return String(item.source_type || "").toUpperCase() === "MANUAL";
  if (value === "affiliate") return leadDirectoryAffiliateLabel(item) === "Afiliado";
  if (value === "high_priority") return leadDirectoryPriorityScore(item) >= 3;
  if (value === "assigned_station") return Boolean(station.assigned);
  if (value === "with_revenue") return purchaseCount > 0 || revenue > 0;
  return true;
}

function leadDirectorySortRows(rows = [], sortKey = "recommended") {
  const sorted = rows.slice();
  sorted.sort((a = {}, b = {}) => {
    if (sortKey === "name") {
      return String(a.name || "").localeCompare(String(b.name || ""), "es", { sensitivity: "base" })
        || leadDirectorySort(a, b);
    }
    if (sortKey === "revenue") {
      return Number(b.total_spent || b.sales_total || b.purchase_total || 0) - Number(a.total_spent || a.sales_total || a.purchase_total || 0)
        || leadDirectorySort(a, b);
    }
    if (sortKey === "activations") {
      return leadDirectoryActivationCount(b) - leadDirectoryActivationCount(a)
        || leadDirectorySort(a, b);
    }
    if (sortKey === "tickets") {
      return Number(b.active_tickets || 0) - Number(a.active_tickets || 0)
        || Number(b.redeemed_tickets || 0) - Number(a.redeemed_tickets || 0)
        || leadDirectorySort(a, b);
    }
    if (sortKey === "priority") {
      return leadDirectoryPriorityScore(b) - leadDirectoryPriorityScore(a)
        || Number(b.attention_score || 0) - Number(a.attention_score || 0)
        || leadDirectorySort(a, b);
    }
    if (sortKey === "recent") {
      return leadDirectoryComparableDate(b) - leadDirectoryComparableDate(a)
        || leadDirectorySort(a, b);
    }
    return leadDirectorySort(a, b);
  });
  return sorted;
}

function leadDirectoryCurrentFilters() {
  if (!state.leadDirectoryFilters || typeof state.leadDirectoryFilters !== "object") {
    state.leadDirectoryFilters = { search: "", signal: "", sort: "recommended" };
  }
  return state.leadDirectoryFilters;
}

function leadDirectoryFilterOptions(audience = leadDirectoryAudience()) {
  const base = [
    ["", "Todas las señales"],
    ["active_tickets", "Ticket activo"],
    ["activations", "Con activaciones"],
    ["assigned_station", "Con estacion RMS"],
    ["affiliate", "Afiliados"],
    ["without_contact", "Sin telefono/correo"],
  ];
  if (audience === "customers") {
    return [
      ["", "Todos los clientes"],
      ["with_revenue", "Con revenue"],
      ["active_tickets", "Ticket activo"],
      ["activations", "Con activaciones"],
      ["affiliate", "Afiliados"],
      ["without_contact", "Sin telefono/correo"],
    ];
  }
  return [
    ...base,
    ["high_priority", "Prioridad alta"],
    ["ticket_issues", "Tickets por revisar"],
    ["manual", "Ingresados manualmente"],
  ];
}

function leadDirectoryFilterOptionMarkup(options = [], selected = "") {
  return options.map(([value, label]) => (
    `<option value="${escapeHtml(value)}" ${String(selected) === String(value) ? "selected" : ""}>${escapeHtml(label)}</option>`
  )).join("");
}

function leadDirectoryFilteredResult(rows = [], audience = leadDirectoryAudience()) {
  const filters = leadDirectoryCurrentFilters();
  const segmentedRows = leadDirectorySegmentRows(rows, audience);
  const filteredRows = segmentedRows
    .filter((item) => leadDirectoryMatchesSearch(item, filters.search))
    .filter((item) => leadDirectoryMatchesSignal(item, filters.signal));
  return {
    baseRows: segmentedRows,
    filteredRows,
    sortedRows: leadDirectorySortRows(filteredRows, filters.sort),
  };
}

function leadDirectoryCardMarkup(item = {}, segment = "lead") {
  const isCustomer = segment === "customer" || leadDirectoryIsCustomer(item);
  const badges = leadBadges(item).slice(0, 2);
  const sales = leadDirectorySalesSummary(item);
  const primarySignal = isCustomer
    ? sales.label
    : (item.recommended_action || item.commercial_status_label || "Revisar oportunidad");
  const secondarySignal = isCustomer
    ? sales.detail
    : leadOriginText(item);
  return `
    <article class="contact-directory-card-row" role="button" tabindex="0" data-lead-id="${escapeHtml(item.id)}" data-source-type="${escapeHtml(item.source_type || "PLAYER")}">
      <div class="contact-directory-name">
        <span>
          <strong>${escapeHtml(item.name || "Contacto sin nombre")}</strong>
          <small>${escapeHtml(leadDirectoryContactLine(item))}</small>
        </span>
        <span class="contact-directory-badges">
          <span class="status-chip ${isCustomer ? "ok" : leadPriorityChipClass(item.care_priority)}">${isCustomer ? "Cliente" : escapeHtml(item.care_priority_label || "Lead")}</span>
          ${badges.map((badge) => `<span class="pill muted">${escapeHtml(badge)}</span>`).join("")}
        </span>
      </div>
      <div class="contact-directory-main">
        <strong>${escapeHtml(primarySignal)}</strong>
        <small>${escapeHtml(secondarySignal)}</small>
      </div>
      <span class="contact-directory-open">Abrir <span class="material-symbols-outlined" aria-hidden="true">open_in_new</span></span>
    </article>
  `;
}

function renderContactDirectoryCards(rows = state.leadCrmRows || []) {
  const directoryCard = document.querySelector(".lead-directory-card");
  if (!directoryCard) return;
  const audienceTabs = document.getElementById("leadDirectoryAudienceTabs");
  let board = document.getElementById("contactDirectoryVisualBoard");
  if (!board) {
    board = document.createElement("section");
    board.id = "contactDirectoryVisualBoard";
    board.className = "contact-directory-visual-board";
    // Las pestañas y los resultados son una sola superficie de trabajo. Insertar
    // el tablero inmediatamente después evita que el encabezado heredado deje
    // una franja vacía entre el selector de audiencia y los datos.
    if (audienceTabs?.parentElement === directoryCard) {
      directoryCard.insertBefore(board, audienceTabs.nextSibling);
    } else {
      directoryCard.prepend(board);
    }
  }
  const allRows = Array.isArray(rows) ? rows : [];
  syncLeadDirectoryAudienceTabs(allRows);
  const customers = allRows.filter(leadDirectoryIsCustomer);
  const leads = allRows.filter(leadDirectoryHasCommercialPotential);
  const audience = leadDirectoryAudience();
  const filters = leadDirectoryCurrentFilters();
  const signalOptions = leadDirectoryFilterOptions(audience);
  if (!signalOptions.some(([value]) => String(value) === String(filters.signal || ""))) {
    filters.signal = "";
  }
  const { baseRows, filteredRows, sortedRows } = leadDirectoryFilteredResult(allRows, audience);
  const activeTicketRows = filteredRows.filter((item) => Number(item.active_tickets || 0) > 0);
  const sortedVisibleRows = sortedRows.slice(0, 24);
  const hasDirectoryFilters = Boolean(String(filters.search || "").trim() || filters.signal);
  const emptyText = audience === "customers"
    ? (hasDirectoryFilters ? "Sin clientes para esta busqueda." : "Sin clientes para los filtros actuales.")
    : (hasDirectoryFilters ? "Sin leads para esta busqueda." : "Sin leads para los filtros actuales.");
  board.innerHTML = `
    <div class="contact-directory-hero">
      <div>
        <h3>${audience === "customers" ? "Clientes" : "Leads"}</h3>
        <p>${audience === "customers" ? "Revisa compradores con venta atribuida, tickets y señales de postventa sin mezclarlos con prospectos." : "Prioriza prospectos con ticket activo, alta intención o datos incompletos antes de pasarlos a agenda o activación."}</p>
      </div>
      <div class="contact-directory-summary" aria-label="Resumen del directorio">
        <span><strong>${filteredRows.length.toLocaleString("es-CO")}</strong> filtrados</span>
        <span><strong>${customers.length.toLocaleString("es-CO")}</strong> clientes</span>
        <span><strong>${leads.length.toLocaleString("es-CO")}</strong> leads</span>
        <span><strong>${activeTicketRows.length.toLocaleString("es-CO")}</strong> tickets activos</span>
      </div>
    </div>
    <section class="contact-directory-toolbar" aria-label="Buscador y filtros del directorio">
      <label class="contact-directory-search-control">
        <span class="material-symbols-outlined" aria-hidden="true">search</span>
        <input id="contactDirectorySearchInput" type="search" value="${escapeHtml(filters.search || "")}" placeholder="Buscar por nombre, telefono, correo, cedula, campaña o canal">
      </label>
      <label class="contact-directory-select-control">
        <span>Filtro</span>
        <select id="contactDirectorySignalFilter">
          ${leadDirectoryFilterOptionMarkup(signalOptions, filters.signal)}
        </select>
      </label>
      <label class="contact-directory-select-control">
        <span>Ordenar</span>
        <select id="contactDirectorySortSelect">
          ${leadDirectoryFilterOptionMarkup([
            ["recommended", "Recomendado"],
            ["recent", "Mas recientes"],
            ["priority", "Prioridad"],
            ["revenue", "Revenue"],
            ["activations", "Activaciones"],
            ["tickets", "Tickets activos"],
            ["name", "Nombre A-Z"],
          ], filters.sort || "recommended")}
        </select>
      </label>
      <button class="ghost-button contact-directory-clear" id="contactDirectoryClearFilters" type="button" ${hasDirectoryFilters || filters.sort !== "recommended" ? "" : "disabled"}>
        Limpiar
      </button>
      <small class="contact-directory-result-note">
        Mostrando ${sortedVisibleRows.length.toLocaleString("es-CO")} de ${filteredRows.length.toLocaleString("es-CO")} coincidencias · ${baseRows.length.toLocaleString("es-CO")} en ${leadDirectoryAudienceLabel(audience).toLowerCase()}.
      </small>
    </section>
    <div class="contact-directory-list-head" aria-hidden="true">
      <span>Contacto</span>
      <span>Oportunidad</span>
      <span></span>
    </div>
    <div class="contact-directory-list contact-directory-unified-list">
      ${sortedVisibleRows.length
        ? sortedVisibleRows.map((item) => leadDirectoryCardMarkup(item, audience === "customers" ? "customer" : "lead")).join("")
        : `<div class="empty-state compact">${escapeHtml(emptyText)}</div>`}
    </div>
  `;
  board.querySelectorAll("[data-lead-id]").forEach((card) => {
    const open = () => openLeadDetail({
      id: card.dataset.leadId,
      source_type: card.dataset.sourceType || "PLAYER",
    });
    card.addEventListener("click", open);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        open();
      }
    });
  });
  bindContactDirectoryControls(board);
}

function bindContactDirectoryControls(board) {
  const filters = leadDirectoryCurrentFilters();
  const rerender = (focusId = "", selectionStart = null) => {
    renderContactDirectoryCards(state.leadCrmRows || []);
    if (!focusId) return;
    requestAnimationFrame(() => {
      const target = document.getElementById(focusId);
      if (!target) return;
      target.focus();
      if (target instanceof HTMLInputElement && Number.isFinite(selectionStart)) {
        target.setSelectionRange(selectionStart, selectionStart);
      }
    });
  };
  const searchInput = board.querySelector("#contactDirectorySearchInput");
  const signalFilter = board.querySelector("#contactDirectorySignalFilter");
  const sortSelect = board.querySelector("#contactDirectorySortSelect");
  const clearButton = board.querySelector("#contactDirectoryClearFilters");
  searchInput?.addEventListener("input", () => {
    filters.search = searchInput.value;
    rerender("contactDirectorySearchInput", searchInput.selectionStart);
  });
  signalFilter?.addEventListener("change", () => {
    filters.signal = signalFilter.value;
    rerender("contactDirectorySignalFilter");
  });
  sortSelect?.addEventListener("change", () => {
    filters.sort = sortSelect.value || "recommended";
    rerender("contactDirectorySortSelect");
  });
  clearButton?.addEventListener("click", () => {
    filters.search = "";
    filters.signal = "";
    filters.sort = "recommended";
    rerender("contactDirectorySearchInput", 0);
  });
}

