function setDefaultLeadAgendaReminderIfEmpty() {
  if (!leadAgendaReminderInput || leadAgendaReminderInput.value) return;
  const nextHour = new Date();
  nextHour.setHours(nextHour.getHours() + 1, 0, 0, 0);
  leadAgendaReminderInput.value = datetimeLocalValue(nextHour);
}

function openLeadAgendaCreateModal(options = {}) {
  if (!leadAgendaCreateModal) return;
  ensureLeadAgendaCreateModalStyles();
  if (leadAgendaCreateModal.parentElement !== document.body) {
    document.body.appendChild(leadAgendaCreateModal);
  }
  renderLeadAgendaLeadOptions();
  renderLeadAgendaCampaignOptions();
  setDefaultLeadAgendaReminderIfEmpty();
  document.body.classList.add("lead-agenda-modal-open");
  leadAgendaCreateModal.classList.remove("hidden");
  leadAgendaCreateModal.removeAttribute("aria-hidden");
  const focusTarget = options.focusTarget || leadAgendaActionInput || leadAgendaScopeInput;
  window.setTimeout(() => {
    focusTarget?.focus?.({ preventScroll: true });
  }, 80);
}

function closeLeadAgendaCreateModal() {
  if (!leadAgendaCreateModal) return;
  leadAgendaCreateModal.classList.add("hidden");
  leadAgendaCreateModal.setAttribute("aria-hidden", "true");
  document.body.classList.remove("lead-agenda-modal-open");
  leadAgendaOpenCreateButton?.focus?.({ preventScroll: true });
}

async function createAgendaItemFromForm(event) {
  event.preventDefault();
  const leadRef = parseAgendaLeadValue(leadAgendaLeadInput?.value || "");
  const scope = String(leadAgendaScopeInput?.value || "").toUpperCase();
  const campaign = selectedAgendaCampaign();
  const reminderValue = leadAgendaReminderInput?.value || "";
  const nextAction = String(leadAgendaActionInput?.value || "").trim();
  const noteDetail = String(leadAgendaNoteInput?.value || "").trim();
  const progress = Math.max(0, Math.min(100, Number(leadAgendaProgressInput?.value || 0)));
  if (!scope) {
    showFeedback("Elige un alcance o usa Sin alcance / tarea interna.", "error");
    return;
  }
  if (scope === "CONTACT" && !leadRef.id) {
    showFeedback("Selecciona contacto o cambia el alcance a campaña, marketing o activación.", "error");
    return;
  }
  if (!reminderValue || !nextAction) {
    showFeedback("Completa alcance, acción y fecha para crear la tarea.", "error");
    return;
  }
  try {
    const result = await api("/api/business/leads/agenda", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        lead_id: scope === "CONTACT" ? leadRef.id : null,
        source_id: scope === "CONTACT" || scope === "GENERAL" ? null : campaign?.id || null,
        source_type: agendaSourceTypeForScope(scope, leadRef.source_type || "PLAYER"),
        note: noteDetail || nextAction,
        note_type: "follow_up",
        next_action: nextAction,
        reminder_at: agendaScheduledDateIso(reminderValue),
        agenda_priority: leadAgendaPriorityInput?.value || "MEDIUM",
        progress_percent: progress,
        checklist: agendaChecklistItems(leadAgendaChecklistInput?.value || ""),
        metadata: agendaOperationalPayloadFromFields(null, reminderValue),
      }),
    });
    if (result?.item?.id) {
      const createdItem = result.item;
      state.leadAgenda = [
        createdItem,
        ...(state.leadAgenda || []).filter((item) => String(item.id) !== String(createdItem.id)),
      ];
      state.leadAgendaLoaded = true;
      state.leadAgendaAnchorDate = dateInputValue(result.item.reminder_at || reminderValue);
      state.leadAgendaStatus = "OPEN";
      renderLeadAgenda();
    }
    leadAgendaActionInput.value = "";
    leadAgendaNoteInput.value = "";
    if (leadAgendaScopeInput) leadAgendaScopeInput.value = "";
    if (leadAgendaCampaignInput) leadAgendaCampaignInput.value = "";
    if (leadAgendaPriorityInput) leadAgendaPriorityInput.value = "MEDIUM";
    if (leadAgendaActivityTypeInput) leadAgendaActivityTypeInput.value = "TASK";
    if (leadAgendaMeetingModeInput) leadAgendaMeetingModeInput.value = "";
    if (leadAgendaMeetingPlatformInput) leadAgendaMeetingPlatformInput.value = "";
    if (leadAgendaMeetingUrlInput) leadAgendaMeetingUrlInput.value = "";
    if (leadAgendaMeetingAddressInput) leadAgendaMeetingAddressInput.value = "";
    if (leadAgendaProgressInput) leadAgendaProgressInput.value = "0";
    if (leadAgendaChecklistInput) leadAgendaChecklistInput.value = "";
    const nextHour = new Date();
    nextHour.setHours(nextHour.getHours() + 1, 0, 0, 0);
    leadAgendaReminderInput.value = datetimeLocalValue(nextHour);
    await refreshLeadAgendaAfterMutation({ anchorDate: result?.item?.reminder_at || reminderValue, status: "OPEN", preserveItem: result?.item || null });
    closeLeadAgendaCreateModal();
    showFeedback("Tarea creada en la agenda.", "success");
  } catch (error) {
    showFeedback(error.message || "No se pudo crear la tarea.", "error");
  }
}

function moveLeadAgendaAnchor(direction = 1) {
  const current = startOfLocalDay(state.leadAgendaAnchorDate || new Date());
  if (state.leadAgendaView === "year") current.setFullYear(current.getFullYear() + direction);
  else if (state.leadAgendaView === "month") current.setMonth(current.getMonth() + direction);
  else if (state.leadAgendaView === "week") current.setDate(current.getDate() + (7 * direction));
  else if (state.leadAgendaView === "board" || state.leadAgendaView === "list") current.setDate(current.getDate() + (30 * direction));
  else current.setDate(current.getDate() + direction);
  state.leadAgendaAnchorDate = dateInputValue(current);
  state.leadAgendaLoaded = false;
  loadLeadAgendaData({ force: true, quiet: true }).then(renderLeadAgenda);
}

function appendIfFound(parent, node) {
  if (parent && node && node.parentElement !== parent) parent.appendChild(node);
}

const CONTACT_CENTER_TAB_KEYS = ["overview", "directory", "tickets", "agenda", "captures", "manual", "sales"];
const CONTACT_CENTER_VISIBLE_TAB_KEYS = ["directory", "manual", "agenda"];

function normalizeContactCenterTab(tab = "directory") {
  const requested = CONTACT_CENTER_TAB_KEYS.includes(tab) ? tab : "directory";
  return CONTACT_CENTER_VISIBLE_TAB_KEYS.includes(requested) ? requested : "directory";
}

