function mountContactCenterLayout() {
  if (state.contactCenterMounted) return;
  const contactCenterShell = document.getElementById("contactCenterShell");
  ensureContactDirectoryUxStyles();
  if (contactCenterShell) contactCenterShell.dataset.contactDirectoryUx = "simple";
  document.querySelectorAll('[data-contact-center-tab="directory"]').forEach((button) => {
    button.hidden = false;
    button.removeAttribute("hidden");
  });
  const overviewPanel = document.querySelector('[data-contact-center-panel="overview"]');
  const directoryPanel = document.querySelector('[data-contact-center-panel="directory"]');
  const ticketsPanel = document.querySelector('[data-contact-center-panel="tickets"]');
  const agendaPanel = document.querySelector('[data-contact-center-panel="agenda"]');
  const capturesPanel = document.querySelector('[data-contact-center-panel="captures"]');
  const manualPanel = document.querySelector('[data-contact-center-panel="manual"]');
  const salesPanel = document.querySelector('[data-contact-center-panel="sales"]');
  if (!overviewPanel || !directoryPanel || !ticketsPanel || !agendaPanel || !capturesPanel || !manualPanel || !salesPanel) return;

  appendIfFound(overviewPanel, leadFeedKpiGrid);
  appendIfFound(overviewPanel, leadAttentionBoard);

  const directoryCard = document.querySelector(".lead-directory-card");
  const audienceTabs = document.getElementById("leadDirectoryAudienceTabs");
  // El selector de Clientes/Leads pertenece al directorio; antes se movía al
  // panel padre y dejaba una columna vacía a su derecha. Se conserva junto a
  // la lista para que ambos ocupen el mismo ancho.
  appendIfFound(directoryCard, audienceTabs);
  appendIfFound(directoryPanel, directoryCard);

  appendIfFound(ticketsPanel, leadTicketInventoryBoard);

  appendIfFound(agendaPanel, leadAgendaCard);

  appendIfFound(capturesPanel, leadCaptureForm?.closest("article"));
  appendIfFound(capturesPanel, leadCaptureTable?.closest("article"));

  appendIfFound(manualPanel, document.getElementById("manualContactsDirectoryCard"));
  appendIfFound(manualPanel, manualLeadForm?.closest("article"));

  // La ficha debe vivir en el body: así el fixed cubre toda la aplicación y no
  // queda limitado por el shell desplazable del directorio.
  appendIfFound(document.body, leadDetailModal);
  // La entrega de ticket debe vivir fuera del directorio para no quedar recortada.
  appendIfFound(document.body, leadActivationModal);

  keepAgendaFocusedOnTasks();

  state.contactCenterMounted = true;
}

// Agenda solo debe contener trabajo programado. Estas dos tablas pertenecen a
// sus flujos de origen (Directorio y Campañas) y, si una versión anterior del
// markup las deja dentro de Agenda, duplican información y vuelven la pantalla
// inmanejable. Se retiran únicamente cuando están anidadas en Agenda.
function keepAgendaFocusedOnTasks() {
  const agendaPanel = document.querySelector('[data-contact-center-panel="agenda"]');
  if (!agendaPanel) return;

  [
    document.getElementById("leadFeedCard"),
    document.getElementById("campaignLeadsCard"),
    leadFeedTable?.closest("article"),
    campaignLeadsTable?.closest("article"),
  ].filter(Boolean).forEach((card) => {
    if (agendaPanel.contains(card)) card.remove();
  });
}

