function leadDetailAgendaRows(detail = {}) {
  const lead = detail.lead || {};
  return (detail.notes || [])
    .filter((item) => item.reminder_at)
    .map((item) => ({
      ...item,
      lead_name: lead.name || item.lead_name || "Contacto",
      lead_email: lead.email || item.lead_email || null,
      lead_phone: lead.phone || item.lead_phone || null,
      lead_company: lead.organization || lead.metadata?.manual_company || item.lead_company || null,
      campaign_name: item.campaign_name || lead.campaign_name || item.metadata?.campaign_name || null,
      agenda_status: item.agenda_status || "OPEN",
      agenda_priority: item.agenda_priority || "MEDIUM",
      progress_percent: Number(item.progress_percent || 0),
      checklist: Array.isArray(item.checklist) ? item.checklist : [],
    }))
    .sort((a, b) => new Date(a.reminder_at || 0) - new Date(b.reminder_at || 0));
}

function renderLeadDetailAgenda(detail = {}) {
  const rows = leadDetailAgendaRows(detail);
  const openRows = rows.filter((item) => String(item.agenda_status || "OPEN").toUpperCase() === "OPEN");
  const doneRows = rows.filter((item) => String(item.agenda_status || "").toUpperCase() === "DONE");
  const overdueRows = openRows.filter((item) => new Date(item.reminder_at).getTime() < Date.now() && dateInputValue(item.reminder_at) !== dateInputValue(new Date()));
  return `
    <section class="lead-client-agenda">
      <div class="lead-client-agenda-head">
        <div>
          <span class="mono-label">Tareas del cliente</span>
          <strong>${openRows.length.toLocaleString("es-CO")} pendiente(s)</strong>
          <small>${doneRows.length.toLocaleString("es-CO")} hecha(s) · ${overdueRows.length.toLocaleString("es-CO")} vencida(s)</small>
        </div>
        <button class="ghost-button" type="button" data-lead-create-task>Crear tarea</button>
      </div>
      <div class="lead-agenda-list">
        ${rows.length ? rows.map((item) => agendaCardMarkup(item)).join("") : '<div class="empty-state compact">Este cliente no tiene tareas agendadas.</div>'}
      </div>
    </section>
  `;
}

function renderLeadDetailPendingAgendaSnapshot(detail = {}) {
  const pendingRows = leadDetailAgendaRows(detail)
    .filter((item) => String(item.agenda_status || "OPEN").toUpperCase() === "OPEN");
  const visibleRows = pendingRows.slice(0, 4);
  return `
    <section class="lead-pending-agenda-snapshot">
      <div class="lead-client-agenda-head">
        <div>
          <span class="mono-label">Agenda pendiente</span>
          <strong>${pendingRows.length.toLocaleString("es-CO")} tarea(s) por hacer</strong>
          <small>Seguimientos abiertos para este contacto.</small>
        </div>
        <button class="ghost-button" type="button" data-open-lead-tasks>Ver agenda completa</button>
      </div>
      <div class="lead-agenda-list">
        ${visibleRows.length ? visibleRows.map((item) => agendaCardMarkup(item)).join("") : '<div class="empty-state compact">Este contacto no tiene tareas pendientes de agenda.</div>'}
      </div>
    </section>
  `;
}

function renderLeadDetailRelatedSalesSnapshot(detail = {}) {
  const purchases = Array.isArray(detail.purchases) ? detail.purchases : [];
  const visiblePurchases = purchases.slice(0, 4);
  const totalSpent = purchases.reduce((sum, item) => sum + Number(item.sale_amount || 0), 0);
  return `
    <section class="lead-related-sales-snapshot">
      <div class="lead-client-agenda-head">
        <div>
          <span class="mono-label">Ventas relacionadas</span>
          <strong>${purchases.length.toLocaleString("es-CO")} venta(s) · ${money(totalSpent)}</strong>
          <small>Compras asociadas a este cliente por documento, teléfono, correo, QR o vínculo CRM.</small>
        </div>
        <button class="ghost-button" type="button" data-lead-tab-shortcut="purchases">Ver ventas completas</button>
      </div>
      <div class="lead-agenda-list">
        ${visiblePurchases.length ? visiblePurchases.map((item) => `
          <article class="lead-detail-item">
            <strong>${escapeHtml(item.product_name || "Venta registrada")}</strong>
            <span>${money(item.sale_amount || 0)} · ${formatDate(item.created_at)}</span>
            <small>${escapeHtml(item.campaign_name || item.acquisition_source || "Sin campaña")} · ${escapeHtml(item.branch_name || "Sin sucursal")} ${item.notes ? `· ${escapeHtml(item.notes)}` : ""}</small>
          </article>
        `).join("") : '<div class="empty-state compact">Este contacto aún no tiene ventas relacionadas.</div>'}
      </div>
    </section>
  `;
}

async function saveCommunicationEmailConnection({ removeApiKey = false } = {}) {
  const senderName = optionalInputValue(accountCommunicationSenderNameInput);
  const senderEmail = optionalInputValue(accountCommunicationSenderEmailInput);
  const resendApiKey = String(accountCommunicationResendKeyInput?.value || "").trim();
  if (!senderName || !senderEmail) {
    setInlineMessage(accountCommunicationConnectionMessage, "Completa el nombre y email del remitente antes de conectar Resend.", "error");
    return null;
  }
  if (!removeApiKey && !resendApiKey && !state.communicationEmailConnection?.api_key_configured) {
    setInlineMessage(accountCommunicationConnectionMessage, "Pega la API Key de Resend para completar la conexión.", "error");
    return null;
  }
  setButtonLoading(accountCommunicationConnectButton, true, "Guardando...");
  try {
    const data = await api("/api/business/communications/email-connection", {
      method: "PATCH",
      headers: authHeaders(),
      body: JSON.stringify({
        sender_name: senderName,
        sender_email: senderEmail,
        resend_api_key: removeApiKey ? "" : resendApiKey,
        remove_api_key: removeApiKey,
      }),
    });
    state.communicationEmailConnection = data;
    state.communicationEmailConnectionLoaded = true;
    state.businessProfile = {
      ...(state.businessProfile || {}),
      communication_sender_name: data.sender_name || senderName,
      communication_sender_email: data.sender_email || senderEmail,
    };
    if (accountCommunicationResendKeyInput) accountCommunicationResendKeyInput.value = "";
    renderCommunicationEmailConnection();
    setInlineMessage(accountCommunicationConnectionMessage, removeApiKey ? "Conexión eliminada. No se enviarán campañas hasta conectar una nueva clave." : "Conexión guardada. Envía una prueba antes de hacer un envío masivo.", "success");
    return data;
  } catch (error) {
    setInlineMessage(accountCommunicationConnectionMessage, error.message || "No se pudo guardar la conexión de Resend.", "error");
    return null;
  } finally {
    setButtonLoading(accountCommunicationConnectButton, false);
  }
}

async function testCommunicationEmailConnection() {
  const recipientEmail = optionalInputValue(accountCommunicationTestEmailInput);
  if (!recipientEmail) {
    setInlineMessage(accountCommunicationConnectionMessage, "Escribe el correo donde quieres recibir la prueba.", "error");
    return;
  }
  setButtonLoading(accountCommunicationTestButton, true, "Enviando...");
  try {
    const data = await api("/api/business/communications/email-connection/test", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({ recipient_email: recipientEmail }),
    });
    setInlineMessage(accountCommunicationConnectionMessage, `Prueba enviada a ${data.recipient_email}. Revisa también spam o promociones.`, "success");
    showFeedback("El correo de prueba fue aceptado por Resend.", "success", { title: "Conexión de correo" });
  } catch (error) {
    setInlineMessage(accountCommunicationConnectionMessage, error.message || "La prueba no pudo enviarse. Revisa la clave y el dominio en Resend.", "error");
  } finally {
    setButtonLoading(accountCommunicationTestButton, false);
  }
}

