async function openRewardPassCreateModal() {
  if (!rewardPassCreateModal) return;
  if (rewardPassCreateModal.parentElement !== document.body) document.body.appendChild(rewardPassCreateModal);
  state.rewardPassIssuanceKey = createRewardPassOperationKey("reward-pass-issue");
  renderRewardPassBranchOptions();
  if (!state.businessBranchesLoaded) {
    try {
      await loadBusinessBranches({ quiet: true });
    } catch (error) {
      state.businessBranchesLoadError = error.message || "No fue posible cargar las sedes.";
    }
  }
  renderRewardPassBranchOptions();
  setRewardPassDefaults();
  renderRewardPassContext();
  renderRewardPassPreview(null);
  rewardPassCreateModal.classList.remove("hidden");
  rewardPassValueInput?.focus?.({ preventScroll: true });
}

function closeRewardPassCreateModal() {
  rewardPassCreateModal?.classList.add("hidden");
  state.rewardPassIssuanceKey = "";
}

async function retryRewardPassBranches() {
  state.businessBranchesLoaded = false;
  state.businessBranchesLoadError = "";
  renderRewardPassBranchOptions();
  try {
    await loadBusinessBranches({ force: true, quiet: true });
  } catch (error) {
    state.businessBranchesLoadError = error.message || "No fue posible cargar las sedes.";
  }
  renderRewardPassBranchOptions();
}

function openBranchesFromRewardPass() {
  closeRewardPassCreateModal();
  setView("branches");
}

function rewardPassDefaultExpiry() {
  const date = new Date();
  date.setMonth(date.getMonth() + 12);
  return formatInputDateTime(date.toISOString());
}

function setRewardPassDefaults() {
  if (rewardPassIssuedAtInput && !rewardPassIssuedAtInput.value) {
    rewardPassIssuedAtInput.value = formatInputDateTime(new Date().toISOString());
  }
  if (rewardPassExpiresAtInput && !rewardPassExpiresAtInput.value) {
    rewardPassExpiresAtInput.value = rewardPassDefaultExpiry();
  }
  if (rewardPassTermsInput && !rewardPassTermsInput.value && state.rewardPassContext?.default_terms) {
    rewardPassTermsInput.value = state.rewardPassContext.default_terms;
  }
  renderRewardPassCampaignOptions();
  renderRewardPassBranchOptions();
}

function renderRewardPassCampaignOptions() {
  if (!rewardPassCampaignInput) return;
  const options = ['<option value="">Sin campaña asociada</option>']
    .concat((state.campaigns || []).map((campaign) => `<option value="${escapeHtml(campaign.id)}">${escapeHtml(campaign.name || campaign.slug || campaign.id)}</option>`));
  rewardPassCampaignInput.innerHTML = options.join("");
}

function renderRewardPassContext() {
  const context = state.rewardPassContext?.context || state.rewardPassContext || {};
  const cost = toNumber(context.reward_pass_ticket_cost || 1);
  const balance = toNumber(context.ticket_balance || context.qr_balance || 0);
  if (rewardPassTicketContext) {
    rewardPassTicketContext.textContent = `Costo de emision: ${cost} ticket${cost === 1 ? "" : "s"} Qori. Saldo actual: ${balance.toLocaleString("es-CO")} tickets.`;
  }
}

async function loadRewardPasses() {
  const scopeKey = businessScopeKey();
  const queryParams = new URLSearchParams();
  const statusFilter = rewardPassStatusFilter?.value || "";
  if (statusFilter) queryParams.set("status", statusFilter);
  const search = rewardPassSearchInput?.value.trim() || "";
  if (search) queryParams.set("search", search);
  if (rewardPassBranchFilter?.value) queryParams.set("branch_id", rewardPassBranchFilter.value);
  const pagination = state.rewardPassPagination || { limit: 50, offset: 0 };
  queryParams.set("limit", String(pagination.limit || 50));
  queryParams.set("offset", String(pagination.offset || 0));
  state.rewardPassLoading = true;
  state.rewardPassError = "";
  const data = await api(`/api/business/reward-passes?${queryParams.toString()}`, { headers: authHeaders() });
  if (!isCurrentBusinessScope(scopeKey)) return false;
  state.rewardPasses = data.reward_passes || [];
  state.rewardPassMetrics = data.metrics || null;
  state.rewardPassPagination = data.pagination || { total: state.rewardPasses.length, limit: 50, offset: 0, has_more: false };
  state.rewardPassContext = {
    ...(state.rewardPassContext || {}),
    context: data.context || data.reward_pass_context || data.context,
  };
  if (!state.selectedRewardPassId && state.rewardPasses[0]) {
    state.selectedRewardPassId = state.rewardPasses[0].id;
  }
  state.rewardPassLoading = false;
  return true;
}

async function loadRewardPassContext() {
  const scopeKey = businessScopeKey();
  const data = await api("/api/business/reward-passes/context", { headers: authHeaders() });
  if (!isCurrentBusinessScope(scopeKey)) return false;
  state.rewardPassContext = data || {};
  renderRewardPassContext();
  setRewardPassDefaults();
  return true;
}

function renderRewardPassMetrics() {
  const metrics = state.rewardPassMetrics || {};
  const cards = [
    ["Emitidos", toNumber(metrics.issued_count || 0), `${toNumber(metrics.active_count || 0)} activos`],
    ["Valor emitido", money(metrics.total_issued_cop || 0), "Obligacion comercial del emisor"],
    ["Valor redimido", money(metrics.total_redeemed_cop || 0), `${toNumber(metrics.redemption_count || 0)} redenciones`],
    ["Saldo pendiente", money(metrics.pending_balance_cop || 0), `${toNumber(metrics.partially_redeemed_count || 0)} parciales`],
    ["Saldo vencido", money(metrics.expired_balance_cop || 0), `${toNumber(metrics.expired_count || 0)} vencidos`],
    ["Tickets consumidos", toNumber(metrics.tickets_consumed || 0), "Derecho tecnologico Qori"],
  ];
  if (rewardPassKpiGrid) {
    rewardPassKpiGrid.innerHTML = cards.map(([label, value, meta]) => `
      <article class="kpi-card">
        <span class="mono-label">${escapeHtml(label)}</span>
        <strong>${escapeHtml(value)}</strong>
        <div class="kpi-meta">${escapeHtml(meta)}</div>
      </article>
    `).join("");
  }
}

function renderRewardPassInsight() {
  if (!rewardPassInsight) return;
  const metrics = state.rewardPassMetrics || {};
  const pending = toNumber(metrics.pending_claim_count || 0);
  const expiring = toNumber(metrics.expiring_soon_count || 0);
  const title = pending ? `${pending} por activar` : expiring ? `${expiring} vencen pronto` : "La operación está al día";
  const copy = pending ? "Comparte el enlace y el PIN desde la ficha." : expiring ? "Envía recordatorios antes del vencimiento." : "No detectamos activaciones pendientes ni vencimientos próximos.";
  rewardPassInsight.innerHTML = `<span class="material-symbols-outlined" aria-hidden="true">${pending ? "lock_clock" : expiring ? "schedule" : "verified"}</span><div><strong>${escapeHtml(title)}</strong><p>${escapeHtml(copy)}</p></div>`;
}

function renderRewardPassPreview(pass = state.selectedRewardPass) {
  const isPending = !pass || pass.status === "pending_claim";
  const beneficiary = pass?.beneficiary_name || rewardPassBeneficiaryNameInput?.value || "Beneficiario por activar";
  if (rewardPassPreviewTitle) rewardPassPreviewTitle.textContent = pass ? pass.public_code : "Vista previa";
  if (rewardPassPreviewValue) rewardPassPreviewValue.textContent = isPending ? "ACTIVACION" : "GIFT CARD OFICIAL";
  if (rewardPassPreviewBeneficiary) rewardPassPreviewBeneficiary.textContent = isPending ? "Escanea para reclamar el QR definitivo" : beneficiary;
  if (rewardPassPreviewMeta) {
    const branchLabel = pass ? rewardPassAuthorizedBranchLabel(pass) : selectedRewardPassBranchLabel();
    rewardPassPreviewMeta.textContent = pass
      ? (isPending ? `Sede autorizada: ${branchLabel}. Comparte el enlace y el PIN de activación.` : `Sede autorizada: ${branchLabel}. QR redimible listo para validador.`)
      : `Sede autorizada: ${branchLabel}. El QR aparecerá después de emitir el Reward Pass.`;
  }
  [rewardPassDownloadImageButton, rewardPassDownloadPdfButton, rewardPassReceiptButton].forEach((button) => {
    if (button) button.disabled = !pass;
  });
}

function rewardPassUsedValue(pass = {}) {
  return Math.max(toNumber(pass.initial_value_cop || 0) - toNumber(pass.current_balance_cop || 0), 0);
}

function rewardPassBuyerContact(pass = {}) {
  return [pass.buyer_phone, pass.buyer_email, pass.buyer_document].filter(Boolean).join(" · ") || "Sin contacto";
}

function filteredRewardPassRows() {
  const filter = rewardPassStatusFilter?.value || "";
  return filterRows(state.rewardPasses || [], [
    "public_code",
    "buyer_name",
    "buyer_phone",
    "buyer_email",
    "buyer_document",
    "beneficiary_name",
    "beneficiary_document",
    "beneficiary_phone",
    "beneficiary_email",
    "status",
  ]).filter((pass) => {
    if (filter === "used") return rewardPassUsedValue(pass) > 0;
    if (filter === "with_balance") return toNumber(pass.current_balance_cop || 0) > 0 && !["cancelled", "expired", "fully_redeemed"].includes(pass.status);
    if (REWARD_PASS_BACKEND_STATUS_FILTERS.has(filter)) return String(pass.status || "") === filter;
    return true;
  });
}

function rewardPassStatusBreakdown(rows = []) {
  return rows.reduce((acc, pass) => {
    const label = rewardPassStatusLabel(pass.status);
    acc[label] = (acc[label] || 0) + 1;
    return acc;
  }, {});
}

function renderRewardPassCharts(rows = filteredRewardPassRows()) {
  if (!rewardPassChartGrid) return;
  const totalIssued = rows.reduce((sum, pass) => sum + toNumber(pass.initial_value_cop || 0), 0);
  const totalUsed = rows.reduce((sum, pass) => sum + rewardPassUsedValue(pass), 0);
  const totalBalance = rows.reduce((sum, pass) => sum + toNumber(pass.current_balance_cop || 0), 0);
  const financialRows = [
    ["Comprado", totalIssued],
    ["Usado", totalUsed],
    ["Saldo", totalBalance],
  ];
  const maxMoneyValue = Math.max(1, ...financialRows.map((row) => row[1]));
  const statusRows = Object.entries(rewardPassStatusBreakdown(rows)).sort((a, b) => b[1] - a[1]);
  const maxStatusValue = Math.max(1, ...statusRows.map((row) => row[1]));
  const barRows = (items, max, formatter = (value) => value) => items.map(([label, value]) => `
    <div class="reward-pass-bar-row">
      <span><strong>${escapeHtml(label)}</strong><em>${escapeHtml(formatter(value))}</em></span>
      <div class="reward-pass-bar-track"><i style="--bar-width:${Math.max(4, Math.min(100, (Number(value || 0) / max) * 100))}%"></i></div>
    </div>
  `).join("");
  rewardPassChartGrid.innerHTML = `
    <article class="reward-pass-chart-card">
      <div>
        <span class="mono-label">Valores</span>
        <h3>Comprado, usado y saldo</h3>
      </div>
      <div class="reward-pass-bar-list">${barRows(financialRows, maxMoneyValue, money)}</div>
    </article>
    <article class="reward-pass-chart-card">
      <div>
        <span class="mono-label">Estado de giftcards</span>
        <h3>Uso y vigencia</h3>
      </div>
      <div class="reward-pass-bar-list">${statusRows.length ? barRows(statusRows, maxStatusValue, (value) => Number(value || 0).toLocaleString("es-CO")) : '<div class="empty-state compact">Sin giftcards para graficar.</div>'}</div>
    </article>
  `;
}

function renderRewardPassTableLegacy() {
  if (!rewardPassTable) return;
  const rows = filteredRewardPassRows();
  rewardPassTable.innerHTML = rows.map((item) => {
    return `
    <tr class="${item.id === state.selectedRewardPassId ? "active" : ""}">
      <td>
        <button class="link-button reward-pass-table-main" type="button" data-rp-view="${escapeHtml(item.id)}">
          <strong>${escapeHtml(item.public_code)}</strong>
          <small>${escapeHtml(item.public_url ? "Ver detalle" : "Sin link público")}</small>
        </button>
      </td>
      <td><strong>${escapeHtml(item.buyer_name || "-")}</strong><div class="reward-pass-table-contact">${escapeHtml(rewardPassBuyerContact(item))}</div></td>
      <td><strong>${escapeHtml(item.beneficiary_name || "-")}</strong><div class="reward-pass-table-contact">${escapeHtml([item.beneficiary_phone, item.beneficiary_email, item.beneficiary_document].filter(Boolean).join(" · ") || "Puede activarlo después")}</div></td>
      <td>${escapeHtml(money(item.current_balance_cop || 0))}</td>
      <td><span class="status-chip ${rewardPassStatusClass(item.status)}">${escapeHtml(rewardPassStatusLabel(item.status))}</span></td>
      <td>
        <div class="reward-pass-table-actions">
          <button class="ghost-button compact" type="button" data-rp-view="${escapeHtml(item.id)}">Ver</button>
        </div>
      </td>
    </tr>
  `;
  }).join("") || '<tr><td colspan="6">Todavía no hay giftcards emitidas.</td></tr>';

  rewardPassTable.querySelectorAll("[data-rp-view]").forEach((button) => {
    button.addEventListener("click", () => selectRewardPass(button.dataset.rpView));
  });
}

function renderRewardPassTable() {
  if (!rewardPassTable) return;
  const rows = filteredRewardPassRows();
  if (state.rewardPassLoading) {
    rewardPassTable.innerHTML = '<tr><td colspan="7"><div class="empty-state compact">Cargando Reward Pass…</div></td></tr>';
    if (rewardPassMobileCards) rewardPassMobileCards.innerHTML = '<div class="empty-state compact">Cargando Reward Pass…</div>';
    return;
  }
  if (state.rewardPassError) {
    rewardPassTable.innerHTML = `<tr><td colspan="7"><div class="empty-state compact"><strong>No pudimos cargar Reward Pass</strong><p>${escapeHtml(state.rewardPassError)}</p><button class="ghost-button compact" type="button" data-rp-retry>Reintentar</button></div></td></tr>`;
    if (rewardPassMobileCards) rewardPassMobileCards.innerHTML = `<div class="empty-state compact"><strong>No pudimos cargar Reward Pass</strong><p>${escapeHtml(state.rewardPassError)}</p></div>`;
  } else {
    rewardPassTable.innerHTML = rows.map((item) => `
      <tr class="${item.id === state.selectedRewardPassId ? "active" : ""}">
        <td><button class="link-button reward-pass-table-main" type="button" data-rp-view="${escapeHtml(item.id)}"><strong>${escapeHtml(item.public_code)}</strong><small>Ver ficha</small></button></td>
        <td><strong>${escapeHtml(item.buyer_name || "-")}</strong><div class="reward-pass-table-contact">${escapeHtml(rewardPassBuyerContact(item))}</div></td>
        <td><strong>${escapeHtml(item.beneficiary_name || "Pendiente")}</strong><div class="reward-pass-table-contact">${escapeHtml(item.beneficiary_document || "Por activar")}</div></td>
        <td>${escapeHtml(money(item.current_balance_cop || 0))}</td>
        <td><span class="status-chip ${rewardPassStatusClass(item.status)}">${escapeHtml(rewardPassStatusLabel(item.status))}</span></td>
        <td><strong>${escapeHtml(formatDateShort(item.expires_at))}</strong><div class="reward-pass-table-contact">${escapeHtml(rewardPassAuthorizedBranchLabel(item))}</div></td>
        <td><button class="ghost-button compact" type="button" data-rp-view="${escapeHtml(item.id)}">Abrir</button></td>
      </tr>
    `).join("") || '<tr><td colspan="7"><div class="empty-state compact">Sin Reward Pass para estos filtros.</div></td></tr>';
    if (rewardPassMobileCards) rewardPassMobileCards.innerHTML = rows.map((item) => `
      <article class="reward-pass-mobile-card">
        <div class="reward-pass-mobile-card-head"><div><strong>${escapeHtml(item.public_code)}</strong><small>${escapeHtml(item.beneficiary_name || "Pendiente de activar")}</small></div><span class="status-chip ${rewardPassStatusClass(item.status)}">${escapeHtml(rewardPassStatusLabel(item.status))}</span></div>
        <div class="reward-pass-mobile-card-grid"><div><span>Saldo</span><strong>${escapeHtml(money(item.current_balance_cop || 0))}</strong></div><div><span>Sede</span><strong>${escapeHtml(rewardPassAuthorizedBranchLabel(item))}</strong></div></div>
        <div class="reward-pass-mobile-card-actions"><button class="solid-button compact" type="button" data-rp-view="${escapeHtml(item.id)}">Abrir ficha</button></div>
      </article>
    `).join("") || '<div class="empty-state compact">Sin Reward Pass para estos filtros.</div>';
  }
  const pagination = state.rewardPassPagination || { total: rows.length, limit: 50, offset: 0, has_more: false };
  const total = toNumber(pagination.total || rows.length);
  const page = Math.floor(toNumber(pagination.offset || 0) / Math.max(1, toNumber(pagination.limit || 50))) + 1;
  const pages = Math.max(1, Math.ceil(total / Math.max(1, toNumber(pagination.limit || 50))));
  if (rewardPassResultCount) rewardPassResultCount.textContent = `${total} Reward Pass`;
  if (rewardPassPageLabel) rewardPassPageLabel.textContent = `Página ${page} de ${pages}`;
  if (rewardPassPrevPageButton) rewardPassPrevPageButton.disabled = toNumber(pagination.offset || 0) <= 0;
  if (rewardPassNextPageButton) rewardPassNextPageButton.disabled = !pagination.has_more;
  [rewardPassTable, rewardPassMobileCards].filter(Boolean).forEach((root) => root.querySelectorAll("[data-rp-view]").forEach((button) => button.addEventListener("click", () => selectRewardPass(button.dataset.rpView))));
  rewardPassTable.querySelector("[data-rp-retry]")?.addEventListener("click", renderRewardPassesView);
}

function renderRewardPassDetail() {
  const pass = state.selectedRewardPass;
  if (!pass) {
    if (rewardPassDetailTitle) rewardPassDetailTitle.textContent = "Sin Reward Pass seleccionado";
    if (rewardPassDetailGrid) rewardPassDetailGrid.innerHTML = '<p class="table-secondary">Selecciona un Reward Pass del listado.</p>';
    if (rewardPassRedemptionTable) rewardPassRedemptionTable.innerHTML = '<tr><td colspan="9">Sin historial.</td></tr>';
    if (rewardPassTicketLedgerTable) rewardPassTicketLedgerTable.innerHTML = '<tr><td colspan="5">Sin movimientos.</td></tr>';
    renderRewardPassPreview(null);
    return;
  }
  if (rewardPassDetailTitle) rewardPassDetailTitle.textContent = `${pass.public_code} - ${pass.beneficiary_name}`;
  if (rewardPassDetailGrid) {
    const details = [
      ["Empresa emisora", pass.company?.name || "-"],
      ["Comprador", `${pass.buyer_name || "-"} / ${pass.buyer_document || "-"}`],
      ["Beneficiario", `${pass.beneficiary_name || "-"} / ${pass.beneficiary_document || "-"}`],
      ["Valor inicial", money(pass.initial_value_cop)],
      ["Saldo disponible", money(pass.current_balance_cop)],
      ["Estado", rewardPassStatusLabel(pass.status)],
      ["Vigencia", formatDate(pass.expires_at)],
      ["Sede autorizada", rewardPassAuthorizedBranchLabel(pass)],
      ["Condiciones", pass.partial_redemption_allowed ? "Permite redenciones parciales" : "De un solo uso"],
      ["Link público", pass.public_url || "-"],
    ];
    rewardPassDetailGrid.innerHTML = details.map(([label, value]) => `
      <div class="reward-pass-detail-item">
        <span>${escapeHtml(label)}</span>
        <strong>${escapeHtml(value)}</strong>
      </div>
    `).join("");
  }
  if (rewardPassRedemptionTable) {
    rewardPassRedemptionTable.innerHTML = (pass.redemptions || []).map((item) => {
      const purchaseValue = Number(item.purchase_value_cop || 0);
      const redeemedValue = Number(item.redeemed_value_cop || 0);
      const customerDifference = Math.max(purchaseValue - redeemedValue, 0);
      return `
        <tr>
          <td>${escapeHtml(item.invoice_number || "-")}</td>
          <td>${escapeHtml(purchaseValue ? money(purchaseValue) : "-")}</td>
          <td>${escapeHtml(money(redeemedValue))}</td>
          <td>${escapeHtml(customerDifference ? money(customerDifference) : "-")}</td>
          <td>${escapeHtml(money(item.balance_before_cop || 0))}</td>
          <td>${escapeHtml(money(item.balance_after_cop || 0))}</td>
          <td>${escapeHtml(item.branch || "-")}</td>
          <td>${escapeHtml(item.cashier_name || "-")}</td>
          <td>${escapeHtml(formatDate(item.redeemed_at))}</td>
        </tr>
      `;
    }).join("") || '<tr><td colspan="9">Sin redenciones registradas.</td></tr>';
  }
  if (rewardPassTicketLedgerTable) {
    rewardPassTicketLedgerTable.innerHTML = (pass.ticket_transactions || []).map((item) => `
      <tr>
        <td>${escapeHtml(item.tickets_debited)}</td>
        <td>${escapeHtml(item.balance_before)}</td>
        <td>${escapeHtml(item.balance_after)}</td>
        <td>${escapeHtml(item.transaction_type)}</td>
        <td>${escapeHtml(formatDate(item.created_at))}</td>
      </tr>
    `).join("") || '<tr><td colspan="5">Sin movimientos de tickets.</td></tr>';
  }
  renderRewardPassPreview(pass);
}

function ensureRewardPassDetailModal() {
  let modal = document.getElementById("rewardPassDetailModal");
  if (modal) return modal;
  modal = document.createElement("section");
  modal.id = "rewardPassDetailModal";
  modal.className = "modal-shell hidden reward-pass-detail-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "rewardPassDetailModalTitle");
  document.body.appendChild(modal);
  modal.addEventListener("click", (event) => {
    if (event.target === modal || event.target.closest("[data-rp-detail-close]")) modal.classList.add("hidden");
  });
  return modal;
}

function renderRewardPassDetailModal() {
  const pass = state.selectedRewardPass;
  if (!pass) return;
  const modal = ensureRewardPassDetailModal();
  const hasClaim = pass.status !== "pending_claim" && Boolean(pass.beneficiary_name && pass.beneficiary_document);
  const initialValue = Number(pass.initial_value_cop || 0);
  const currentBalance = Number(pass.current_balance_cop || 0);
  const redeemedValue = Math.max(initialValue - currentBalance, 0);
  const redemptionRows = Array.isArray(pass.redemptions) ? pass.redemptions : [];
  const ticketRows = Array.isArray(pass.ticket_transactions) ? pass.ticket_transactions : [];
  const reminderPhone = String(pass.beneficiary_phone || pass.buyer_phone || "").replace(/\D/g, "");
  const activationPin = String(pass.security_pin || "");
  const reminderTarget = pass.beneficiary_name || pass.buyer_name || "la persona beneficiaria";
  const reminderText = hasClaim
    ? `Hola ${reminderTarget}, te recordamos que tu giftcard ${pass.public_code} tiene un saldo disponible de ${money(pass.current_balance_cop || 0)}. Puedes usarla antes del ${formatDateShort(pass.expires_at)}.`
    : `Hola ${reminderTarget}, tu giftcard ${pass.public_code} está pendiente de activación. Completa los datos del beneficiario para revelar y usar el valor: ${pass.public_url || ""}`;
  const whatsappUrl = reminderPhone ? `https://wa.me/${reminderPhone}?text=${encodeURIComponent(reminderText)}` : "";
  modal.innerHTML = `
    <article class="modal-card reward-pass-detail-modal-card">
      <div class="modal-head reward-pass-detail-head">
        <div>
          <span class="mono-label">Giftcard emitida</span>
          <h3 id="rewardPassDetailModalTitle">${escapeHtml(pass.public_code)}</h3>
          <p>${escapeHtml(pass.campaign_name || "Sin campaña asociada")}</p>
        </div>
        <button class="icon-button" type="button" data-rp-detail-close aria-label="Cerrar detalle"><span class="material-symbols-outlined">close</span></button>
      </div>
      <div class="reward-pass-detail-summary">
        <div><span>Valor emitido</span><strong>${escapeHtml(money(initialValue))}</strong></div>
        <div><span>Redimido</span><strong>${escapeHtml(money(redeemedValue))}</strong></div>
        <div class="reward-pass-balance-summary"><span>Saldo disponible</span><strong>${escapeHtml(money(currentBalance))}</strong></div>
        <div><span>Estado</span><strong><span class="status-chip ${rewardPassStatusClass(pass.status)}">${escapeHtml(rewardPassStatusLabel(pass.status))}</span></strong></div>
        <div><span>Vence</span><strong>${escapeHtml(formatDateShort(pass.expires_at))}</strong></div>
      </div>
      <div class="reward-pass-detail-people">
        <section><span class="mono-label">Comprador</span><strong>${escapeHtml(pass.buyer_name || "Sin registrar")}</strong><p>${escapeHtml([pass.buyer_document, pass.buyer_phone, pass.buyer_email].filter(Boolean).join(" · ") || "Sin datos adicionales")}</p></section>
        <section><span class="mono-label">Beneficiario</span><strong>${escapeHtml(pass.beneficiary_name || "Pendiente de registro")}</strong><p>${escapeHtml([pass.beneficiary_document, pass.beneficiary_phone, pass.beneficiary_email].filter(Boolean).join(" · ") || "Completará sus datos al activar la giftcard")}</p></section>
      </div>
      <section class="reward-pass-reveal-status ${hasClaim ? "is-revealed" : "is-pending"}">
        <span class="material-symbols-outlined" aria-hidden="true">${hasClaim ? "verified" : "lock"}</span>
        <div><strong>${hasClaim ? "Valor revelado" : "Valor pendiente de revelar"}</strong><p>${hasClaim ? "El beneficiario completó sus datos; la giftcard puede utilizarse según su vigencia." : "El valor solo se revela cuando el beneficiario completa el formulario con sus datos."}</p></div>
      </section>
      <section class="reward-pass-detail-security" aria-label="Seguridad de activación">
        <div><span class="mono-label">Seguridad del beneficiario</span><strong>${hasClaim ? "Activación completada" : "PIN de activación"}</strong>${hasClaim ? "" : `<code>${escapeHtml(activationPin || "------")}</code>`}</div>
        ${hasClaim ? '<span class="status-chip ok">Identidad vinculada</span>' : '<button class="ghost-button compact" type="button" data-rp-copy-pin>Copiar PIN y enlace</button>'}
      </section>
      <section class="reward-pass-history-panel" aria-label="Historial de la giftcard">
        <div class="reward-pass-history-heading">
          <div>
            <span class="mono-label">Trazabilidad comercial</span>
            <h4>Historial de saldo y redenciones</h4>
          </div>
          <span class="status-chip ${redemptionRows.length ? "ok" : "pending"}">${escapeHtml(`${redemptionRows.length} ${redemptionRows.length === 1 ? "movimiento" : "movimientos"}`)}</span>
        </div>
        <div class="reward-pass-history-list">
          <article class="reward-pass-history-row reward-pass-history-issue">
            <span class="material-symbols-outlined" aria-hidden="true">add_card</span>
            <div><strong>Gift Card emitida</strong><p>${escapeHtml(formatDate(pass.issued_at || pass.created_at))}${pass.payment_method_received ? ` · ${escapeHtml(pass.payment_method_received)}` : ""}</p></div>
            <strong>${escapeHtml(money(initialValue))}</strong>
          </article>
          ${redemptionRows.map((item) => `
            <article class="reward-pass-history-row">
              <span class="material-symbols-outlined" aria-hidden="true">shopping_bag</span>
              <div>
                <strong>Redención ${escapeHtml(item.invoice_number ? `· ${item.invoice_number}` : "registrada")}</strong>
                <p>${escapeHtml(formatDate(item.redeemed_at))}${item.branch ? ` · ${escapeHtml(item.branch)}` : ""}${item.cashier_name ? ` · ${escapeHtml(item.cashier_name)}` : ""}</p>
                <small>Saldo: ${escapeHtml(money(item.balance_before_cop || 0))} → ${escapeHtml(money(item.balance_after_cop || 0))}</small>
              </div>
              <strong>-${escapeHtml(money(item.redeemed_value_cop || 0))}</strong>
            </article>
          `).join("") || '<p class="reward-pass-history-empty">Aún no hay redenciones. El saldo total sigue disponible hasta que venza o se anule la Gift Card.</p>'}
        </div>
      </section>
      <section class="reward-pass-admin-panel" aria-label="Datos operativos de la giftcard">
        <div><span>Permite saldo parcial</span><strong>${pass.partial_redemption_allowed ? "Sí" : "No, es de un solo uso"}</strong></div>
        <div><span>Sede autorizada</span><strong>${escapeHtml(rewardPassAuthorizedBranchLabel(pass))}</strong></div>
        <div><span>Movimientos Qori</span><strong>${escapeHtml(`${ticketRows.length} ${ticketRows.length === 1 ? "registro" : "registros"}`)}</strong></div>
      </section>
      <div class="modal-actions reward-pass-detail-actions">
        <button class="ghost-button" type="button" data-rp-detail-close>Cerrar</button>
        <button class="ghost-button" type="button" data-rp-copy-link>Copiar enlace</button>
        <button class="ghost-button" type="button" data-rp-download="pdf">PDF</button>
        <button class="ghost-button" type="button" data-rp-download="receipt">Comprobante</button>
        ${!["cancelled", "fully_redeemed"].includes(pass.status) ? '<button class="ghost-button" type="button" data-rp-extend>Prorrogar</button>' : ""}
        ${redemptionRows.length === 0 && !["cancelled", "fully_redeemed"].includes(pass.status) ? '<button class="ghost-button danger" type="button" data-rp-cancel>Anular</button>' : ""}
        ${whatsappUrl ? `<a class="solid-button" href="${escapeHtml(whatsappUrl)}" target="_blank" rel="noopener"><span class="material-symbols-outlined" aria-hidden="true">chat</span> Recordar por WhatsApp</a>` : '<span class="table-secondary">Agrega un celular para enviar recordatorios por WhatsApp.</span>'}
      </div>
    </article>
  `;
  modal.classList.remove("hidden");
  modal.querySelector("[data-rp-copy-pin]")?.addEventListener("click", () => copyRewardPassActivation(pass));
  modal.querySelector("[data-rp-copy-link]")?.addEventListener("click", () => copyRewardPassLink(pass.public_url));
  modal.querySelectorAll("[data-rp-download]").forEach((button) => button.addEventListener("click", () => downloadSelectedRewardPassPdf(button.dataset.rpDownload).catch((error) => showFeedback(error.message, "error"))));
  modal.querySelector("[data-rp-extend]")?.addEventListener("click", () => extendSelectedRewardPass(pass.id));
  modal.querySelector("[data-rp-cancel]")?.addEventListener("click", () => cancelSelectedRewardPass(pass.id));
}

async function selectRewardPass(id) {
  if (!id) return;
  const scopeKey = businessScopeKey();
  state.selectedRewardPassId = id;
  showFeedback("Cargando detalle del Reward Pass.", "loading", { title: "Reward Pass", timeout: 0 });
  try {
    const data = await api(`/api/business/reward-passes/${encodeURIComponent(id)}`, { headers: authHeaders() });
    if (!isCurrentBusinessScope(scopeKey) || state.selectedRewardPassId !== id) return;
    state.selectedRewardPass = data.reward_pass;
    renderRewardPassTable();
    renderRewardPassDetail();
    renderRewardPassDetailModal();
    showFeedback("Detalle de Reward Pass cargado.");
  } catch (error) {
    if (!isCurrentBusinessScope(scopeKey) || state.selectedRewardPassId !== id) return;
    showFeedback(error.message, "error");
  }
}

async function renderRewardPassesView() {
  const scopeKey = businessScopeKey();
  ensureRewardPassUxStyles();
  renderRewardPassContext();
  setRewardPassDefaults();
  state.rewardPassLoading = true;
  renderRewardPassTable();
  try {
    if (!state.businessBranchesLoaded) {
      try {
        await loadBusinessBranches({ quiet: true });
      } catch (branchError) {
        state.businessBranchesLoadError = branchError.message || "No fue posible cargar las sedes.";
      }
      if (!isCurrentBusinessScope(scopeKey)) return;
      renderRewardPassBranchOptions();
    }
    if (!state.rewardPassContext?.default_terms) {
      const contextLoaded = await loadRewardPassContext();
      if (contextLoaded === false || !isCurrentBusinessScope(scopeKey)) return;
    }
    const passesLoaded = await loadRewardPasses();
    if (passesLoaded === false || !isCurrentBusinessScope(scopeKey)) return;
    state.rewardPassError = "";
    renderRewardPassMetrics();
    renderRewardPassInsight();
    renderRewardPassCharts();
    renderRewardPassTable();
  } catch (error) {
    if (!isCurrentBusinessScope(scopeKey)) return;
    state.rewardPassLoading = false;
    state.rewardPassError = error.message || "No pudimos cargar Reward Pass.";
    state.rewardPasses = [];
    renderRewardPassTable();
  }
}

function rewardPassPayload() {
  const beneficiaryName = rewardPassBeneficiaryNameInput?.value.trim();
  const beneficiaryDocument = rewardPassBeneficiaryDocumentInput?.value.trim();
  const beneficiaryPhone = rewardPassBeneficiaryPhoneInput?.value.trim();
  const beneficiaryEmail = rewardPassBeneficiaryEmailInput?.value.trim();
  const branchSelection = rewardPassBranchInput?.value || "";
  if (rewardPassBranchInput?.disabled || !branchSelection) {
    throw new Error("Selecciona Todas las Sedes o una sede activa antes de emitir el Reward Pass.");
  }
  const allBranches = branchSelection === REWARD_PASS_ALL_BRANCHES_VALUE;
  const payload = {
    campaign_id: rewardPassCampaignInput?.value || null,
    initial_value_cop: Number(rewardPassValueInput?.value || 0),
    buyer_name: rewardPassBuyerNameInput?.value.trim(),
    buyer_document: rewardPassBuyerDocumentInput?.value.trim() || null,
    buyer_phone: rewardPassBuyerPhoneInput?.value.trim() || null,
    buyer_email: rewardPassBuyerEmailInput?.value.trim() || null,
    issued_at: rewardPassIssuedAtInput?.value ? new Date(rewardPassIssuedAtInput.value).toISOString() : null,
    expires_at: rewardPassExpiresAtInput?.value ? new Date(rewardPassExpiresAtInput.value).toISOString() : null,
    authorized_branch_id: allBranches ? null : branchSelection,
    branch_authorization_scope: allBranches ? REWARD_PASS_ALL_BRANCHES_VALUE : "SPECIFIC_BRANCH",
    payment_method_received: rewardPassPaymentMethodInput?.value.trim() || null,
    partial_redemption_allowed: Boolean(rewardPassPartialInput?.checked),
    transferable: Boolean(rewardPassTransferableInput?.checked),
    terms: rewardPassTermsInput?.value.trim() || null,
    internal_notes: rewardPassNotesInput?.value.trim() || null,
    idempotency_key: state.rewardPassIssuanceKey || (state.rewardPassIssuanceKey = createRewardPassOperationKey("reward-pass-issue")),
  };
  if (beneficiaryName) payload.beneficiary_name = beneficiaryName;
  if (beneficiaryDocument) payload.beneficiary_document = beneficiaryDocument;
  if (beneficiaryPhone) payload.beneficiary_phone = beneficiaryPhone;
  if (beneficiaryEmail) payload.beneficiary_email = beneficiaryEmail;
  return payload;
}

async function submitRewardPass(event) {
  event.preventDefault();
  setInlineMessage(rewardPassCreateMessage, "Emitiendo Reward Pass y descontando tickets...", "info");
  setButtonLoading(rewardPassCreateButton, true, "Emitiendo...");
  showFeedback("Emitiendo Reward Pass con transacción atómica de tickets.", "loading", { title: "Reward Pass", timeout: 0 });
  try {
    const data = await api("/api/business/reward-passes", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify(rewardPassPayload()),
    });
    state.selectedRewardPassId = data.reward_pass?.id;
    state.selectedRewardPass = data.reward_pass;
    const createdId = data.reward_pass?.id;
    state.rewardPassIssuanceKey = "";
    rewardPassCreateForm?.reset();
    setRewardPassDefaults();
    await loadRewardPassContext();
    await renderRewardPassesView();
    closeRewardPassCreateModal();
    setInlineMessage(rewardPassCreateMessage, data.message || "Reward Pass emitido correctamente.", "success");
    showFeedback(data.message || "Reward Pass emitido correctamente.", "success", { title: "Reward Pass emitido" });
    if (createdId) await selectRewardPass(createdId);
  } catch (error) {
    setInlineMessage(rewardPassCreateMessage, error.message, "error");
    showFeedback(error.message, "error", { title: "No se pudo emitir" });
  } finally {
    setButtonLoading(rewardPassCreateButton, false);
  }
}

async function copyRewardPassLink(link) {
  if (!link) return;
  await navigator.clipboard?.writeText(link);
  showFeedback("Link público del Reward Pass copiado.");
}

async function copyRewardPassActivation(pass = state.selectedRewardPass) {
  if (!pass?.public_url) return;
  const content = `Reward Pass ${pass.public_code}\nEnlace: ${pass.public_url}\nPIN de activación: ${pass.security_pin || "-"}`;
  await navigator.clipboard?.writeText(content);
  showFeedback("Enlace y PIN de activación copiados.", "success", { title: "Reward Pass" });
}

async function extendSelectedRewardPass(id) {
  const pass = state.selectedRewardPass;
  if (!id || !pass) return;
  const current = new Date(pass.expires_at || Date.now());
  current.setMonth(current.getMonth() + 3);
  const value = window.prompt("Nueva fecha de vencimiento (AAAA-MM-DD)", current.toISOString().slice(0, 10));
  if (!value) return;
  try {
    await api(`/api/business/reward-passes/${encodeURIComponent(id)}/extend`, {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({ expires_at: new Date(`${value}T23:59:59`).toISOString(), notes: "Vigencia prorrogada desde Reward Pass." }),
    });
    await renderRewardPassesView();
    await selectRewardPass(id);
    showFeedback("Vigencia prorrogada correctamente.", "success");
  } catch (error) {
    showFeedback(error.message, "error", { title: "No se pudo prorrogar" });
  }
}

function openRewardPassWhatsapp(id) {
  const pass = state.rewardPasses.find((item) => item.id === id) || state.selectedRewardPass;
  if (!pass) return;
  const phone = String(pass.beneficiary_phone || pass.buyer_phone || "").replace(/\D/g, "");
  const greeting = pass.beneficiary_name ? `Hola ${pass.beneficiary_name},` : "Hola,";
  const message = encodeURIComponent(`${greeting} te comparto un Reward Pass de ${pass.company?.name || "nuestro negocio"}. Escanea el QR o abre este enlace para activar tu Gift Card Digital oficial: ${pass.public_url}`);
  window.open(`https://wa.me/${phone || ""}?text=${message}`, "_blank", "noopener");
}

async function cancelSelectedRewardPass(id) {
  if (!window.confirm("Solo puedes anular Reward Pass sin redenciones. Deseas continuar?")) return;
  try {
    await api(`/api/business/reward-passes/${encodeURIComponent(id)}/cancel`, {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({ notes: "Anulado desde portal empresa." }),
    });
    await renderRewardPassesView();
    showFeedback("Reward Pass anulado correctamente.");
  } catch (error) {
    showFeedback(error.message, "error");
  }
}

async function downloadSelectedRewardPassPdf(kind = "pdf") {
  const pass = state.selectedRewardPass;
  if (!pass) return;
  const endpoint = kind === "receipt"
    ? `/api/business/reward-passes/${encodeURIComponent(pass.id)}/acquisition-receipt.pdf`
    : `/api/business/reward-passes/${encodeURIComponent(pass.id)}/pdf`;
  const response = await fetch(endpoint, { headers: authHeaders() });
  const blob = await response.blob();
  if (!response.ok) {
    const text = await blob.text().catch(() => "");
    throw new Error(text || "No se pudo descargar el PDF.");
  }
  triggerBlobDownload(blob, kind === "receipt" ? `comprobante-${pass.public_code}.pdf` : `${pass.public_code}.pdf`);
}

async function buildRewardPassImageDataUrl(pass) {
  if (!pass) return "";
  const canvas = document.createElement("canvas");
  canvas.width = 1200;
  canvas.height = 720;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#071017";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = "#e8c170";
  ctx.lineWidth = 8;
  ctx.strokeRect(42, 42, 1116, 636);
  ctx.fillStyle = "#ffffff";
  ctx.font = "700 74px Inter, sans-serif";
  ctx.fillText("REWARD PASS", 90, 140);
  ctx.fillStyle = "#e8c170";
  ctx.font = "500 30px Inter, sans-serif";
  ctx.fillText("Gift Card Digital", 94, 184);
  ctx.fillStyle = "#ffffff";
  ctx.font = "700 42px Inter, sans-serif";
  ctx.fillText(pass.company?.name || "Empresa emisora", 94, 248);
  ctx.fillStyle = "#ffd783";
  ctx.font = "800 62px Inter, sans-serif";
  ctx.fillText(pass.status === "pending_claim" ? "ACTIVAR GIFT CARD" : "GIFT CARD OFICIAL", 94, 338);
  ctx.fillStyle = "#d7e2eb";
  ctx.font = "500 28px Inter, sans-serif";
  ctx.fillText(`Beneficiario: ${pass.beneficiary_name || "Pendiente de activación"}`, 94, 406);
  ctx.fillText(`Documento: ${pass.beneficiary_document || "Se solicita al activar"}`, 94, 448);
  ctx.fillText(`Codigo: ${pass.public_code}`, 94, 490);
  ctx.fillText(`Vigencia: ${formatDate(pass.expires_at)}`, 94, 532);
  ctx.font = "500 22px Inter, sans-serif";
  const pending = pass.status === "pending_claim";
  ctx.fillText(pending ? "Escanea este QR para reclamar y activar el QR definitivo redimible en caja." : "Presenta este QR junto con tu documento de identidad en el negocio emisor.", 94, 608);
  ctx.fillText("Administrado por Qori GOS Portal.", 94, 642);
  if (pass.qr_image_data_url) {
    const qrImage = await new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = pass.qr_image_data_url;
    });
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(795, 198, 330, 330);
    ctx.drawImage(qrImage, 805, 208, 310, 310);
  }
  ctx.fillStyle = "#d7e2eb";
  ctx.font = "500 22px Inter, sans-serif";
  ctx.fillText(pass.partial_redemption_allowed ? "Permite redenciones parciales." : "De un solo uso.", 790, 575);
  return canvas.toDataURL("image/png");
}

async function downloadSelectedRewardPassImage() {
  const pass = state.selectedRewardPass;
  if (!pass) return;
  const dataUrl = await buildRewardPassImageDataUrl(pass);
  downloadDataUrl(`${pass.public_code}.png`, dataUrl);
  showFeedback("Reward Pass descargado como imagen PNG.");
}

