function rmsFactoryStages(data = {}) {
  const serverStages = Array.isArray(data.stages) && data.stages.length ? data.stages : [];
  const operations = data.operations || {};
  const source = serverStages.length ? serverStages : RMS_FACTORY_STAGE_BLUEPRINT;
  return [...source].sort((left, right) => rmsFlowIndex(left.key) - rmsFlowIndex(right.key)).map((stage) => {
    const blueprint = RMS_FACTORY_STAGE_BLUEPRINT.find((item) => item.key === stage.key) || {};
    const mergedOperation = {
      ...(blueprint.operation || {}),
      ...(operations[stage.key] || {}),
      ...(stage.operation || {}),
      nextPhase: RMS_FLOW_NEXT_PHASE[stage.key] || stage.operation?.nextPhase || operations[stage.key]?.nextPhase || blueprint.operation?.nextPhase,
    };
    return {
      ...blueprint,
      ...stage,
      label: blueprint.label || stage.label,
      short_label: blueprint.short_label || stage.short_label || blueprint.label || stage.label,
      storageLabel: blueprint.storageLabel || stage.storageLabel,
      operation: mergedOperation,
    };
  });
}

async function loadChannelEfforts(options = {}) {
  if (!session?.user?.business_id) {
    state.acquisitionChannelEfforts = [];
    state.acquisitionChannelEffortTotals = null;
    state.acquisitionChannelEffortsLoaded = true;
    state.acquisitionChannelEffortsLoading = false;
    return [];
  }
  if (state.acquisitionChannelEffortsLoaded && !options.force) return state.acquisitionChannelEfforts;
  if (state.acquisitionChannelEffortsLoading) return state.acquisitionChannelEfforts;
  state.acquisitionChannelEffortsLoading = true;
  const scopeKey = businessScopeKey();
  try {
    const period = acquisitionReportingPeriod();
    const params = new URLSearchParams({ start_date: period.start, end_date: period.end });
    const data = await apiSafe(`/api/business/channel-efforts?${params.toString()}`, { headers: authHeaders() }, { efforts: [], totals: null });
    if (!isCurrentBusinessScope(scopeKey)) return state.acquisitionChannelEfforts;
    state.acquisitionChannelEfforts = Array.isArray(data.efforts) ? data.efforts : [];
    state.acquisitionChannelEffortTotals = data.totals || null;
    state.acquisitionChannelEffortsLoaded = true;
    return state.acquisitionChannelEfforts;
  } finally {
    if (isCurrentBusinessScope(scopeKey)) state.acquisitionChannelEffortsLoading = false;
  }
}

function acquisitionReportingPeriod() {
  const toIsoDate = (date) => {
    const local = new Date(date.getTime() - (date.getTimezoneOffset() * 60000));
    return local.toISOString().slice(0, 10);
  };
  const end = state.acquisitionDateEnd || toIsoDate(new Date());
  const startDate = new Date(`${end}T12:00:00`);
  startDate.setDate(startDate.getDate() - 29);
  const start = state.acquisitionDateStart || toIsoDate(startDate);
  state.acquisitionDateStart = start;
  state.acquisitionDateEnd = end;
  return { start, end };
}

function acquisitionPercent(value, total) {
  return total > 0 ? Math.round((Number(value || 0) / Number(total)) * 100) : 0;
}

function acquisitionCsvCell(value) {
  return `"${String(value ?? "").replace(/"/g, '""')}"`;
}

function exportAcquisitionReport() {
  const period = acquisitionReportingPeriod();
  const headers = ["Medio", "Atracción", "Atribución", "Fuente", "Vistas", "Leads", "Completadas", "Descargas", "QR", "Redenciones", "Ventas", "Revenue", "Inversión", "ROI", "Desde", "Hasta"];
  const rows = (state.acquisitionChannelEfforts || []).map((effort) => {
    const metrics = effort.metrics || {};
    return [effort.channel_name, effort.title, metrics.attribution_quality === "EXACT_LINK" ? "Exacta" : "Estimada", effort.interactive_activation_name || effort.lead_capture_activation_name || effort.digital_asset_name || "Histórica", metrics.views || 0, metrics.leads || 0, metrics.completions || 0, metrics.downloads || 0, metrics.qr_generated || 0, metrics.redemptions || 0, metrics.sales || 0, metrics.revenue || 0, metrics.investment || effort.budget_amount || 0, metrics.roi ?? "", effort.starts_at || effort.published_at || "", effort.ends_at || ""];
  });
  const csv = `\uFEFF${[headers, ...rows].map((row) => row.map(acquisitionCsvCell).join(";")).join("\r\n")}`;
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const link = document.createElement("a");
  link.href = url;
  link.download = `medios-adquisicion-${period.start}-${period.end}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

function effortDateRangeLabel(effort = {}) {
  const start = effort.starts_at || effort.published_at;
  const end = effort.ends_at;
  if (!start && !end) return "-";
  if (start && end) return `${formatDate(start)} - ${formatDate(end)}`;
  return formatDate(start || end);
}

function renderAcquisitionAttributionBoard(rows = []) {
  if (!acquisitionAttributionBoard) return;
  const exactCount = rows.filter((item) => item.metrics?.attribution_quality === "EXACT_LINK").length;
  const exactRevenue = rows.reduce((sum, item) => sum + (item.metrics?.attribution_quality === "EXACT_LINK" ? Number(item.metrics?.revenue || 0) : 0), 0);
  const exactLeads = rows.reduce((sum, item) => sum + (item.metrics?.attribution_quality === "EXACT_LINK" ? Number(item.metrics?.leads || 0) : 0), 0);
  const totalRevenue = Number(state.acquisitionChannelTotals?.revenue || 0);
  const revenueGap = Math.max(totalRevenue - exactRevenue, 0);
  const coverage = acquisitionPercent(exactCount, rows.length);
  const period = acquisitionReportingPeriod();
  const channels = (state.acquisitionChannels || []).filter((channel) => channel.id && channel.status !== "ARCHIVED");
  const channelCards = channels.map((channel) => {
    const channelEfforts = rows.filter((effort) => effort.channel_id === channel.id);
    const metrics = acquisitionChannelPortfolioMetrics(channel, channelEfforts);
    const linked = channelEfforts.filter((effort) => effort.metrics?.attribution_quality === "EXACT_LINK").length;
    const investment = Number(metrics.investment || channel.period_budget || 0);
    return `<article class="acq-channel-card">
      <div class="acq-card-head"><div><span class="mono-label">${escapeHtml(channel.platform || acquisitionChannelTypeLabel(channel.channel_type))}</span><h4>${escapeHtml(channel.name || "Medio")}</h4></div><span class="status-chip ${channel.status === "ACTIVE" ? "ok" : "pending"}">${escapeHtml(acquisitionChannelStatusLabel(channel.status))}</span></div>
      <div class="acq-channel-score"><strong>${escapeHtml(channelRoiLabel(metrics.roi))}</strong><span>ROI del medio</span></div>
      <dl><div><dt>Revenue</dt><dd>${escapeHtml(money(metrics.revenue || 0))}</dd></div><div><dt>Inversión</dt><dd>${escapeHtml(money(investment))}</dd></div><div><dt>Ventas</dt><dd>${Number(metrics.sales || 0)}</dd></div><div><dt>Leads</dt><dd>${Number(metrics.leads || 0)}</dd></div></dl>
      <div class="acq-progress"><span><b>${linked}</b> de ${channelEfforts.length} atracciones exactas</span><i><b style="width:${acquisitionPercent(linked, channelEfforts.length)}%"></b></i></div>
      <div class="acq-card-actions"><button class="solid-button compact" type="button" data-channel-insights="${escapeHtml(channel.id)}">Ver análisis</button><button class="ghost-button compact" type="button" data-channel-edit="${escapeHtml(channel.id)}">Configurar</button><button class="ghost-button compact" type="button" data-channel-add-effort="${escapeHtml(channel.id)}">Crear atracción</button></div>
    </article>`;
  }).join("");
  const cards = rows.map((effort) => {
    const metrics = effort.metrics || {};
    const exact = metrics.attribution_quality === "EXACT_LINK";
    const sourceName = effort.interactive_activation_name || effort.lead_capture_activation_name || effort.digital_asset_name || "Sin fuente exclusiva";
    return `<article class="acquisition-effort-card"><div class="acq-card-head"><div><span class="mono-label">${escapeHtml(effort.channel_name || "Medio")}</span><h4>${escapeHtml(effort.title || "Atracción")}</h4><small>${escapeHtml(sourceName)} · asignada a ${escapeHtml(effort.channel_name || "su medio")}</small></div><span class="acq-badge ${exact ? "" : "legacy"}">${exact ? "Exacta" : "Estimada"}</span></div><div class="acq-funnel"><div><strong>${Number(metrics.views || 0)}</strong><span>Vistas</span></div><div><strong>${Number(metrics.leads || 0)}</strong><span>Leads</span></div><div><strong>${Number(metrics.completions || 0)}</strong><span>Completadas</span></div><div><strong>${Number(metrics.downloads || 0)}</strong><span>Descargas</span></div><div><strong>${Number(metrics.qr_generated || 0)}</strong><span>QR emitidos</span></div><div><strong>${Number(metrics.redemptions || 0)}</strong><span>Redenciones</span></div></div><div class="acq-outcome"><div><small>Revenue atribuido</small><strong>${escapeHtml(money(metrics.revenue || 0))}</strong></div><div><small>Ventas</small><strong>${Number(metrics.sales || 0)}</strong></div><div><small>ROI</small><strong>${escapeHtml(channelRoiLabel(metrics.roi))}</strong></div></div><div class="acq-card-footer"><span>${escapeHtml(effortDateRangeLabel(effort))}</span><div><button class="ghost-button compact" type="button" data-effort-insights="${escapeHtml(effort.id)}" data-parent-channel="${escapeHtml(effort.channel_id)}">Ver personas</button>${effort.tracked_url ? `<button class="solid-button compact" type="button" data-copy-acquisition-url="${escapeHtml(effort.tracked_url)}">Copiar enlace</button>` : `<button class="solid-button compact" type="button" data-channel-effort-edit="${escapeHtml(effort.id)}">Conectar fuente</button>`}<button class="ghost-button compact" type="button" data-channel-effort-edit="${escapeHtml(effort.id)}">Editar</button></div></div></article>`;
  }).join("");
  const priority = rows.length === 0 ? "Crea una atracción y conecta una fuente exclusiva." : exactCount < rows.length ? `Conecta ${rows.length - exactCount} atracción${rows.length - exactCount === 1 ? "" : "es"} para cerrar la brecha.` : "La trazabilidad exacta está completa en el periodo.";
  acquisitionAttributionBoard.innerHTML = `<section class="acquisition-control-card"><div class="acq-control-copy"><span class="mono-label">Centro de atribución</span><h3>Convierte cada medio en evidencia de revenue.</h3><p>Una fuente exclusiva conserva el origen desde el clic o descarga hasta el lead, el beneficio QR, la redención y la venta.</p></div><div class="acq-period"><label>Desde<input type="date" data-acquisition-start value="${escapeHtml(period.start)}"></label><label>Hasta<input type="date" data-acquisition-end value="${escapeHtml(period.end)}"></label><button class="solid-button compact" type="button" data-acquisition-apply>Aplicar</button><button class="ghost-button compact" type="button" data-acquisition-export>Exportar CSV</button></div><div class="acq-period-shortcuts"><span>Ventana rápida</span><button type="button" data-acquisition-days="30">30 días</button><button type="button" data-acquisition-days="90">90 días</button></div></section>
    <section class="acq-truth-grid"><article><span>Cobertura exacta</span><strong>${coverage}%</strong><small>${exactCount} de ${rows.length} atracciones</small><i><b style="width:${coverage}%"></b></i></article><article><span>Revenue con fuente exacta</span><strong>${escapeHtml(money(exactRevenue))}</strong><small>${exactLeads} leads trazados</small></article><article class="${revenueGap > 0 ? "attention" : ""}"><span>Revenue sin atracción exacta</span><strong>${escapeHtml(money(revenueGap))}</strong><small>${revenueGap > 0 ? "Brecha por cerrar" : "Cobertura conciliada"}</small></article><article class="acq-priority"><span>Próximo movimiento</span><strong>${escapeHtml(priority)}</strong></article></section>
    <section class="acq-section-head"><div><span class="mono-label">Portafolio de medios</span><h3>Rendimiento por origen</h3></div><button class="ghost-button compact" type="button" data-acquisition-new-channel>+ Crear medio</button></section><section class="acq-channel-grid">${channelCards || `<article class="acq-empty"><strong>Aún no hay medios creados.</strong><p>Crea Instagram, Google, WhatsApp u otro origen para comenzar.</p><button class="solid-button compact" type="button" data-acquisition-new-channel>Crear primer medio</button></article>`}</section>
    <section class="acq-section-head"><div><span class="mono-label">Atracciones medibles</span><h3>Del alcance al revenue</h3></div><span class="acq-legend"><i></i> Exacta <i class="legacy"></i> Estimada</span></section><section class="acq-effort-grid">${cards || `<article class="acq-empty"><strong>Crea tu primera atracción medible.</strong><p>Conecta una activación, captura de leads o activo digital y comparte únicamente su enlace medible.</p><button class="solid-button compact" type="button" data-acquisition-new-effort>Crear atracción</button></article>`}</section>`;
}

function renderChannelEffortsView() {
  renderChannelEffortOptions();
  if (channelEffortTotalsChip) {
    const totals = state.acquisitionChannelEffortTotals || {};
    channelEffortTotalsChip.textContent = `${Number(totals.efforts || 0)} esfuerzos · ${money(totals.revenue || 0)}`;
  }
  if (!channelEffortTable) return;
  const rows = withFilters(
    state.acquisitionChannelEfforts || [],
    ["title", "channel_name", "campaign_name", "content_type", "objective", "description", "notes"],
    ["published_at", "starts_at", "ends_at", "created_at"]
  );
  renderAcquisitionAttributionBoard(rows);
  if (state.acquisitionChannelEffortsLoading && !rows.length) {
    channelEffortTable.innerHTML = '<tr><td colspan="12">Cargando esfuerzos y publicaciones...</td></tr>';
    return;
  }
  channelEffortTable.innerHTML = rows.map((effort) => {
    const metrics = effort.metrics || {};
    const investment = Number(metrics.investment || effort.budget_amount || 0);
    const revenue = Number(metrics.revenue || 0);
    const roi = metrics.roi;
    return `
      <tr>
        <td>
          <strong>${escapeHtml(effort.title || "Esfuerzo sin nombre")}</strong>
          <br><span class="table-secondary">${escapeHtml(effort.content_type || "POST")} · ${escapeHtml(effort.objective || "Sin objetivo")}</span>
        </td>
        <td>${escapeHtml(effort.channel_name || "-")}</td>
        <td>${escapeHtml(effort.campaign_name || "Sin campaña")}</td>
        <td>${escapeHtml(effortDateRangeLabel(effort))}</td>
        <td>${escapeHtml(money(investment))}</td>
        <td>${escapeHtml(metrics.leads || 0)}</td>
        <td>${escapeHtml(metrics.sales || 0)}</td>
        <td>${escapeHtml(metrics.rebuy_sales || 0)}</td>
        <td>${escapeHtml(metrics.referral_sales || 0)}</td>
        <td><strong>${escapeHtml(money(revenue))}</strong></td>
        <td><strong>${escapeHtml(metrics.cac === null || metrics.cac === undefined ? "-" : money(metrics.cac))}</strong></td>
        <td>
          <strong>${escapeHtml(channelRoiLabel(roi))}</strong>
          <br><span class="table-secondary">${escapeHtml(roiDecisionLabel(roi, revenue, investment))}</span>
        </td>
        <td>
          <button class="ghost-button" type="button" data-channel-effort-edit="${escapeHtml(effort.id)}">Editar</button>
          ${effort.source_url ? `<a class="ghost-button" href="${escapeHtml(effort.source_url)}" target="_blank" rel="noopener">Ver pieza</a>` : ""}
          <button class="link-button danger-link" type="button" data-channel-effort-archive="${escapeHtml(effort.id)}">Archivar</button>
        </td>
      </tr>
    `;
  }).join("") || '<tr><td colspan="12">Registra una publicación, pauta o acción del canal para medir ROI por pieza.</td></tr>';
}

async function submitChannelEffort(event) {
  event.preventDefault();
  const payload = channelEffortPayload();
  if (!payload.channel_id) {
    setInlineMessage(channelEffortMessage, "Primero selecciona o crea un canal.", "error");
    channelEffortChannelInput?.focus();
    return;
  }
  if (!payload.title) {
    setInlineMessage(channelEffortMessage, "Escribe el título del esfuerzo.", "error");
    channelEffortTitleInput?.focus();
    return;
  }
  if (payload.status === "ACTIVE" && !payload.interactive_activation_id && !payload.lead_capture_activation_id && !payload.digital_asset_id) {
    setInlineMessage(channelEffortMessage, "Selecciona una fuente medible exclusiva. Sin una activación o activo enlazado no es posible atribuir personas ni ventas.", "error");
    channelEffortAttributionSourceInput?.focus();
    return;
  }
  const editingId = state.channelEffortEditingId || channelEffortIdInput?.value || "";
  setButtonLoading(channelEffortSaveButton, true, "Guardando...");
  setInlineMessage(channelEffortMessage, "Guardando esfuerzo y recalculando análisis del canal...", "info");
  try {
    await api(editingId ? `/api/business/channel-efforts/${encodeURIComponent(editingId)}` : "/api/business/channel-efforts", {
      method: editingId ? "PATCH" : "POST",
      headers: authHeaders(),
      body: JSON.stringify(payload),
    });
    resetChannelEffortForm();
    state.acquisitionChannelEffortsLoaded = false;
    state.acquisitionChannelsLoaded = false;
    await Promise.all([
      loadAcquisitionChannels({ force: true, quiet: true }),
      loadChannelEfforts({ force: true, quiet: true }),
    ]);
    renderAcquisitionChannelsView();
    closeChannelEffortModal();
    showFeedback("Esfuerzo del medio guardado con análisis de ROI por fechas.", "success", { title: "Medios de adquisición" });
  } catch (error) {
    setInlineMessage(channelEffortMessage, error.message, "error");
    showFeedback(error.message, "error", { title: "No se pudo guardar el esfuerzo" });
  } finally {
    setButtonLoading(channelEffortSaveButton, false);
  }
}

async function archiveChannelEffort(effortId = "") {
  if (!effortId) return;
  try {
    await api(`/api/business/channel-efforts/${encodeURIComponent(effortId)}`, {
      method: "DELETE",
      headers: authHeaders(),
    });
    if (state.channelEffortEditingId === effortId) resetChannelEffortForm();
    await loadChannelEfforts({ force: true, quiet: true });
    renderAcquisitionChannelsView();
    showFeedback("Esfuerzo archivado. El medio conserva su histórico de ventas y campañas.", "success", { title: "Medios de adquisición" });
  } catch (error) {
    showFeedback(error.message, "error", { title: "No se pudo archivar el esfuerzo" });
  }
}

async function loadAcquisitionChannels(options = {}) {
  if (!session?.user?.business_id) {
    state.acquisitionChannels = [];
    state.acquisitionChannelTotals = null;
    state.acquisitionChannelsLoaded = true;
    state.acquisitionChannelsLoading = false;
    renderAcquisitionChannelDatalist();
    return [];
  }
  if (state.acquisitionChannelsLoaded && !options.force) return state.acquisitionChannels;
  if (state.acquisitionChannelsLoading) return state.acquisitionChannels;
  state.acquisitionChannelsLoading = true;
  const scopeKey = businessScopeKey();
  try {
    const period = acquisitionReportingPeriod();
    const params = new URLSearchParams({ include_archived: "true", start_date: period.start, end_date: period.end });
    const data = await apiSafe(`/api/business/channels?${params.toString()}`, { headers: authHeaders() }, { channels: [], totals: null });
    if (!isCurrentBusinessScope(scopeKey)) return state.acquisitionChannels;
    state.acquisitionChannels = Array.isArray(data.channels) ? data.channels : [];
    state.acquisitionChannelTotals = data.totals || null;
    state.acquisitionChannelMatrix = Array.isArray(data.campaign_channel_matrix) ? data.campaign_channel_matrix : [];
    state.acquisitionChannelsLoaded = true;
    renderAcquisitionChannelDatalist();
    renderChannelEffortOptions();
    return state.acquisitionChannels;
  } finally {
    if (isCurrentBusinessScope(scopeKey)) state.acquisitionChannelsLoading = false;
  }
}

function resetAcquisitionChannelForm(channel = null) {
  state.acquisitionChannelEditingId = channel?.id || null;
  if (acquisitionChannelFormTitle) acquisitionChannelFormTitle.textContent = channel?.id ? "Editar medio" : "Crear medio";
  if (acquisitionChannelIdInput) acquisitionChannelIdInput.value = channel?.id || "";
  if (acquisitionChannelNameInput) acquisitionChannelNameInput.value = channel?.name || "";
  if (acquisitionChannelTypeInput) acquisitionChannelTypeInput.value = channel?.channel_type || "DIGITAL";
  if (acquisitionChannelPlatformInput) acquisitionChannelPlatformInput.value = channel?.platform || channel?.name || "";
  if (acquisitionChannelBudgetInput) acquisitionChannelBudgetInput.value = Number(channel?.period_budget || 0);
  if (acquisitionChannelCurrencyInput) acquisitionChannelCurrencyInput.value = channel?.currency || "COP";
  if (acquisitionChannelStatusInput) acquisitionChannelStatusInput.value = channel?.status && channel.status !== "DETECTED" ? channel.status : "ACTIVE";
  if (acquisitionChannelNotesInput) acquisitionChannelNotesInput.value = channel?.notes || "";
  if (acquisitionChannelSaveButton) acquisitionChannelSaveButton.textContent = channel?.id ? "Guardar cambios" : "Guardar medio";
  setInlineMessage(acquisitionChannelMessage, "", "info");
}

function acquisitionChannelPayload() {
  return {
    name: acquisitionChannelNameInput?.value?.trim() || "",
    channel_type: acquisitionChannelTypeInput?.value || "DIGITAL",
    platform: acquisitionChannelPlatformInput?.value?.trim() || null,
    period_budget: Number(acquisitionChannelBudgetInput?.value || 0),
    currency: acquisitionChannelCurrencyInput?.value?.trim() || "COP",
    status: acquisitionChannelStatusInput?.value || "ACTIVE",
    notes: acquisitionChannelNotesInput?.value?.trim() || null,
  };
}

async function submitAcquisitionChannel(event) {
  event.preventDefault();
  const payload = acquisitionChannelPayload();
  if (!payload.name) {
    setInlineMessage(acquisitionChannelMessage, "Escribe el nombre del medio.", "error");
    acquisitionChannelNameInput?.focus();
    return;
  }
  const editingId = state.acquisitionChannelEditingId || acquisitionChannelIdInput?.value || "";
  setButtonLoading(acquisitionChannelSaveButton, true, "Guardando...");
  setInlineMessage(acquisitionChannelMessage, "Guardando canal independiente de campañas...", "info");
  try {
    await api(editingId ? `/api/business/channels/${encodeURIComponent(editingId)}` : "/api/business/channels", {
      method: editingId ? "PATCH" : "POST",
      headers: authHeaders(),
      body: JSON.stringify(payload),
    });
    resetAcquisitionChannelForm();
    await loadAcquisitionChannels({ force: true, quiet: true });
    renderAcquisitionChannelsView();
    renderAcquisitionChannelDatalist();
    closeAcquisitionChannelModal();
    showFeedback("Medio guardado para análisis independiente de ROI.", "success", { title: "Medios de adquisición" });
  } catch (error) {
    setInlineMessage(acquisitionChannelMessage, error.message, "error");
    showFeedback(error.message, "error", { title: "No se pudo guardar el medio" });
  } finally {
    setButtonLoading(acquisitionChannelSaveButton, false);
  }
}

async function archiveAcquisitionChannel(channelId = "") {
  const channel = acquisitionChannelById(channelId);
  if (!channel?.id) return;
  try {
    await api(`/api/business/channels/${encodeURIComponent(channel.id)}`, {
      method: "DELETE",
      headers: authHeaders(),
    });
    if (state.acquisitionChannelEditingId === channel.id) resetAcquisitionChannelForm();
    await loadAcquisitionChannels({ force: true, quiet: true });
    renderAcquisitionChannelsView();
    renderAcquisitionChannelDatalist();
    showFeedback("Medio archivado. Los datos históricos siguen disponibles por texto de medio.", "success", { title: "Medios de adquisición" });
  } catch (error) {
    showFeedback(error.message, "error", { title: "No se pudo archivar" });
  }
}

function createDetectedAcquisitionChannel(name = "") {
  resetAcquisitionChannelForm({
    name,
    platform: name,
    channel_type: "DIGITAL",
    status: "ACTIVE",
    period_budget: 0,
    currency: "COP",
    notes: "Canal detectado automáticamente desde ventas, leads o tickets. Ajusta inversión para medir ROI real.",
  });
  openAcquisitionChannelModal();
  acquisitionChannelNameInput?.focus();
  setInlineMessage(acquisitionChannelMessage, "Completa la inversión del canal detectado y guarda para controlarlo.", "info");
}

function applyAcquisitionChannelTemplate(rawTemplate = "") {
  const [name, type, platform, costModel] = String(rawTemplate || "").split("|");
  resetAcquisitionChannelForm({
    name: name || "",
    platform: platform || name || "",
    channel_type: type || "DIGITAL",
    status: "ACTIVE",
    period_budget: 0,
    currency: "COP",
    cost_model: costModel || null,
    notes: `Canal ${name || "nuevo"} creado para controlar inversión, clientes recibidos, ventas y ROI independiente de campañas.`,
  });
  openAcquisitionChannelModal();
  acquisitionChannelBudgetInput?.focus();
  setInlineMessage(acquisitionChannelMessage, "Carga la inversión del periodo y guarda el canal. Luego registra ventas con este canal para medir ROI.", "info");
}

function renderAcquisitionChannelDetail() {
  if (!acquisitionChannelDetailPanel) return;
  const channel = selectedAcquisitionChannel();
  if (!channel) {
    acquisitionChannelDetailPanel.innerHTML = `
      <span class="mono-label">Detalle del canal</span>
      <h3>Sin canal seleccionado</h3>
      <p>Crea Instagram, Facebook, Google, WhatsApp, Web u otro canal. Después registra ventas con ese canal para ver ROI individual.</p>
    `;
    return;
  }
  const metrics = channel.metrics || {};
  const investment = Number(metrics.investment || channel.period_budget || 0);
  const revenue = Number(metrics.revenue || 0);
  const sales = Number(metrics.sales || 0);
  const leads = Number(metrics.leads || 0);
  const roi = metrics.roi;
  const breakdown = Array.isArray(channel.campaign_breakdown) ? channel.campaign_breakdown.slice(0, 4) : [];
  const isDetected = !channel.id || channel.status === "DETECTED";
  acquisitionChannelDetailPanel.innerHTML = `
    <div class="channel-detail-head">
      <div>
        <span class="mono-label">Detalle del canal</span>
        <h3>${escapeHtml(channel.name || "Canal")}</h3>
        <p>${escapeHtml(channel.platform || acquisitionChannelTypeLabel(channel.channel_type))}</p>
      </div>
      <span class="status-chip ${isDetected ? "warning" : channel.status === "ACTIVE" ? "ok" : "pending"}">${escapeHtml(acquisitionChannelStatusLabel(channel.status))}</span>
    </div>
    <div class="channel-detail-metrics">
      <div><span>Inversión</span><strong>${escapeHtml(money(investment))}</strong></div>
      <div><span>Revenue</span><strong>${escapeHtml(money(revenue))}</strong></div>
      <div><span>Ventas</span><strong>${escapeHtml(String(sales))}</strong></div>
      <div><span>Leads</span><strong>${escapeHtml(String(leads))}</strong></div>
      <div><span>CAC</span><strong>${escapeHtml(metrics.cac === null || metrics.cac === undefined ? "-" : money(metrics.cac))}</strong></div>
      <div><span>ROI</span><strong>${escapeHtml(channelRoiLabel(roi))}</strong></div>
    </div>
    <div class="channel-decision-box">
      <strong>${escapeHtml(roiDecisionLabel(roi, revenue, investment))}</strong>
      <p>${investment ? "La inversión del canal se compara contra las ventas atribuidas por canal." : "Carga inversión para saber si este canal está dando retorno real."}</p>
    </div>
    <div class="channel-breakdown-list">
      <strong>Campañas que convierten en este canal</strong>
      ${breakdown.length ? breakdown.map((row) => `
        <button type="button" data-channel-campaign-open="${escapeHtml(row.campaign_id || "")}">
          <span>${escapeHtml(row.campaign_name || "Sin campaña")}</span>
          <strong>${escapeHtml(money(row.revenue || 0))}</strong>
          <small>${escapeHtml(row.sales || 0)} ventas · ROI canal ${escapeHtml(channelRoiLabel(row.channel_roi))}</small>
        </button>
      `).join("") : '<p class="table-secondary">Aún no hay campañas/ventas atribuidas a este canal.</p>'}
    </div>
    <div class="button-row">
      ${isDetected
        ? `<button class="solid-button compact" type="button" data-channel-create="${escapeHtml(channel.name || "")}">Crear medio y cargar inversión</button>`
        : `<button class="ghost-button compact" type="button" data-channel-edit="${escapeHtml(channel.id)}">Editar inversión</button>`}
      <button class="ghost-button compact" type="button" data-channel-open-sales="${escapeHtml(channel.name || "")}">Registrar venta con este canal</button>
      ${!isDetected ? `<button class="solid-button compact" type="button" data-channel-add-effort="${escapeHtml(channel.id)}">Registrar publicación/pauta</button>` : ""}
    </div>
  `;
}

function renderAcquisitionChannelsView() {
  ensureAcquisitionChannelsUxStyles();
  acquisitionChannelKpiGrid?.style.setProperty("display", "none", "important");
  acquisitionAttributionBoard?.style.setProperty("padding", "0", "important");
  acquisitionChannelsViewSection()?.style.setProperty("gap", "1rem", "important");
  const channels = withFilters(
    state.acquisitionChannels || [],
    ["name", "platform", "channel_type", "status", "notes"],
    ["created_at", "updated_at"]
  );
  const totals = state.acquisitionChannelTotals || channels.reduce((acc, channel) => {
    acc.leads += Number(channel.metrics?.leads || 0);
    acc.sales += Number(channel.metrics?.sales || 0);
    acc.revenue += Number(channel.metrics?.revenue || 0);
    acc.investment += Number(channel.metrics?.investment || 0);
    return acc;
  }, { leads: 0, sales: 0, revenue: 0, investment: 0 });
  if (acquisitionChannelKpiGrid) {
    const created = channels.filter((channel) => channel.id).length;
    const detected = channels.filter((channel) => !channel.id || channel.status === "DETECTED").length;
    acquisitionChannelKpiGrid.innerHTML = [
      ["Medios creados", created, "Directorio propio"],
      ["Medios detectados", detected, "Desde ventas, leads o tickets"],
      ["Esfuerzos medidos", Number(state.acquisitionChannelEffortTotals?.efforts || 0), "Posts, pautas, WhatsApp o eventos"],
      ["Revenue por medio", money(totals.revenue || 0), `${Number(totals.sales || 0)} ventas`],
      ["Inversión por medio", money(totals.investment || 0), "Presupuesto cargado"],
      ["ROI total de medios", channelRoiLabel(totals.roi), totals.investment ? roiDecisionLabel(totals.roi, totals.revenue, totals.investment) : "Carga inversión para ROI"],
    ].map(([label, value, meta]) => `
      <article class="kpi-card">
        <span class="mono-label">${escapeHtml(label)}</span>
        <strong>${escapeHtml(value)}</strong>
        <div class="kpi-meta">${escapeHtml(meta || "")}</div>
      </article>
    `).join("");
  }
  renderAcquisitionChannelDetail();
  renderChannelEffortsView();
  if (!acquisitionChannelTable) return;
  if (state.acquisitionChannelsLoading && !channels.length) {
    acquisitionChannelTable.innerHTML = '<tr><td colspan="11">Cargando medios de adquisición...</td></tr>';
    return;
  }
  acquisitionChannelTable.innerHTML = channels.map((channel) => {
    const metrics = channel.metrics || {};
    const isDetected = !channel.id || channel.status === "DETECTED";
    const investment = Number(metrics.investment || channel.period_budget || 0);
    const revenue = Number(metrics.revenue || 0);
    return `
      <tr>
        <td>
          <strong>${escapeHtml(channel.name || "Sin canal")}</strong>
          <br><span class="table-secondary">${escapeHtml(channel.platform || channel.slug || "Canal comercial")}</span>
        </td>
        <td>${escapeHtml(money(investment))}</td>
        <td>${escapeHtml(metrics.leads || 0)}</td>
        <td>${escapeHtml(metrics.sales || 0)}</td>
        <td>${escapeHtml(money(revenue))}</td>
        <td>${escapeHtml(metrics.cac === null || metrics.cac === undefined ? "-" : money(metrics.cac))}</td>
        <td>
          <strong>${escapeHtml(channelRoiLabel(metrics.roi))}</strong>
          <br><span class="table-secondary">${escapeHtml(roiDecisionLabel(metrics.roi, metrics.revenue, metrics.investment))}</span>
        </td>
        <td><span class="status-chip ${isDetected ? "warning" : channel.status === "ACTIVE" ? "ok" : "pending"}">${escapeHtml(acquisitionChannelStatusLabel(channel.status))}</span></td>
        <td>
          <span class="channel-row-actions">
            ${isDetected
              ? `<button class="solid-button compact" type="button" data-channel-create="${escapeHtml(channel.name || "")}">Crear medio</button>`
              : `<button class="ghost-button" type="button" data-channel-edit="${escapeHtml(channel.id)}">Editar</button>
                 <button class="solid-button compact" type="button" data-channel-add-effort="${escapeHtml(channel.id)}">Crear atracción</button>
                 <button class="link-button danger-link" type="button" data-channel-archive="${escapeHtml(channel.id)}">Archivar</button>`}
          </span>
        </td>
      </tr>
    `;
  }).join("") || '<tr><td colspan="8">Crea tu primer canal o registra ventas con canal específico para detectarlos automáticamente.</td></tr>';

  if (acquisitionChannelMatrixTable) {
    const matrix = (state.acquisitionChannelMatrix || []).slice()
      .sort((a, b) => Number(b.revenue || 0) - Number(a.revenue || 0) || Number(b.sales || 0) - Number(a.sales || 0));
    acquisitionChannelMatrixTable.innerHTML = matrix.map((row) => `
      <tr>
        <td><strong>${escapeHtml(row.channel_name || "-")}</strong></td>
        <td>${escapeHtml(row.campaign_name || "Sin campaña")}</td>
        <td>${escapeHtml(row.sales || 0)}</td>
        <td>${escapeHtml(money(row.revenue || 0))}</td>
        <td><strong>${escapeHtml(money(Number(row.revenue || 0) - Number(row.channel_investment_allocated || 0)))}</strong></td>
        <td>${escapeHtml(money(row.channel_investment_allocated || 0))}</td>
        <td>${escapeHtml(channelRoiLabel(row.channel_roi))}</td>
        <td>${escapeHtml(money(row.campaign_investment || 0))}</td>
        <td>${escapeHtml(channelRoiLabel(row.campaign_roi))}</td>
      </tr>
    `).join("") || '<tr><td colspan="9">Registra ventas con campaña y canal para ver el cruce de ROI.</td></tr>';
  }
}

function renderSalesView() {
  ensureSalesAnalysisStyles();
  const allSales = salesRowsForAttributedSalesView();
  renderSalesAnalysisControls(allSales);
  const sales = filteredSalesForAnalysis(allSales);
  const reportingSales = sales.filter((item) => String(item.sale_status || "PAID").toUpperCase() !== "VOIDED");
  const summary = state.attributedSalesSummary || {};
  const items = [
    ["revenue", "payments", "Revenue atribuido", salesMoney(summary.attributed_revenue || 0), "Solo ventas pagadas y conciliadas"],
    ["sales", "verified", "Ventas pagadas", Number(summary.paid_count || 0).toLocaleString("es-CO"), `${Number(summary.total_records || 0).toLocaleString("es-CO")} registros en el filtro`],
    ["customers", "group", "Clientes únicos", Number(summary.unique_customers || 0).toLocaleString("es-CO"), "Identidades únicas con compra"],
    ["average", "monitoring", "Ticket promedio", salesMoney(summary.average_ticket || 0), "Promedio de ventas pagadas"],
    ["quality", "policy", "Anuladas", Number(summary.voided_count || 0).toLocaleString("es-CO"), "Visibles para auditoría; no suman"],
  ];

  salesKpiGrid.innerHTML = items.map(([key, icon, label, value, meta]) => `
    <article class="kpi-card" data-sales-kpi="${escapeHtml(key)}" style="grid-column:auto !important;grid-row:auto !important;height:auto !important;min-height:154px !important;padding:19px !important;${key === "revenue" ? "background-color:#074aa7 !important;background-image:radial-gradient(circle at 100% 0,rgba(0,218,255,.30),transparent 42%),linear-gradient(145deg,#032557,#075dd8) !important;" : ""}">
      <div class="sales-kpi-head"><span class="mono-label">${escapeHtml(label)}</span><span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(icon)}</span></div>
      <strong>${escapeHtml(value)}</strong>
      <div class="kpi-meta">${escapeHtml(meta)}</div>
    </article>
  `).join("");
  renderCustomerAcquisitionCampaignOptions();
  renderCustomerAcquisitionBranchOptions();
  renderSalesCustomerOptions();
  renderCustomerSaleItems();
  renderAcquisitionChannelDatalist();
  renderSalesAnalysisGrid(reportingSales);
  state.salesDetailRows = sales;

  const loadedCount = allSales.length;
  const totalCount = Number(summary.total_records || loadedCount);
  if (salesResultsLabel) salesResultsLabel.textContent = `${totalCount.toLocaleString("es-CO")} registro(s) coinciden con los filtros activos.`;
  if (salesPaginationLabel) salesPaginationLabel.textContent = `Mostrando ${loadedCount.toLocaleString("es-CO")} de ${totalCount.toLocaleString("es-CO")} registros`;
  if (salesLoadMoreButton) {
    salesLoadMoreButton.hidden = !state.attributedSalesPagination?.has_more;
    salesLoadMoreButton.disabled = state.attributedSalesLoading;
  }

  campaignSalesTable.innerHTML = sales.map((item, index) => `
    <tr class="sales-simple-row ${String(item.sale_status || "PAID").toUpperCase() === "VOIDED" ? "is-voided" : ""}" data-sales-detail="${escapeHtml(saleDetailKey(item, index))}" tabindex="0" role="button" aria-label="Ver detalle de venta de ${escapeHtml(item.player_name || item.customer_name || "cliente")}">
      <td><strong>${escapeHtml(item.player_name || item.customer_name || "Cliente sin nombre")}</strong><small>${escapeHtml([item.document_id || item.customer_document_id, item.phone || item.customer_phone, item.customer_email || item.email].filter(Boolean).join(" · ") || "Sin datos de contacto")}</small><span class="sales-sale-status ${String(item.sale_status || "PAID").toUpperCase() === "VOIDED" ? "is-voided" : "is-paid"}">${String(item.sale_status || "PAID").toUpperCase() === "VOIDED" ? "Anulada" : "Pagada"}</span></td>
      <td><strong>${escapeHtml(salesMoney(item.sale_amount, item.currency))}</strong><small>${escapeHtml(item.payment_method || "Medio de pago no registrado")}</small></td>
      <td>${saleProductSummary(item)}</td>
      <td><strong>${escapeHtml(saleCampaignText(item))}</strong><small>${escapeHtml(saleChannelText(item))}</small></td>
      <td>${escapeHtml(saleSourceLabel(item.sale_source))}</td>
      <td>${escapeHtml(saleBranchText(item))}</td>
      <td><strong>${escapeHtml(formatDateShort(item.created_at))}</strong><small>${escapeHtml(formatDate(item.created_at))}</small></td>
    </tr>
  `).join("") || '<tr><td colspan="7"><div class="empty-state compact">No hay ventas para los filtros actuales. Ajusta la búsqueda o limpia los filtros.</div></td></tr>';
  bindSalesTableRows(sales);
}

