function ensureRmsActiveOnboarding() {
  if (document.getElementById("rmsActiveOnboardingStyle")) return;
  const style = document.createElement("style");
  style.id = "rmsActiveOnboardingStyle";
  style.textContent = `
    #rmsMachineTutorial { display:none!important; }
    .rms-active-onboarding-overlay { position:fixed!important; inset:0!important; z-index:1200!important; background:rgba(3,22,45,.68)!important; }
    .rms-active-onboarding-focus { position:relative!important; z-index:1202!important; outline:3px solid #17c6f3!important; outline-offset:6px!important; border-radius:12px!important; box-shadow:0 0 0 9999px rgba(3,22,45,.0),0 0 0 7px rgba(23,198,243,.18),0 18px 42px rgba(0,0,0,.28)!important; }
    .rms-active-onboarding-callout { position:fixed!important; z-index:1203!important; width:min(360px,calc(100vw - 32px))!important; padding:18px!important; border:1px solid rgba(255,255,255,.5)!important; border-radius:16px!important; background:#fff!important; box-shadow:0 24px 70px rgba(0,0,0,.35)!important; color:#062d67!important; }
    .rms-active-onboarding-callout .mono-label { color:#1682b5!important; }
    .rms-active-onboarding-callout h3 { margin:5px 0 7px!important; color:#062d67!important; font-size:1.05rem!important; line-height:1.2!important; }
    .rms-active-onboarding-callout p { margin:0!important; color:#526e89!important; font-size:.82rem!important; line-height:1.5!important; }
    .rms-active-onboarding-progress { display:flex!important; align-items:center!important; justify-content:space-between!important; gap:12px!important; margin-top:14px!important; padding-top:12px!important; border-top:1px solid #e5edf3!important; color:#5b7791!important; font-size:.72rem!important; font-weight:800!important; }
    .rms-active-onboarding-actions { display:flex!important; gap:8px!important; margin-top:12px!important; }
    .rms-active-onboarding-actions button { min-height:36px!important; }
    .rms-active-onboarding-actions .rms-active-onboarding-skip { margin-left:auto!important; }
    @media (max-width:620px) { .rms-active-onboarding-focus { outline-offset:3px!important; } .rms-active-onboarding-callout { padding:16px!important; } }
  `;
  document.head.appendChild(style);
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && state.rmsActiveOnboardingOpen) closeRmsActiveOnboarding();
  });
}

function closeRmsActiveOnboarding() {
  state.rmsActiveOnboardingOpen = false;
  document.querySelectorAll(".rms-active-onboarding-focus").forEach((node) => node.classList.remove("rms-active-onboarding-focus"));
  document.getElementById("rmsActiveOnboardingOverlay")?.remove();
  document.getElementById("rmsActiveOnboardingCallout")?.remove();
}

function renderRmsActiveOnboarding() {
  if (!state.rmsActiveOnboardingOpen) return;
  ensureRmsActiveOnboarding();
  const index = Math.max(0, Math.min(Number(state.rmsActiveOnboardingStep || 0), RMS_ACTIVE_ONBOARDING_STEPS.length - 1));
  const step = RMS_ACTIVE_ONBOARDING_STEPS[index];
  const target = document.querySelector(step.target);
  if (!target) {
    window.setTimeout(renderRmsActiveOnboarding, 120);
    return;
  }
  document.querySelectorAll(".rms-active-onboarding-focus").forEach((node) => node.classList.remove("rms-active-onboarding-focus"));
  target.classList.add("rms-active-onboarding-focus");
  target.scrollIntoView({ behavior: "smooth", block: "center", inline: "center" });

  let overlay = document.getElementById("rmsActiveOnboardingOverlay");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "rmsActiveOnboardingOverlay";
    overlay.className = "rms-active-onboarding-overlay";
    overlay.addEventListener("click", () => {});
    document.body.appendChild(overlay);
  }
  let callout = document.getElementById("rmsActiveOnboardingCallout");
  if (!callout) {
    callout = document.createElement("aside");
    callout.id = "rmsActiveOnboardingCallout";
    callout.className = "rms-active-onboarding-callout";
    callout.setAttribute("role", "dialog");
    callout.setAttribute("aria-live", "polite");
    document.body.appendChild(callout);
  }
  callout.innerHTML = `
    <span class="mono-label">Aprendizaje activo · ${String(index + 1).padStart(2, "0")}/${String(RMS_ACTIVE_ONBOARDING_STEPS.length).padStart(2, "0")}</span>
    <h3>${escapeHtml(step.title)}</h3>
    <p>${escapeHtml(step.copy)}</p>
    <div class="rms-active-onboarding-progress"><span>Haz clic en el elemento iluminado</span><strong>${index + 1} de ${RMS_ACTIVE_ONBOARDING_STEPS.length}</strong></div>
    <div class="rms-active-onboarding-actions">
      ${step.event ? `<button class="ghost-button compact" type="button" data-rms-active-tutorial-next>Continuar sin acción</button>` : `<button class="solid-button compact" type="button" data-rms-active-tutorial-finish>Terminar tutorial</button>`}
      <button class="text-button rms-active-onboarding-skip" type="button" data-rms-active-tutorial-close>Salir</button>
    </div>
  `;
  const placeCallout = () => {
    const rect = target.getBoundingClientRect();
    const width = Math.min(360, window.innerWidth - 32);
    const left = Math.max(16, Math.min(window.innerWidth - width - 16, rect.left));
    const estimatedHeight = callout.offsetHeight || 190;
    const top = rect.bottom + 16 + estimatedHeight < window.innerHeight ? rect.bottom + 16 : Math.max(16, rect.top - estimatedHeight - 16);
    callout.style.left = `${left}px`;
    callout.style.top = `${top}px`;
  };
  requestAnimationFrame(placeCallout);
  const advance = () => {
    state.rmsActiveOnboardingStep = index + 1;
    if (state.rmsActiveOnboardingStep >= RMS_ACTIVE_ONBOARDING_STEPS.length) {
      closeRmsActiveOnboarding();
      return;
    }
    window.setTimeout(renderRmsActiveOnboarding, 180);
  };
  if (step.event) target.addEventListener(step.event, advance, { once: true });
  callout.querySelector("[data-rms-active-tutorial-next]")?.addEventListener("click", advance);
  callout.querySelector("[data-rms-active-tutorial-finish]")?.addEventListener("click", closeRmsActiveOnboarding);
  callout.querySelector("[data-rms-active-tutorial-close]")?.addEventListener("click", closeRmsActiveOnboarding);
}

function startRmsActiveOnboarding() {
  state.rmsActiveOnboardingOpen = true;
  state.rmsActiveOnboardingStep = 0;
  document.querySelector(".rms-machine-filter-disclosure")?.setAttribute("open", "");
  window.setTimeout(renderRmsActiveOnboarding, 120);
}

function focusRmsTutorial() {
  setView("rms-machine");
  state.rmsStationScreenOpen = false;
  state.rmsStationPhase = "";
  state.rmsMachineFilters.phase = "";
  if (rmsMachinePhaseFilter) rmsMachinePhaseFilter.value = "";
  renderRmsMachineView();
  startRmsActiveOnboarding();
}

function arrangeRmsMachineOverview() {
  const consoleShell = rmsStationWorkspace?.closest(".rms-factory-console");
  if (!consoleShell) return;
  const filters = consoleShell.querySelector(":scope > .rms-board-tools");
  const stations = consoleShell.querySelector(":scope > .rms-stage-slider-shell");
  const controls = document.getElementById("rmsQualityControlAccess");
  filters?.style.setProperty("order", "1", "important");
  stations?.style.setProperty("order", "2", "important");
  controls?.style.setProperty("order", "3", "important");
  if (filters && stations && filters.previousElementSibling !== rmsStationWorkspace) {
    consoleShell.insertBefore(filters, stations);
  }
  if (controls && stations && controls.previousElementSibling !== stations) {
    stations.insertAdjacentElement("afterend", controls);
  }
}

function renderRmsMachineView() {
  const data = state.rmsMachine || {};
  const stages = rmsPrimaryFactoryStages(data);
  const allOpportunities = data.opportunities || [];
  const opportunities = rmsVisibleOpportunities(allOpportunities);
  const metrics = data.metrics || {};
  const totalOpportunities = Number(metrics.total_opportunities || allOpportunities.length || 0);
  const isEmpty = allOpportunities.length === 0 && totalOpportunities === 0;
  arrangeRmsMachineOverview();
  if (state.rmsStationScreenOpen) {
    renderRmsStationOnly();
    return;
  }
  hideRmsStationWorkspace();
  if (rmsMachineGeneratedAt) {
    rmsMachineGeneratedAt.textContent = data.generated_at ? formatDate(data.generated_at) : "Sin cargar";
  }
  const activeStationCount = stages.filter((stage) => allOpportunities.some((item) => item.stage === stage.key)).length;
  if (rmsMachineActiveStations) rmsMachineActiveStations.textContent = `${activeStationCount} de ${stages.length || 10}`;
  if (rmsMachineLiveStatus) {
    const priorityCount = Number(metrics.operate_now || 0);
    rmsMachineLiveStatus.textContent = priorityCount
      ? `${priorityCount.toLocaleString("es-CO")} por atender`
      : isEmpty ? "Lista para recibir leads" : "Operación al día";
  }
  if (rmsMachineOpportunityCount) {
    const phase = state.rmsMachineFilters?.phase || "";
    rmsMachineOpportunityCount.textContent = phase
      ? `${opportunities.length.toLocaleString("es-CO")} en estación / ${totalOpportunities.toLocaleString("es-CO")} total`
      : `${totalOpportunities.toLocaleString("es-CO")} oportunidades`;
  }
  renderRmsMachineFilterFeedback(data, allOpportunities);
  rmsEmptyStateGuide?.classList.toggle("hidden", !isEmpty);
  renderRmsCollectorActivation();
  renderRmsTutorial();
  renderRmsMachineKpis(metrics);
  renderRmsIntakeFunnel(data.funnel || []);
  renderRmsIndustrialFlow(data.process_flow || []);
  renderRmsAlerts(data.alerts || []);
  renderRmsDailyQueue(rmsDailySectionsFromOpportunities(opportunities));
  renderRmsMachineFilterOptions(stages);
  renderRmsQualityControlAccess(data, allOpportunities);
  try {
    renderRmsStationWorkspace(stages, allOpportunities, isEmpty);
  } catch (error) {
    console.error("RMS station render failed", error);
    resetRmsStationMode();
    renderRmsStationWorkspace(stages, allOpportunities, isEmpty);
    showFeedback("La estación no pudo abrirse completa. Volvimos al mapa para que el portal no quede bloqueado.", "error", { title: "Estaciones" });
  }
  renderRmsStageBoard(stages, allOpportunities, isEmpty);
  renderRmsBulkToolbar();
  renderRmsEventLog(data.events || []);
  renderRmsLeadInspector();
}

function rmsStationLeanRowMarkup(item = {}, stage = {}, nextPhase = null) {
  const selected = state.rmsMachineSelectedIds.includes(item.id);
  const readiness = stage.key === "recoleccion" ? rmsCollectorReadiness(item) : { ready: true, label: item.priority_label || "Operable" };
  const origin = item.entry_summary || item.source_detail || item.campaign_name || item.channel || item.source_label || item.source_type || "Origen sin definir";
  const interest = item.product_interest || item.top_interest || item.interest || item.raw_recommended_action || "-";
  const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
  const enteredAt = item.created_at || item.last_interaction_at || item.updated_at;
  let stationControl = stage.key === "recoleccion"
    ? `<td class="rms-lean-station-status ${readiness.ready ? "ready" : "pending"}"><strong>${escapeHtml(readiness.label)}</strong><small>${escapeHtml(readiness.detail)}</small></td>`
    : `<td class="rms-lean-station-status ${escapeHtml(item.priority_class || "medium")}">${escapeHtml(item.priority_label || readiness.label || "Media")}</td>`;
  if (stage.key === "alimentacion") {
    stationControl = `<td class="rms-lean-station-quality">${rmsLeadQualitySelectMarkup(item)}</td>`;
  } else if (stage.key === "curaduria") {
    stationControl = `<td class="rms-lean-station-product">${rmsProductClassificationMarkup(item)}</td>`;
  } else if (stage.key === "clasificacion") {
    stationControl = `<td class="rms-lean-station-activation">${rmsActivationDeliveryCardMarkup(item)}</td>`;
  }
  const controlFirst = ["alimentacion", "curaduria", "clasificacion"].includes(stage.key);
  return `
    <tr data-rms-station-lead="${escapeHtml(item.id)}" data-rms-review-capture="${escapeHtml(item.id)}" class="${selected ? "is-selected" : ""}">
      <td>
        <label class="rms-lean-station-check">
          <input type="checkbox" data-rms-select="${escapeHtml(item.id)}" aria-label="Seleccionar ${escapeHtml(item.name || "lead")}" ${selected ? "checked" : ""}>
        </label>
      </td>
      <td>
        <strong>${escapeHtml(item.name || "Contacto")}</strong>
        <small>${escapeHtml(contact)}</small>
      </td>
      ${controlFirst ? stationControl : ""}
      <td>
        <span>${escapeHtml(origin)}</span>
        <small>${escapeHtml(enteredAt ? formatDate(enteredAt) : "-")}</small>
      </td>
      <td>
        <span>${escapeHtml(interest)}</span>
        <small>${escapeHtml(item.stage_label || stage.label || "")}</small>
      </td>
      ${controlFirst ? "" : stationControl}
      <td>
        <button class="ghost-button compact" type="button" data-rms-review-capture="${escapeHtml(item.id)}">Detalle</button>
        ${stage.key === "recoleccion" ? `<button class="solid-button compact" type="button" data-rms-station-send-single="${escapeHtml(item.id)}" ${readiness.ready && nextPhase ? "" : "disabled"} title="${escapeHtml(readiness.ready ? `Enviar a ${nextPhase?.label || "Curaduría"}` : readiness.detail)}"><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span> Enviar</button>` : ""}
      </td>
    </tr>
  `;
}

