const RMS_COMMERCIAL_SUMMARY_PHASES = new Set(["curaduria", "clasificacion", "procesamiento", "accion_correctiva", "control_anti_fuga", "cierre", "postventa"]);

function rmsCommercialSummaryStageLabel(phase = "") {
  return {
    curaduria: "Asignación",
    clasificacion: "Activación 1",
    procesamiento: "Evaluación",
    accion_correctiva: "Negociación",
    control_anti_fuga: "Riesgos de fuga",
    cierre: "Ventas atribuidas",
    postventa: "Valorización Clientes",
  }[phase] || "estación comercial";
}

function rmsCommercialSummaryReason(item = {}, phase = "") {
  const workflow = rmsCommercialWorkflow(item);
  const evaluation = workflow.evaluation || {};
  const response = String(evaluation.response || "").toUpperCase();
  const responseLabel = RMS_EVALUATION_RESPONSES.find((entry) => entry.value === response)?.short || response || "Sin respuesta registrada";
  const detail = [evaluation.need, evaluation.objections, evaluation.note].filter(Boolean).join(" · ");
  if (phase === "procesamiento") return detail ? `${responseLabel}: ${detail}` : `${responseLabel}: pendiente de decidir el siguiente paso.`;
  if (phase === "accion_correctiva") return detail ? `${responseLabel}: ${detail}` : `${responseLabel}: requiere acordar condiciones.`;
  if (phase === "control_anti_fuga") return detail ? `${responseLabel}: ${detail}` : `${responseLabel}: requiere proteger o recuperar el acuerdo.`;
  if (phase === "cierre") {
    const confirmation = workflow.confirmation || {};
    return confirmation.route === "NEGOTIATION_CLEAN"
      ? "Acuerdo limpio confirmado en Negociación."
      : response === "PAID_SALE"
        ? "Compra directa reportada desde Evaluación."
        : detail || "Venta liberada para registrar y atribuir.";
  }
  return detail || responseLabel;
}

function rmsCommercialStationSummaryMarkup(rows = [], phase = "") {
  const title = rmsCommercialSummaryStageLabel(phase);
  const isAssignment = phase === "curaduria";
  const isActivation = phase === "clasificacion";
  const isValuation = phase === "postventa";
  if (isActivation) {
    const tableRows = rows.map((item) => {
      const delivery = rmsActivationDelivery(item);
      const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
      const channel = delivery.channel === "email" ? "Email" : delivery.channel === "whatsapp" ? "WhatsApp" : "Sin canal";
      const offer = delivery.offer || rmsClassifiedProductName(item) || item.product_interest || "Sin oferta definida";
      const followUp = delivery.followUpAt ? formatDate(delivery.followUpAt) : "Sin seguimiento";
      const status = rmsActivationReadyForEvaluation(item)
        ? "Listo para Evaluación"
        : rmsActivationReady(item)
          ? "Respuesta pendiente"
          : delivery.sentAt
            ? "Seguimiento pendiente"
            : "Por activar";
      return `<tr><td><strong>${escapeHtml(item.name || "Contacto")}</strong><small>${escapeHtml(contact)}</small></td><td><strong>${escapeHtml(offer)}</strong><small>${escapeHtml(item.campaign_name || "Sin campaña")}</small></td><td><strong>${escapeHtml(channel)}</strong><small>${escapeHtml(delivery.sentAt ? formatDate(delivery.sentAt) : "Sin envío registrado")}</small></td><td><strong>${escapeHtml(rmsActivationOutcomeLabel(delivery.outcome))}</strong><small>${escapeHtml(followUp)}</small></td><td>${escapeHtml(status)}</td></tr>`;
    }).join("") || '<tr><td colspan="5">No hay leads en Activación 1.</td></tr>';
    return `<section class="rms-commercial-station-summary" aria-label="Resumen de Activación 1"><header><div><span class="mono-label">Resumen de estación</span><h4>Activación 1 · ${rows.length.toLocaleString("es-CO")} lead${rows.length === 1 ? "" : "s"}</h4><p>Consulta oferta, canal, respuesta y seguimiento antes de enviar la selección a Evaluación.</p></div><button class="ghost-button compact" type="button" data-rms-station-summary aria-expanded="true"><span class="material-symbols-outlined" aria-hidden="true">visibility_off</span> Ocultar resumen</button></header><div class="rms-commercial-summary-table-wrap"><table><thead><tr><th>Lead</th><th>Oferta</th><th>Canal y envío</th><th>Respuesta y seguimiento</th><th>Estado</th></tr></thead><tbody>${tableRows}</tbody></table></div></section>`;
  }
  if (isAssignment || isValuation) {
    const tableHead = isAssignment
      ? "<tr><th>Lead</th><th>Producto asignado</th><th>Interés declarado</th><th>Entrada</th><th>Estado</th></tr>"
      : "<tr><th>Cliente</th><th>Compra atribuida</th><th>Activación previa</th><th>Último movimiento</th><th>Estado</th></tr>";
    const tableRows = rows.map((item) => {
      const workflow = rmsCommercialWorkflow(item);
      const confirmation = workflow.confirmation || {};
      const activation = rmsActivationDelivery(item);
      const product = confirmation.product_name || rmsClassifiedProductName(item) || item.product_interest || "Sin producto definido";
      const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
      if (isAssignment) return `<tr><td><strong>${escapeHtml(item.name || "Contacto")}</strong><small>${escapeHtml(contact)}</small></td><td><strong>${escapeHtml(product)}</strong><small>${escapeHtml(rmsClassificationSourceLabel(item) || "Pendiente de confirmar")}</small></td><td>${escapeHtml(item.product_interest || item.top_interest || "Sin interés declarado")}</td><td>${escapeHtml(item.created_at ? formatDate(item.created_at) : "Sin fecha")}</td><td>${escapeHtml(rmsHasConfirmedProductClassification(item) ? "Listo para Activación 1" : "Completa la asignación")}</td></tr>`;
      const amount = confirmation.amount || item.state_metadata?.rms_attributed_sale_amount || 0;
      return `<tr><td><strong>${escapeHtml(item.name || "Cliente")}</strong><small>${escapeHtml(contact)}</small></td><td><strong>${escapeHtml(product)}</strong><small>${escapeHtml(amount ? money(amount) : "Valor registrado al atribuir")}</small></td><td>${escapeHtml(activation.offer || "Sin activación previa")}</td><td>${escapeHtml(item.last_interaction_at ? formatDate(item.last_interaction_at) : "Pendiente de valorización")}</td><td>${escapeHtml(workflow.risk?.result === "RECYCLE" ? "Reciclaje" : "Valorización activa")}</td></tr>`;
    }).join("") || `<tr><td colspan="5">No hay ${isValuation ? "clientes" : "leads"} en esta estación.</td></tr>`;
    const intro = isAssignment
      ? "Consulta la asignación de producto antes de activar a cada lead."
      : "Consulta los clientes atribuidos antes de activar recompra, referidos o fidelización.";
    return `<section class="rms-commercial-station-summary" aria-label="Resumen de ${escapeHtml(title)}"><header><div><span class="mono-label">Resumen de estación</span><h4>${escapeHtml(title)} · ${rows.length.toLocaleString("es-CO")} ${isValuation ? "cliente" : "lead"}${rows.length === 1 ? "" : "s"}</h4><p>${escapeHtml(intro)}</p></div><button class="ghost-button compact" type="button" data-rms-station-summary aria-expanded="true"><span class="material-symbols-outlined" aria-hidden="true">visibility_off</span> Ocultar resumen</button></header><div class="rms-commercial-summary-table-wrap"><table><thead>${tableHead}</thead><tbody>${tableRows}</tbody></table></div></section>`;
  }
  return `
    <section class="rms-commercial-station-summary" aria-label="Resumen de ${escapeHtml(title)}">
      <header>
        <div><span class="mono-label">Resumen de estación</span><h4>${escapeHtml(title)} · ${rows.length.toLocaleString("es-CO")} lead${rows.length === 1 ? "" : "s"}</h4><p>Consulta lo registrado en Evaluación antes de abrir una ficha o tomar la decisión comercial.</p></div>
        <button class="ghost-button compact" type="button" data-rms-station-summary aria-expanded="true"><span class="material-symbols-outlined" aria-hidden="true">visibility_off</span> Ocultar resumen</button>
      </header>
      <div class="rms-commercial-summary-table-wrap">
        <table>
          <thead><tr><th>Lead</th><th>Respuesta en Evaluación</th><th>Información u objeción</th><th>Producto y valor</th><th>Por qué está aquí</th></tr></thead>
          <tbody>${rows.map((item) => {
            const workflow = rmsCommercialWorkflow(item);
            const evaluation = workflow.evaluation || {};
            const confirmation = workflow.confirmation || {};
            const response = String(evaluation.response || "").toUpperCase();
            const responseLabel = RMS_EVALUATION_RESPONSES.find((entry) => entry.value === response)?.short || response || "Sin respuesta";
            const product = confirmation.product_name || evaluation.recommended_product || rmsClassifiedProductName(item) || item.product_interest || "Sin producto definido";
            const amount = confirmation.amount ?? evaluation.budget_amount ?? "";
            const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
            return `<tr><td><strong>${escapeHtml(item.name || "Contacto")}</strong><small>${escapeHtml(contact)}</small></td><td><strong>${escapeHtml(responseLabel)}</strong><small>${escapeHtml(evaluation.decision_maker || "Decisor sin registrar")}</small></td><td>${escapeHtml([evaluation.need, evaluation.objections, evaluation.note].filter(Boolean).join(" · ") || "Sin detalle adicional")}</td><td><strong>${escapeHtml(product)}</strong><small>${escapeHtml(amount ? `${money(amount)} ${confirmation.currency || evaluation.currency || "COP"}` : "Valor pendiente")}</small></td><td>${escapeHtml(rmsCommercialSummaryReason(item, phase))}</td></tr>`;
          }).join("") || `<tr><td colspan="5">No hay leads en esta estación.</td></tr>`}</tbody>
        </table>
      </div>
    </section>
  `;
}

function rmsEvaluationStationCardMarkup(item = {}) {
  const delivery = rmsActivationDelivery(item);
  const defaultProduct = rmsClassifiedProductName(item) || item.product_interest || "";
  const draft = rmsEvaluationCachedDraft(item.id);
  const evaluationProductId = draft.recommended_inventory_product_id || item.classified_product_id || "";
  const selectedResponse = draft.response || "";
  const selectedDestination = rmsEvaluationAutoDestination(selectedResponse) || draft.destination || "";
  const selectedResponseLabel = RMS_EVALUATION_RESPONSES.find((option) => option.value === selectedResponse)?.short || "Pendiente";
  const selectedDestinationLabel = selectedResponse && selectedDestination ? rmsEvaluationRoute(selectedResponse, selectedDestination).label : "Por elegir";
  const saveLabel = selectedDestination ? `Guardar y enviar a ${selectedDestinationLabel}` : "Elige una estación de destino";
  const contactSummary = delivery.sentAt
    ? `${delivery.channel === "email" ? "Email" : "WhatsApp"} enviado ${formatDate(delivery.sentAt)} · ${delivery.contactCount || 1} contacto(s)`
    : "No hay envío confirmado; revisa el historial antes de decidir.";
  return `
    <article class="rms-commercial-work-item rms-evaluation-work-item" data-rms-station-lead="${escapeHtml(item.id)}">
      ${rmsCommercialLeadAsideMarkup(item, "Evaluación · decide el siguiente destino")}
      <section class="rms-commercial-work-console">
        <header class="rms-evaluation-hero"><div class="rms-evaluation-hero-copy"><span class="mono-label" style="color:#ffffff !important;opacity:1 !important;">Estación 06 · Después de Activación 1</span><h4 style="color:#ffffff !important;opacity:1 !important;">Convierte la respuesta en una decisión comercial clara.</h4><p style="color:#ffffff !important;opacity:1 !important;">Documenta lo que dijo el cliente, define el destino y entrega al siguiente equipo un contexto que sí pueda ejecutar.</p><div class="rms-evaluation-hero-metrics"><div><span>Respuesta</span><strong data-rms-evaluation-response-label="${escapeHtml(item.id)}">${escapeHtml(selectedResponseLabel)}</strong></div><div><span>Destino</span><strong data-rms-evaluation-destination-label="${escapeHtml(item.id)}">${escapeHtml(selectedDestinationLabel)}</strong></div></div></div><div class="rms-evaluation-hero-signal"><span class="material-symbols-outlined" aria-hidden="true">insights</span><strong>${escapeHtml(delivery.sentAt ? "Contacto activo" : "Validar contacto")}</strong><small>${escapeHtml(delivery.sentAt ? "Ya existe un contacto para evaluar" : "Revisa el historial antes de registrar la decisión")}</small></div></header>
        <ol class="rms-evaluation-steps" aria-label="Flujo de evaluación"><li class="is-done"><b>1</b><span>Contexto</span></li><li class="${selectedResponse ? "is-done" : "is-active"}"><b>2</b><span>Respuesta</span></li><li class="${selectedDestination ? "is-done" : selectedResponse ? "is-active" : ""}"><b>3</b><span>Destino</span></li><li class="${selectedDestination ? "is-active" : ""}"><b>4</b><span>Contexto útil</span></li></ol>
        <section class="rms-evaluation-context" aria-label="Resumen de Activación 1"><span class="material-symbols-outlined" aria-hidden="true">history</span><div><strong>${escapeHtml(delivery.offer || defaultProduct || "Oferta comercial")}</strong><small>${escapeHtml(contactSummary)}</small></div><span class="rms-evaluation-context-outcome">${escapeHtml(rmsActivationOutcomeLabel(delivery.outcome))}</span></section>
        ${selectedResponse === "PAID_SALE" ? `<section class="rms-payment-reported-notice" aria-label="Pago informado"><span class="material-symbols-outlined" aria-hidden="true">verified</span><div><strong>Pago informado: falta confirmar la venta</strong><p>El cliente reportó un pago. Primero confirma producto, valor, condición acordada y soporte antes de atribuir la venta.</p></div><div><button class="solid-button compact" type="button" data-rms-payment-confirmation="${escapeHtml(item.id)}">Ir a confirmación comercial</button><button class="ghost-button compact" type="button" data-rms-payment-continue="${escapeHtml(item.id)}">Seguir evaluando</button></div></section>` : ""}
        <input type="hidden" data-rms-evaluation-response="${escapeHtml(item.id)}" value="${escapeHtml(selectedResponse)}">
        <input type="hidden" data-rms-evaluation-destination="${escapeHtml(item.id)}" value="${escapeHtml(selectedDestination)}">
        <section class="rms-evaluation-decision-panel" aria-label="Respuesta del cliente"><div class="rms-evaluation-panel-head"><div><span class="mono-label">Paso 2 · Lo que pasó</span><h5>¿Cuál fue el resultado de este contacto?</h5></div><small>Describe la realidad; la ruta la eliges después.</small></div><div class="rms-evaluation-decision-grid">${RMS_EVALUATION_RESPONSES.map((option) => `<button class="rms-evaluation-choice ${selectedResponse === option.value ? "is-selected" : ""}" type="button" data-rms-evaluation-choice="${escapeHtml(item.id)}" data-rms-evaluation-value="${option.value}" aria-pressed="${selectedResponse === option.value ? "true" : "false"}"><span class="material-symbols-outlined rms-evaluation-choice-icon" aria-hidden="true">${option.icon}</span><span class="rms-evaluation-choice-copy"><em>${escapeHtml(option.eyebrow)}</em><strong>${escapeHtml(option.title)}</strong><small>${escapeHtml(option.hint)}</small></span><span class="material-symbols-outlined rms-evaluation-choice-check" aria-hidden="true">check</span></button>`).join("")}</div></section>
        <section class="rms-evaluation-destination-panel" aria-label="Estación de destino"><div class="rms-evaluation-panel-head"><div><span class="mono-label" style="color:#ffffff !important;opacity:1 !important;">Paso 3 · Tu decisión</span><h5 style="color:#ffffff !important;opacity:1 !important;">¿A qué estación envías este lead?</h5></div><small style="color:#ffffff !important;opacity:1 !important;">La respuesta sugiere; tú decides</small></div><div class="rms-evaluation-destination-grid">${RMS_EVALUATION_DESTINATIONS.map((option) => `<button class="rms-evaluation-destination-choice ${selectedDestination === option.value ? "is-selected" : ""}" type="button" data-rms-evaluation-destination-choice="${escapeHtml(item.id)}" data-rms-evaluation-destination-value="${option.value}" aria-pressed="${selectedDestination === option.value ? "true" : "false"}"><span class="material-symbols-outlined" aria-hidden="true" style="color:#ffffff !important;opacity:1 !important;">${option.icon}</span><span><em style="color:#ffffff !important;opacity:1 !important;">${escapeHtml(option.eyebrow)}</em><strong style="color:#ffffff !important;opacity:1 !important;">${escapeHtml(option.label)}</strong><small style="color:#ffffff !important;opacity:1 !important;">${escapeHtml(option.hint)}</small></span><span class="material-symbols-outlined rms-evaluation-destination-arrow" aria-hidden="true" style="color:#ffffff !important;opacity:1 !important;">arrow_forward</span></button>`).join("")}</div></section>
        <aside class="rms-evaluation-route-preview" data-rms-evaluation-route="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">alt_route</span><div><span class="mono-label">Confirmación de ruta</span><strong>Elige una estación de destino</strong><small>La respuesta y el destino quedarán registrados en el historial del contacto.</small></div><span class="rms-evaluation-route-state" data-rms-evaluation-route-state="${escapeHtml(item.id)}">Pendiente</span></aside>
        <section class="rms-evaluation-next-panel ${selectedResponse && selectedDestination ? "is-visible" : ""}" data-rms-evaluation-next-panel="${escapeHtml(item.id)}"><div class="rms-evaluation-panel-head"><div><span class="mono-label">Paso 4 · Contexto de continuidad</span><h5>Deja el contexto mínimo útil</h5></div><small>El resumen es opcional; el sistema registra uno si no lo escribes.</small></div><div class="rms-evaluation-form-grid">
          <label data-rms-evaluation-detail="commercial"><span>Producto o servicio</span><select data-rms-evaluation-product-id="${escapeHtml(item.id)}" data-rms-evaluation-draft-field>${rmsInventoryProductPickerOptions(evaluationProductId, draft.recommended_product || defaultProduct)}</select><small>Elige el producto activo que se evaluó. Los textos históricos no se vinculan automáticamente.</small></label>
          <label data-rms-evaluation-detail="commercial"><span>Presupuesto</span><input type="number" min="0" step="0.01" value="${escapeHtml(draft.budget_amount ?? "")}" data-rms-evaluation-budget="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Opcional"></label>
          <label data-rms-evaluation-detail="commercial"><span>Moneda</span><select data-rms-evaluation-currency="${escapeHtml(item.id)}" data-rms-evaluation-draft-field>${RMS_CURRENCIES.map((currency) => `<option value="${currency}" ${(draft.currency || "COP") === currency ? "selected" : ""}>${currency}</option>`).join("")}</select></label>
          <label data-rms-evaluation-detail="commercial"><span>Decisor o influenciador</span><input type="text" value="${escapeHtml(draft.decision_maker || "")}" data-rms-evaluation-decision-maker="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Nombre, rol o pendiente"></label>
          <label data-rms-evaluation-detail="followup"><span>Próximo paso</span><input type="text" value="${escapeHtml(draft.next_action || rmsEvaluationDefaultNextAction(selectedResponse))}" data-rms-evaluation-next-action="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Ej.: Llamar para acordar dos cuotas"></label>
          <label data-rms-evaluation-detail="followup"><span>Fecha del próximo paso</span><input type="datetime-local" data-rms-evaluation-next-at="${escapeHtml(item.id)}" data-rms-evaluation-draft-field value="${escapeHtml(draft.next_action_at ? rmsSaleDatetimeLocal(draft.next_action_at) : rmsActivationDatetimeLocal("", 2))}"></label>
          <label><span>Urgencia</span><select data-rms-evaluation-urgency="${escapeHtml(item.id)}" data-rms-evaluation-draft-field><option value="LOW" ${(draft.urgency || "MEDIUM") === "LOW" ? "selected" : ""}>Baja</option><option value="MEDIUM" ${(draft.urgency || "MEDIUM") === "MEDIUM" ? "selected" : ""}>Media</option><option value="HIGH" ${(draft.urgency || "MEDIUM") === "HIGH" ? "selected" : ""}>Alta</option><option value="URGENT" ${(draft.urgency || "MEDIUM") === "URGENT" ? "selected" : ""}>Urgente</option></select></label>
          <label data-rms-evaluation-detail="followup"><span>Objeción o bloqueo</span><input type="text" value="${escapeHtml(draft.objections || "")}" data-rms-evaluation-objections="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Precio, plazo, confianza, competencia..."></label>
          <label data-rms-evaluation-detail="context"><span>Necesidad</span><input type="text" value="${escapeHtml(draft.need || "")}" data-rms-evaluation-need="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Qué necesita resolver"></label>
          <label data-rms-evaluation-detail="context"><span>Resultado esperado</span><input type="text" value="${escapeHtml(draft.desired_outcome || "")}" data-rms-evaluation-outcome="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Qué cambio espera"></label>
          <label data-rms-evaluation-detail="recycle"><span>Motivo de Reciclaje</span><select data-rms-evaluation-recycle-reason="${escapeHtml(item.id)}" data-rms-evaluation-draft-field><option value="" ${draft.recycle_reason ? "" : "selected"} disabled>Selecciona el motivo</option><option value="BUDGET" ${draft.recycle_reason === "BUDGET" ? "selected" : ""}>No tiene presupuesto</option><option value="TIMING" ${draft.recycle_reason === "TIMING" ? "selected" : ""}>No es el momento</option><option value="NOT_VIABLE_NOW" ${draft.recycle_reason === "NOT_VIABLE_NOW" ? "selected" : ""}>No es viable por ahora</option><option value="NO_RESPONSE" ${draft.recycle_reason === "NO_RESPONSE" ? "selected" : ""}>No responde tras los intentos</option><option value="OTHER" ${draft.recycle_reason === "OTHER" ? "selected" : ""}>Otro motivo</option></select></label>
          <label data-rms-evaluation-detail="recycle"><span>Revisar de nuevo el</span><input type="datetime-local" value="${escapeHtml(draft.recycle_at ? rmsSaleDatetimeLocal(draft.recycle_at) : rmsActivationDatetimeLocal("", 30))}" data-rms-evaluation-recycle-at="${escapeHtml(item.id)}" data-rms-evaluation-draft-field><small>El lead conserva su estación y aparece además en la cola de Reciclaje hasta que decidas reactivarlo.</small></label>
        </div>
        <label class="rms-commercial-note-field" data-rms-evaluation-detail="recycle"><span>Explica por qué no es convertible <small>(obligatorio para Reciclaje)</small></span><textarea rows="3" data-rms-evaluation-recycle-note="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Ej.: no tiene presupuesto este trimestre y no autorizó nuevos contactos.">${escapeHtml(draft.recycle_note || "")}</textarea></label>
        <label class="rms-commercial-note-field"><span>Resumen de lo que dijo el cliente <small>(opcional)</small></span><textarea rows="4" data-rms-evaluation-note="${escapeHtml(item.id)}" data-rms-evaluation-draft-field placeholder="Opcional: respuesta, condiciones y promesas hechas. Quedará en el historial del contacto.">${escapeHtml(draft.note || "")}</textarea></label></section>
        <div class="rms-commercial-action-row"><small><span class="material-symbols-outlined" aria-hidden="true">history</span>La decisión y el destino se guardan en la ficha del contacto.</small><button class="solid-button compact" type="button" data-rms-save-evaluation="${escapeHtml(item.id)}" ${selectedResponse && selectedDestination ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span><span data-rms-evaluation-save-label="${escapeHtml(item.id)}">${escapeHtml(saveLabel)}</span></button></div>
      </section>
    </article>
  `;
}

function rmsCommercialWorkflow(item = {}) {
  const metadata = item.state_metadata || item.metadata || item.rms_metadata || {};
  return { evaluation: metadata.rms_evaluation || {}, confirmation: metadata.commercial_confirmation || {}, risk: metadata.risk_review || {}, riskHandoff: metadata.risk_sale_handoff || {} };
}

function rmsRiskRecoveryPresentation(risk = {}, metadata = {}) {
  const handoff = metadata.risk_sale_handoff || {};
  const offer = handoff.recovery_offer || risk.recovery_offer || metadata.recovery_offer || {};
  const custom = offer.custom_benefit || {};
  const type = String(offer.type || "NONE").toUpperCase();
  const label = type === "DISCOUNT"
    ? `Descuento extraordinario del ${Number(offer.discount_percent || 0)}%`
    : type === "TWO_FOR_ONE"
      ? (offer.detail || "Beneficio extraordinario 2x1")
      : type === "GIFT"
        ? (offer.detail || "Obsequio extraordinario")
        : type === "CUSTOM"
          ? (custom.label || offer.detail || "Beneficio extraordinario personalizado")
          : "Sin beneficio extraordinario";
  const benefitType = type === "DISCOUNT" || custom.type === "DISCOUNT"
    ? "DISCOUNT"
    : type === "GIFT" || custom.type === "GIFT"
      ? "GIFT"
      : ["TWO_FOR_ONE", "CUSTOM"].includes(type)
        ? "BONUS"
        : "NONE";
  const explicitCost = [custom.effective_cost_cop, custom.cost_cop, custom.cost, offer.effective_cost_cop, offer.cost_cop]
    .map(Number)
    .find((value) => Number.isFinite(value) && value >= 0);
  const resource = handoff.recovery_resource || risk.recovery_resource || metadata.risk_recovery_resource || null;
  const ticketAction = handoff.ticket_action || risk.ticket_action || "NONE";
  const ticketActionLabel = ({ REMIND_ACTIVE: "Recordar ticket activo", PREPARE_NEW_ACTIVATION: "Preparar nueva activación", CONFIRM_REDEMPTION: "Confirmar redención", NONE: "Sin acción adicional de ticket" })[ticketAction] || ticketAction;
  const signals = handoff.signals || risk.signals || {};
  const signalCount = Object.values(signals).filter(Boolean).length;
  return {
    decision: handoff.decision || risk.result || "",
    reason: handoff.reason || risk.reason || "",
    responsible: handoff.responsible || risk.responsible || risk.confirmation_snapshot?.responsible || "",
    reviewedAt: handoff.reviewed_at || risk.reviewed_at || "",
    offer,
    label,
    benefitType,
    benefitCost: explicitCost ?? 0,
    ticketAction,
    ticketActionLabel,
    resource,
    signalCount,
  };
}

function rmsDealProgressMarkup(active = "evaluation", detail = "") {
  const steps = [["evaluation", "1", "Evaluación"], ["confirmation", "2", "Confirmación comercial"], ["risk", "3", "Validación anti-fuga"], ["sale", "4", "Venta atribuida"]];
  const activeIndex = steps.findIndex(([key]) => key === active);
  return `<section class="rms-deal-progress" aria-label="Progreso comercial"><ol>${steps.map(([key, number, label], index) => `<li class="${index < activeIndex ? "is-done" : index === activeIndex ? "is-active" : ""}"><b>${escapeHtml(number)}</b><span>${escapeHtml(label)}</span></li>`).join("")}</ol><p>${escapeHtml(detail)}</p></section>`;
}

const RMS_NEGOTIATION_TABS = [
  { key: "conversion", label: "Conversi\u00f3n", icon: "paid", result: "ACCEPTED", route: "NEGOTIATION_CLEAN", detail: "Confirma la venta y env\u00eda los datos a Ventas atribuidas." },
  { key: "risk", label: "Riesgos de fuga", icon: "shield", result: "ACCEPTED", route: "NEEDS_RISK_REVIEW", detail: "Protege el acuerdo antes de atribuir la venta." },
  { key: "recycle", label: "Reciclaje", icon: "autorenew", result: "RECYCLE", route: "NEEDS_RISK_REVIEW", detail: "Documenta por qu\u00e9 no convirti\u00f3 y programa una reactivaci\u00f3n permitida." },
  { key: "followup", label: "Espera o p\u00e9rdida", icon: "schedule", result: "WAITING", route: "NEEDS_RISK_REVIEW", detail: "Conserva seguimiento, reproceso o p\u00e9rdida sin mezclarlo con una venta." },
];

function rmsNegotiationTabsMarkup(item = {}) {
  return `<section class="rms-negotiation-tabs" data-rms-negotiation-tabs="${escapeHtml(item.id)}" aria-label="Decisi\u00f3n de Negociaci\u00f3n">
    <header><span class="mono-label">Elige la condici\u00f3n real</span><strong>Cada ruta muestra solo los datos que necesita.</strong></header>
    <div role="tablist">${RMS_NEGOTIATION_TABS.map((tab, index) => `<button type="button" role="tab" aria-selected="${index === 0 ? "true" : "false"}" class="${index === 0 ? "is-active" : ""}" data-rms-negotiation-tab="${escapeHtml(item.id)}" data-rms-negotiation-tab-key="${tab.key}"><span class="material-symbols-outlined" aria-hidden="true">${tab.icon}</span><span><strong>${escapeHtml(tab.label)}</strong><small>${escapeHtml(tab.detail)}</small></span></button>`).join("")}</div>
  </section>
  <aside class="rms-negotiation-cost-card" data-rms-nonconversion-cost="${escapeHtml(item.id)}" hidden><span class="material-symbols-outlined" aria-hidden="true">analytics</span><div><strong>Costo efectivo de no conversi\u00f3n</strong><p>Calculando solo descuentos y beneficios ya redimidos…</p></div></aside>`;
}

// Renderizador histórico. Se mantiene temporalmente por compatibilidad, pero
// la estación Negociación usa exclusivamente la versión compacta más abajo.
function rmsCommercialConfirmationStationCardMarkupLegacy(item = {}) {
  const flow = rmsCommercialWorkflow(item);
  const evaluation = flow.evaluation;
  const confirmation = flow.confirmation;
  const negotiation = (item.state_metadata || {}).negotiation_current || {};
  const history = Array.isArray((item.state_metadata || {}).negotiation_history) ? (item.state_metadata || {}).negotiation_history.slice(-4).reverse() : [];
  const product = confirmation.product_name || evaluation.recommended_product || rmsClassifiedProductName(item) || item.product_interest || "";
  const productId = confirmation.inventory_product_id || evaluation.recommended_inventory_product_id || item.classified_product_id || "";
  const amount = confirmation.amount ?? evaluation.budget_amount ?? "";
  const currency = confirmation.currency || evaluation.currency || "COP";
  const paymentReported = evaluation.response === "PAID_SALE";
  const scenarioLabel = evaluation.scenario === "EASY_CLOSE" ? "Venta fácil por Activación 1" : "Negociación asistida";
  const status = confirmation.status === "CONFIRMED" ? "Acuerdo confirmado" : negotiation.result === "WAITING" ? "Esperando respuesta" : negotiation.result === "REPROCESS" ? "Requiere nueva propuesta" : negotiation.result === "LOST" ? "Perdido" : paymentReported ? "Pago informado" : "En negociación";
  const initialDraft = {
    inventory_product_id: productId,
    product_name: product,
    amount: Number(amount || 0),
    payment_reference: confirmation.payment_reference || "",
    evidence: confirmation.evidence || "",
    responsible: confirmation.responsible || "",
    customer_condition: negotiation.customer_condition || confirmation.negotiation?.customer_condition || "",
    proposal: negotiation.proposal || confirmation.negotiation?.proposal || "",
    concession: negotiation.concession || confirmation.negotiation?.concession || "",
    channel: negotiation.channel || confirmation.negotiation?.channel || "",
    summary: confirmation.note || negotiation.summary || "",
    objection_type: negotiation.objection_type || confirmation.negotiation?.objection_type || "OTHER",
    objection_status: negotiation.objection_status || confirmation.negotiation?.objection_status || "NOT_APPLICABLE",
    objection_resolution: negotiation.objection_resolution || confirmation.negotiation?.objection_resolution || "",
  };
  const health = rmsNegotiationCleanHealth(item, initialDraft);
  const riskSuggested = health.requiresRisk;
  const recommendedRoute = riskSuggested ? "NEEDS_RISK_REVIEW" : "NEGOTIATION_CLEAN";
  return `
    <article class="rms-commercial-work-item rms-confirmation-work-item" data-rms-station-lead="${escapeHtml(item.id)}">
      ${rmsCommercialLeadAsideMarkup(item, "Estación 07 · Negociación")}
      <section class="rms-commercial-work-console">
        ${rmsDealProgressMarkup("confirmation", "Estás confirmando la condición comercial antes de proteger la venta.")}
        <header class="rms-commercial-console-head"><div><span class="mono-label">Estación 07 · Negociación · ${escapeHtml(scenarioLabel)}</span><h4>${escapeHtml(paymentReported ? "Pago informado · pendiente de confirmación comercial" : status)}</h4><p>${escapeHtml(paymentReported ? "El cliente reportó un pago. Confirma producto, valor, condición acordada y soporte antes de decidir entre venta limpia o protección anti-fuga." : "Confirma la condición comercial y decide si la venta puede atribuirse limpia o requiere protección anti-fuga.")}</p></div><span class="rms-commercial-state ${status === "Perdido" ? "is-risk" : paymentReported ? "is-pending" : ""}">${escapeHtml(status)}</span></header>
        <aside class="rms-negotiation-intent-strip"><span class="material-symbols-outlined" aria-hidden="true">handshake</span><div><span>Lo importante ahora</span><strong>Confirma que la promesa y el soporte coinciden.</strong><small>Negociar no es presionar: es dejar una condición clara que el cliente pueda reconocer y el equipo pueda cumplir.</small></div></aside>
        ${rmsNegotiationTabsMarkup(item)}
        <section class="rms-commercial-info-block rms-negotiation-context-block"><h5>A. Contexto heredado</h5><dl><div><dt>Respuesta u objeción</dt><dd>${escapeHtml(paymentReported ? "Reportó que ya realizó el pago" : evaluation.objections || evaluation.note || "Sin respuesta registrada")}</dd></div><div><dt>Oferta o producto</dt><dd>${escapeHtml(product || "Pendiente de confirmar")}</dd></div><div><dt>Valor previo</dt><dd>${escapeHtml(amount ? `${amount} ${currency}` : "Pendiente")}</dd></div><div><dt>Canal y último contacto</dt><dd>${escapeHtml(rmsActivationDelivery(item).channel === "email" ? "Email" : "WhatsApp")}</dd></div><div><dt>Campaña u origen</dt><dd>${escapeHtml(item.campaign_name || item.source_detail || item.source_type || "Sin origen definido")}</dd></div><div><dt>Retorno de Riesgos</dt><dd>${escapeHtml(flow.risk?.result === "RETURN_TO_NEGOTIATION" ? `Caso devuelto: ${flow.risk.reason || "requiere ajuste"}` : "No aplica")}</dd></div></dl></section>
        <section class="rms-commercial-info-block rms-negotiation-condition-block"><h5>B. Condición comercial y ronda actual</h5><div class="rms-sale-form-grid"><label><span>Objetivo de la ronda</span><input type="text" value="${escapeHtml(negotiation.objective || "Confirmar condición comercial")}" data-rms-negotiation-objective="${escapeHtml(item.id)}"></label><label><span>Tipo de objeción</span><select data-rms-negotiation-objection="${escapeHtml(item.id)}"><option value="PRICE" ${initialDraft.objection_type === "PRICE" ? "selected" : ""}>Precio</option><option value="PAYMENT" ${initialDraft.objection_type === "PAYMENT" ? "selected" : ""}>Condiciones de pago</option><option value="TIME" ${initialDraft.objection_type === "TIME" ? "selected" : ""}>Tiempo</option><option value="SCOPE" ${initialDraft.objection_type === "SCOPE" ? "selected" : ""}>Alcance o producto</option><option value="TRUST" ${initialDraft.objection_type === "TRUST" ? "selected" : ""}>Confianza</option><option value="COMPETITION" ${initialDraft.objection_type === "COMPETITION" ? "selected" : ""}>Competencia</option><option value="OTHER" ${initialDraft.objection_type === "OTHER" ? "selected" : ""}>Otra / sin objeción</option></select></label><label><span>Estado de la objeción</span><select data-rms-negotiation-objection-status="${escapeHtml(item.id)}"><option value="NOT_APPLICABLE" ${initialDraft.objection_status === "NOT_APPLICABLE" ? "selected" : ""}>No aplica</option><option value="PENDING" ${initialDraft.objection_status === "PENDING" ? "selected" : ""}>Pendiente</option><option value="RESOLVED" ${initialDraft.objection_status === "RESOLVED" ? "selected" : ""}>Resuelta</option><option value="NEEDS_VALIDATION" ${initialDraft.objection_status === "NEEDS_VALIDATION" ? "selected" : ""}>Requiere validación adicional</option></select></label><label><span>Condición inicial del cliente</span><input type="text" value="${escapeHtml(initialDraft.customer_condition)}" data-rms-negotiation-condition="${escapeHtml(item.id)}" placeholder="Qué pidió o confirmó"></label><label><span>Propuesta o contraoferta</span><input type="text" value="${escapeHtml(initialDraft.proposal)}" data-rms-negotiation-proposal="${escapeHtml(item.id)}" placeholder="Qué se ofreció"></label><label><span>Beneficio o concesión</span><input type="text" value="${escapeHtml(initialDraft.concession)}" data-rms-negotiation-concession="${escapeHtml(item.id)}" placeholder="Opcional"></label><label><span>Canal de contacto</span><select data-rms-negotiation-channel="${escapeHtml(item.id)}"><option value="WHATSAPP" ${initialDraft.channel === "WHATSAPP" ? "selected" : ""}>WhatsApp</option><option value="EMAIL" ${initialDraft.channel === "EMAIL" ? "selected" : ""}>Email</option><option value="CALL" ${initialDraft.channel === "CALL" ? "selected" : ""}>Llamada</option><option value="MEETING" ${initialDraft.channel === "MEETING" ? "selected" : ""}>Reunión</option><option value="OTHER" ${initialDraft.channel === "OTHER" || !initialDraft.channel ? "selected" : ""}>Otro</option></select></label><label><span>Producto o servicio final</span><select data-rms-confirm-product="${escapeHtml(item.id)}">${rmsInventoryProductPickerOptions(productId, product)}</select><small>Selecciona el producto activo del inventario; el nombre y precio histórico quedan como evidencia.</small></label><label><span>Valor final esperado</span><input type="number" min="1" step="0.01" value="${escapeHtml(amount)}" data-rms-confirm-amount="${escapeHtml(item.id)}" placeholder="0"></label><label><span>Moneda</span><select data-rms-confirm-currency="${escapeHtml(item.id)}">${RMS_CURRENCIES.map((code) => `<option value="${code}" ${currency === code ? "selected" : ""}>${code}</option>`).join("")}</select></label><label><span>Referencia de pago</span><input type="text" value="${escapeHtml(confirmation.payment_reference || "")}" data-rms-confirm-reference="${escapeHtml(item.id)}" placeholder="Factura, link o referencia"></label><label><span>Responsable</span><input type="text" value="${escapeHtml(confirmation.responsible || "")}" data-rms-confirm-responsible="${escapeHtml(item.id)}" placeholder="Quien confirmó"></label><label><span>Próximo contacto</span><input type="datetime-local" value="${escapeHtml(rmsActivationDatetimeLocal(negotiation.next_action_at || "", 2))}" data-rms-negotiation-next-at="${escapeHtml(item.id)}"></label></div><label class="rms-commercial-note-field" data-rms-objection-resolution-wrap="${escapeHtml(item.id)}"><span>Cómo se resolvió la objeción</span><textarea rows="2" data-rms-negotiation-objection-resolution="${escapeHtml(item.id)}" placeholder="Propuesta, evidencia o condición verificable">${escapeHtml(initialDraft.objection_resolution)}</textarea></label><label class="rms-commercial-note-field"><span>Evidencia, referencia o comprobante</span><textarea rows="3" data-rms-confirm-evidence="${escapeHtml(item.id)}" placeholder="Link, número de factura, soporte o detalle verificable">${escapeHtml(confirmation.evidence || "")}</textarea></label><label class="rms-commercial-note-field"><span>Resumen de conversación y condición acordada</span><textarea rows="3" data-rms-confirm-note="${escapeHtml(item.id)}" placeholder="Qué dijo el cliente, qué se acordó y qué falta">${escapeHtml(confirmation.note || negotiation.summary || "")}</textarea></label></section>
        <section class="rms-commercial-info-block rms-negotiation-health" data-rms-negotiation-health="${escapeHtml(item.id)}">${rmsNegotiationCleanHealthMarkup(item, initialDraft)}</section>
        <section class="rms-commercial-info-block rms-negotiation-decision-block"><h5>D. Decisión y destino</h5><label><span>Resultado de esta ronda</span><select data-rms-negotiation-result="${escapeHtml(item.id)}"><option value="ACCEPTED">Acuerdo confirmado</option><option value="WAITING">Esperar respuesta</option><option value="REPROCESS">Requiere nueva propuesta</option><option value="NO_RESPONSE">Sin respuesta</option><option value="RECYCLE">No convierte hoy, pero es recuperable</option><option value="LOST">Pérdida definitiva</option></select></label><label data-rms-negotiation-route-wrap="${escapeHtml(item.id)}"><span>Ruta de acuerdo</span><select data-rms-negotiation-route="${escapeHtml(item.id)}"><option value="NEGOTIATION_CLEAN" ${recommendedRoute === "NEGOTIATION_CLEAN" ? "selected" : ""}>Venta limpia · enviar a Ventas atribuidas</option><option value="NEEDS_RISK_REVIEW" ${recommendedRoute === "NEEDS_RISK_REVIEW" ? "selected" : ""}>Acuerdo frágil · enviar a Riesgos de fuga</option></select><small>${riskSuggested ? "Hay una señal que exige proteger el acuerdo antes de atribuir." : "No hay señal crítica abierta; puedes confirmar una venta limpia cuando completes el checklist."}</small></label><label data-rms-negotiation-reprocess-wrap="${escapeHtml(item.id)}"><span>Destino de reproceso</span><select data-rms-negotiation-reprocess="${escapeHtml(item.id)}"><option value="procesamiento">Evaluación</option><option value="clasificacion">Activación 1</option></select></label><label data-rms-negotiation-recycle-wrap="${escapeHtml(item.id)}"><span>Motivo de reciclaje</span><select data-rms-negotiation-recycle-reason="${escapeHtml(item.id)}"><option value="TIMING">Momento inadecuado</option><option value="BUDGET">Presupuesto</option><option value="NO_RESPONSE">Sin respuesta</option><option value="WAITING_DECISION">Espera de decisión</option><option value="NOT_VIABLE_NOW">Condición no viable hoy</option><option value="OTHER">Otro</option></select></label><label data-rms-negotiation-recycle-wrap="${escapeHtml(item.id)}"><span>Estrategia de reactivación</span><select data-rms-negotiation-recycle-strategy="${escapeHtml(item.id)}"><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva activación</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option><option value="NURTURE">Nutrición comercial</option></select></label><label data-rms-negotiation-recycle-wrap="${escapeHtml(item.id)}"><span>Consentimiento y canal permitido</span><select data-rms-negotiation-recycle-consent="${escapeHtml(item.id)}"><option value="CONFIRMED">Consentimiento confirmado</option><option value="NOT_REQUIRED">No requiere nuevo contacto</option></select></label><label data-rms-negotiation-lost-wrap="${escapeHtml(item.id)}"><span>Clasificación de pérdida</span><select data-rms-negotiation-lost-classification="${escapeHtml(item.id)}"><option value="DEFINITIVE">Rechazo definitivo</option><option value="NOT_NOW">No es el momento</option><option value="NO_BUDGET">Sin presupuesto</option><option value="PROLONGED_NO_RESPONSE">Sin respuesta prolongada</option><option value="NO_CONSENT">Sin consentimiento</option><option value="OTHER">Otro</option></select></label><label class="rms-commercial-note-field"><span>Motivo de la decisión</span><textarea rows="3" data-rms-negotiation-reason="${escapeHtml(item.id)}" placeholder="Obligatorio: explica acuerdo, espera, retorno, reciclaje o pérdida"></textarea></label></section>
        <aside class="rms-negotiation-route-preview" data-rms-negotiation-preview="${escapeHtml(item.id)}"><strong>Siguiente paso: Riesgos de fuga</strong><small>Se validará evidencia, condición, contacto y posibles bloqueos antes de atribuir la venta.</small></aside>
        <section class="rms-commercial-info-block rms-negotiation-history"><h5>Historial comercial</h5>${rmsNegotiationTimelineMarkup(item, history, evaluation, confirmation, flow.risk)}</section>
        <div class="rms-commercial-action-row"><small data-rms-negotiation-help="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">verified_user</span>Completa la condición, producto, valor, canal, evidencia, responsable y resumen antes de confirmar.</small><button class="solid-button compact" type="button" data-rms-save-negotiation-decision="${escapeHtml(item.id)}" data-rms-negotiation-cta-button="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span><span data-rms-negotiation-cta="${escapeHtml(item.id)}">Confirmar acuerdo y enviar a Riesgos de fuga</span></button></div>
      </section>
    </article>`;
}

function rmsRiskTabsMarkup(item = {}) {
  return `<section class="rms-risk-tabs" data-rms-risk-tabs="${escapeHtml(item.id)}" aria-label="Decisión de Riesgos de fuga"><header><span class="mono-label">Elige el destino del acuerdo</span><strong>Solo una decisión por vez.</strong></header><div role="tablist"><button class="is-active" type="button" role="tab" aria-selected="true" data-rms-risk-tab="${escapeHtml(item.id)}" data-rms-risk-tab-key="sale"><span class="material-symbols-outlined" aria-hidden="true">paid</span><span><strong>Liberar venta</strong><small>Enviar a Ventas atribuidas.</small></span></button><button type="button" role="tab" aria-selected="false" data-rms-risk-tab="${escapeHtml(item.id)}" data-rms-risk-tab-key="recycle"><span class="material-symbols-outlined" aria-hidden="true">autorenew</span><span><strong>Reciclar lead</strong><small>Explicar qué ocurrió y cuándo retomarlo.</small></span></button></div></section><aside class="rms-negotiation-cost-card" data-rms-nonconversion-cost="${escapeHtml(item.id)}" hidden><span class="material-symbols-outlined" aria-hidden="true">analytics</span><div><strong>Costo efectivo de no conversión</strong><p>Calculando solo descuentos y beneficios ya redimidos…</p></div></aside>`;
}

function rmsRiskValidationStationCardMarkup(item = {}) {
  const flow = rmsCommercialWorkflow(item);
  const confirmation = flow.confirmation;
  const hasSupport = Boolean(confirmation.evidence || confirmation.payment_reference || confirmation.note);
  const contact = Boolean(item.phone || item.email);
  const checks = [[hasSupport, "Pago o evidencia consistente"], [Boolean(confirmation.product_name) && Number(confirmation.amount) > 0, "Producto y valor confirmados"], [contact && Boolean(confirmation.responsible), "Contacto y responsable identificados"], [!flow.risk?.critical_open, "Sin bloqueo crítico abierto"]];
  const ready = checks.every(([value]) => value);
  const ticketStatus = item.redeemed_tickets ? "Beneficio usado; falta confirmar resultado comercial" : item.expired_tickets ? "Ticket vencido: no se reactiva" : item.active_tickets ? "Ticket activo: revisa su vigencia antes de contactar" : "No hay incentivo activo";
  return `<article class="rms-commercial-work-item rms-risk-work-item" data-rms-station-lead="${escapeHtml(item.id)}">${rmsCommercialLeadAsideMarkup(item, "Estación 08 · Riesgos de fuga")}<section class="rms-commercial-work-console">${rmsDealProgressMarkup("risk", "La venta está confirmada; revisa riesgos antes de registrarla como atribuida.")}<header class="rms-commercial-console-head"><div><span class="mono-label">ESTACIÓN 08 · RIESGOS DE FUGA</span><h4>Protege acuerdos antes de atribuir la venta</h4><p>Confirma que el cliente, la condición y la evidencia siguen vigentes antes de registrar el resultado comercial.</p></div><span class="rms-commercial-state ${ready ? "is-sale" : "is-pending"}">${ready ? "Listo para atribución" : "Requiere decisión"}</span></header><section class="rms-commercial-info-block"><h5>A. Acuerdo que se está protegiendo</h5><dl><div><dt>Producto</dt><dd>${escapeHtml(confirmation.product_name || "Pendiente")}</dd></div><div><dt>Valor</dt><dd>${escapeHtml(confirmation.amount ? `${confirmation.amount} ${confirmation.currency || "COP"}` : "Pendiente")}</dd></div><div><dt>Condición</dt><dd>${escapeHtml(confirmation.negotiation?.customer_condition || confirmation.note || "Pendiente")}</dd></div><div><dt>Responsable</dt><dd>${escapeHtml(confirmation.responsible || "Pendiente")}</dd></div><div><dt>Ticket / Reward Pass</dt><dd>${escapeHtml(ticketStatus)}</dd></div><div><dt>Campaña</dt><dd>${escapeHtml(item.campaign_name || item.source_detail || "Sin campaña")}</dd></div></dl></section><section class="rms-risk-checklist" aria-label="Señales de fuga">${checks.map(([value, label]) => `<div class="${value ? "is-ready" : "is-pending"}"><span class="material-symbols-outlined" aria-hidden="true">${value ? "check_circle" : "pending"}</span><strong>${escapeHtml(label)}</strong><small>${value ? "Listo" : "Atención: revísalo antes de atribuir"}</small></div>`).join("")}${item.redeemed_tickets ? `<div class="is-pending"><span class="material-symbols-outlined" aria-hidden="true">confirmation_number</span><strong>Ticket redimido sin venta atribuida</strong><small>Atención: confirma compra o condición final.</small></div>` : ""}</section><section class="rms-commercial-info-block"><h5>B. Decisión final</h5><label><span>Decisión de riesgo</span><select data-rms-risk-decision="${escapeHtml(item.id)}"><option value="CLEARED">Liberar para Ventas atribuidas</option><option value="RETURN_TO_NEGOTIATION">Devolver a Negociación</option><option value="WAITING">Mantener en seguimiento</option><option value="RECYCLE">Enviar a Reciclaje comercial</option><option value="LOST">Marcar pérdida definitiva</option></select></label><label><span>Acción sobre ticket o beneficio</span><select data-rms-risk-ticket-action="${escapeHtml(item.id)}"><option value="NONE">Sin acción sobre ticket</option>${item.active_tickets ? '<option value="REMIND_ACTIVE">Recordar beneficio vigente</option>' : ""}${item.redeemed_tickets ? '<option value="CONFIRM_REDEMPTION">Confirmar resultado de ticket redimido</option>' : ""}${item.expired_tickets ? '<option value="PREPARE_NEW_ACTIVATION">Preparar nueva activación (sin modificar ticket)</option>' : ""}</select></label><label data-rms-risk-recycle-wrap="${escapeHtml(item.id)}"><span>Motivo de reciclaje</span><select data-rms-risk-recycle-reason="${escapeHtml(item.id)}"><option value="TIMING">Momento inadecuado</option><option value="BUDGET">Presupuesto</option><option value="NO_RESPONSE">Sin respuesta</option><option value="EXPIRED_TICKET">Ticket vencido</option><option value="WAITING_DECISION">Espera de decisión</option><option value="NOT_VIABLE_NOW">Condición no viable hoy</option><option value="OTHER">Otro</option></select></label><label data-rms-risk-recycle-wrap="${escapeHtml(item.id)}"><span>Estrategia de reactivación</span><select data-rms-risk-recycle-strategy="${escapeHtml(item.id)}"><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva activación</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option><option value="NURTURE">Nutrición comercial</option></select></label><label class="rms-commercial-note-field"><span>Motivo y nota de control</span><textarea rows="3" data-rms-risk-reason="${escapeHtml(item.id)}" placeholder="Explica qué protege, qué falta o por qué se recicla/pierde"></textarea></label><label><span>Próximo contacto o reactivación</span><input type="datetime-local" data-rms-risk-next-at="${escapeHtml(item.id)}" value="${escapeHtml(rmsActivationDatetimeLocal("", 1))}"></label></section><aside class="rms-negotiation-route-preview" data-rms-risk-preview="${escapeHtml(item.id)}"><strong>Siguiente paso: Ventas atribuidas</strong><small>Solo se libera cuando no existe una señal crítica abierta.</small></aside><div class="rms-commercial-action-row"><small>${ready ? "Puedes liberar con una nota de control. Si hay bloqueo, devuelve, programa, recicla o documenta la pérdida." : "Completa las señales críticas o toma una decisión explícita; nunca atribuyas una venta con un bloqueo abierto."}</small><button class="solid-button compact" type="button" data-rms-save-risk-decision="${escapeHtml(item.id)}">Guardar decisión de riesgo</button></div></section></article>`;
}

function rmsOpenRecyclingOpportunities(opportunities = []) {
  const activeStatuses = new Set(["RECYCLED", "SCHEDULED", "REACTIVATING"]);
  return (opportunities || []).filter((item) => {
    if (item.stage === "reciclaje") return true;
    return activeStatuses.has(String(item.state_metadata?.recycling?.status || "").toUpperCase());
  });
}

function rmsRecyclingQueueMarkup(opportunities = []) {
  const recycled = rmsOpenRecyclingOpportunities(opportunities);
  const now = Date.now();
  const buckets = {
    today: recycled.filter((item) => new Date(item.state_metadata?.recycling?.reactivate_at || 0).getTime() <= now),
    week: recycled.filter((item) => { const time = new Date(item.state_metadata?.recycling?.reactivate_at || 0).getTime(); return time > now && time <= now + 7 * 86400000; }),
  };
  return `<section class="rms-recycling-queue" aria-label="Reciclaje comercial"><header><div><span class="mono-label">COLA LATERAL</span><h4>Reciclaje comercial · oportunidades para reactivar</h4><p>Conserva el contexto. Al reactivar, el lead vuelve a Evaluación para recalificar la conversación actual.</p></div><span>${recycled.length} en reciclaje · ${buckets.today.length} para hoy</span></header><div class="rms-recycling-list">${recycled.map((item) => { const recycle = item.state_metadata?.recycling || {}; return `<article><div><strong>${escapeHtml(item.name || "Contacto")}</strong><small>${escapeHtml(recycle.reason || "Motivo pendiente")} · ${escapeHtml(recycle.strategy || "Estrategia pendiente")}</small><p>${escapeHtml(recycle.note || "Sin nota de reactivación")}</p></div><div><small>Reactivar: ${escapeHtml(recycle.reactivate_at ? formatDate(recycle.reactivate_at) : "Sin fecha")}</small><textarea rows="2" data-rms-recycle-note="${escapeHtml(item.id)}" placeholder="Contexto actualizado para volver a Evaluación"></textarea><button class="solid-button compact" type="button" data-rms-reactivate-recycled="${escapeHtml(item.id)}">Reactivar y enviar a Evaluación</button></div></article>`; }).join("") || "<p class=\"empty-state compact\">No hay oportunidades en Reciclaje comercial.</p>"}</div></section>`;
}

function rmsRiskStationMetricsMarkup(rows = [], allOpportunities = []) {
  const incomplete = rows.filter((item) => !rmsCommercialWorkflow(item).confirmation?.evidence && !rmsCommercialWorkflow(item).confirmation?.payment_reference && !rmsCommercialWorkflow(item).confirmation?.note);
  const today = rows.filter((item) => item.days_since_interaction >= 1 || item.redeemed_tickets > 0);
  const recoverable = rows.filter((item) => !rmsCommercialWorkflow(item).risk?.result || rmsCommercialWorkflow(item).risk?.result === "RETURN_TO_NEGOTIATION");
  const recycled = rmsOpenRecyclingOpportunities(allOpportunities);
  const released = (allOpportunities || []).filter((item) => item.stage === "cierre" && rmsCommercialWorkflow(item).risk?.result === "CLEARED");
  const cards = [
    { key: "today", label: "Revisar hoy", value: today.length, tone: "priority", title: "Casos que necesitan atención hoy", description: "Incluye leads con al menos un día sin interacción o con una redención que todavía exige comprobar el resultado comercial.", action: "Empieza por estos casos. Un número alto representa carga prioritaria, no ventas perdidas." },
    { key: "tickets", label: "Tickets por vencer / activos", value: rows.filter((item) => item.active_tickets > 0).length, tone: "attention", title: "Beneficios todavía vigentes", description: "Cuenta leads de Riesgos de fuga que tienen uno o más tickets activos. El ticket es una señal contextual y no confirma una venta por sí solo.", action: "Revisa vigencia y condición antes de contactar; no reactives ni cambies el ticket automáticamente." },
    { key: "redeemed", label: "Redimidos sin venta", value: rows.filter((item) => item.redeemed_tickets > 0 && !item.purchase_count).length, tone: "attention", title: "Beneficio usado sin venta atribuida", description: "Muestra clientes que redimieron un ticket, pero todavía no tienen una compra registrada y atribuida en Qori.", action: "Confirma si hubo compra, cuánto se pagó y qué producto se vendió. Si no hubo venta, documenta el resultado." },
    { key: "support", label: "Acuerdos sin soporte", value: incomplete.length, tone: "warning", title: "Acuerdos sin evidencia verificable", description: "Son casos sin comprobante, referencia de pago, evidencia ni nota comercial suficiente para entender qué se acordó.", action: "Obtén al menos una evidencia o una nota concreta antes de liberar la venta." },
    { key: "recoverable", label: "Recuperables en Negociación", value: recoverable.length, tone: "opportunity", title: "Oportunidades que aún pueden recuperarse", description: "Agrupa casos sin decisión final de Riesgos o con contexto comercial recuperable. No significa que la venta ya esté confirmada.", action: "Aplica únicamente una alternativa extraordinaria autorizada y registra la respuesta real del lead." },
    { key: "recycling", label: "Para Reciclaje", value: recycled.length, tone: "neutral", title: "Casos fuera del intento de cierre actual", description: "Cuenta oportunidades enviadas a Reciclaje porque no fue viable convertirlas ahora, pero su historial debe conservarse.", action: "Respeta la fecha y estrategia de reactivación. Al retomarlas deben volver a Evaluación." },
    { key: "released", label: "Liberados para atribución", value: released.length, tone: "success", title: "Ventas liberadas por Riesgos", description: "Son casos aprobados en Riesgos de fuga que ya están en Ventas atribuidas, pendientes de completar o confirmar el registro canónico de la compra.", action: "Registra producto, cantidad, pago y costos; después envía el cliente a Valorización." },
  ];
  return `<section class="rms-risk-metrics" aria-label="Métricas de acción">${cards.map((card) => {
    const popoverId = `rms-risk-kpi-${card.key}`;
    return `<article class="rms-risk-kpi is-${escapeHtml(card.tone)}" data-rms-risk-kpi="${escapeHtml(card.key)}"><div class="rms-risk-kpi-value"><strong>${escapeHtml(String(card.value))}</strong><span>${escapeHtml(card.label)}</span></div><button class="rms-risk-kpi-help" type="button" data-rms-risk-kpi-help aria-expanded="false" aria-controls="${popoverId}" aria-label="Explicar ${escapeHtml(card.label)}"><span class="material-symbols-outlined" aria-hidden="true">help</span></button><aside class="rms-risk-kpi-popover" id="${popoverId}" role="tooltip"><span class="mono-label">Cómo leer este indicador</span><strong>${escapeHtml(card.title)}</strong><p>${escapeHtml(card.description)}</p><small><b>Qué hacer:</b> ${escapeHtml(card.action)}</small></aside></article>`;
  }).join("")}</section>`;
}

function bindRmsRiskMetricPopovers(root) {
  root?.querySelectorAll("[data-rms-risk-kpi-help]").forEach((button) => {
    if (button.dataset.rmsRiskKpiBound === "true") return;
    button.dataset.rmsRiskKpiBound = "true";
    const card = button.closest("[data-rms-risk-kpi]");
    const close = () => {
      card?.classList.remove("is-explaining");
      button.setAttribute("aria-expanded", "false");
    };
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const willOpen = !card?.classList.contains("is-explaining");
      root.querySelectorAll("[data-rms-risk-kpi].is-explaining").forEach((item) => {
        item.classList.remove("is-explaining");
        item.querySelector("[data-rms-risk-kpi-help]")?.setAttribute("aria-expanded", "false");
      });
      card?.classList.toggle("is-explaining", willOpen);
      button.setAttribute("aria-expanded", String(willOpen));
    });
    card?.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        close();
        button.focus();
      }
    });
  });
  if (document.body && document.body.dataset.rmsRiskKpiDismissBound !== "true") {
    document.body.dataset.rmsRiskKpiDismissBound = "true";
    document.addEventListener("click", (event) => {
      if (event.target.closest("[data-rms-risk-kpi]")) return;
      document.querySelectorAll("[data-rms-risk-kpi].is-explaining").forEach((card) => {
        card.classList.remove("is-explaining");
        card.querySelector("[data-rms-risk-kpi-help]")?.setAttribute("aria-expanded", "false");
      });
    });
  }
}

function rmsAttributedSalePricing({ inventoryProduct = {}, quantity = 1, confirmation = {}, saleContext = {}, riskContext = {}, currency = "COP" } = {}) {
  const saleQuantity = Math.max(0.01, Number(quantity || 1));
  const originalUnitPrice = Math.max(0, Number(inventoryProduct?.unit_price || confirmation.product_price_snapshot || 0));
  const originalAmount = Math.round(originalUnitPrice * saleQuantity * 100) / 100;
  const confirmedAmount = Math.max(0, Number(confirmation.amount || 0));
  const confirmedQuantity = Math.max(0.01, Number(saleContext.quantity || 1));
  const productMatchesConfirmation = !confirmation.inventory_product_id || !inventoryProduct?.id || String(confirmation.inventory_product_id) === String(inventoryProduct.id);
  const negotiatedUnitPrice = confirmedAmount > 0 && productMatchesConfirmation
    ? confirmedAmount / confirmedQuantity
    : originalUnitPrice;
  const negotiatedAmount = Math.round(negotiatedUnitPrice * saleQuantity * 100) / 100;
  const riskDiscountPercent = Math.min(100, Math.max(0, Number(riskContext.offer?.discount_percent || 0)));
  const riskDiscountAmount = riskDiscountPercent > 0 ? Math.round(negotiatedAmount * riskDiscountPercent) / 100 : 0;
  const finalAmount = Math.max(0, Math.round((riskDiscountAmount > 0 ? negotiatedAmount - riskDiscountAmount : negotiatedAmount) * 100) / 100);
  const discountAmount = Math.max(0, Math.round((originalAmount - finalAmount) * 100) / 100);
  return {
    originalUnitPrice,
    originalAmount,
    negotiatedUnitPrice,
    negotiatedAmount,
    finalAmount,
    discountAmount,
    discountPercent: originalAmount > 0 ? Math.round((discountAmount / originalAmount) * 10000) / 100 : 0,
    currency,
    detail: saleContext.benefit_description || riskContext.offer?.label || "Beneficio negociado",
  };
}

function rmsAttributedSaleStationCardMarkup(item = {}) {
  const workflow = rmsCommercialWorkflow(item);
  const stateMetadata = item.state_metadata || item.metadata || item.rms_metadata || {};
  const confirmation = workflow.confirmation || {};
  const risk = workflow.risk || {};
  const riskContext = rmsRiskRecoveryPresentation(risk, stateMetadata);
  const negotiationResponse = (item.state_metadata || {}).negotiation_current || {};
  const evaluation = workflow.evaluation || {};
  const saleContext = confirmation.sale_context || negotiationResponse.sale_context || {};
  const activation = rmsActivationDelivery(item);
  const saleOrigin = riskContext.decision === "CLEARED"
    ? "Venta protegida y liberada desde Riesgos de fuga"
    : confirmation.route === "NEGOTIATION_CLEAN"
      ? "Venta limpia confirmada desde Negociación"
      : negotiationResponse.result === "ACCEPTED"
      ? "Compra confirmada por el cliente en Negociación"
      : evaluation.response === "PAID_SALE"
        ? "Pago informado desde Evaluación"
        : "Venta protegida y liberada desde Riesgos de fuga";
  // La confirmación es la fuente preferida, pero una compra directa desde
  // Evaluación o Negociación conserva el producto ya elegido en esas estaciones.
  const inheritedInventoryProductId = String(
    confirmation.inventory_product_id
      || evaluation.recommended_inventory_product_id
      || item.classified_product_id
      || item.inventory_product_id
      || ""
  );
  const inventoryProduct = findInventoryProductById(inheritedInventoryProductId);
  const defaultProduct = confirmation.product_name
    || evaluation.recommended_product
    || inventoryProduct?.name
    || rmsClassifiedProductName(item)
    || item.product_interest
    || "";
  const quantity = Math.max(0.01, Number(saleContext.quantity || 1));
  const unitCost = Math.max(0, Number(inventoryProduct?.cost_price || 0));
  const benefitType = String(saleContext.benefit_type || riskContext.benefitType || "NONE").toUpperCase();
  const benefitCost = Math.max(0, Number(saleContext.benefit_cost ?? riskContext.benefitCost ?? 0));
  const acquisitionCost = Math.max(0, Number(saleContext.acquisition_cost || 0));
  const inheritedAmount = confirmation.amount ?? evaluation.budget_amount ?? negotiationResponse.amount ?? "";
  const inheritedCurrency = confirmation.currency || evaluation.currency || negotiationResponse.currency || "COP";
  const pricing = rmsAttributedSalePricing({ inventoryProduct, quantity, confirmation, saleContext, riskContext, currency: inheritedCurrency });
  const inheritedChannel = confirmation.negotiation?.channel || negotiationResponse.channel || activation.channel || "";
  const inheritedResponsible = riskContext.responsible || confirmation.responsible || negotiationResponse.responsible || "";
  const evaluationResponse = RMS_EVALUATION_RESPONSES.find((entry) => entry.value === evaluation.response)?.short || evaluation.response || "Sin respuesta registrada";
  const activationDetail = [activation.offer || defaultProduct, activation.channel ? `por ${activation.channel}` : "", activation.outcome ? rmsActivationOutcomeLabel(activation.outcome) : ""].filter(Boolean).join(" · ");
  const evaluationDetail = [evaluationResponse, evaluation.need, evaluation.objections, evaluation.decision_maker].filter(Boolean).join(" · ");
  const negotiationDetail = [confirmation.negotiation?.customer_condition, inheritedChannel, inheritedResponsible, confirmation.payment_reference, negotiationResponse.reason].filter(Boolean).join(" · ");
  const riskDetail = [
    riskContext.decision === "CLEARED" ? "Venta liberada" : riskContext.decision,
    riskContext.reason,
    riskContext.label,
    riskContext.ticketActionLabel,
  ].filter(Boolean).join(" · ");
  const inheritedNotes = [
    evaluation.note && `Evaluación: ${evaluation.note}`,
    confirmation.payment_reference,
    confirmation.evidence,
    confirmation.note,
    saleContext.benefit_description && `Beneficio o esfuerzo comercial: ${saleContext.benefit_description}`,
    riskContext.decision && `Riesgos de fuga: ${riskContext.reason || "venta liberada"}`,
    riskContext.offer?.type && riskContext.offer.type !== "NONE" && `Alternativa extraordinaria aplicada: ${riskContext.label}`,
    riskContext.ticketAction !== "NONE" && `Acción sobre ticket: ${riskContext.ticketActionLabel}`,
    riskContext.resource?.public_ticket_url && `Ticket de recuperación: ${riskContext.resource.public_ticket_url}`,
    riskContext.responsible && `Responsable de liberación: ${riskContext.responsible}`,
  ].filter(Boolean).join(" · ");
  return `
    <article class="rms-commercial-work-item rms-sale-work-item" data-rms-station-lead="${escapeHtml(item.id)}">
      ${rmsCommercialLeadAsideMarkup(item, "Ventas atribuidas · evidencia de una compra real")}
      <section class="rms-commercial-work-console">
        <details class="rms-attributed-sale-entry" open>
          <summary>
            <span class="material-symbols-outlined" aria-hidden="true">point_of_sale</span>
            <span><strong>Registrar venta atribuida</strong><small>${escapeHtml([defaultProduct || "Producto por confirmar", inheritedAmount ? money(inheritedAmount) : "Valor por confirmar", inheritedChannel || "Canal por confirmar"].join(" · "))}</small></span>
            <span class="rms-attributed-sale-entry-action">Abrir</span>
          </summary>
          <div class="rms-attributed-sale-entry-body">
        ${rmsDealProgressMarkup("sale", "La validación final fue aprobada. Registra el resultado comercial.")}
        <section class="rms-sale-trust-ribbon"><span class="material-symbols-outlined" aria-hidden="true">verified</span><div><strong>Venta lista para atribuir</strong><small>${escapeHtml(saleOrigin)}. Producto, valor y evidencia fueron precargados.</small></div></section>
        <section class="rms-sale-price-journey" data-rms-sale-pricing="${escapeHtml(item.id)}" aria-label="Trazabilidad del precio"><header><div><span class="mono-label">TRAZABILIDAD DEL PRECIO</span><strong>Así se calculó lo que pagó el cliente</strong></div><span class="material-symbols-outlined" aria-hidden="true">receipt_long</span></header><div class="rms-sale-price-journey-track"><article><small>Precio original</small><strong data-rms-sale-original-price="${escapeHtml(item.id)}">${escapeHtml(rmsCommercialMoney(pricing.originalAmount, inheritedCurrency))}</strong><span>${escapeHtml(`${quantity} unidad(es) · ${rmsCommercialMoney(pricing.originalUnitPrice, inheritedCurrency)} c/u`)}</span></article><span class="material-symbols-outlined rms-sale-price-arrow" aria-hidden="true">arrow_forward</span><article class="is-benefit"><small>Beneficio negociado</small><strong data-rms-sale-discount="${escapeHtml(item.id)}">-${escapeHtml(rmsCommercialMoney(pricing.discountAmount, inheritedCurrency))}</strong><span data-rms-sale-discount-detail="${escapeHtml(item.id)}">${escapeHtml(pricing.detail)}</span></article><span class="material-symbols-outlined rms-sale-price-arrow" aria-hidden="true">arrow_forward</span><article class="is-final"><small>Precio final cobrado</small><strong data-rms-sale-final-price="${escapeHtml(item.id)}">${escapeHtml(rmsCommercialMoney(pricing.finalAmount, inheritedCurrency))}</strong><span data-rms-sale-final-detail="${escapeHtml(item.id)}">${pricing.discountPercent > 0 ? `${pricing.discountPercent}% menos` : "Valor confirmado"}</span></article></div><small class="rms-sale-price-journey-note">El descuento se arrastra desde la negociación o la liberación anti-fuga; el valor final es el que se registra como dinero recibido.</small></section>
        <header class="rms-commercial-console-head"><div><span class="mono-label">Compra confirmada</span><h4>Registra el pago y su rentabilidad</h4><p>La venta se atribuye a este contacto y a la ruta de Activación 1. Los costos son los que declare tu equipo.</p></div><span class="rms-commercial-state is-sale">Pago por registrar</span></header>
        <details class="rms-sale-handoff"><summary><span class="material-symbols-outlined" aria-hidden="true">route</span><span><strong>Ver información heredada</strong><small>Activación, Evaluación, Negociación y Riesgos de fuga quedan guardados. Ábrelo solo si necesitas revisar el contexto.</small></span></summary><div class="rms-sale-handoff-grid"><article><span>Activación</span><strong>${escapeHtml(activationDetail || "Sin detalle adicional")}</strong><small>${escapeHtml(activation.firstContactAt ? `Contacto ${formatDate(activation.firstContactAt)}` : "Sin fecha de contacto")}</small></article><article><span>Evaluación</span><strong>${escapeHtml(evaluationDetail || "Sin detalle adicional")}</strong><small>${escapeHtml(evaluation.next_action || "Sin próximo paso pendiente")}</small></article><article><span>Negociación</span><strong>${escapeHtml(negotiationDetail || "Venta confirmada")}</strong><small>${escapeHtml(confirmation.evidence ? "Evidencia registrada" : "Sin evidencia adicional")}</small></article><article class="rms-sale-handoff-risk"><span>Riesgos de fuga</span><strong>${escapeHtml(riskDetail || "No fue necesario intervenir")}</strong><small>${escapeHtml([riskContext.reviewedAt ? `Revisado ${formatDate(riskContext.reviewedAt)}` : "", riskContext.signalCount ? `${riskContext.signalCount} señal(es) revisada(s)` : ""].filter(Boolean).join(" · ") || "Sin revisión anti-fuga")}</small></article></div></details>
        <div class="rms-sale-form-grid">
          <label><span>Producto comprado</span><select data-rms-sale-product="${escapeHtml(item.id)}" aria-describedby="rms-sale-product-hint-${escapeHtml(item.id)}">${rmsInventoryProductPickerOptions(inheritedInventoryProductId, defaultProduct)}</select><small id="rms-sale-product-hint-${escapeHtml(item.id)}">Producto precargado desde ${escapeHtml(confirmation.inventory_product_id ? "Negociación" : evaluation.recommended_inventory_product_id ? "Evaluación" : "la asignación del lead")}. Cámbialo solo si el cliente compró otra referencia; Qori conservará ambas referencias en el historial.</small></label>
          <input type="hidden" value="${escapeHtml(defaultProduct)}" data-rms-sale-product-name="${escapeHtml(item.id)}">
          <label><span>Cantidad comprada</span><input type="number" min="0.01" step="0.01" value="${escapeHtml(String(quantity))}" data-rms-sale-quantity="${escapeHtml(item.id)}"></label>
          <label><span>Dinero recibido</span><input type="number" min="1" step="0.01" value="${escapeHtml(String(pricing.finalAmount || inheritedAmount || ""))}" data-rms-sale-amount="${escapeHtml(item.id)}" placeholder="0"></label>
          <label><span>Moneda</span><select data-rms-sale-currency="${escapeHtml(item.id)}">${RMS_CURRENCIES.map((currency) => `<option value="${currency}" ${currency === inheritedCurrency ? "selected" : ""}>${currency}</option>`).join("")}</select></label>
          <label><span>Costo unitario</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(unitCost))}" data-rms-sale-unit-cost="${escapeHtml(item.id)}"></label>
          <label><span>Medio de pago</span><select data-rms-sale-payment="${escapeHtml(item.id)}"><option value="TRANSFER">Transferencia</option><option value="CASH">Efectivo</option><option value="CARD">Tarjeta</option><option value="PAYMENT_LINK">Link de pago</option><option value="OTHER">Otro</option></select></label>
          <label><span>Beneficio usado</span><select data-rms-sale-benefit-type="${escapeHtml(item.id)}"><option value="NONE" ${benefitType === "NONE" ? "selected" : ""}>No se usó beneficio</option><option value="DISCOUNT" ${benefitType === "DISCOUNT" ? "selected" : ""}>Descuento</option><option value="GIFT" ${benefitType === "GIFT" ? "selected" : ""}>Obsequio</option><option value="BONUS" ${benefitType === "BONUS" ? "selected" : ""}>Bono / incentivo</option><option value="OTHER" ${benefitType === "OTHER" ? "selected" : ""}>Otro</option></select></label>
          <label><span>Costo del beneficio</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(benefitCost))}" data-rms-sale-benefit-cost="${escapeHtml(item.id)}"></label>
          <label><span>Costo de adquisición</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(acquisitionCost))}" data-rms-sale-acquisition-cost="${escapeHtml(item.id)}"></label>
          <label><span>Pago recibido el</span><input type="datetime-local" value="${escapeHtml(rmsSaleDatetimeLocal())}" data-rms-sale-paid-at="${escapeHtml(item.id)}"></label>
        </div>
        <label class="rms-commercial-note-field"><span>Evidencia y acuerdos de la venta</span><textarea rows="4" data-rms-sale-notes="${escapeHtml(item.id)}" placeholder="Explica condiciones, comprobante, factura, promesas y alertas de postventa.">${escapeHtml(inheritedNotes)}</textarea></label>
        <div class="rms-sale-economics" data-rms-sale-economics="${escapeHtml(item.id)}"></div>
        <aside class="rms-sale-intelligence-handoff"><span class="material-symbols-outlined" aria-hidden="true">workspace_premium</span><div><strong>Siguiente estación: Valorización Clientes</strong><small>Al registrar la venta, este cliente pasa a Valorización para trabajar referidos, afiliación, puntos, sellos o recompra. Inteligencia GOS recibe el resultado automáticamente para análisis.</small></div></aside>
        <div class="rms-commercial-action-row"><small><span class="material-symbols-outlined" aria-hidden="true">calculate</span>Utilidad neta = pago − costo del producto − beneficio − adquisición. Un segundo clic no duplica esta venta.</small><button class="solid-button compact" type="button" data-rms-save-attributed-sale="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span>Registrar venta y enviar a Valorización</button></div>
          </div>
        </details>
      </section>
    </article>
  `;
}

function recyclingStatusLabel(status) {
  return ({ SCHEDULED: "Programado", DUE: "Próximo", OVERDUE: "Vencido", REACTIVATING: "En reactivación", REACTIVATED: "Reactivado", CONVERTED: "Convertido", LOST: "Perdido", CANCELLED: "Cancelado" })[status] || "Programado";
}

async function loadRmsRecyclingData(options = {}) {
  if (state.rmsRecyclingLoading) return state.rmsRecycling;
  state.rmsRecyclingLoading = true;
  try {
    const status = options.status || state.rmsRecyclingStatus || "ALL";
    const data = await api(`/api/business/rms-machine/recycling?status=${encodeURIComponent(status)}`, { headers: authHeaders() });
    state.rmsRecycling = data;
    return data;
  } finally {
    state.rmsRecyclingLoading = false;
  }
}

function recyclingDateTimeValue(value) {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return "";
  const pad = (part) => String(part).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function renderRmsRecyclingQueue() {
  const root = document.getElementById("recyclingWorkspace");
  if (!root) return;
  const data = state.rmsRecycling || { cases: [], metrics: {} };
  const metrics = data.metrics || {};
  const cases = data.cases || [];
  const status = state.rmsRecyclingStatus || "ALL";
  const selectable = ["ALL", "SCHEDULED", "DUE", "OVERDUE", "REACTIVATED", "CONVERTED", "LOST", "CANCELLED"];
  root.innerHTML = `
    <section class="recycling-metrics" aria-label="Resumen de reciclaje">
      ${[["Próximos", metrics.upcoming || 0], ["Vencidos", metrics.overdue || 0], ["Reactivados", metrics.reactivated || 0], ["Convertidos", metrics.converted || 0], ["Perdidos", metrics.lost || 0]].map(([label, value]) => `<article><strong>${escapeHtml(String(value))}</strong><span>${escapeHtml(label)}</span></article>`).join("")}
    </section>
    <section class="recycling-toolbar" aria-label="Filtros de Reciclaje">
      <label><span>Estado</span><select data-recycling-status>${selectable.map((value) => `<option value="${value}" ${value === status ? "selected" : ""}>${value === "ALL" ? "Todos" : recyclingStatusLabel(value)}</option>`).join("")}</select></label>
      <p>Primero vencidos, luego las reactivaciones de hoy y los próximos siete días.</p>
    </section>
    <section class="recycling-table-wrap" aria-label="Cola de reactivaciones">
      <table class="recycling-table"><thead><tr><th>Lead</th><th>Motivo y estrategia</th><th>Reactivación</th><th>Responsable</th><th>Destino</th><th>Acción</th></tr></thead><tbody>
        ${cases.map((item) => { const opportunity = item.opportunity || {}; const isOpen = ["SCHEDULED", "DUE", "OVERDUE"].includes(item.recycle_status); return `<tr data-recycling-case="${escapeHtml(item.id)}"><td><strong>${escapeHtml(opportunity.name || "Contacto histórico")}</strong><small>${escapeHtml(opportunity.product_interest || "Producto pendiente")} · ${escapeHtml(opportunity.campaign_name || "Sin campaña")}</small></td><td><span class="recycling-status status-${escapeHtml(String(item.recycle_status).toLowerCase())}">${escapeHtml(recyclingStatusLabel(item.recycle_status))}</span><strong>${escapeHtml(item.recycle_reason || "Sin motivo")}</strong><small>${escapeHtml(item.recycle_strategy || "Sin estrategia")} · ${escapeHtml(item.recycle_channel || "Sin contacto nuevo")}</small></td><td><strong>${escapeHtml(formatDate(item.recycle_at))}</strong><small>${escapeHtml(opportunity.last_interaction_at ? `Última interacción: ${formatDate(opportunity.last_interaction_at)}` : "Sin interacción reciente")}</small></td><td>${escapeHtml(item.recycle_owner || "Sin asignar")}</td><td>${escapeHtml(item.recycle_target_phase === "clasificacion" ? "Activación 1" : "Evaluación")}</td><td>${isOpen ? `<div class="recycling-row-actions"><select data-recycling-destination><option value="procesamiento" ${item.recycle_target_phase === "procesamiento" ? "selected" : ""}>Evaluación</option><option value="clasificacion" ${item.recycle_target_phase === "clasificacion" ? "selected" : ""}>Activación 1</option></select><textarea rows="2" data-recycling-note placeholder="Contexto o motivo de la decisión"></textarea><button class="solid-button compact" type="button" data-recycling-action="REACTIVATE">Reactivar ahora</button><input type="datetime-local" value="${escapeHtml(recyclingDateTimeValue(item.recycle_at))}" data-recycling-at><button class="ghost-button compact" type="button" data-recycling-action="RESCHEDULE">Reprogramar</button><select data-recycling-strategy><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva Activación 1</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option><option value="NURTURE">Nutrición comercial</option></select><button class="ghost-button compact" type="button" data-recycling-action="CHANGE_STRATEGY">Cambiar estrategia</button><button class="ghost-button compact danger" type="button" data-recycling-action="LOST">Cerrar como pérdida</button><button class="ghost-button compact danger" type="button" data-recycling-action="CANCEL">Cancelar</button></div>` : `<small>Historial conservado · ${escapeHtml(recyclingStatusLabel(item.recycle_status))}</small>`}</td></tr>`; }).join("") || `<tr><td colspan="6" class="empty-state">No hay reciclajes en este filtro.</td></tr>`}
      </tbody></table>
    </section>`;
  root.querySelector("[data-recycling-status]")?.addEventListener("change", async (event) => {
    state.rmsRecyclingStatus = event.target.value;
    await loadRmsRecyclingData({ status: event.target.value });
    renderRmsRecyclingView();
  });
  root.querySelectorAll("[data-recycling-action]").forEach((button) => button.addEventListener("click", async () => {
    const row = button.closest("[data-recycling-case]");
    const recyclingCaseId = row?.dataset.recyclingCase;
    const action = button.dataset.recyclingAction;
    const note = String(row?.querySelector("[data-recycling-note]")?.value || "").trim();
    if (!recyclingCaseId || !note) return showFeedback("Escribe el contexto o motivo antes de confirmar esta acción.", "info", { title: "Reciclaje" });
    if (!window.confirm(`${action === "REACTIVATE" ? "Reactivar este lead manualmente" : "Confirmar esta decisión de Reciclaje"}?`)) return;
    button.disabled = true;
    try {
      await api("/api/business/rms-machine/recycling/action", { method: "POST", headers: authHeaders(), body: JSON.stringify({ recycling_case_id: recyclingCaseId, action, note, destination: row.querySelector("[data-recycling-destination]")?.value || null, recycle_at: row.querySelector("[data-recycling-at]")?.value ? new Date(row.querySelector("[data-recycling-at]").value).toISOString() : null, recycle_strategy: row.querySelector("[data-recycling-strategy]")?.value || null, idempotency_key: `recycling:${recyclingCaseId}:${action}:${Date.now()}` }) });
      state.rmsMachineLoaded = false;
      await loadRmsRecyclingData({ status: state.rmsRecyclingStatus });
      renderRmsRecyclingView();
      showFeedback(action === "REACTIVATE" ? "Lead reactivado y enviado al destino seleccionado." : "Reciclaje actualizado con trazabilidad.", "success", { title: "Reciclaje" });
    } catch (error) { button.disabled = false; showFeedback(error.message || "No pudimos actualizar el reciclaje.", "error", { title: "Reciclaje" }); }
  }));
}

function recyclingReasonLabel(reason = "") {
  return ({ TIMING: "Momento inadecuado", BUDGET: "Presupuesto", NO_RESPONSE: "Sin respuesta", WAITING_DECISION: "Espera de decision", NOT_VIABLE_NOW: "Condicion no viable", OTHER: "Otro" })[String(reason).toUpperCase()] || reason || "Sin motivo";
}

function rmsClassifierStationCardMarkup(item = {}) {
  const selected = state.rmsMachineSelectedIds.includes(item.id);
  const origin = item.entry_summary || item.source_detail || item.campaign_name || item.channel || item.source_label || item.source_type || "Origen sin definir";
  const interest = item.product_interest || item.top_interest || item.interest || item.raw_recommended_action || "Sin interés registrado";
  const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
  return `
    <article class="rms-classifier-station-card ${selected ? "is-selected" : ""}" data-rms-station-lead="${escapeHtml(item.id)}">
      <header class="rms-classifier-station-card-head">
        <label class="rms-lean-station-check">
          <input type="checkbox" data-rms-select="${escapeHtml(item.id)}" aria-label="Seleccionar ${escapeHtml(item.name || "lead")}" ${selected ? "checked" : ""}>
        </label>
        <div>
          <span class="mono-label">Lead para clasificar</span>
          <strong>${escapeHtml(item.name || "Contacto")}</strong>
          <small>${escapeHtml(contact)}</small>
        </div>
        <button class="ghost-button compact" type="button" data-rms-review-capture="${escapeHtml(item.id)}">Ver datos</button>
      </header>
      <div class="rms-classifier-context">
        <span><small>Interés</small><strong>${escapeHtml(interest)}</strong></span>
        <span><small>Origen</small><strong>${escapeHtml(origin)}</strong></span>
      </div>
      ${rmsProductClassificationMarkup(item)}
    </article>
  `;
}

function recyclingStrategyLabel(strategy = "") {
  return ({ NEW_CONTACT: "Nuevo contacto", NEW_PROPOSAL: "Nueva propuesta", NEW_ACTIVATION: "Nueva activacion", PERMITTED_BENEFIT: "Beneficio permitido", NURTURE: "Nutricion comercial" })[String(strategy).toUpperCase()] || strategy || "Sin estrategia";
}

function recyclingCaseIdentity(item = {}) {
  const opportunity = item.opportunity || {};
  return {
    name: opportunity.name || "Contacto historico",
    context: [opportunity.product_interest || "Producto pendiente", opportunity.campaign_name || "Sin campana"].join(" · "),
    lastInteraction: opportunity.last_interaction_at ? `Ultima interaccion: ${formatDate(opportunity.last_interaction_at)}` : "Sin interaccion reciente",
  };
}

function recyclingTabMarkup(section = "recycling") {
  return [["intelligence", "Inteligencia"], ["recycling", "Reciclaje"], ["recoverable", "Oportunidades recuperables"], ["learning", "Aprendizajes"]]
    .map(([key, label]) => `<button type="button" data-recycling-section="${key}" class="${section === key ? "active" : ""}" ${section === key ? 'aria-current="page"' : ""}>${label}</button>`).join("");
}

function recyclingActionPanelMarkup(item = {}) {
  if (!["SCHEDULED", "DUE", "OVERDUE"].includes(item.recycle_status)) return `<small class="recycling-history-note">Historial conservado · ${escapeHtml(recyclingStatusLabel(item.recycle_status))}</small>`;
  return `<div class="recycling-row-actions"><label><span>Destino al reactivar</span><select data-recycling-destination><option value="procesamiento" ${item.recycle_target_phase === "procesamiento" ? "selected" : ""}>Evaluacion</option><option value="clasificacion" ${item.recycle_target_phase === "clasificacion" ? "selected" : ""}>Activacion 1</option></select></label><label class="recycling-action-note"><span>Nota de decision</span><textarea rows="2" data-recycling-note placeholder="Contexto o motivo de la decision"></textarea></label><div class="recycling-action-buttons"><button class="solid-button compact" type="button" data-recycling-action="REACTIVATE">Reactivar ahora</button><button class="ghost-button compact danger" type="button" data-recycling-action="LOST">Cerrar como perdida</button></div><details class="recycling-more-actions"><summary>Programacion y estrategia</summary><label><span>Proximo intento</span><input type="datetime-local" value="${escapeHtml(recyclingDateTimeValue(item.recycle_at))}" data-recycling-at></label><button class="ghost-button compact" type="button" data-recycling-action="RESCHEDULE">Reprogramar</button><label><span>Estrategia</span><select data-recycling-strategy><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva Activacion 1</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option><option value="NURTURE">Nutricion comercial</option></select></label><button class="ghost-button compact" type="button" data-recycling-action="CHANGE_STRATEGY">Actualizar estrategia</button><button class="ghost-button compact danger" type="button" data-recycling-action="CANCEL">Cancelar</button></details></div>`;
}

function recyclingGroupEntries(cases = [], key, labelFor) {
  const groups = new Map();
  cases.forEach((item) => { const value = String(item[key] || "OTHER").toUpperCase(); groups.set(value, (groups.get(value) || 0) + 1); });
  return Array.from(groups.entries()).sort((a, b) => b[1] - a[1]).map(([value, count]) => ({ label: labelFor(value), count }));
}

function selectRecyclingSection(target = "recycling") {
  state.recyclingSection = ["intelligence", "recycling", "recoverable", "learning"].includes(target) ? target : "recycling";
  if (state.recyclingSection !== "recycling" && state.rmsRecyclingStatus !== "ALL") {
    state.rmsRecyclingStatus = "ALL";
    loadRmsRecyclingData({ status: "ALL" }).then(renderRmsRecyclingView).catch((error) => {
      showFeedback(error.message || "No pudimos actualizar la lectura de Reciclaje.", "error", { title: "Reciclaje" });
      renderRmsRecyclingView();
    });
    return;
  }
  renderRmsRecyclingView();
}

function bindRecyclingActions(root) {
  root.querySelectorAll("[data-recycling-go-to]").forEach((button) => button.addEventListener("click", () => {
    selectRecyclingSection(button.dataset.recyclingGoTo || "recycling");
  }));
  root.querySelectorAll("[data-recycling-action]").forEach((button) => button.addEventListener("click", async () => {
    const row = button.closest("[data-recycling-case]");
    const recyclingCaseId = row?.dataset.recyclingCase;
    const action = button.dataset.recyclingAction;
    const note = String(row?.querySelector("[data-recycling-note]")?.value || "").trim();
    if (!recyclingCaseId || !note) return showFeedback("Escribe el contexto o motivo antes de confirmar esta accion.", "info", { title: "Reciclaje" });
    if (!window.confirm(`${action === "REACTIVATE" ? "Reactivar este lead manualmente" : "Confirmar esta decision de Reciclaje"}?`)) return;
    button.disabled = true;
    try {
      await api("/api/business/rms-machine/recycling/action", { method: "POST", headers: authHeaders(), body: JSON.stringify({ recycling_case_id: recyclingCaseId, action, note, destination: row.querySelector("[data-recycling-destination]")?.value || null, recycle_at: row.querySelector("[data-recycling-at]")?.value ? new Date(row.querySelector("[data-recycling-at]").value).toISOString() : null, recycle_strategy: row.querySelector("[data-recycling-strategy]")?.value || null, idempotency_key: `recycling:${recyclingCaseId}:${action}:${Date.now()}` }) });
      state.rmsMachineLoaded = false;
      await loadRmsRecyclingData({ status: state.rmsRecyclingStatus });
      renderRmsRecyclingView();
      showFeedback(action === "REACTIVATE" ? "Lead reactivado y enviado al destino seleccionado." : "Reciclaje actualizado con trazabilidad.", "success", { title: "Reciclaje" });
    } catch (error) { button.disabled = false; showFeedback(error.message || "No pudimos actualizar el reciclaje.", "error", { title: "Reciclaje" }); }
  }));
}

function renderRmsRecyclingView() {
  const root = document.getElementById("recyclingWorkspace");
  if (!root) return;
  const section = ["intelligence", "recycling", "recoverable", "learning"].includes(state.recyclingSection) ? state.recyclingSection : "recycling";
  const subnav = document.querySelector(".recycling-subnav");
  if (subnav) {
    subnav.innerHTML = recyclingTabMarkup(section);
    subnav.querySelectorAll("[data-recycling-section]").forEach((button) => button.addEventListener("click", () => {
      selectRecyclingSection(button.dataset.recyclingSection || "recycling");
    }));
  }
  if (section === "recycling") return renderRmsRecyclingQueue();

  const data = state.rmsRecycling || { cases: [], metrics: {} };
  const cases = data.cases || [];
  const metrics = data.metrics || {};
  const openCases = cases.filter((item) => ["SCHEDULED", "DUE", "OVERDUE"].includes(item.recycle_status));
  const reasonGroups = recyclingGroupEntries(cases, "recycle_reason", recyclingReasonLabel);
  const strategyGroups = recyclingGroupEntries(cases, "recycle_strategy", recyclingStrategyLabel);
  const closed = Math.max(1, Number(metrics.converted || 0) + Number(metrics.lost || 0));

  if (section === "intelligence") {
    root.innerHTML = `<section class="recycling-intelligence-hero"><div><span class="mono-label">INTELIGENCIA COMERCIAL</span><h3>Una cola que conserva contexto y ensena</h3><p>Reciclaje no es una estacion RMS. Aqui se coordina la recuperacion transversal: se lee el estado, se decide el siguiente contacto y se aprende sin perder la historia comercial.</p></div><aside><strong>${openCases.length}</strong><span>oportunidades activas</span></aside></section><section class="recycling-intelligence-grid"><article><span class="material-symbols-outlined" aria-hidden="true">schedule</span><h4>Prioriza por momento</h4><p>${metrics.overdue || 0} vencido${Number(metrics.overdue || 0) === 1 ? "" : "s"} requiere${Number(metrics.overdue || 0) === 1 ? "" : "n"} una decision hoy. Las demas mantienen fecha y responsable visibles.</p><button class="ghost-button compact" type="button" data-recycling-go-to="recoverable">Abrir recuperables</button></article><article><span class="material-symbols-outlined" aria-hidden="true">history_edu</span><h4>Protege la trazabilidad</h4><p>Cada accion exige una nota: el contexto se conserva y solo una reactivacion confirmada devuelve el lead a su fase comercial.</p><button class="ghost-button compact" type="button" data-recycling-go-to="recycling">Ver cola operativa</button></article><article><span class="material-symbols-outlined" aria-hidden="true">auto_graph</span><h4>Convierte casos en criterio</h4><p>Los motivos y estrategias se acumulan como aprendizaje para que la siguiente propuesta no empiece de cero.</p><button class="ghost-button compact" type="button" data-recycling-go-to="learning">Abrir aprendizajes</button></article></section>`;
    return bindRecyclingActions(root);
  }

  if (section === "recoverable") {
    root.innerHTML = `<section class="recycling-section-intro"><div><span class="mono-label">PRIORIZACION COMERCIAL</span><h3>Oportunidades recuperables</h3><p>Estas conversaciones siguen siendo recuperables. Cada decision queda aqui; solo al reactivar vuelve el lead a Evaluacion o Activacion 1.</p></div><span class="recycling-focus-badge">${openCases.length} abiertas</span></section><section class="recycling-opportunity-grid" aria-label="Oportunidades recuperables">${openCases.map((item) => { const contact = recyclingCaseIdentity(item); return `<article class="recycling-opportunity-card ${escapeHtml(String(item.recycle_status).toLowerCase())}" data-recycling-case="${escapeHtml(item.id)}"><header><div><span class="recycling-status status-${escapeHtml(String(item.recycle_status).toLowerCase())}">${escapeHtml(recyclingStatusLabel(item.recycle_status))}</span><h4>${escapeHtml(contact.name)}</h4><p>${escapeHtml(contact.context)}</p></div><strong>${escapeHtml(formatDate(item.recycle_at))}</strong></header><dl><div><dt>Por que vuelve</dt><dd>${escapeHtml(recyclingReasonLabel(item.recycle_reason))}</dd></div><div><dt>Plan actual</dt><dd>${escapeHtml(recyclingStrategyLabel(item.recycle_strategy))}</dd></div><div><dt>Responsable</dt><dd>${escapeHtml(item.recycle_owner || "Por asignar")}</dd></div><div><dt>Contexto</dt><dd>${escapeHtml(contact.lastInteraction)}</dd></div></dl>${recyclingActionPanelMarkup(item)}</article>`; }).join("") || `<section class="recycling-empty-insight"><span class="material-symbols-outlined" aria-hidden="true">verified</span><div><h3>No hay oportunidades pendientes por recuperar</h3><p>Cuando un acuerdo sea recuperable, aparecera aqui con su motivo, estrategia y proximo intento.</p></div></section>`}</section>`;
    return bindRecyclingActions(root);
  }

  root.innerHTML = `<section class="recycling-section-intro"><div><span class="mono-label">MEMORIA DE NO CONVERSION</span><h3>Aprendizajes que ayudan a decidir mejor</h3><p>Lectura de los casos documentados. No mueve leads ni ejecuta contactos: sirve para mejorar la siguiente intervencion.</p></div><span class="recycling-focus-badge">${cases.length} casos analizados</span></section><section class="recycling-learning-kpis"><article><span class="material-symbols-outlined" aria-hidden="true">restart_alt</span><div><strong>${escapeHtml(String(metrics.reactivated || 0))}</strong><span>reactivados con trazabilidad</span></div></article><article><span class="material-symbols-outlined" aria-hidden="true">paid</span><div><strong>${escapeHtml(String(metrics.converted || 0))}</strong><span>convertidos despues de reciclar</span></div></article><article><span class="material-symbols-outlined" aria-hidden="true">insights</span><div><strong>${escapeHtml(`${Math.round((Number(metrics.converted || 0) / closed) * 100)}%`)}</strong><span>conversion sobre resultados cerrados</span></div></article></section><section class="recycling-learning-grid"><article class="recycling-learning-card"><header><span class="material-symbols-outlined" aria-hidden="true">flag</span><div><h4>Motivos que se repiten</h4><p>Base para ajustar oferta, momento o seguimiento.</p></div></header><ol>${reasonGroups.map((entry) => `<li><span>${escapeHtml(entry.label)}</span><strong>${escapeHtml(String(entry.count))}</strong></li>`).join("") || "<li><span>Aun no hay motivos documentados</span><strong>0</strong></li>"}</ol></article><article class="recycling-learning-card"><header><span class="material-symbols-outlined" aria-hidden="true">route</span><div><h4>Estrategias que el equipo intenta</h4><p>Contrasta el plan aplicado antes de programar el siguiente caso.</p></div></header><ol>${strategyGroups.map((entry) => `<li><span>${escapeHtml(entry.label)}</span><strong>${escapeHtml(String(entry.count))}</strong></li>`).join("") || "<li><span>Aun no hay estrategias documentadas</span><strong>0</strong></li>"}</ol></article><article class="recycling-learning-card recycling-learning-guidance"><header><span class="material-symbols-outlined" aria-hidden="true">psychology</span><div><h4>Senal operativa</h4><p>Una regla simple basada en el estado real de la cola.</p></div></header><p>${openCases.length ? `${openCases.length} caso${openCases.length === 1 ? "" : "s"} sigue${openCases.length === 1 ? "" : "n"} abierto${openCases.length === 1 ? "" : "s"}. Prioriza primero los vencidos y deja una nota verificable en cada decision.` : "La cola no tiene casos abiertos. Usa esta lectura para revisar los resultados cerrados antes de planear una nueva activacion."}</p><button class="ghost-button compact" type="button" data-recycling-go-to="recoverable">Ver oportunidades recuperables</button></article></section>`;
  bindRecyclingActions(root);
}

// RMS never treats a free-text product as a current catalog reference. This
// reusable native picker keeps keyboard type-ahead, shows catalog context, and
// deliberately leaves historic text as evidence instead of silently matching it.
function rmsInventoryProductPickerOptions(selectedId = "", historicName = "") {
  const selected = String(selectedId || "");
  const option = (value, label, extra = "") => `<option value="${escapeHtml(value)}" ${selected === String(value) ? "selected" : ""} ${extra}>${escapeHtml(label)}</option>`;
  const activeProducts = activeInventoryProducts().filter((product) => product.status === "ACTIVE");
  // A product already committed in a commercial confirmation remains a valid
  // historical reference even if the catalog entry was archived afterwards.
  const selectedProduct = (state.inventoryProducts || []).find((product) => String(product.id) === selected);
  const products = selectedProduct && !activeProducts.some((product) => String(product.id) === selected)
    ? [selectedProduct, ...activeProducts]
    : activeProducts;
  const historic = String(historicName || "").trim();
  return [
    option("", products.length ? "Selecciona producto o servicio del inventario" : "No hay productos activos en el inventario", "disabled"),
    ...products.map((product) => {
      const refs = [product.sku, product.category].filter(Boolean).join(" · ");
      const stock = product.stock_quantity === null || product.stock_quantity === undefined ? "" : ` · disponible ${Number(product.stock_quantity || 0).toLocaleString("es-CO")}`;
      const archived = product.status && product.status !== "ACTIVE" ? " · histórico no disponible para nuevas selecciones" : "";
      return option(product.id, `${product.name}${refs ? ` · ${refs}` : ""} · ${money(product.unit_price || 0)} ${product.currency || "COP"}${stock}${archived}`);
    }),
    ...(!selected && historic ? [option("", `Producto histórico sin vincular: ${historic}`, "disabled")] : []),
  ].join("");
}

function upgradeRmsInventoryProductInputs(root) {
  if (!root) return;
  const replaceFreeInput = (input, attribute) => {
    if (!input || input.dataset.rmsInventoryPickerReady === "true") return;
    const historicName = String(input.value || "").trim();
    const known = findInventoryProduct(historicName);
    const select = document.createElement("select");
    select.setAttribute(attribute, input.getAttribute(attribute) || "");
    select.dataset.rmsInventoryPickerReady = "true";
    select.innerHTML = rmsInventoryProductPickerOptions(known?.id || "", historicName);
    input.replaceWith(select);
    const hint = document.createElement("small");
    hint.className = "rms-inventory-picker-hint";
    hint.textContent = historicName && !known
      ? `Producto histórico sin vincular: ${historicName}. Selecciona el producto real antes de continuar.`
      : "Producto activo del inventario; el nombre y precio quedan guardados como evidencia histórica.";
    select.insertAdjacentElement("afterend", hint);
  };
  root.querySelectorAll("[data-rms-evaluation-product]").forEach((input) => replaceFreeInput(input, "data-rms-evaluation-product-id"));
  root.querySelectorAll("[data-rms-confirm-product]").forEach((input) => replaceFreeInput(input, "data-rms-confirm-product-id"));
  root.querySelectorAll("[data-rms-sale-product-name]").forEach((input) => {
    const card = input.closest("[data-rms-station-lead]");
    const item = rmsOpportunityById(card?.dataset.rmsStationLead || "");
    const selected = rmsCommercialWorkflow(item || {}).confirmation?.inventory_product_id || "";
    const saleSelect = card?.querySelector("[data-rms-sale-product]");
    if (saleSelect && selected) saleSelect.value = selected;
    const historicName = String(input.value || "").trim();
    const hint = document.createElement("small");
    hint.className = "rms-inventory-picker-hint";
    hint.textContent = historicName ? `Producto confirmado: ${historicName}` : "Selecciona el producto confirmado del inventario.";
    input.replaceWith(hint);
  });
  root.querySelectorAll("[data-rms-negotiation-recycle-strategy]").forEach((field) => {
    const id = field.getAttribute("data-rms-negotiation-recycle-strategy") || "";
    if (root.querySelector(`[data-rms-negotiation-recycle-responsible="${CSS.escape(id)}"]`)) return;
    const label = document.createElement("label");
    label.dataset.rmsNegotiationRecycleWrap = id;
    label.innerHTML = `<span>Responsable de reactivación</span><input type="text" data-rms-negotiation-recycle-responsible="${escapeHtml(id)}" placeholder="Quién retoma el caso">`;
    field.closest("label")?.insertAdjacentElement("afterend", label);
  });
  root.querySelectorAll("[data-rms-recycle-note]").forEach((field) => {
    const id = field.getAttribute("data-rms-recycle-note") || "";
    if (root.querySelector(`[data-rms-recycle-destination="${CSS.escape(id)}"]`)) return;
    const select = document.createElement("select");
    select.dataset.rmsRecycleDestination = id;
    select.setAttribute("aria-label", "Destino de reactivación");
    select.innerHTML = '<option value="procesamiento">Reactivar en Evaluación</option><option value="clasificacion">Reactivar en Activación 1</option>';
    field.insertAdjacentElement("afterend", select);
  });
  upgradeRmsNegotiationDecisionFields(root);
}

function upgradeRmsNegotiationDecisionFields(root) {
  if (!root) return;
  root.querySelectorAll("[data-rms-negotiation-concession]").forEach((field) => {
    const id = field.getAttribute("data-rms-negotiation-concession") || "";
    const fieldLabel = field.closest("label");
    if (!id || !fieldLabel) return;
    fieldLabel.dataset.rmsNegotiationConcessionWrap = id;
    let mode = root.querySelector(`[data-rms-negotiation-concession-mode="${CSS.escape(id)}"]`);
    if (!mode) {
      const modeLabel = document.createElement("label");
      modeLabel.className = "rms-negotiation-applicability";
      modeLabel.innerHTML = `<span>¿Hubo condición especial o concesión?</span><select data-rms-negotiation-concession-mode="${escapeHtml(id)}"><option value="NOT_APPLICABLE">No aplica · no hubo concesión</option><option value="APPLIES">Sí · documentar la concesión</option></select><small>Una concesión no obliga por sí sola a Riesgos de fuga; debe quedar clara y vigente en la evidencia del acuerdo.</small>`;
      fieldLabel.insertAdjacentElement("beforebegin", modeLabel);
      mode = modeLabel.querySelector("select");
      mode.value = field.value.trim() ? "APPLIES" : "NOT_APPLICABLE";
      mode.addEventListener("change", () => updateRmsNegotiationDecisionUi(root, id));
    }
  });
  root.querySelectorAll("[data-rms-negotiation-next-at]").forEach((field) => {
    const id = field.getAttribute("data-rms-negotiation-next-at") || "";
    const label = field.closest("label");
    if (id && label) label.dataset.rmsNegotiationFollowupWrap = id;
  });
  root.querySelectorAll(".rms-negotiation-decision-block").forEach((block) => {
    if (block.querySelector(".rms-negotiation-decision-guide")) return;
    const guide = document.createElement("aside");
    guide.className = "rms-negotiation-decision-guide";
    guide.innerHTML = "<strong>Completa solo la ruta que elijas</strong><small>Venta limpia: condición, producto, valor, canal, responsable y evidencia. Riesgos de fuga: acuerdo frágil. Espera, reproceso, reciclaje y pérdida revelan únicamente sus propios campos; los demás no aplican.</small>";
    block.querySelector("h5")?.insertAdjacentElement("afterend", guide);
  });
}

function rmsPostSaleActionStatusLabel(status = "PLANNED") {
  return ({ PLANNED: "Pendiente", SCHEDULED: "Programada", ISSUED: "Emitida", DELIVERED: "Entregada", CLAIMED: "Reclamada", COMPLETED: "Completada", REDEEMED: "Redimida", EXPIRED: "Vencida", CANCELLED: "Cancelada", NOT_APPLICABLE: "No aplica", FAILED: "Fallida" })[String(status || "").toUpperCase()] || status;
}

const RMS_POST_SALE_REFINERY_PATHS = Object.freeze([
  { key: "REFERRAL", icon: "group_add", title: "Referidos", detail: "Entrega un QR o beneficio y convierte los datos autorizados del referido en un nuevo lead." },
  { key: "LOYALTY", icon: "workspace_premium", title: "Fidelizar", detail: "Afílialo o reconoce su compra con puntos y beneficios por visitas." },
  { key: "REBUY", icon: "shopping_bag", title: "Recompra", detail: "Crea un ticket o beneficio concreto para su próxima compra." },
]);

function rmsPostSaleRefineryPath(root, id) {
  return rmsCommercialNode(root, "[data-rms-refinery-path]", id)?.value || "REFERRAL";
}

function rmsPostSaleAffiliateFor(item = {}) {
  const phone = String(item.phone || "").replace(/\D/g, "");
  const email = String(item.email || "").trim().toLowerCase();
  return (state.affiliates || []).find((affiliate) => {
    const affiliatePhone = String(affiliate.phone || "").replace(/\D/g, "");
    const affiliateEmail = String(affiliate.email || "").trim().toLowerCase();
    return Boolean((phone && affiliatePhone && phone === affiliatePhone) || (email && affiliateEmail && email === affiliateEmail));
  }) || null;
}

function rmsPostSaleRefineryPanel(root, id, path) {
  return Array.from(root?.querySelectorAll?.("[data-rms-refinery-panel]") || [])
    .find((panel) => panel.dataset.rmsRefineryPanel === String(id) && panel.dataset.rmsRefineryPanelKey === path) || null;
}

function rmsPostSaleRefineryValue(root, id, path, selector) {
  return rmsPostSaleRefineryPanel(root, id, path)?.querySelector(selector)?.value || "";
}

function rmsPostSaleRefineryChecked(root, id, path, selector) {
  return Boolean(rmsPostSaleRefineryPanel(root, id, path)?.querySelector(selector)?.checked);
}

function syncRmsPostSaleRefinery(root, id) {
  const path = rmsPostSaleRefineryPath(root, id);
  root.querySelectorAll(`[data-rms-refinery-route="${id}"]`).forEach((button) => {
    const active = button.dataset.rmsRefineryRouteKey === path;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  root.querySelectorAll(`[data-rms-refinery-panel="${id}"]`).forEach((panel) => {
    panel.hidden = panel.dataset.rmsRefineryPanelKey !== path;
  });
  const loyaltyPanel = rmsPostSaleRefineryPanel(root, id, "LOYALTY");
  const loyaltyMode = loyaltyPanel?.querySelector("[data-rms-refinery-loyalty-mode]")?.value || "POINTS";
  loyaltyPanel?.querySelectorAll("[data-rms-refinery-loyalty-detail]").forEach((field) => {
    field.hidden = field.dataset.rmsRefineryLoyaltyDetail !== loyaltyMode;
  });
  const label = root.querySelector(`[data-rms-refinery-submit-label="${id}"]`);
  if (!label) return;
  if (path === "REFERRAL") label.textContent = "Crear QR de referido";
  else if (path === "REBUY") label.textContent = "Crear ticket de recompra";
  else if (loyaltyMode === "VISITS") {
    const visit = Number(loyaltyPanel?.querySelector("[data-rms-refinery-visit-number]")?.value || 0);
    const target = Number(loyaltyPanel?.querySelector("[data-rms-refinery-visit-target]")?.value || 0);
    label.textContent = visit >= target && target > 0 ? "Entregar beneficio por sellos" : "Registrar sello de compra";
  } else label.textContent = "Afiliar y sumar puntos";
}

function rmsPostSaleStationCardMarkup(item = {}) {
  const metadata = item.state_metadata || {};
  const saleId = metadata.rms_attributed_sale_id || metadata.rms_sale_id || "";
  const actions = (state.rmsPostSaleActions || []).filter((action) => action.source_type === item.source_type && String(action.source_id) === String(item.source_id) && (!saleId || String(action.sale_id || "") === String(saleId)));
  const saleProduct = metadata.rms_sale_product || item.product_interest || item.top_product || "Producto registrado";
  const saleAmount = metadata.rms_sale_amount || item.total_spent || 0;
  const affiliate = rmsPostSaleAffiliateFor(item);
  const recordedVisit = actions.reduce((maximum, action) => Math.max(maximum, Number(action.metadata?.loyalty?.visit_number || 0)), 0);
  const visitNumber = Math.max(1, Number(item.purchase_count || metadata.purchase_count || 1), recordedVisit + 1);
  const actionLabel = actions.length === 1 ? "1 acción registrada" : `${actions.length} acciones registradas`;
  const affiliateLabel = affiliate
    ? `${Number(affiliate.points_total || affiliate.ledger_points || 0).toLocaleString("es-CO")} puntos disponibles`
    : "Sin afiliación todavía";
  const activityMarkup = actions.map((action) => `<li><strong>${escapeHtml(rmsPostSaleActionStatusLabel(action.status))} · ${escapeHtml(action.action_type)}</strong><span>${escapeHtml(action.result_note || action.content || "Sin detalle adicional")}</span><small>${escapeHtml(action.resource_type || "Sin recurso")}${action.resource_url ? ` · ${escapeHtml(action.resource_url)}` : ""}</small></li>`).join("") || "<li><strong>Sin acciones postventa</strong><span>Elige una de las tres rutas para trabajar esta relación comercial.</span></li>";
  return `
    <article class="rms-commercial-work-item rms-post-sale-work-item" data-rms-station-lead="${escapeHtml(item.id)}">
      ${rmsCommercialLeadAsideMarkup(item, "Valorización Clientes · relación posterior a una venta atribuida")}
      <section class="rms-commercial-work-console">
        <header class="rms-commercial-console-head rms-refinery-head"><div class="rms-refinery-head-copy"><span class="rms-refinery-head-icon material-symbols-outlined" aria-hidden="true">diamond</span><div><span class="mono-label">ESTACIÓN 09 · VALORIZACIÓN CLIENTES</span><h4>Haz que esta compra produzca una relación de mayor valor</h4><p>Elige el siguiente movimiento. Solo verás los datos de referidos, fidelización o recompra que realmente vas a operar.</p></div></div><div class="rms-refinery-head-state"><small>Compra confirmada</small><span class="rms-commercial-state is-sale"><span class="material-symbols-outlined" aria-hidden="true">verified</span>Lista para valorizar</span></div></header>
        <input type="hidden" data-rms-refinery-path="${escapeHtml(item.id)}" value="REFERRAL">
        <nav class="rms-refinery-journey" aria-label="Ruta de Valorización Clientes"><span class="is-complete"><b>1</b><small>Venta atribuida</small></span><i aria-hidden="true"></i><span class="is-current"><b>2</b><small>Elegir crecimiento</small></span><i aria-hidden="true"></i><span><b>3</b><small>Inteligencia GOS</small></span></nav>
        <section class="rms-refinery-value-strip" aria-label="Resumen de la venta"><article><span class="material-symbols-outlined" aria-hidden="true">shopping_bag</span><small>Compra atribuida</small><strong>${escapeHtml(saleProduct)}</strong><b>${escapeHtml(money(saleAmount))}</b></article><article><span class="material-symbols-outlined" aria-hidden="true">workspace_premium</span><small>Fidelización</small><strong>${escapeHtml(affiliate ? "Cliente afiliado" : "Cliente por afiliar")}</strong><b>${escapeHtml(affiliateLabel)}</b></article><article><span class="material-symbols-outlined" aria-hidden="true">auto_awesome</span><small>Actividad postventa</small><strong>${escapeHtml(actionLabel)}</strong><b>${escapeHtml(recordedVisit ? `Sello más reciente: ${recordedVisit}` : "Aún sin actividad")}</b></article><article><span class="material-symbols-outlined" aria-hidden="true">insights</span><small>Cierre de estación</small><strong>Inteligencia GOS</strong><b>Con o sin acción postventa</b></article></section>
        <section class="rms-refinery-workbench" aria-label="Operación de Valorización Clientes">
        <aside class="rms-refinery-objective"><header><div><span class="mono-label">SIGUIENTE MOVIMIENTO</span><h5>¿Cómo quieres aumentar el valor de este cliente?</h5><p>Selecciona una ruta. El formulario de trabajo cambia sin perder la venta ni el historial.</p></div></header><div class="rms-refinery-route-picker" aria-label="Objetivo de Valorización Clientes">${RMS_POST_SALE_REFINERY_PATHS.map((path, index) => `<button type="button" class="rms-refinery-route ${index === 0 ? "is-active" : ""}" data-rms-refinery-route="${escapeHtml(item.id)}" data-rms-refinery-route-key="${path.key}" aria-pressed="${index === 0 ? "true" : "false"}"><span class="material-symbols-outlined" aria-hidden="true">${path.icon}</span><span><strong>${path.title}</strong><small>${path.detail}</small></span><span class="material-symbols-outlined rms-refinery-route-arrow" aria-hidden="true">arrow_forward</span></button>`).join("")}</div><small class="rms-refinery-objective-note"><span class="material-symbols-outlined" aria-hidden="true">info</span>También puedes cerrar la estación sin crear una acción postventa.</small></aside>
        <section class="rms-refinery-panel" data-rms-refinery-panel="${escapeHtml(item.id)}" data-rms-refinery-panel-key="REFERRAL"><header><span class="mono-label">REFERIDOS</span><h5>Activa una recomendación con beneficio</h5><p>Genera el QR para el cliente. Los datos del referido solo se crean como lead con autorización explícita.</p></header><div class="rms-sale-form-grid"><label><span>Beneficio del QR</span><input type="text" data-rms-refinery-referral-benefit="${escapeHtml(item.id)}" placeholder="Ej.: 10% para quien recomienda"></label><label><span>Canal para compartirlo</span><select data-rms-refinery-channel="${escapeHtml(item.id)}"><option value="WHATSAPP">WhatsApp</option><option value="EMAIL">Email</option><option value="">Solo generar QR</option></select></label><label><span>Nombre del referido</span><input type="text" data-rms-refinery-referral-name="${escapeHtml(item.id)}" placeholder="Opcional: nombre completo"></label><label><span>WhatsApp o teléfono</span><input type="text" data-rms-refinery-referral-phone="${escapeHtml(item.id)}" placeholder="Opcional: 300 000 0000"></label><label><span>Correo del referido</span><input type="email" data-rms-refinery-referral-email="${escapeHtml(item.id)}" placeholder="Opcional si dejó teléfono"></label><label><span>Interés del referido</span><input type="text" data-rms-refinery-referral-interest="${escapeHtml(item.id)}" placeholder="Producto o necesidad"></label></div><label class="rms-commercial-note-field"><span>Mensaje o instrucciones</span><textarea rows="2" data-rms-refinery-message="${escapeHtml(item.id)}" placeholder="Gracias por tu compra. Comparte este QR y recibe tu beneficio cuando tu referido se registre."></textarea></label><label class="rms-post-sale-consent"><input type="checkbox" style="width:14px!important;min-width:14px!important;max-width:14px!important;height:14px!important;min-height:0!important;max-height:14px!important;margin:0!important;padding:0!important" data-rms-refinery-referral-consent="${escapeHtml(item.id)}"> <span>Confirmo que el referido autorizó compartir sus datos de contacto.</span></label></section>
        <section class="rms-refinery-panel" data-rms-refinery-panel="${escapeHtml(item.id)}" data-rms-refinery-panel-key="LOYALTY" hidden><header><span class="mono-label">FIDELIZACIÓN</span><h5>Reconoce esta compra sin crear una venta nueva</h5><p>${escapeHtml(affiliate ? "El cliente ya está afiliado. Registra puntos o sellos sobre la venta que acaba de hacer." : "Puedes afiliar al cliente y reconocer esta compra con puntos o sellos.")}</p></header><div class="rms-sale-form-grid"><label><span>Programa</span><select data-rms-refinery-loyalty-mode="${escapeHtml(item.id)}"><option value="POINTS">Sumar puntos por compra</option><option value="VISITS">Beneficio por número de compra</option></select></label><label><span>Estado de afiliación</span><select data-rms-refinery-affiliate-mode="${escapeHtml(item.id)}"><option value="${affiliate ? "EXISTING" : "ENROLL"}">${affiliate ? "Ya es afiliado" : "Afiliar a este cliente"}</option><option value="NONE">No afiliar en esta compra</option></select><small>${escapeHtml(affiliate ? "Se usará su cuenta actual de afiliado." : "Se crea una cuenta de afiliado con sus datos de cliente.")}</small></label><label data-rms-refinery-loyalty-detail="VISITS"><span>Compra número</span><input type="number" min="1" step="1" value="${visitNumber}" data-rms-refinery-visit-number="${escapeHtml(item.id)}"></label><label data-rms-refinery-loyalty-detail="VISITS"><span>Entregar beneficio en la compra #</span><input type="number" min="2" step="1" value="5" data-rms-refinery-visit-target="${escapeHtml(item.id)}"></label><label data-rms-refinery-loyalty-detail="VISITS"><span>Beneficio por completar sellos</span><input type="text" data-rms-refinery-visit-benefit="${escapeHtml(item.id)}" placeholder="Ej.: servicio gratis en la quinta visita"></label></div><label class="rms-commercial-note-field"><span>Nota de fidelización</span><textarea rows="2" data-rms-refinery-loyalty-note="${escapeHtml(item.id)}" placeholder="Opcional: condición del programa o beneficio entregado."></textarea></label></section>
        <section class="rms-refinery-panel" data-rms-refinery-panel="${escapeHtml(item.id)}" data-rms-refinery-panel-key="REBUY" hidden><header><span class="mono-label">RECOMPRA</span><h5>Deja listo el siguiente motivo para volver</h5><p>Crea un ticket QR ligado a esta relación. No altera el valor ni la atribución de la venta actual.</p></header><div class="rms-sale-form-grid"><label><span>Beneficio de recompra</span><input type="text" data-rms-refinery-rebuy-benefit="${escapeHtml(item.id)}" placeholder="Ej.: $20.000 en la próxima compra"></label><label><span>Canal para compartirlo</span><select data-rms-refinery-channel="${escapeHtml(item.id)}"><option value="WHATSAPP">WhatsApp</option><option value="EMAIL">Email</option><option value="">Solo generar QR</option></select></label></div><label class="rms-commercial-note-field"><span>Mensaje para el cliente</span><textarea rows="2" data-rms-refinery-message="${escapeHtml(item.id)}" placeholder="Gracias por tu compra. Aquí tienes un beneficio para tu próxima visita."></textarea></label></section>
        </section>
        <details class="rms-post-sale-history" ${actions.length ? "" : "open"}><summary><span><span class="material-symbols-outlined" aria-hidden="true">history</span>Actividad de esta venta</span><small>${escapeHtml(actionLabel)}</small></summary><ol>${activityMarkup}</ol></details>
        <section class="rms-refinery-finish"><div><span class="mono-label">CIERRE DE LA GESTIÓN</span><strong>La acción queda registrada en Inteligencia GOS</strong><p>Al guardar un referido, fidelización o recompra se conserva el resultado. Si no activarás nada, registra el motivo para cerrar el caso con contexto.</p></div><details><summary>Cerrar sin activar</summary><label><span>Motivo para Inteligencia <em>Opcional</em></span><input type="text" data-rms-post-sale-result="${escapeHtml(item.id)}" placeholder="Ej.: no aplica beneficio en esta compra"></label></details><div class="button-row"><button class="ghost-button compact" type="button" data-rms-post-sale-skip-to-intelligence="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">insights</span>Cerrar sin activación</button><button class="solid-button compact" type="button" data-rms-save-post-sale="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">auto_awesome</span><span data-rms-refinery-submit-label="${escapeHtml(item.id)}">Crear QR de referido</span></button></div></section>
      </section>
    </article>`;
}

function rmsIntelligenceCaseKey(item = {}) {
  return `${item.source_type || "PLAYER"}:${item.source_id || item.id || ""}`;
}

function rmsIntelligenceCaseRefMarkup(ref = "") {
  const [sourceType, sourceId] = String(ref || "").split(":");
  if (!sourceType || !sourceId) return "";
  return `<button class="ghost-button compact" type="button" data-rms-intelligence-case-ref="${escapeHtml(ref)}">Ver caso</button>`;
}

function rmsIntelligenceRecyclingMarkup(rows = []) {
  const recycled = rows.filter((item) => item.lifecycle_status === "RECYCLED" || item.operational_phase === "reciclaje");
  const discarded = rows.filter((item) => item.lifecycle_status === "LOST_ANALYZED");
  const list = (items, kind) => items.map((item) => {
    const pending = kind === "recycled";
    const detail = item.next_action?.description || item.why_now || item.recommended_action || "Sin motivo adicional legible.";
    const reference = rmsIntelligenceCaseKey(item);
    return `<li><div><strong>${escapeHtml(item.name || "Contacto sin nombre")}</strong><span>${escapeHtml(item.campaign_name || item.channel || item.product_interest || "Sin origen, canal o producto registrado")}</span><small>${escapeHtml(pending ? `Reciclaje pendiente · ${detail}` : `Conversión no completada · ${detail}`)}</small></div><button class="ghost-button compact" type="button" data-rms-intelligence-recycling-case="${escapeHtml(reference)}">Abrir expediente</button></li>`;
  }).join("") || `<li><div><strong>${kind === "recycled" ? "No hay reciclajes pendientes" : "No hay conversiones descartadas"}</strong><span>${kind === "recycled" ? "Los casos con reactivación programada aparecerán aquí sin salir de su cola." : "Las pérdidas documentadas aparecerán como aprendizaje, sin volver a Recolección."}</span></div></li>`;
  return `<section class="rms-intelligence-recycling" aria-label="Reciclaje y conversiones descartadas"><header><div><span class="mono-label">RECICLAJE · MEMORIA DE OPORTUNIDADES NO CONVERTIDAS</span><h4>Qué no convirtió y qué puede recuperarse</h4><p>Reciclaje conserva su cola operativa. Los descartados quedan aquí para aprender de la no conversión; esta vista no contacta, no mueve ni reactiva leads.</p></div><span class="rms-commercial-state is-pending">${recycled.length} por reactivar</span></header><div class="rms-intelligence-pattern-grid"><section><h5>Reciclaje programado</h5><ol>${list(recycled, "recycled")}</ol></section><section><h5>Conversión descartada</h5><ol>${list(discarded, "discarded")}</ol></section></div></section>`;
}

function upgradeRmsIntelligenceCommandDeck(root) {
  const consoleNode = root?.querySelector?.(".rms-intelligence-console");
  const head = consoleNode?.querySelector?.(".rms-intelligence-console-head");
  if (!consoleNode || !head || consoleNode.querySelector("[data-rms-intelligence-command-deck]")) return;
  const cases = Array.isArray(state.rmsIntelligenceCases) ? state.rmsIntelligenceCases : [];
  const patterns = state.rmsIntelligencePatterns || {};
  const insights = Array.isArray(state.rmsIntelligenceInsights) ? state.rmsIntelligenceInsights : [];
  const patternGroups = [patterns.bottlenecks, patterns.objections, patterns.attributed_sales, patterns.activation_2]
    .filter(Array.isArray)
    .flat();
  const lowEvidence = patternGroups.filter((row) => Number(row?.sample_size || 0) > 0 && Number(row.sample_size) < 5).length;
  const attributedSales = (patterns.attributed_sales || []).reduce((total, row) => total + Number(row?.sample_size || 0), 0);
  const decisionsOpen = insights.filter((insight) => ["PENDING", "MEASURING"].includes(String(insight?.status || "").toUpperCase())).length;
  const currentView = ["case", "patterns", "decisions", "recycling"].includes(state.rmsIntelligenceView) ? state.rmsIntelligenceView : "case";
  const nextAction = decisionsOpen
    ? `${decisionsOpen} aprendizaje${decisionsOpen === 1 ? "" : "s"} requiere${decisionsOpen === 1 ? "" : "n"} seguimiento.`
    : lowEvidence
      ? "Aumenta la evidencia antes de convertir una señal en decisión."
      : cases.length
        ? "Revisa el caso y convierte solo hechos respaldados en una decisión."
        : "Cuando exista una venta o resultado de Valorización, aparecerá aquí para aprender.";
  const deck = document.createElement("section");
  deck.className = "rms-intelligence-command-deck";
  deck.dataset.rmsIntelligenceCommandDeck = "true";
  deck.setAttribute("aria-label", "Resumen operativo de Inteligencia GOS");
  deck.innerHTML = `
    <div class="rms-intelligence-command-copy">
      <span class="mono-label">PANEL DE DECISIÓN</span>
      <strong>${escapeHtml(nextAction)}</strong>
      <small>Inteligencia organiza evidencia; no contacta, mueve ni crea recursos comerciales por sí sola.</small>
    </div>
    <dl class="rms-intelligence-command-metrics">
      <div><dt>Casos con historia</dt><dd>${cases.length}</dd><small>Disponibles para revisar</small></div>
      <div><dt>Ventas en la lectura</dt><dd>${attributedSales}</dd><small>${escapeHtml(patterns.period?.label || "Período actual")}</small></div>
      <div class="${decisionsOpen ? "is-attention" : ""}"><dt>Decisiones abiertas</dt><dd>${decisionsOpen}</dd><small>Pendientes o por medir</small></div>
      <div class="${lowEvidence ? "is-caution" : ""}"><dt>Señales por validar</dt><dd>${lowEvidence}</dd><small>Muestra menor de 5</small></div>
    </dl>
    <div class="rms-intelligence-command-actions">
      <button class="ghost-button compact ${currentView === "case" ? "is-active" : ""}" type="button" data-rms-intelligence-deck-view="case"><span class="material-symbols-outlined" aria-hidden="true">person_search</span>Revisar caso</button>
      <button class="ghost-button compact ${currentView === "patterns" ? "is-active" : ""}" type="button" data-rms-intelligence-deck-view="patterns"><span class="material-symbols-outlined" aria-hidden="true">query_stats</span>Ver patrones</button>
      <button class="ghost-button compact ${currentView === "decisions" ? "is-active" : ""}" type="button" data-rms-intelligence-deck-view="decisions"><span class="material-symbols-outlined" aria-hidden="true">task_alt</span>Dar seguimiento</button>
      <button class="ghost-button compact ${currentView === "recycling" ? "is-active" : ""}" type="button" data-rms-intelligence-deck-view="recycling"><span class="material-symbols-outlined" aria-hidden="true">history</span>Aprender de pérdidas</button>
      <button class="solid-button compact" type="button" data-rms-intelligence-deck-refresh><span class="material-symbols-outlined" aria-hidden="true">refresh</span>Actualizar evidencia</button>
    </div>`;
  head.insertAdjacentElement("afterend", deck);
  deck.querySelectorAll("[data-rms-intelligence-deck-view]").forEach((button) => {
    button.addEventListener("click", () => {
      state.rmsIntelligenceView = button.dataset.rmsIntelligenceDeckView || "case";
      renderRmsStationOnly();
    });
  });
  deck.querySelector("[data-rms-intelligence-deck-refresh]")?.addEventListener("click", (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    loadRmsIntelligenceData({ force: true })
      .then(() => renderRmsStationOnly())
      .catch((error) => showFeedback(error.message || "No pudimos actualizar la evidencia de Inteligencia GOS.", "error", { title: "Inteligencia GOS" }))
      .finally(() => { button.disabled = false; });
  });
}

function upgradeRmsIntelligenceClarity(root) {
  const consoleNode = root?.querySelector?.(".rms-intelligence-console");
  if (!consoleNode) return;
  consoleNode.dataset.intelligenceActiveView = state.rmsIntelligenceView || "case";
  const insightForm = consoleNode.querySelector(".rms-intelligence-insight-form");
  if (insightForm && !insightForm.dataset.rmsIntelligenceDisclosure) {
    const title = insightForm.querySelector("h5");
    const disclosure = document.createElement("details");
    disclosure.className = "rms-intelligence-insight-disclosure";
    disclosure.dataset.rmsIntelligenceDisclosure = "true";
    const summary = document.createElement("summary");
    summary.innerHTML = `<span><strong>Documentar un aprendizaje</strong><small>Solo cuando el caso tenga una observación y una recomendación respaldadas.</small></span><span class="material-symbols-outlined" aria-hidden="true">add_circle</span>`;
    disclosure.appendChild(summary);
    Array.from(insightForm.children).forEach((node) => {
      if (node !== title) disclosure.appendChild(node);
    });
    insightForm.replaceChildren(disclosure);
  }
  const filters = consoleNode.querySelector(".rms-intelligence-filter-grid");
  if (filters && !filters.parentElement?.matches(".rms-intelligence-filter-disclosure")) {
    const disclosure = document.createElement("details");
    disclosure.className = "rms-intelligence-filter-disclosure";
    const summary = document.createElement("summary");
    summary.innerHTML = `<span><strong>Filtrar la lectura</strong><small>Usa filtros solo si necesitas aislar una campaña, canal o producto.</small></span><span class="material-symbols-outlined" aria-hidden="true">tune</span>`;
    filters.insertAdjacentElement("beforebegin", disclosure);
    disclosure.appendChild(summary);
    disclosure.appendChild(filters);
  }
  const patterns = consoleNode.querySelector(".rms-intelligence-patterns");
  if (patterns && !patterns.querySelector(".rms-intelligence-reading-hint")) {
    const hint = document.createElement("aside");
    hint.className = "rms-intelligence-reading-hint";
    hint.innerHTML = `<span class="material-symbols-outlined" aria-hidden="true">visibility</span><div><strong>Cómo leer esta pantalla</strong><small>Primero identifica una señal repetida; después abre un caso que la respalde. Una muestra menor de 5 orienta, pero no justifica una decisión general.</small></div>`;
    patterns.querySelector("header")?.insertAdjacentElement("afterend", hint);
  }
  consoleNode.querySelectorAll(".rms-intelligence-case-columns > section").forEach((section) => {
    if (section.querySelector(".rms-intelligence-case-disclosure")) return;
    const header = section.querySelector(":scope > header");
    const list = section.querySelector(":scope > ol");
    if (!header || !list) return;
    const title = String(header.querySelector("h5")?.textContent || "Detalle del caso").trim();
    const description = String(header.querySelector("small")?.textContent || "Abre para revisar el detalle.").trim();
    const itemCount = list.querySelectorAll(":scope > li").length;
    const disclosure = document.createElement("details");
    disclosure.className = "rms-intelligence-case-disclosure";
    const summary = document.createElement("summary");
    summary.innerHTML = `<span><span class="mono-label">DETALLE BAJO DEMANDA</span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(description)}</small></span><span class="rms-intelligence-disclosure-count">${itemCount}</span><span class="material-symbols-outlined" aria-hidden="true">expand_more</span>`;
    disclosure.appendChild(summary);
    disclosure.appendChild(list);
    section.replaceChildren(disclosure);
  });
  const caseSelect = consoleNode.querySelector("[data-rms-intelligence-case-select]");
  const caseLabel = caseSelect?.closest("label");
  if (caseSelect && caseLabel && !caseLabel.querySelector("[data-rms-intelligence-case-pager]")) {
    const cases = Array.from(caseSelect.options).filter((option) => option.value);
    const selectedIndex = Math.max(0, cases.findIndex((option) => option.value === caseSelect.value));
    const pager = document.createElement("div");
    pager.className = "rms-intelligence-case-pager";
    pager.dataset.rmsIntelligenceCasePager = "true";
    pager.innerHTML = `<small>${cases.length ? `Caso ${selectedIndex + 1} de ${cases.length}` : "Sin casos disponibles"} · escribe en el selector para buscar</small><div><button class="icon-button" type="button" data-rms-intelligence-case-step="-1" aria-label="Caso anterior" ${selectedIndex <= 0 ? "disabled" : ""}><span class="material-symbols-outlined" aria-hidden="true">chevron_left</span></button><button class="icon-button" type="button" data-rms-intelligence-case-step="1" aria-label="Caso siguiente" ${selectedIndex >= cases.length - 1 ? "disabled" : ""}><span class="material-symbols-outlined" aria-hidden="true">chevron_right</span></button></div>`;
    caseSelect.insertAdjacentElement("afterend", pager);
    pager.querySelectorAll("[data-rms-intelligence-case-step]").forEach((button) => {
      button.addEventListener("click", () => {
        const next = cases[selectedIndex + Number(button.dataset.rmsIntelligenceCaseStep || 0)];
        if (!next) return;
        loadRmsIntelligenceCase(next.value)
          .then(() => renderRmsStationOnly())
          .catch((error) => showFeedback(error.message || "No pudimos abrir el caso seleccionado.", "error", { title: "Inteligencia GOS" }));
      });
    });
  }
}

function upgradeRmsIntelligenceRecyclingView(root) {
  const consoleNode = root?.querySelector?.(".rms-intelligence-console");
  const tabs = consoleNode?.querySelector?.(".rms-intelligence-tabs");
  if (!consoleNode || !tabs || consoleNode.querySelector("[data-rms-intelligence-recycling-view]")) return;
  const button = document.createElement("button");
  const isActive = state.rmsIntelligenceView === "recycling";
  button.type = "button";
  button.dataset.rmsIntelligenceRecyclingView = "true";
  button.className = isActive ? "is-active" : "";
  button.setAttribute("aria-pressed", isActive ? "true" : "false");
  button.textContent = "Reciclaje y descartados";
  button.addEventListener("click", () => {
    state.rmsIntelligenceView = "recycling";
    renderRmsStationOnly();
  });
  tabs.appendChild(button);
  if (isActive) {
    tabs.querySelectorAll("[data-rms-intelligence-view]").forEach((tab) => {
      tab.classList.remove("is-active");
      tab.setAttribute("aria-pressed", "false");
    });
  }
  const previousViews = Array.from(consoleNode.children).filter((node) => node !== tabs && !node.matches(".rms-intelligence-console-head, .rms-intelligence-command-deck"));
  const recyclingView = document.createElement("div");
  recyclingView.dataset.rmsIntelligenceRecyclingPanel = "true";
  recyclingView.hidden = !isActive;
  recyclingView.innerHTML = rmsIntelligenceRecyclingMarkup(state.rmsIntelligenceCases || []);
  consoleNode.appendChild(recyclingView);
  previousViews.forEach((node) => { node.hidden = isActive; });
  recyclingView.querySelectorAll("[data-rms-intelligence-recycling-case]").forEach((control) => {
    control.addEventListener("click", () => {
      state.rmsIntelligenceView = "case";
      loadRmsIntelligenceCase(control.dataset.rmsIntelligenceRecyclingCase || "")
        .then(() => renderRmsStationOnly())
        .catch((error) => showFeedback(error.message || "No pudimos abrir el expediente de reciclaje.", "error", { title: "Inteligencia GOS" }));
    });
  });
}

function rmsIntelligenceStationMarkup(rows = []) {
  const selectedKey = state.rmsIntelligenceCaseKey || rmsIntelligenceCaseKey(rows[0]);
  const selectedItem = rows.find((item) => rmsIntelligenceCaseKey(item) === selectedKey) || rows[0] || null;
  const caseData = state.rmsIntelligenceCaseKey === selectedKey ? state.rmsIntelligenceCase : null;
  const learning = caseData?.learning || {};
  const facts = caseData?.facts || {};
  const profile = caseData?.case?.profile || {};
  const patterns = state.rmsIntelligencePatterns || {};
  const insights = state.rmsIntelligenceInsights || [];
  const intelligenceFilters = state.rmsIntelligenceFilters || {};
  const view = ["case", "patterns", "decisions"].includes(state.rmsIntelligenceView) ? state.rmsIntelligenceView : "case";
  const caseOptions = rows.map((item) => `<option value="${escapeHtml(rmsIntelligenceCaseKey(item))}" ${rmsIntelligenceCaseKey(item) === selectedKey ? "selected" : ""}>${escapeHtml(item.name || item.source_label || "Caso RMS")} · ${escapeHtml(item.campaign_name || item.product_interest || "Sin detalle")}</option>`).join("");
  const timeline = (learning.timeline || []).map((event) => `<li class="is-${escapeHtml(event.kind || "event")}"><span class="rms-intelligence-timeline-kind">${escapeHtml({ phase: "Cambio", update: "Actualización", event: "Hecho", intelligence: "Análisis", sale: "Venta", post_sale: "Valorización" }[event.kind] || "Hecho")}</span><strong>${escapeHtml(event.title || "Hecho RMS")}</strong><span>${escapeHtml(event.detail || "Sin detalle adicional")}</span><small>${escapeHtml(event.phase || "origen")} · ${escapeHtml(event.at ? formatDate(event.at) : "Fecha no registrada")}</small></li>`).join("");
  const durations = (learning.phase_durations || []).filter((entry) => entry.is_open || Number(entry.milliseconds || 0) >= 60000).map((entry) => `<li class="${entry.is_open ? "is-open" : ""}"><strong>${escapeHtml(entry.phase_label || entry.phase || "Fase")}</strong><span>${escapeHtml(entry.label || "Sin duración")}${entry.is_open ? " · en curso" : ""}</span></li>`).join("");
  const qualityFlags = (learning.data_quality_flags || []).map((flag) => `<li class="is-${escapeHtml(flag.level || "info")}"><span class="material-symbols-outlined" aria-hidden="true">${flag.level === "warning" ? "warning" : "info"}</span><div><strong>${escapeHtml(flag.title || "Dato para revisar")}</strong><small>${escapeHtml(flag.detail || "Revisa el historial antes de decidir.")}</small></div></li>`).join("");
  const journey = facts.journey || {};
  const journeyStages = (journey.phases || []).map((stage) => `<span class="is-visited"><b>${escapeHtml(stage.label || stage.key)}</b></span>`).join("");
  const skippedStages = (journey.skipped_stages || []).map((stage) => `<span class="is-skipped">No pasó por ${escapeHtml(stage.label || stage.key)}</span>`).join("");
  const journeySales = (journey.sales || []).map((sale) => `<article class="rms-intelligence-sale-detail"><header><div><strong>${escapeHtml(sale.product_name || "Producto")}</strong><small>${escapeHtml(`${Number(sale.quantity || 1).toLocaleString("es-CO")} unidad(es) · ${sale.currency || "COP"}`)}</small></div><b>${escapeHtml(money(sale.sale_amount || 0))}</b></header><dl><div><dt>Costo de adquirir</dt><dd>${escapeHtml(money(sale.acquisition_cost || 0))}</dd></div><div><dt>Costo producto</dt><dd>${escapeHtml(money(sale.product_cost_total || 0))}</dd></div><div><dt>Beneficio usado</dt><dd>${escapeHtml(sale.benefit_description || (sale.benefit_type !== "NONE" ? sale.benefit_type : "Sin beneficio"))}${Number(sale.benefit_cost || 0) ? ` · ${escapeHtml(money(sale.benefit_cost))}` : ""}</dd></div><div><dt>Utilidad neta</dt><dd>${escapeHtml(money(sale.net_profit || 0))}</dd></div><div><dt>ROI de esta venta</dt><dd>${sale.roi === null || sale.roi === undefined ? "No calculable" : `${escapeHtml(Number(sale.roi || 0).toLocaleString("es-CO"))}x`}</dd></div><div><dt>Medio de adquisición</dt><dd>${escapeHtml(sale.acquisition_channel || "Sin medio registrado")}</dd></div></dl></article>`).join("");
  const benefitHistory = [
    ...(journey.benefits?.used_in_sale || []).map((benefit) => `Venta: ${benefit.description || benefit.type || "beneficio"}${Number(benefit.cost || 0) ? ` · costo ${money(benefit.cost)}` : ""}`),
    ...(journey.benefits?.post_sale_actions || []).map((action) => `Activación 2: ${action.type} · ${rmsPostSaleActionStatusLabel(action.status)}`),
    ...(journey.benefits?.tickets || []).map((ticket) => `Ticket: ${ticket.type} · ${rmsPostSaleActionStatusLabel(ticket.status)}`),
  ];
  const journeyMarkup = caseData ? `<section class="rms-intelligence-journey"><header><div><span class="mono-label">VIAJE COMERCIAL REAL</span><h5>${escapeHtml(journey.commercial_route || "Ruta por consolidar")}</h5><p>Calidad inicial: <strong>${escapeHtml(journey.quality || "Sin registrar")}</strong>. ${journey.direct_purchase ? "La compra fue directa: no necesitó Negociación ni Riesgos de fuga." : "La ruta se construye con movimientos y decisiones guardadas por RMS."}</p></div></header><div class="rms-intelligence-journey-stages">${journeyStages || "<span>Sin movimientos registrados</span>"}</div>${skippedStages ? `<div class="rms-intelligence-journey-skipped">${skippedStages}</div>` : ""}<dl class="rms-intelligence-economics"><div><dt>Revenue</dt><dd>${escapeHtml(money(journey.economics?.revenue || 0))}</dd></div><div><dt>Costo de adquisición</dt><dd>${escapeHtml(money(journey.economics?.acquisition_cost || 0))}</dd></div><div><dt>Beneficios / descuentos</dt><dd>${escapeHtml(money(journey.economics?.benefit_cost || 0))}</dd></div><div><dt>Utilidad neta</dt><dd>${escapeHtml(money(journey.economics?.net_profit || 0))}</dd></div></dl>${journeySales ? `<div class="rms-intelligence-sale-list">${journeySales}</div>` : ""}${benefitHistory.length ? `<section class="rms-intelligence-benefit-history"><strong>Beneficios y continuidad</strong><ul>${benefitHistory.map((entry) => `<li>${escapeHtml(entry)}</li>`).join("")}</ul></section>` : ""}</section>` : "";
  let card = selectedItem ? `
    <section class="rms-intelligence-case-sheet">
      <header><div><span class="mono-label">CASO INDIVIDUAL · HECHOS CONSOLIDADOS</span><h4>${escapeHtml(selectedItem.name || "Caso RMS")}</h4><p>${escapeHtml([profile.campaign_name || selectedItem.campaign_name, profile.channel || selectedItem.channel, profile.product_interest || selectedItem.product_interest].filter(Boolean).join(" · ") || "La ficha usa únicamente hechos guardados por la máquina.")}</p></div><span class="rms-commercial-state">${escapeHtml(caseData?.case?.current_operational_phase || selectedItem.operational_phase || selectedItem.stage || "sin estación")}</span></header>
      ${caseData ? `
        <dl class="rms-intelligence-facts"><div><dt>Mayor demora</dt><dd>${escapeHtml(learning.longest_phase ? `${learning.longest_phase.phase_label || learning.longest_phase.phase} · ${learning.longest_phase.label}` : "Aún no calculable")}</dd></div><div><dt>Reprocesos reales</dt><dd>${escapeHtml(String(learning.reprocess_count || 0))}</dd></div><div><dt>Objeción principal</dt><dd>${escapeHtml(learning.primary_objection || "No registrada")}</dd></div><div><dt>Riesgo o pérdida</dt><dd>${escapeHtml(learning.loss_or_risk_reason || "No registrado")}</dd></div><div><dt>Condición que permitió vender</dt><dd>${escapeHtml(learning.winning_condition || "No registrada")}</dd></div><div><dt>Valor atribuido</dt><dd>${escapeHtml(money(learning.attributed_value || 0))}</dd></div><div><dt>Activación 2</dt><dd>${escapeHtml((facts.post_sale_actions || []).map((action) => `${action.action_type} · ${rmsPostSaleActionStatusLabel(action.status)}`).join(" | ") || "Sin resultado registrado")}</dd></div><div><dt>Calidad del aprendizaje</dt><dd>${escapeHtml((learning.missing_fields || []).length ? `Faltan: ${(learning.missing_fields || []).join(", ")}` : "Ficha con hechos suficientes")}</dd></div></dl>
        ${qualityFlags ? `<aside class="rms-intelligence-data-quality"><header><span class="mono-label">ANTES DE APRENDER DE ESTE CASO</span><strong>Datos que requieren validación</strong></header><ul>${qualityFlags}</ul></aside>` : ""}
        <div class="rms-intelligence-case-columns"><section><header><div><span class="mono-label">HITOS COMERCIALES</span><h5>Qué ocurrió y por qué importa</h5></div><small>Ocultamos eventos técnicos duplicados.</small></header><ol class="rms-intelligence-timeline">${timeline || "<li><strong>Sin eventos</strong><span>El caso aún no tiene eventos RMS legibles.</span></li>"}</ol></section><section><header><div><span class="mono-label">TIEMPO REAL</span><h5>Dónde esperó el caso</h5></div><small>Tiempo consolidado; las ediciones no lo fragmentan.</small></header><ol class="rms-intelligence-durations">${durations || "<li><strong>Sin espera relevante</strong><span>Los movimientos registrados fueron inmediatos.</span></li>"}</ol></section></div>
      ` : `<div class="empty-state compact"><strong>Ficha aún sin cargar</strong><p>Selecciona el caso para consultar sus eventos, venta y Activación 2 sin duplicar datos.</p></div>`}
      <section class="rms-intelligence-insight-form"><h5>Guardar aprendizaje respaldado</h5><div class="rms-sale-form-grid"><label><span>Observación</span><textarea rows="3" data-rms-intelligence-observation placeholder="Hecho visible en el historial; no una conclusión inventada."></textarea></label><label><span>Hipótesis</span><textarea rows="3" data-rms-intelligence-hypothesis placeholder="Qué conviene validar con más casos."></textarea></label><label><span>Recomendación concreta</span><textarea rows="3" data-rms-intelligence-recommendation placeholder="Qué debe repetirse, corregirse, detenerse o probarse."></textarea></label><label><span>Evidencia</span><textarea rows="3" data-rms-intelligence-evidence placeholder="Eventos, venta, resultado de Activación 2 o referencias que la sustentan."></textarea></label><label><span>Responsable</span><input type="text" data-rms-intelligence-owner placeholder="Quien revisará el aprendizaje"></label><label><span>Prioridad</span><select data-rms-intelligence-priority><option value="LOW">Baja</option><option value="MEDIUM" selected>Media</option><option value="HIGH">Alta</option><option value="URGENT">Urgente</option></select></label><label><span>Estado</span><select data-rms-intelligence-status><option value="PENDING" selected>Pendiente</option><option value="MEASURING">Por medir</option><option value="APPLIED">Aplicada</option><option value="DISCARDED">Descartada</option></select></label><label><span>Métrica esperada</span><input type="text" data-rms-intelligence-metric placeholder="Ej.: reducir espera en negociación"></label><label><span>Fecha de revisión</span><input type="datetime-local" data-rms-intelligence-review-at></label></div><button class="solid-button compact" type="button" data-rms-save-intelligence-insight="${escapeHtml(rmsIntelligenceCaseKey(selectedItem))}"><span class="material-symbols-outlined" aria-hidden="true">lightbulb</span>Guardar aprendizaje</button></section>
    </section>` : `<div class="empty-state compact"><strong>No hay casos listos para aprender</strong><p>Inteligencia recibe resultados reales de Activación 2; no reinicia clientes ni inventa oportunidades.</p></div>`;
  const patternsView = `<section class="rms-intelligence-patterns"><header><div><span class="mono-label">PATRONES DE LA FÁBRICA</span><h4>${escapeHtml(patterns.period?.label || "Últimos 30 días")}</h4><p>${escapeHtml(patterns.caveat || "Las agrupaciones muestran hechos, no causalidad automática.")}</p></div><button class="ghost-button compact" type="button" data-rms-refresh-intelligence-patterns>Actualizar</button></header><div class="rms-intelligence-filter-grid"><label><span>Período</span><select data-rms-intelligence-filter="days"><option value="7" ${intelligenceFilters.days === "7" ? "selected" : ""}>7 días</option><option value="30" ${intelligenceFilters.days === "30" ? "selected" : ""}>30 días</option><option value="90" ${intelligenceFilters.days === "90" ? "selected" : ""}>90 días</option><option value="365" ${intelligenceFilters.days === "365" ? "selected" : ""}>365 días</option></select></label><label><span>Campaña</span><input data-rms-intelligence-filter="campaign" value="${escapeHtml(intelligenceFilters.campaign || "")}" placeholder="Nombre o parte"></label><label><span>Canal</span><input data-rms-intelligence-filter="channel" value="${escapeHtml(intelligenceFilters.channel || "")}" placeholder="WhatsApp, QR..."></label><label><span>Producto</span><input data-rms-intelligence-filter="product" value="${escapeHtml(intelligenceFilters.product || "")}" placeholder="Producto o servicio"></label><label><span>Vendedor</span><input data-rms-intelligence-filter="seller" value="${escapeHtml(intelligenceFilters.seller || "")}" placeholder="Nombre o ID"></label><label><span>Sede</span><input data-rms-intelligence-filter="branch" value="${escapeHtml(intelligenceFilters.branch || "")}" placeholder="Sede o ID"></label><label><span>Tipo de lead</span><select data-rms-intelligence-filter="source_type"><option value="">Todos</option><option value="PLAYER" ${intelligenceFilters.source_type === "PLAYER" ? "selected" : ""}>Jugador</option><option value="MANUAL" ${intelligenceFilters.source_type === "MANUAL" ? "selected" : ""}>Manual</option><option value="BUYER" ${intelligenceFilters.source_type === "BUYER" ? "selected" : ""}>Comprador</option><option value="AFFILIATE" ${intelligenceFilters.source_type === "AFFILIATE" ? "selected" : ""}>Afiliado</option></select></label></div><div class="rms-intelligence-pattern-grid"><section><h5>Cuellos de botella</h5><ol>${(patterns.bottlenecks || []).map((row) => `<li><strong>${escapeHtml(row.key || "Sin fase")}</strong><span>${escapeHtml(row.sample_label || `Muestra: ${row.sample_size || 0}`)}</span>${rmsIntelligenceCaseRefMarkup(row.case_refs?.[0])}</li>`).join("") || "<li><strong>Sin datos suficientes</strong><span>Se requiere historial RMS para agrupar.</span></li>"}</ol></section><section><h5>Objeciones registradas</h5><ol>${(patterns.objections || []).map((row) => `<li><strong>${escapeHtml(row.key || "No registrada")}</strong><span>${escapeHtml(row.sample_label || `Muestra: ${row.sample_size || 0}`)}</span>${rmsIntelligenceCaseRefMarkup(row.case_refs?.[0])}</li>`).join("") || "<li><strong>Sin datos suficientes</strong><span>Registra la objeción al evaluar o negociar.</span></li>"}</ol></section><section><h5>Ventas atribuidas</h5><ol>${(patterns.attributed_sales || []).map((row) => `<li><strong>${escapeHtml(`${row.campaign || "Sin campaña"} · ${row.product || "Sin producto"}`)}</strong><span>${escapeHtml(`${money(row.attributed_value || 0)} · ${row.sample_label || `Muestra: ${row.sample_size || 0}`}`)}</span>${rmsIntelligenceCaseRefMarkup(row.case_refs?.[0])}</li>`).join("") || "<li><strong>Sin datos suficientes</strong><span>No hay ventas RMS en este período.</span></li>"}</ol></section><section><h5>Resultados de Activación 2</h5><ol>${(patterns.activation_2 || []).map((row) => `<li><strong>${escapeHtml(`${row.key || "Acción"} · ${rmsPostSaleActionStatusLabel(row.status)}`)}</strong><span>${escapeHtml(row.sample_label || `Muestra: ${row.sample_size || 0}`)}</span>${rmsIntelligenceCaseRefMarkup(row.case_refs?.[0])}</li>`).join("") || "<li><strong>Sin datos suficientes</strong><span>Los resultados llegarán desde Postventa.</span></li>"}</ol></section></div></section>`;
  const decisionsView = `<section class="rms-intelligence-decisions"><header><div><span class="mono-label">EXPERIMENTOS Y DECISIONES</span><h4>Aprendizajes que esperan una acción explícita</h4><p>Guardar un insight no crea campañas, mensajes, descuentos ni leads. Una tarea se crea solo al confirmarla.</p></div></header><ol>${insights.map((insight) => `<li><div><strong>${escapeHtml(insight.recommendation || insight.observation || "Aprendizaje")}</strong><span>${escapeHtml(`${insight.status || "PENDING"} · ${insight.priority || "MEDIUM"}${insight.expected_metric ? ` · ${insight.expected_metric}` : ""}`)}</span><small>${escapeHtml(insight.evidence_note || "Sin evidencia narrativa adicional")}</small></div>${insight.source_id ? `<button class="ghost-button compact" type="button" data-rms-intelligence-create-task="${escapeHtml(insight.id)}">Crear tarea explícita</button>` : ""}</li>`).join("") || "<li><div><strong>Aún no hay recomendaciones guardadas</strong><span>Selecciona un caso y documenta una observación respaldada.</span></div></li>"}</ol></section>`;
  return `<section class="rms-intelligence-console" aria-label="Inteligencia GOS"><header class="rms-intelligence-console-head"><div><span class="mono-label">ESTACIÓN 10 · MEMORIA OPERATIVA</span><h3>Inteligencia GOS convierte hechos en decisiones verificables</h3><p>Conecta la historia del lead, la venta y Activación 2; no reinicia clientes ni ejecuta cambios automáticos.</p></div><label><span>Caso</span><select data-rms-intelligence-case-select>${caseOptions || "<option>Sin casos</option>"}</select></label></header><nav class="rms-intelligence-tabs" aria-label="Vistas de Inteligencia GOS"><button type="button" data-rms-intelligence-view="case" class="${view === "case" ? "is-active" : ""}">Caso individual</button><button type="button" data-rms-intelligence-view="patterns" class="${view === "patterns" ? "is-active" : ""}">Patrones de la fábrica</button><button type="button" data-rms-intelligence-view="decisions" class="${view === "decisions" ? "is-active" : ""}">Experimentos y decisiones</button></nav>${view === "case" ? card : view === "patterns" ? patternsView : decisionsView}</section>`;
}

function rmsIntelligenceJourneyMarkup(facts = {}) {
  const journey = facts.journey || {};
  const stages = (journey.phases || []).map((stage) => `<span class="is-visited"><b>${escapeHtml(stage.label || stage.key)}</b></span>`).join("");
  const skipped = (journey.skipped_stages || []).map((stage) => `<span class="is-skipped">No pasó por ${escapeHtml(stage.label || stage.key)}</span>`).join("");
  const saleCards = (journey.sales || []).map((sale) => `<article class="rms-intelligence-sale-detail"><header><div><strong>${escapeHtml(sale.product_name || "Producto")}</strong><small>${escapeHtml(`${Number(sale.quantity || 1).toLocaleString("es-CO")} unidad(es) · ${sale.currency || "COP"}`)}</small></div><b>${escapeHtml(money(sale.sale_amount || 0))}</b></header><dl><div><dt>Costo de adquirir</dt><dd>${escapeHtml(money(sale.acquisition_cost || 0))}</dd></div><div><dt>Costo producto</dt><dd>${escapeHtml(money(sale.product_cost_total || 0))}</dd></div><div><dt>Beneficio usado</dt><dd>${escapeHtml(sale.benefit_description || (sale.benefit_type !== "NONE" ? sale.benefit_type : "Sin beneficio"))}${Number(sale.benefit_cost || 0) ? ` · ${escapeHtml(money(sale.benefit_cost))}` : ""}</dd></div><div><dt>Utilidad neta</dt><dd>${escapeHtml(money(sale.net_profit || 0))}</dd></div><div><dt>ROI de esta venta</dt><dd>${sale.roi === null || sale.roi === undefined ? "No calculable" : `${escapeHtml(Number(sale.roi || 0).toLocaleString("es-CO"))}x`}</dd></div><div><dt>Medio de adquisición</dt><dd>${escapeHtml(sale.acquisition_channel || "Sin medio registrado")}</dd></div></dl></article>`).join("");
  const continuity = [
    ...(journey.benefits?.used_in_sale || []).map((benefit) => `Venta: ${benefit.description || benefit.type || "beneficio"}${Number(benefit.cost || 0) ? ` · costo ${money(benefit.cost)}` : ""}`),
    ...(journey.benefits?.post_sale_actions || []).map((action) => `Activación 2: ${action.type} · ${rmsPostSaleActionStatusLabel(action.status)}`),
    ...(journey.benefits?.tickets || []).map((ticket) => `Ticket: ${ticket.type} · ${rmsPostSaleActionStatusLabel(ticket.status)}`),
  ];
  return `<section class="rms-intelligence-journey" data-rms-intelligence-journey><header><div><span class="mono-label">VIAJE COMERCIAL REAL</span><h5>${escapeHtml(journey.commercial_route || "Ruta por consolidar")}</h5><p>Calidad inicial: <strong>${escapeHtml(journey.quality || "Sin registrar")}</strong>. ${journey.direct_purchase ? "La compra fue directa: no necesitó Negociación ni Riesgos de fuga." : "La ruta se construye con movimientos y decisiones guardadas por RMS."}</p></div></header><div class="rms-intelligence-journey-stages">${stages || "<span>Sin movimientos registrados</span>"}</div>${skipped ? `<div class="rms-intelligence-journey-skipped">${skipped}</div>` : ""}<dl class="rms-intelligence-economics"><div><dt>Revenue</dt><dd>${escapeHtml(money(journey.economics?.revenue || 0))}</dd></div><div><dt>Costo de adquisición</dt><dd>${escapeHtml(money(journey.economics?.acquisition_cost || 0))}</dd></div><div><dt>Beneficios / descuentos</dt><dd>${escapeHtml(money(journey.economics?.benefit_cost || 0))}</dd></div><div><dt>Utilidad neta</dt><dd>${escapeHtml(money(journey.economics?.net_profit || 0))}</dd></div></dl>${saleCards ? `<div class="rms-intelligence-sale-list">${saleCards}</div>` : ""}${continuity.length ? `<section class="rms-intelligence-benefit-history"><strong>Beneficios y continuidad</strong><ul>${continuity.map((entry) => `<li>${escapeHtml(entry)}</li>`).join("")}</ul></section>` : ""}</section>`;
}

function hydrateRmsIntelligenceJourney(root) {
  const sheet = root?.querySelector?.(".rms-intelligence-case-sheet");
  const facts = state.rmsIntelligenceCase?.facts;
  if (!sheet || !facts || sheet.querySelector("[data-rms-intelligence-journey]")) return;
  const header = sheet.querySelector("header");
  header?.insertAdjacentHTML("afterend", rmsIntelligenceJourneyMarkup(facts));
}

function renderRmsStationLeanOnly() {
  if (!state.rmsStationScreenOpen) {
    hideRmsStationWorkspace();
    return;
  }
  const data = state.rmsMachine || {};
  const stages = rmsPrimaryFactoryStages(data);
  const allOpportunities = data.opportunities || [];
  const metrics = data.metrics || {};
  const totalOpportunities = Number(metrics.total_opportunities || allOpportunities.length || 0);
  const isEmpty = allOpportunities.length === 0 && totalOpportunities === 0;
  const phase = state.rmsStationPhase || state.rmsMachineFilters?.phase || stages[0]?.key || "recoleccion";
  const stageIndex = Math.max(0, stages.findIndex((item) => item.key === phase));
  const stage = stages[stageIndex] || stages[0] || { key: phase, label: "Estación RMS", operation: {} };
  const nextPhase = rmsPrimaryStationNextPhase(stage, stages);
  const rows = rmsStationRows(phase, allOpportunities);
  const display = rmsStationDisplayRows(rows, phase);
  const renderedRows = display.visibleRows;
  const selectedRows = phase === "clasificacion"
    ? rmsActivationBulkSelectedRows()
    : rmsStationSelectedRows(phase, rows);
  const eligibleRows = rmsStationOutputEligibleRows(phase, rows);
  const visual = rmsStationVisualMeta(phase);
  const stationControlLabel = phase === "curaduria" ? "Producto" : phase === "alimentacion" ? "Calidad" : "Estado";
  const isCurationStation = phase === "alimentacion";
  const isClassifierStation = phase === "curaduria";
  const isActivationStation = phase === "clasificacion";
  const activationEvaluationRows = isActivationStation ? rows.filter((item) => rmsActivationReadyForEvaluation(item)) : [];
  const selectedActivationEvaluationRows = isActivationStation ? selectedRows.filter((item) => rmsActivationReadyForEvaluation(item)) : [];
  const isCommercialStation = ["clasificacion", "procesamiento", "accion_correctiva", "control_anti_fuga", "cierre", "postventa", "inteligencia"].includes(phase);
  const supportsCommercialSummary = RMS_COMMERCIAL_SUMMARY_PHASES.has(phase);
  const hasStandardHandoff = ["recoleccion", "alimentacion", "curaduria"].includes(phase) && Boolean(nextPhase);
  if (isActivationStation) {
    const visibleActivationIds = new Set(renderedRows.map((item) => item.id));
    if (!visibleActivationIds.has(state.rmsActivationWorkId)) state.rmsActivationWorkId = renderedRows[0]?.id || "";
  }
  const selectReadyLabel = phase === "recoleccion"
    ? "Seleccionar procesables"
    : phase === "alimentacion"
      ? "Seleccionar cualificados"
      : "Seleccionar clasificados";
  const pendingQualityCount = isCurationStation
    ? rows.filter((item) => !rmsLeadQualityValue(item)).length
    : 0;
  const pendingProductCount = isClassifierStation
    ? rows.filter((item) => !rmsHasConfirmedProductClassification(item)).length
    : 0;
  const stationTableHeadMarkup = isCurationStation
    ? `<th>Lead</th><th class="rms-lean-quality-heading">Asigna calidad</th><th>Origen</th><th>Interés</th>`
    : isClassifierStation
      ? `<th>Lead</th><th class="rms-lean-quality-heading">Clasifica producto o servicio</th><th>Origen</th><th>Interés</th>`
      : isActivationStation
        ? `<th>Lead</th><th class="rms-lean-quality-heading">Contacto y seguimiento</th><th>Origen</th><th>Interés</th>`
      : `<th>Lead</th><th>Origen</th><th>Interés</th><th>${escapeHtml(stationControlLabel)}</th>`;
  if (rmsMachineGeneratedAt) {
    rmsMachineGeneratedAt.textContent = data.generated_at ? `Actualizado ${formatDate(data.generated_at)}` : "Sin cargar";
  }
  if (rmsMachineOpportunityCount) {
    rmsMachineOpportunityCount.textContent = phase
      ? `${rows.length.toLocaleString("es-CO")} en estación / ${totalOpportunities.toLocaleString("es-CO")} total`
      : `${totalOpportunities.toLocaleString("es-CO")} oportunidades`;
  }
  renderRmsMachineFilterOptions(stages);
  if (!rmsStationWorkspace) return;
  syncRmsStationShellMode(true);
  rmsStationWorkspace.classList.remove("hidden");
  rmsStationWorkspace.hidden = false;
  rmsStationWorkspace.dataset.stationTheme = visual.tone || "default";
  rmsStationWorkspace.innerHTML = `
    <section class="rms-lean-station" aria-label="Estación RMS simple">
      <header class="rms-lean-station-head">
        <button class="ghost-button compact" type="button" data-rms-close-station>
          <span class="material-symbols-outlined" aria-hidden="true">arrow_back</span> Estaciones
        </button>
        <div class="rms-lean-station-title">
          <figure class="rms-lean-station-media">
            <img src="${escapeHtml(visual.image || "")}" alt="${escapeHtml(visual.imageAlt || stage.label || "Estacion RMS")}" decoding="async">
            <span class="rms-lean-station-symbol material-symbols-outlined" aria-hidden="true">${escapeHtml(visual.icon || "precision_manufacturing")}</span>
          </figure>
          <div>
            <span class="mono-label">Estación ${String(stageIndex + 1).padStart(2, "0")} · Qori RMS</span>
            <h3>${escapeHtml(stage.label || "Estación RMS")}</h3>
            <p>${escapeHtml(stage.operation?.primaryAction || "Trabaja la lista sin cargar paneles pesados.")}</p>
          </div>
        </div>
        <div class="rms-lean-station-actions">
          ${phase === "recoleccion" ? `<button class="ghost-button compact" type="button" data-rms-open-collector><span class="material-symbols-outlined" aria-hidden="true">person_add</span> Nuevo lead</button>` : ""}
          ${supportsCommercialSummary ? `<button class="ghost-button compact" type="button" data-rms-station-summary aria-expanded="${state.rmsStationSummaryOpen ? "true" : "false"}"><span class="material-symbols-outlined" aria-hidden="true">table_chart</span> ${state.rmsStationSummaryOpen ? "Ocultar resumen" : "Resumen"}</button>` : ""}
          ${isActivationStation ? `<button class="ghost-button compact" type="button" data-rms-select-activation-evaluation ${activationEvaluationRows.length ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">done_all</span> Seleccionar listos (${activationEvaluationRows.length.toLocaleString("es-CO")})</button>` : ""}
          ${isActivationStation ? `<button class="solid-button compact" type="button" data-rms-open-bulk-activation ${selectedRows.length ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">group_work</span> Activación masiva (${selectedRows.length.toLocaleString("es-CO")})</button>` : ""}
          ${isActivationStation ? `<button class="solid-button compact" type="button" data-rms-send-selected-activation-evaluation ${selectedActivationEvaluationRows.length ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span> Enviar a Evaluación (${selectedActivationEvaluationRows.length.toLocaleString("es-CO")})</button>` : ""}
          ${hasStandardHandoff ? `
            <button class="ghost-button compact" type="button" data-rms-station-clear-selection ${selectedRows.length ? "" : "disabled"}>Limpiar selección</button>
            <button class="ghost-button compact" type="button" data-rms-station-select-ready="${escapeHtml(phase)}" ${eligibleRows.length ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">done_all</span> ${escapeHtml(selectReadyLabel)}</button>
            <button class="solid-button compact" type="button" data-rms-station-bulk-next ${selectedRows.length && nextPhase ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span> Enviar a ${escapeHtml(nextPhase?.label || "siguiente estación")}</button>
          ` : ""}
        </div>
      </header>
      ${rmsStationHandoffMarkup(stage, nextPhase)}
      ${supportsCommercialSummary && state.rmsStationSummaryOpen ? rmsCommercialStationSummaryMarkup(rows, phase) : ""}
      ${isActivationStation && state.rmsActivationBulkOpen ? rmsActivationBulkComposerMarkup(selectedRows) : ""}
      ${isCurationStation ? `
        <section class="rms-lean-quality-guide" aria-label="Prioridad de Curaduría">
          <span class="material-symbols-outlined" aria-hidden="true">grade</span>
          <div>
            <strong>Primero, asigna la calidad del lead</strong>
            <small>Elige Alta, Media o Baja antes de enviarlo a Asignación. La calidad define el orden de trabajo.</small>
          </div>
          <span class="rms-lean-quality-guide-count"><strong>${pendingQualityCount.toLocaleString("es-CO")}</strong> pendiente${pendingQualityCount === 1 ? "" : "s"}</span>
        </section>
      ` : ""}
      ${isClassifierStation ? `
        <section class="rms-lean-quality-guide rms-lean-product-guide" aria-label="Prioridad de Clasificador">
          <span class="material-symbols-outlined" aria-hidden="true">category</span>
          <div>
            <strong>Primero, asigna el producto o servicio ideal</strong>
            <small>Asigna uno o varios productos antes de enviar el lead a Activación 1. Esta decisión define la oferta.</small>
          </div>
          <span class="rms-lean-quality-guide-count"><strong>${pendingProductCount.toLocaleString("es-CO")}</strong> por asignar</span>
        </section>
      ` : ""}
      ${isActivationStation ? `
        <section class="rms-lean-quality-guide rms-lean-activation-guide" aria-label="Prioridad de Activación 1">
          <span class="material-symbols-outlined" aria-hidden="true">send</span>
          <div>
            <strong>Contacta con contexto y deja un seguimiento real</strong>
            <small>Personaliza el mensaje, confirma el contacto y programa la fecha de seguimiento antes de pasar a Evaluación.</small>
          </div>
          <span class="rms-lean-quality-guide-count"><strong>${rows.filter((item) => !rmsActivationReady(item)).length.toLocaleString("es-CO")}</strong> pendientes</span>
        </section>
      ` : ""}
      ${state.rmsStationSyncing ? `
        <section class="rms-station-progress" role="status" aria-live="polite" aria-busy="true">
          <span class="busy-spinner" aria-hidden="true"></span>
          <div><strong>Actualizando esta estación</strong><small>Puedes revisar la pantalla mientras traemos los datos más recientes.</small></div>
        </section>
      ` : ""}
      <div class="rms-lean-station-tools">
        <label>
          <span class="material-symbols-outlined" aria-hidden="true">search</span>
          <input type="search" data-rms-station-search value="${escapeHtml(state.rmsStationSearch || "")}" placeholder="Buscar en esta estación">
        </label>
        <select data-rms-station-picker aria-label="Cambiar estación">
          ${stages.map((item, index) => `<option value="${escapeHtml(item.key)}" ${index === stageIndex ? "selected" : ""}>${String(index + 1).padStart(2, "0")} · ${escapeHtml(item.short_label || item.label || "Estación")}</option>`).join("")}
        </select>
        <span>${selectedRows.length.toLocaleString("es-CO")} seleccionados · ${eligibleRows.length.toLocaleString("es-CO")} listos · ${rows.length.toLocaleString("es-CO")} total</span>
      </div>
      ${isClassifierStation ? `
        <section class="rms-classifier-station-list" aria-label="Leads por clasificar">
          ${renderedRows.map((item) => rmsClassifierStationCardMarkup(item)).join("") || `<div class="empty-state compact">${escapeHtml(isEmpty ? "No hay leads todavía." : "No hay leads con este filtro.")}</div>`}
        </section>
      ` : isCommercialStation ? `
        ${phase === "inteligencia" ? rmsIntelligenceStationMarkup(state.rmsIntelligenceCases || rows) : ""}
        ${phase !== "inteligencia" ? `
        ${phase === "control_anti_fuga" ? rmsRiskStationMetricsMarkup(rows, allOpportunities) : ""}
        <div class="rms-activation-work-list" aria-label="Consolas comerciales RMS">
          ${renderedRows.map((item) => rmsActivationStationCardMarkup(item)).join("") || `<div class="empty-state compact">${escapeHtml(isEmpty ? "No hay leads todavía." : "No hay leads con este filtro.")}</div>`}
        </div>
        ` : ""}
      ` : `
      <div class="rms-lean-station-table-wrap">
        <table class="rms-lean-station-table">
          <thead>
            <tr>
              <th class="rms-lean-selection-heading" aria-label="Seleccionar"></th>
              ${stationTableHeadMarkup}
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            ${renderedRows.map((item) => rmsStationLeanRowMarkup(item, stage, nextPhase)).join("") || `<tr><td colspan="6">${escapeHtml(isEmpty ? "No hay leads todavía." : "No hay leads con este filtro.")}</td></tr>`}
          </tbody>
        </table>
      </div>
      `}
      <footer class="rms-lean-station-foot">
        ${display.matchingRows.length > RMS_STATION_RENDER_INITIAL_LIMIT ? `<nav class="rms-station-pagination" aria-label="Paginación de leads"><button class="ghost-button compact" type="button" data-rms-station-page-prev ${display.page <= 1 ? "disabled" : ""}>Anterior</button><span>Página ${display.page} de ${display.pageCount} · 10 por página</span><button class="ghost-button compact" type="button" data-rms-station-page-next ${display.page >= display.pageCount ? "disabled" : ""}>Siguiente</button></nav>` : ""}
        <span>Mostrando ${renderedRows.length.toLocaleString("es-CO")} de ${display.matchingRows.length.toLocaleString("es-CO")}${display.hiddenCount ? ` · ${display.hiddenCount.toLocaleString("es-CO")} más sin dibujar` : ""}</span>
        ${display.hiddenCount ? `<button class="ghost-button compact" type="button" data-rms-station-show-more>Ver ${Math.min(RMS_STATION_RENDER_INCREMENT, display.hiddenCount).toLocaleString("es-CO")} más</button>` : ""}
      </footer>
    </section>
  `;
  prepareRmsCommercialAccordions(rmsStationWorkspace);
  bindRmsMachineActions(rmsStationWorkspace);
  rmsStationWorkspace.querySelectorAll("[data-rms-close-station]").forEach((button) => button.addEventListener("click", closeRmsStation));
  rmsStationWorkspace.querySelectorAll("[data-rms-station-summary]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      state.rmsStationSummaryOpen = !state.rmsStationSummaryOpen;
      button.setAttribute("aria-expanded", state.rmsStationSummaryOpen ? "true" : "false");
      renderRmsStationOnly();
    });
  });
  rmsStationWorkspace.querySelector("[data-rms-select-activation-evaluation]")?.addEventListener("click", () => {
    state.rmsMachineSelectedIds = activationEvaluationRows.map((item) => item.id);
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-send-selected-activation-evaluation]")?.addEventListener("click", (event) => {
    event.currentTarget.disabled = true;
    moveSelectedRmsActivationsToEvaluation().catch((error) => showFeedback(error.message || "No se pudieron enviar los leads a Evaluación.", "error", { title: "Activación 1" }));
  });
  rmsStationWorkspace.querySelector("[data-rms-open-bulk-activation]")?.addEventListener("click", () => {
    state.rmsActivationBulkOpen = true;
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-close-bulk-activation]")?.addEventListener("click", () => {
    state.rmsActivationBulkOpen = false;
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-prepare-bulk-activation]")?.addEventListener("click", () => {
    prepareRmsBulkActivation(rmsStationWorkspace).catch((error) => showFeedback(error.message || "No se pudo preparar la activación masiva.", "error", { title: "Activación 1" }));
  });
  rmsStationWorkspace.querySelector("[data-rms-dispatch-next-bulk-activation]")?.addEventListener("click", () => {
    dispatchNextRmsBulkActivation().catch((error) => showFeedback(error.message || "No se pudo registrar este envío.", "error", { title: "Activación 1" }));
  });
  const bulkActivationCatalog = rmsStationWorkspace.querySelector("[data-rms-bulk-activation-catalog]");
  if (bulkActivationCatalog) {
    const loadBulkActivationCatalog = async () => {
      if (bulkActivationCatalog.dataset.rmsActivationLoading === "1") return;
      bulkActivationCatalog.dataset.rmsActivationLoading = "1";
      try {
        const activations = await listRmsActivationCatalogOptions();
        bulkActivationCatalog.innerHTML = `<option value="">Selecciona una activación publicada</option>${activations.map((activation) => {
          const url = activation.public_url || activation.share_url || activation.claim_url;
          const label = activation.title || activation.name || activation.campaign_name || "Activación publicada";
          return `<option value="${escapeHtml(url)}">${escapeHtml(label)} · ${escapeHtml(activation.campaign_name || activation.type || "Activación")}</option>`;
        }).join("")}`;
        bulkActivationCatalog.disabled = !activations.length;
        if (!activations.length) bulkActivationCatalog.innerHTML = '<option value="">No hay activaciones publicadas</option>';
      } catch (_error) {
        bulkActivationCatalog.innerHTML = '<option value="">No se pudieron cargar las activaciones</option>';
        bulkActivationCatalog.disabled = true;
      } finally {
        delete bulkActivationCatalog.dataset.rmsActivationLoading;
      }
    };
    bulkActivationCatalog.addEventListener("focus", loadBulkActivationCatalog, { once: true });
    bulkActivationCatalog.addEventListener("pointerdown", loadBulkActivationCatalog, { once: true });
    bulkActivationCatalog.addEventListener("change", () => {
      const ticketInput = rmsStationWorkspace.querySelector("[data-rms-bulk-activation-ticket]");
      if (ticketInput && bulkActivationCatalog.value) ticketInput.value = bulkActivationCatalog.value;
    });
  }
  rmsStationWorkspace.querySelector("[data-rms-station-picker]")?.addEventListener("change", (event) => openRmsStation(event.target.value || "", { source: "picker" }));
  rmsStationWorkspace.querySelector("[data-rms-station-search]")?.addEventListener("input", (event) => {
    state.rmsStationSearch = event.target.value || "";
    state.rmsStationRenderLimit = RMS_STATION_RENDER_INITIAL_LIMIT;
    state.rmsStationPage = 1;
    window.clearTimeout(state.rmsStationSearchRenderTimer);
    state.rmsStationSearchRenderTimer = window.setTimeout(() => renderRmsStationOnly(), 120);
  });
  rmsStationWorkspace.querySelector("[data-rms-station-page-prev]")?.addEventListener("click", () => {
    state.rmsStationPage = Math.max(1, Number(state.rmsStationPage || 1) - 1);
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-station-page-next]")?.addEventListener("click", () => {
    state.rmsStationPage = Number(state.rmsStationPage || 1) + 1;
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-station-clear-selection]")?.addEventListener("click", () => {
    const currentIds = new Set(rows.map((item) => item.id));
    state.rmsMachineSelectedIds = (state.rmsMachineSelectedIds || []).filter((id) => !currentIds.has(id));
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-station-select-ready]")?.addEventListener("click", () => {
    const currentIds = new Set(rows.map((item) => item.id));
    state.rmsMachineSelectedIds = [
      ...(state.rmsMachineSelectedIds || []).filter((id) => !currentIds.has(id)),
      ...eligibleRows.map((item) => item.id),
    ];
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelectorAll("[data-rms-station-send-single]").forEach((button) => {
    button.addEventListener("click", async () => {
      const item = rmsOpportunityById(button.dataset.rmsStationSendSingle || "");
      if (!item || !nextPhase) return;
      await moveRmsOpportunityToPhase(item, nextPhase.key, {
        reason: "Lead con contacto confirmado desde Recolector.",
        last_operation: "collector_valid_lead_handoff",
        metadata: { decision: "VALID_LEAD", source_flow: "collector_single_handoff" },
      });
    });
  });
  rmsStationWorkspace.querySelector("[data-rms-station-bulk-next]")?.addEventListener("click", async () => {
    if (!nextPhase) return;
    await moveSelectedRmsPhase(nextPhase.key, phase);
  });
  renderRmsBulkToolbar();
}

function renderRmsRiskStationFallback(error) {
  if (!rmsStationWorkspace) return false;
  const opportunities = Array.isArray(state.rmsMachine?.opportunities) ? state.rmsMachine.opportunities : [];
  const rows = opportunities.filter((item) => item?.stage === "control_anti_fuga");
  const cards = rows.map((item) => {
    const id = escapeHtml(item.id || "");
    return `<article class="rms-commercial-work-item rms-risk-work-item rms-risk-safe-mode" data-rms-station-lead="${id}"><header class="rms-commercial-console-head"><div><span class="mono-label">RIESGOS DE FUGA · MODO SEGURO</span><h4>${escapeHtml(item.name || item.first_name || item.email || "Lead sin nombre")}</h4><p>${escapeHtml(item.campaign_name || item.source_detail || item.channel || "Contexto comercial disponible")}</p></div></header><p class="rms-risk-safe-copy">El lead ya está en Riesgos. Registra una salida real; no se creará una copia.</p><input type="hidden" data-rms-risk-decision="${id}" value="CLEARED"><div class="rms-sale-form-grid"><label><span>Resultado</span><select data-rms-risk-safe-result="${id}"><option value="CLEARED">Venta lograda · Ventas atribuidas</option><option value="RECYCLE">No fue viable · Reciclaje</option></select></label><label data-rms-risk-safe-recycle-wrap="${id}" hidden><span>Motivo</span><select data-rms-risk-recycle-reason="${id}"><option value="BUDGET">Presupuesto</option><option value="TIMING">Momento inadecuado</option><option value="NO_RESPONSE">Sin respuesta</option><option value="WAITING_DECISION">Decisión aplazada</option><option value="NOT_VIABLE_NOW">No es viable ahora</option><option value="OTHER">Otro</option></select></label></div><label class="rms-commercial-note-field"><span>Justificación</span><textarea rows="3" data-rms-risk-reason="${id}" placeholder="Qué ocurrió y qué debe conocer la siguiente estación"></textarea></label><div class="rms-commercial-action-row"><button class="solid-button compact" type="button" data-rms-save-risk-decision="${id}"><span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas</button></div></article>`;
  }).join("") || '<div class="empty-state compact">No hay casos disponibles en Riesgos de fuga.</div>';
  rmsStationWorkspace.classList.remove("hidden");
  rmsStationWorkspace.hidden = false;
  rmsStationWorkspace.innerHTML = `<section class="rms-lean-station rms-risk-safe-station"><header class="rms-lean-station-head"><button class="ghost-button compact" type="button" data-rms-close-station><span class="material-symbols-outlined" aria-hidden="true">arrow_back</span> Estaciones</button><div class="rms-lean-station-title"><div><span class="mono-label">ESTACIÓN 07 · QORI RMS</span><h3>Riesgos de fuga</h3><p>El movimiento desde Evaluación se conservó. Puedes registrar el resultado sin volver al mapa.</p></div></div></header><div class="rms-activation-work-list">${cards}</div></section>`;
  rmsStationWorkspace.querySelectorAll("[data-rms-close-station]").forEach((button) => button.addEventListener("click", closeRmsStation));
  rmsStationWorkspace.querySelectorAll("[data-rms-risk-safe-result]").forEach((select) => select.addEventListener("change", () => {
    const id = select.dataset.rmsRiskSafeResult || "";
    const recycle = select.value === "RECYCLE";
    const decision = rmsCommercialNode(rmsStationWorkspace, "[data-rms-risk-decision]", id);
    const recycleWrap = rmsCommercialNode(rmsStationWorkspace, "[data-rms-risk-safe-recycle-wrap]", id);
    const button = rmsCommercialNode(rmsStationWorkspace, "[data-rms-save-risk-decision]", id);
    if (decision) decision.value = recycle ? "RECYCLE" : "CLEARED";
    if (recycleWrap) recycleWrap.hidden = !recycle;
    if (button) button.innerHTML = recycle ? '<span class="material-symbols-outlined" aria-hidden="true">autorenew</span>Enviar a Reciclaje' : '<span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas';
  }));
  rmsStationWorkspace.querySelectorAll("[data-rms-save-risk-decision]").forEach((button) => button.addEventListener("click", async () => {
    const item = opportunities.find((row) => row?.id === button.dataset.rmsSaveRiskDecision);
    if (item) await saveRmsRiskDecision(item, rmsStationWorkspace);
  }));
  console.error("RMS risk station fallback", error);
  return true;
}

function renderRmsStationOnly() {
  if (!state.rmsStationScreenOpen) {
    hideRmsStationWorkspace();
    return;
  }
  try {
    syncRmsStationShellMode(true);
    if (state.rmsQualityControlKey) {
      renderRmsQualityControlDashboard(state.rmsQualityControlKey);
      return;
    }
    if (state.rmsRecyclingFocus) {
      renderRmsRecyclingWorkspace();
      return;
    }
    renderRmsStationLeanOnly();
  } catch (error) {
    console.error("RMS station simple render failed", error);
    if (state.rmsStationPhase === "control_anti_fuga" && renderRmsRiskStationFallback(error)) {
      showFeedback("Riesgos de fuga se abrió en modo seguro. El movimiento se conservó y puedes registrar el resultado.", "info", { title: "Riesgos de fuga" });
      return;
    }
    resetRmsStationMode();
    renderRmsMachineView();
    showFeedback("La estación falló y volvimos al mapa para no bloquear el portal.", "error", { title: "Estaciones" });
  }
}

function rmsVisibleOpportunities(rows = []) {
  const phase = state.rmsMachineFilters?.phase || "";
  return rows.filter((item) => !phase || item.stage === phase);
}

function renderManualLeadBranchOptions() {
  if (!manualLeadBranchInput) return;
  const selected = manualLeadBranchInput.value || "";
  const rows = (state.businessBranches || []).filter((branch) => branch.is_active !== false);
  manualLeadBranchInput.innerHTML = [
    `<option value="">${state.businessBranchesLoading ? "Cargando sedes..." : "Sin sede asignada"}</option>`,
    ...rows.map((branch) => `<option value="${escapeHtml(branch.id)}">${escapeHtml(branch.name)}</option>`),
  ].join("");
  if (selected && rows.some((branch) => String(branch.id) === String(selected))) {
    manualLeadBranchInput.value = selected;
  }
}

function renderInteractiveActivationBranchOptions() {
  if (!triviaBranchInput) return;
  if (!state.businessBranchesLoaded && !state.businessBranchesLoading && session?.user?.business_id) {
    loadBusinessBranches({ quiet: true }).then(renderInteractiveActivationBranchOptions).catch(() => {});
  }
  const selected = triviaBranchInput.value || "";
  const rows = (state.businessBranches || []).filter((branch) => branch.is_active !== false);
  triviaBranchInput.innerHTML = [
    `<option value="">${state.businessBranchesLoading ? "Cargando sedes..." : "Sin sede asignada"}</option>`,
    `<option value="__ALL_BRANCHES__">Todas las sedes</option>`,
    ...rows.map((branch) => `<option value="${escapeHtml(branch.id)}">${escapeHtml(branch.name)}</option>`),
  ].join("");
  if (selected === "__ALL_BRANCHES__" || (selected && rows.some((branch) => String(branch.id) === String(selected)))) {
    triviaBranchInput.value = selected;
  }
}

function interactiveActivationBranchId() {
  const selected = String(triviaBranchInput?.value || "").trim();
  return selected && selected !== "__ALL_BRANCHES__" ? selected : null;
}

function interactiveActivationBranchScope() {
  return triviaBranchInput?.value === "__ALL_BRANCHES__" ? "ALL" : interactiveActivationBranchId() ? "SINGLE" : "UNASSIGNED";
}

function renderRmsMachineFilterFeedback(data = state.rmsMachine || {}, rows = data.opportunities || []) {
  if (!rmsMachineFilterFeedback) return;
  const search = String(state.rmsMachineFilters?.search || "").trim();
  const phase = String(state.rmsMachineFilters?.phase || "").trim();
  const priority = String(state.rmsMachineFilters?.priority || "").trim();
  const hasFilters = Boolean(search || phase || priority);
  rmsMachineFilterFeedback.classList.toggle("hidden", !hasFilters);
  if (!hasFilters) {
    rmsMachineFilterFeedback.textContent = "";
    rmsMachineFilterFeedback.classList.remove("is-empty");
    return;
  }
  const visibleRows = rmsVisibleOpportunities(rows);
  rmsMachineFilterFeedback.classList.toggle("is-empty", visibleRows.length === 0);
  const filters = [
    search ? `“${search}”` : "",
    phase ? `estación: ${rmsPrimaryFactoryStages(state.rmsMachine || {}).find((stage) => stage.key === phase)?.short_label || phase}` : "",
    priority ? `prioridad: ${priority.toLowerCase()}` : "",
  ].filter(Boolean);
  rmsMachineFilterFeedback.textContent = visibleRows.length
    ? `${visibleRows.length.toLocaleString("es-CO")} lead${visibleRows.length === 1 ? "" : "s"} encontrado${visibleRows.length === 1 ? "" : "s"} · ${filters.join(" · ")}`
    : `No encontramos leads para ${filters.join(" · ")}. Prueba otro dato o usa Limpiar.`;
}

async function applyRmsMachineFilters(options = {}) {
  const search = rmsMachineSearchInput?.value?.trim() || "";
  state.rmsMachineFilters = {
    search,
    phase: rmsMachinePhaseFilter?.value || "",
    priority: rmsMachinePriorityFilter?.value || "",
  };
  if (state.rmsMachineFilterTimer) {
    window.clearTimeout(state.rmsMachineFilterTimer);
    state.rmsMachineFilterTimer = null;
  }
  if (rmsMachineFilterFeedback) {
    rmsMachineFilterFeedback.classList.remove("hidden", "is-empty");
    rmsMachineFilterFeedback.textContent = search ? `Buscando “${search}”…` : "Actualizando filtros…";
  }
  setButtonLoading(rmsMachineFilterButton, true, "Buscando...");
  state.rmsMachineLoaded = false;
  try {
    await loadRmsMachineData({ force: true, quiet: Boolean(options.quiet), fresh: true });
    renderRmsMachineView();
    const matches = rmsVisibleOpportunities(state.rmsMachine?.opportunities || []).length;
    const summary = search ? ` para “${search}”` : "";
    showFeedback(
      matches ? `${matches.toLocaleString("es-CO")} lead${matches === 1 ? "" : "s"} encontrado${matches === 1 ? "" : "s"}${summary}.` : `No encontramos leads${summary}.`,
      "info",
      { title: "Búsqueda de leads" }
    );
  } catch (error) {
    if (rmsMachineFilterFeedback) {
      rmsMachineFilterFeedback.classList.remove("hidden");
      rmsMachineFilterFeedback.classList.add("is-empty");
      rmsMachineFilterFeedback.textContent = "No se pudo completar la búsqueda. Intenta actualizar la Máquina RMS.";
    }
    throw error;
  } finally {
    setButtonLoading(rmsMachineFilterButton, false);
  }
}

function renderRmsMachineFilterOptions(stages = []) {
  const options = ['<option value="">Todas las estaciones</option>'].concat((stages || []).map((stage) => (
    `<option value="${escapeHtml(stage.key)}">${escapeHtml(stage.label)}</option>`
  )));
  if (rmsMachinePhaseFilter) {
    const selected = state.rmsMachineFilters?.phase || "";
    rmsMachinePhaseFilter.innerHTML = options.join("");
    rmsMachinePhaseFilter.value = selected;
  }
}

