function missionStatusLabel(status = "") {
  const labels = {
    ACTIVE: "Activa",
    DRAFT: "Borrador",
    PAUSED: "Pausada",
    COMPLETED: "Finalizada",
    FINISHED: "Finalizada",
    CLOSED: "Cerrada",
    ARCHIVED: "Archivada",
  };
  return labels[String(status || "ACTIVE").toUpperCase()] || status || "Activa";
}

function missionStatusClass(status = "") {
  const normalized = String(status || "ACTIVE").toUpperCase();
  if (normalized === "ACTIVE") return "ok";
  if (["DRAFT", "PAUSED"].includes(normalized)) return "pending";
  return "muted";
}

function missionRankingLabel(season = {}) {
  const rankingType = String(season.settings_json?.ranking?.ranking_type || "").toUpperCase();
  if (rankingType === "PURCHASES") return "Ranking por compras";
  if (rankingType === "POINTS") return "Ranking por puntos";
  return rankingType ? `Ranking ${rankingType}` : "Dinámica de temporada";
}

function missionDateProgress(season = {}) {
  const start = season.start_date ? new Date(season.start_date) : null;
  const end = season.end_date ? new Date(season.end_date) : null;
  if (!start || !end || Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return 0;
  const now = new Date();
  const progress = ((now.getTime() - start.getTime()) / (end.getTime() - start.getTime())) * 100;
  return Math.max(0, Math.min(100, Math.round(progress)));
}

const MISSION_PERIOD_LABELS = {
  day: "Hoy",
  week: "Semana actual",
  month: "Mes actual",
  year: "Año actual",
};

function normalizeMissionPeriod(period = "week") {
  const value = String(period || "").trim().toLowerCase();
  return ["day", "week", "month", "year"].includes(value) ? value : "week";
}

function missionPeriodLabel(period = "week") {
  return MISSION_PERIOD_LABELS[normalizeMissionPeriod(period)] || MISSION_PERIOD_LABELS.week;
}

function syncMissionPeriodControls() {
  const period = normalizeMissionPeriod(state.missionSeasonFilter || "week");
  if (missionSeasonFilter) missionSeasonFilter.value = period;
  document.querySelectorAll("[data-mission-period]").forEach((button) => {
    const active = normalizeMissionPeriod(button.dataset.missionPeriod) === period;
    button.classList.toggle("solid-button", active);
    button.classList.toggle("ghost-button", !active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function rmsCommercialNode(root, selector, id) {
  return Array.from(root?.querySelectorAll(selector) || []).find((node) => Object.values(node.dataset || {}).includes(String(id))) || null;
}

function rmsEvaluationCachedDraft(id = "") {
  return state.rmsEvaluationDrafts?.[id] || {};
}

function rmsEvaluationDefaultNextAction(response = "") {
  return {
    NEGOTIATION: "Contactar para acordar condiciones y siguiente compromiso",
    PAID_SALE: "Confirmar pago y condiciones con el cliente",
    MISSING_INFORMATION: "Preparar y reenviar la información solicitada",
    NURTURE: "Programar seguimiento de nutrición comercial",
    NOT_QUALIFIED: "Documentar el motivo y detener seguimiento comercial",
    RECYCLE: "Registrar el motivo y programar una posible reactivación",
  }[response] || "";
}

function persistRmsEvaluationDraft(root, id = "") {
  if (!id) return;
  if (!state.rmsEvaluationDrafts) state.rmsEvaluationDrafts = {};
  state.rmsEvaluationDrafts[id] = rmsEvaluationDraftFromDom(root, id);
}

function rmsEvaluationRoute(response = "", destination = "") {
  const directDestinations = {
    NEGOTIATION: { label: "Negociación", detail: "Continuar el acuerdo de precio, alcance, plazos o forma de pago.", icon: "handshake" },
    RISK_REVIEW: { label: "Riesgos de fuga", detail: "Registra la objeción, el silencio o la falta de interés antes de decidir cómo recuperar el caso.", icon: "shield", phase: "control_anti_fuga" },
    ATTRIBUTED_SALE: { label: "Ventas atribuidas", detail: "La venta ya fue reportada. Completa producto, cantidad, pago y evidencia para atribuirla.", icon: "point_of_sale", phase: "cierre" },
    RECYCLE: { label: "Reciclaje", detail: "El lead no es convertible ahora. Conserva su estación, el motivo y una fecha para revisarlo en la cola transversal.", icon: "autorenew", phase: "procesamiento" },
  };
  if (directDestinations[destination]) return directDestinations[destination];
  const routes = {
    PAID_SALE: { label: "Pasa a Negociación", detail: "Confirma la condición comercial antes de controlar el riesgo del acuerdo.", icon: "handshake" },
    NEGOTIATION: { label: "Pasa a Negociación", detail: "Continúa el acuerdo de precio, alcance, plazos o forma de pago.", icon: "handshake" },
    MISSING_INFORMATION: { label: "Pasa a Negociación", detail: "Acorda la información que falta y el siguiente compromiso comercial.", icon: "handshake" },
    NURTURE: { label: "Pasa a Negociación", detail: "Acorda el siguiente compromiso comercial y programa el seguimiento.", icon: "handshake" },
    NOT_QUALIFIED: { label: "Pasa a Inteligencia GOS", detail: "Conserva el aprendizaje sin seguir presionando al contacto.", icon: "psychology" },
    RECYCLE: { label: "Pasa a Reciclaje", detail: "Registra el motivo y conserva el caso para una posible reactivación responsable.", icon: "autorenew" },
  };
  return routes[response] || { label: "Enviar a Negociación", detail: "La Evaluación abre la conversación comercial antes de Riesgos de fuga.", icon: "alt_route" };
}

function updateRmsEvaluationRoutePreview(root, id) {
  const select = rmsCommercialNode(root, "[data-rms-evaluation-response]", id);
  const destinationSelect = rmsCommercialNode(root, "[data-rms-evaluation-destination]", id);
  const preview = rmsCommercialNode(root, "[data-rms-evaluation-route]", id);
  const response = select?.value || "";
  const destination = destinationSelect?.value || "";
  const route = rmsEvaluationRoute(select?.value || "", destination);
  const responseLabel = RMS_EVALUATION_RESPONSES.find((option) => option.value === select?.value)?.short || "Pendiente";
  const destinationLabel = response && destination ? route.label : "Por elegir";
  const responseMetric = rmsCommercialNode(root, "[data-rms-evaluation-response-label]", id);
  const destinationMetric = rmsCommercialNode(root, "[data-rms-evaluation-destination-label]", id);
  const routeState = rmsCommercialNode(root, "[data-rms-evaluation-route-state]", id);
  const saveLabel = rmsCommercialNode(root, "[data-rms-evaluation-save-label]", id);
  if (responseMetric) responseMetric.textContent = responseLabel;
  if (destinationMetric) destinationMetric.textContent = destinationLabel;
  if (routeState) {
    routeState.textContent = response && destination ? "Ruta lista" : "Pendiente";
    routeState.classList.toggle("is-ready", Boolean(response && destination));
  }
  if (saveLabel) saveLabel.textContent = destination ? `Guardar y enviar a ${destinationLabel}` : "Elige una estación de destino";
  if (preview) {
    preview.querySelector(".material-symbols-outlined")?.replaceChildren(document.createTextNode(route.icon));
    if (saveLabel) saveLabel.textContent = destination ? `Guardar y enviar a ${destinationLabel}` : "Registra la respuesta del lead";
    const eyebrow = preview.querySelector(".mono-label");
    if (eyebrow) eyebrow.textContent = "Destino automático";
    const title = preview.querySelector("strong");
    const detail = preview.querySelector("small");
    if (title) title.textContent = route.label;
    if (detail) detail.textContent = route.detail;
    preview.classList.toggle("is-ready", Boolean(response && destination));
  }
  const nextPanel = rmsCommercialNode(root, "[data-rms-evaluation-next-panel]", id);
  nextPanel?.classList.toggle("is-visible", Boolean(response && destination));
  const detailVisibility = {
    commercial: ["NEGOTIATION", "PAID_SALE"].includes(response),
    followup: ["NEGOTIATION", "MISSING_INFORMATION", "NURTURE", "NO_RESPONSE", "OBJECTION", "NOT_QUALIFIED"].includes(response),
    context: ["NEGOTIATION", "PAID_SALE", "MISSING_INFORMATION"].includes(response),
    recycle: response === "RECYCLE",
  };
  root.querySelectorAll("[data-rms-evaluation-detail]").forEach((field) => {
    const fieldId = field.closest("[data-rms-station-lead]")?.dataset.rmsStationLead || "";
    if (String(fieldId) !== String(id)) return;
    const visible = Boolean(detailVisibility[field.dataset.rmsEvaluationDetail]);
    field.hidden = !visible;
    field.querySelectorAll("input, select, textarea").forEach((control) => { control.disabled = !visible; });
  });
  const saveButton = rmsCommercialNode(root, "[data-rms-save-evaluation]", id);
  if (saveButton) saveButton.disabled = !response || !destination;
}

function rmsCommercialNumber(root, selector, id) {
  const parsed = Number(rmsCommercialNode(root, selector, id)?.value || 0);
  return Number.isFinite(parsed) ? parsed : 0;
}

function rmsCommercialLocalToIso(value = "") {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function rmsSaleDatetimeLocal(value = "") {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return "";
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

function rmsCommercialMoney(value, currency = "COP") {
  return `${currency} ${Number(value || 0).toLocaleString("es-CO", { maximumFractionDigits: 2 })}`;
}

function rmsEvaluationDraftFromDom(root, id) {
  const product = findInventoryProductById(rmsCommercialNode(root, "[data-rms-evaluation-product-id]", id)?.value || "");
  const response = rmsCommercialNode(root, "[data-rms-evaluation-response]", id)?.value || "";
  const destination = rmsCommercialNode(root, "[data-rms-evaluation-destination]", id)?.value || "";
  const recycleReason = rmsCommercialNode(root, "[data-rms-evaluation-recycle-reason]", id)?.value || "";
  const recycleReasons = new Set(["BUDGET", "TIMING", "NO_RESPONSE", "WAITING_DECISION", "NOT_VIABLE_NOW", "OTHER"]);
  const isRecycleRoute = response === "RECYCLE" || destination === "RECYCLE";
  const draft = {
    response,
    destination,
    need: String(rmsCommercialNode(root, "[data-rms-evaluation-need]", id)?.value || "").trim(),
    desired_outcome: String(rmsCommercialNode(root, "[data-rms-evaluation-outcome]", id)?.value || "").trim(),
    recommended_inventory_product_id: product?.id || null,
    recommended_product: product?.name || null,
    budget_amount: rmsCommercialNode(root, "[data-rms-evaluation-budget]", id)?.value === "" ? null : rmsCommercialNumber(root, "[data-rms-evaluation-budget]", id),
    currency: rmsCommercialNode(root, "[data-rms-evaluation-currency]", id)?.value || "COP",
    decision_maker: String(rmsCommercialNode(root, "[data-rms-evaluation-decision-maker]", id)?.value || "").trim(),
    urgency: rmsCommercialNode(root, "[data-rms-evaluation-urgency]", id)?.value || "MEDIUM",
    objections: String(rmsCommercialNode(root, "[data-rms-evaluation-objections]", id)?.value || "").trim(),
    next_action: String(rmsCommercialNode(root, "[data-rms-evaluation-next-action]", id)?.value || "").trim(),
    next_action_at: rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-evaluation-next-at]", id)?.value || ""),
    // Un motivo de reciclaje no es parte de Riesgos de fuga ni de ninguna otra ruta.
    // Limpiarlo evita que un borrador anterior invalide el envío del lead.
    recycle_reason: isRecycleRoute && recycleReasons.has(recycleReason) ? recycleReason : null,
    recycle_at: isRecycleRoute ? rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-evaluation-recycle-at]", id)?.value || "") : null,
    recycle_note: isRecycleRoute ? String(rmsCommercialNode(root, "[data-rms-evaluation-recycle-note]", id)?.value || "").trim() : "",
    note: String(rmsCommercialNode(root, "[data-rms-evaluation-note]", id)?.value || "").trim(),
  };
  // Los controles de Reciclaje pueden conservar valores de un borrador previo.
  // No deben viajar al contrato cuando el operador escogió otra ruta.
  if (!isRecycleRoute) {
    delete draft.recycle_reason;
    delete draft.recycle_at;
    delete draft.recycle_note;
  }
  return draft;
}

async function saveRmsEvaluationResponse(item, root) {
  const draft = rmsEvaluationDraftFromDom(root, item.id);
  if (!draft.response || !draft.destination) {
    showFeedback("Selecciona el resultado y envíalo a Negociación para confirmar la condición comercial.", "info", { title: "Evaluación" });
    return;
  }
  if (draft.response === "RECYCLE" && (!draft.recycle_reason || !draft.recycle_note || !draft.recycle_at)) {
    showFeedback("Para enviar a Reciclaje registra el motivo, explícalo brevemente y define cuándo revisar el caso.", "info", { title: "Evaluación" });
    return;
  }
  const saveButton = rmsCommercialNode(root, "[data-rms-save-evaluation]", item.id);
  if (saveButton) saveButton.disabled = true;
  showFeedback("Guardando la evaluación y dirigiendo el lead…", "info", { title: "Evaluación" });
  const result = await api("/api/business/rms-machine/evaluation-response", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft }),
  });
  if (state.rmsEvaluationDrafts) delete state.rmsEvaluationDrafts[item.id];
  const destination = {
    NEGOTIATION: "accion_correctiva",
    RISK_REVIEW: "control_anti_fuga",
    ATTRIBUTED_SALE: "cierre",
    RECYCLE: "procesamiento",
  }[draft.destination] || "accion_correctiva";
  state.rmsMachineLoaded = false;
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
  const warning = result?.agenda_warning ? " La tarea automática no se pudo crear, pero el lead sí fue dirigido." : "";
  showFeedback(`Evaluación registrada: el lead fue enviado a ${rmsEvaluationRoute(draft.response, draft.destination).label}.${warning}`, result?.agenda_warning ? "info" : "success", { title: "Evaluación" });
  if (draft.destination === "RECYCLE") {
    setView("recycling");
    return;
  }
  openRmsStation(destination, { source: "evaluation" });
}

function rmsCommercialConfirmationDraft(root, id) {
  const product = findInventoryProductById(rmsCommercialNode(root, "[data-rms-confirm-product-id]", id)?.value || rmsCommercialNode(root, "[data-rms-confirm-product]", id)?.value || "");
  return {
    inventory_product_id: product?.id || null,
    product_name: product?.name || "",
    amount: rmsCommercialNumber(root, "[data-rms-confirm-amount]", id),
    currency: rmsCommercialNode(root, "[data-rms-confirm-currency]", id)?.value || "COP",
    payment_reference: String(rmsCommercialNode(root, "[data-rms-confirm-reference]", id)?.value || "").trim(),
    evidence: String(rmsCommercialNode(root, "[data-rms-confirm-evidence]", id)?.value || "").trim(),
    responsible: String(rmsCommercialNode(root, "[data-rms-confirm-responsible]", id)?.value || "").trim(),
    confirmed_at: rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-confirm-at]", id)?.value || ""),
    note: String(rmsCommercialNode(root, "[data-rms-confirm-note]", id)?.value || "").trim(),
  };
}

async function saveRmsCommercialConfirmation(item, root) {
  const draft = rmsCommercialConfirmationDraft(root, item.id);
  const missing = [!draft.inventory_product_id && "producto del inventario", draft.amount <= 0 && "valor", !draft.responsible && "responsable", !(draft.payment_reference || draft.evidence || draft.note) && "evidencia, referencia o nota"].filter(Boolean);
  if (missing.length) {
    showFeedback(`Falta confirmar: ${missing.join(", ")}.`, "info", { title: "Confirmación comercial" });
    return;
  }
  await api("/api/business/rms-machine/commercial-confirmation", {
    method: "POST", headers: authHeaders(),
    body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft }),
  });
  state.rmsMachineLoaded = false;
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: "control_anti_fuga" });
  showFeedback("Condición comercial confirmada. Ahora protege la venta en la validación anti-fuga.", "success", { title: "Confirmación comercial" });
  openRmsStation("control_anti_fuga", { source: "commercial-confirmation" });
}

function rmsNegotiationDraft(root, id) {
  const confirmation = rmsCommercialConfirmationDraft(root, id);
  return {
    ...confirmation,
    result: rmsCommercialNode(root, "[data-rms-negotiation-result]", id)?.value || "ACCEPTED",
    objective: String(rmsCommercialNode(root, "[data-rms-negotiation-objective]", id)?.value || "").trim(),
    objection_type: rmsCommercialNode(root, "[data-rms-negotiation-objection]", id)?.value || "OTHER",
    customer_condition: String(rmsCommercialNode(root, "[data-rms-negotiation-condition]", id)?.value || "").trim(),
    proposal: String(rmsCommercialNode(root, "[data-rms-negotiation-proposal]", id)?.value || "").trim(),
    concession: rmsCommercialNode(root, "[data-rms-negotiation-concession-mode]", id)?.value === "APPLIES"
      ? String(rmsCommercialNode(root, "[data-rms-negotiation-concession]", id)?.value || "").trim()
      : "",
    channel: rmsCommercialNode(root, "[data-rms-negotiation-channel]", id)?.value || "OTHER",
    objection_status: rmsCommercialNode(root, "[data-rms-negotiation-objection-status]", id)?.value || "NOT_APPLICABLE",
    objection_resolution: String(rmsCommercialNode(root, "[data-rms-negotiation-objection-resolution]", id)?.value || "").trim(),
    summary: String(rmsCommercialNode(root, "[data-rms-confirm-note]", id)?.value || "").trim(),
    reason: String(rmsCommercialNode(root, "[data-rms-negotiation-reason]", id)?.value || "").trim(),
    next_action_at: rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-negotiation-next-at]", id)?.value || ""),
    reprocess_phase: rmsCommercialNode(root, "[data-rms-negotiation-reprocess]", id)?.value || "procesamiento",
    commercial_route: rmsCommercialNode(root, "[data-rms-negotiation-route]", id)?.value || "NEEDS_RISK_REVIEW",
    recycle_reason: rmsCommercialNode(root, "[data-rms-negotiation-recycle-reason]", id)?.value || null,
    recycle_strategy: rmsCommercialNode(root, "[data-rms-negotiation-recycle-strategy]", id)?.value || null,
    recycle_consent: rmsCommercialNode(root, "[data-rms-negotiation-recycle-consent]", id)?.value || null,
    recycle_responsible: String(rmsCommercialNode(root, "[data-rms-negotiation-recycle-responsible]", id)?.value || rmsCommercialNode(root, "[data-rms-confirm-responsible]", id)?.value || "").trim(),
    recycle_target_phase: rmsCommercialNode(root, "[data-rms-negotiation-recycle-target]", id)?.value || "procesamiento",
    lost_classification: rmsCommercialNode(root, "[data-rms-negotiation-lost-classification]", id)?.value || null,
  };
}

function rmsNegotiationTicketContext(item = {}) {
  const delivery = rmsActivationDelivery(item);
  const linked = Boolean(delivery.ticketUrl || item.active_ticket_qr_id || item.active_tickets || item.redeemed_tickets || item.expired_tickets);
  if (!linked) return { linked: false, label: "No hay ticket ni beneficio vinculado", source: "No aplica", action: "La venta puede avanzar sin incentivo." };
  if (item.redeemed_tickets) return { linked: true, status: "REDEEMED", label: "Ticket redimido", source: delivery.ticketUrl ? "Link enviado en Activación 1" : "Registro de redención del lead", action: "Contrasta la redención con la evidencia de pago o la condición acordada." };
  if (item.expired_tickets) return { linked: true, status: "EXPIRED", label: "Ticket vencido", source: delivery.ticketUrl ? "Link enviado en Activación 1" : "Historial del lead", action: "No lo modifiques; confirma si la condición actual dependía de ese beneficio." };
  return { linked: true, status: "ACTIVE", label: "Ticket o beneficio activo", source: delivery.ticketUrl ? "Link enviado en Activación 1" : "QR/beneficio vinculado al lead", action: "Confirma su vigencia antes de contactar; no se reenvía ni modifica automáticamente." };
}

function rmsNegotiationRiskSignals(item = {}, draft = {}) {
  const signals = [];
  const support = Boolean(draft.payment_reference || draft.evidence || draft.summary);
  const add = (code, severity, title, source, impact, action, status = "OPEN") => signals.push({ code, severity, title, source, impact, action, status });
  if (!support) add("MISSING_SUPPORT", "REQUIRES_RISK", "Pago o evidencia sin soporte", "Referencia, comprobante y resumen de la ronda", "No es posible verificar el acuerdo sin protegerlo.", "Adjunta una referencia, evidencia o nota verificable.");
  if (!draft.inventory_product_id || Number(draft.amount) <= 0) add("UNCONFIRMED_VALUE", "REQUIRES_RISK", "Producto o valor sin confirmar", "Condición comercial actual", "La atribución no puede contrastar qué se vendió ni por cuánto.", "Confirma producto y valor final con el cliente.");
  if (!draft.responsible) add("MISSING_OWNER", "REQUIRES_RISK", "Falta responsable", "Ficha comercial", "No hay quién sostenga el siguiente compromiso.", "Asigna a la persona responsable antes de confirmar.");
  if (draft.concession) add("SPECIAL_CONDITION", "ATTENTION", "Condición especial o concesión", "Ronda de Negociación", "No bloquea por sí sola una venta limpia; la condición y su vigencia deben quedar claras en la evidencia.", "Documenta qué se concedió y confirma que la condición sigue vigente. Si no hubo concesión, marca No aplica.");
  if (["PENDING", "NEEDS_VALIDATION"].includes(draft.objection_status) || (draft.objection_type && draft.objection_type !== "OTHER" && draft.objection_status === "NOT_APPLICABLE")) add("OPEN_OBJECTION", "REQUIRES_RISK", "Objeción comercial abierta", "Estado de objeción definido por el operador", "El acuerdo puede enfriarse o cambiar antes de la atribución.", "Resuélvela con nota verificable o protégela en Riesgos de fuga.");
  const ticket = rmsNegotiationTicketContext(item);
  if (ticket.status === "ACTIVE") add("ACTIVE_TICKET", "ATTENTION", ticket.label, ticket.source, "Puede requerir una confirmación de vigencia, pero no bloquea por sí solo una venta limpia.", ticket.action);
  if (ticket.status === "EXPIRED") add("EXPIRED_TICKET", "ATTENTION", ticket.label, ticket.source, "El histórico no se reactiva; solo importa si afectaba la condición vigente.", ticket.action);
  if (ticket.status === "REDEEMED") add("REDEEMED_TICKET", support ? "INFO" : "REQUIRES_RISK", ticket.label, ticket.source, support ? "La evidencia disponible puede sostener una venta limpia." : "Hay beneficio usado sin soporte comercial suficiente.", ticket.action);
  return signals;
}

function rmsNegotiationCleanHealth(item = {}, draft = {}) {
  const contactReady = Boolean(item.name && (item.phone || item.email));
  const supportReady = Boolean(draft.payment_reference || draft.evidence || draft.summary);
  const hasObjection = Boolean(draft.objection_type && draft.objection_type !== "OTHER");
  const objectionReady = !hasObjection || (draft.objection_status === "RESOLVED" && draft.objection_resolution);
  const checks = [
    { key: "contact", label: "Cliente y contacto identificables", ready: contactReady, detail: contactReady ? "Listo" : "Falta nombre o canal de contacto." },
    { key: "product", label: "Producto o servicio definido", ready: Boolean(draft.product_name), detail: draft.product_name ? "Listo" : "Confirma qué se vendió." },
    { key: "amount", label: "Valor final definido", ready: Number(draft.amount) > 0, detail: Number(draft.amount) > 0 ? "Listo" : "Indica un valor mayor que cero." },
    { key: "condition", label: "Condición comercial confirmada", ready: Boolean(draft.customer_condition), detail: draft.customer_condition ? "Listo" : "Describe la condición que aceptó el cliente." },
    { key: "owner", label: "Canal y responsable", ready: Boolean(draft.channel && draft.responsible), detail: draft.channel && draft.responsible ? "Listo" : "Define canal y responsable." },
    { key: "support", label: "Evidencia, referencia o nota verificable", ready: supportReady, detail: supportReady ? "Listo" : "Agrega soporte, referencia o resumen verificable." },
    { key: "objection", label: "Objeción resuelta o no aplicable", ready: Boolean(objectionReady), detail: objectionReady ? "Listo" : draft.objection_status === "RESOLVED" ? "Falta explicar cómo se resolvió." : "La objeción está pendiente o requiere validación." },
  ];
  const signals = rmsNegotiationRiskSignals(item, draft);
  const requiresRisk = signals.some((signal) => signal.severity === "REQUIRES_RISK");
  const canClean = checks.every((check) => check.ready) && !requiresRisk;
  return { checks, signals, requiresRisk, canClean, blockers: [...checks.filter((check) => !check.ready).map((check) => check.label), ...signals.filter((signal) => signal.severity === "REQUIRES_RISK").map((signal) => signal.title)] };
}

function rmsNegotiationCleanHealthMarkup(item = {}, draft = {}) {
  const health = rmsNegotiationCleanHealth(item, draft);
  const checkMarkup = health.checks.map((check) => {
    const status = check.ready ? "Listo" : health.requiresRisk ? "Requiere Riesgos de fuga" : "Pendiente";
    return `<li class="${check.ready ? "is-ready" : health.requiresRisk ? "is-risk" : "is-pending"}"><span class="material-symbols-outlined" aria-hidden="true">${check.ready ? "check_circle" : health.requiresRisk ? "shield" : "pending"}</span><div><strong>${escapeHtml(check.label)}</strong><small>${escapeHtml(status)} · ${escapeHtml(check.detail)}</small></div></li>`;
  }).join("");
  const signalMarkup = health.signals.length ? `<div class="rms-negotiation-signals">${health.signals.map((signal) => `<article class="is-${escapeHtml(signal.severity.toLowerCase())}"><strong>${escapeHtml(signal.title)}</strong><small><b>Fuente:</b> ${escapeHtml(signal.source)}</small><small><b>Impacto:</b> ${escapeHtml(signal.impact)}</small><small><b>Acción sugerida:</b> ${escapeHtml(signal.action)}</small></article>`).join("")}</div>` : "<p class=\"rms-negotiation-health-ok\">No hay señales asociadas que exijan Riesgos de fuga.</p>";
  return `<header><div><span class="mono-label">C. Salud del acuerdo</span><h5>¿Esta venta puede atribuirse sin Riesgos de fuga?</h5></div><span class="rms-commercial-state ${health.canClean ? "is-sale" : health.requiresRisk ? "is-risk" : "is-pending"}">${health.canClean ? "Venta limpia posible" : health.requiresRisk ? "Protección necesaria" : "Datos pendientes"}</span></header><ol class="rms-negotiation-clean-checklist">${checkMarkup}</ol><div class="rms-negotiation-ticket-context"><span class="material-symbols-outlined" aria-hidden="true">confirmation_number</span><div><strong>${escapeHtml(rmsNegotiationTicketContext(item).label)}</strong><small>${escapeHtml(rmsNegotiationTicketContext(item).source)} · ${escapeHtml(rmsNegotiationTicketContext(item).action)}</small></div></div>${signalMarkup}`;
}

function rmsNegotiationTimelineMarkup(item = {}, history = [], evaluation = {}, confirmation = {}, risk = {}) {
  const events = [];
  if (evaluation.response) events.push({ label: "Ingreso desde Evaluación", detail: evaluation.response === "PAID_SALE" ? "Pago informado por el cliente." : evaluation.note || evaluation.objections || "Respuesta evaluada.", at: evaluation.recorded_at || evaluation.evaluated_at, by: evaluation.recorded_by });
  if (evaluation.response === "PAID_SALE") events.push({ label: "Pago informado", detail: "Pendiente de contraste comercial y soporte.", at: evaluation.recorded_at || evaluation.evaluated_at, by: evaluation.recorded_by });
  if (item.active_tickets || item.redeemed_tickets || item.expired_tickets) events.push({ label: "Ticket o beneficio asociado", detail: rmsNegotiationTicketContext(item).label, at: item.last_interaction_at, by: "RMS" });
  history.forEach((round) => events.push({ label: round.result || "Ronda de Negociación", detail: round.proposal || round.objection_resolution || round.reason || "Sin detalle", at: round.recorded_at, by: round.recorded_by }));
  if (risk?.result === "RETURN_TO_NEGOTIATION") events.push({ label: "Devuelto desde Riesgos de fuga", detail: risk.reason || "Requiere ajuste comercial.", at: risk.reviewed_at, by: risk.reviewed_by });
  if (confirmation.status === "CONFIRMED") events.push({ label: "Acuerdo confirmado", detail: confirmation.note || confirmation.product_name || "Condición documentada.", at: confirmation.confirmed_at, by: confirmation.responsible });
  if (!events.length) return "<p>Aún no hay eventos; esta será la primera ronda documentada.</p>";
  return `<ol>${events.slice(-8).reverse().map((event) => `<li><strong>${escapeHtml(event.label)}</strong><span>${escapeHtml(event.detail)}</span><small>${escapeHtml(event.at ? formatDate(event.at) : "Sin fecha")} · ${escapeHtml(event.by || "Responsable pendiente")}</small></li>`).join("")}</ol>`;
}

function updateRmsNegotiationDecisionUi(root, id) {
  const result = rmsCommercialNode(root, "[data-rms-negotiation-result]", id)?.value || "ACCEPTED";
  const messages = {
    ACCEPTED: ["Siguiente paso: Riesgos de fuga", "Se validará evidencia, condición, contacto y posibles bloqueos antes de atribuir la venta.", "Confirmar acuerdo y enviar a Riesgos de fuga"],
    WAITING: ["El caso permanece en Negociación", "Programa el próximo contacto para retomar la conversación en la fecha acordada.", "Guardar espera y seguimiento"],
    REPROCESS: ["El caso vuelve a propuesta", "Elige Evaluación o Activación 1 y deja una razón clara para el reproceso.", "Devolver para nueva propuesta"],
    NO_RESPONSE: ["El caso permanece en Negociación", "Programa una acción de recuperación; no se atribuye una venta por falta de respuesta.", "Guardar seguimiento de recuperación"],
    RECYCLE: ["Siguiente paso: Reciclaje comercial", "Conserva el historial y programa la reactivación; al volver se recalifica en Evaluación.", "Enviar a Reciclaje comercial"],
    LOST: ["El seguimiento comercial se detendrá", "Registra el motivo para conservar el aprendizaje sin crear una venta.", "Registrar pérdida"],
  };
  const commercialRoute = rmsCommercialNode(root, "[data-rms-negotiation-route]", id)?.value || "NEEDS_RISK_REVIEW";
  const item = rmsOpportunityById(id) || {};
  const draft = rmsNegotiationDraft(root, id);
  const health = rmsNegotiationCleanHealth(item, draft);
  if (result === "ACCEPTED" && commercialRoute === "NEGOTIATION_CLEAN") {
    messages.ACCEPTED = ["Siguiente paso: Ventas atribuidas", "La condición, evidencia y responsable están completos y no hay señal crítica abierta.", "Confirmar venta limpia y enviar a Ventas atribuidas"];
  }
  const [title, detail, cta] = messages[result] || messages.ACCEPTED;
  const preview = rmsCommercialNode(root, "[data-rms-negotiation-preview]", id);
  if (preview) preview.innerHTML = `<strong>${escapeHtml(title)}</strong><small>${escapeHtml(detail)}</small>`;
  const ctaNode = rmsCommercialNode(root, "[data-rms-negotiation-cta]", id);
  if (ctaNode) ctaNode.textContent = cta;
  const reprocess = rmsCommercialNode(root, "[data-rms-negotiation-reprocess-wrap]", id);
  if (reprocess) reprocess.hidden = result !== "REPROCESS";
  root.querySelectorAll(`[data-rms-negotiation-recycle-wrap="${CSS.escape(id)}"]`).forEach((node) => { node.hidden = result !== "RECYCLE"; });
  const route = rmsCommercialNode(root, "[data-rms-negotiation-route-wrap]", id);
  if (route) route.hidden = result !== "ACCEPTED";
  const lost = rmsCommercialNode(root, "[data-rms-negotiation-lost-wrap]", id);
  if (lost) lost.hidden = result !== "LOST";
  const followup = rmsCommercialNode(root, "[data-rms-negotiation-followup-wrap]", id);
  if (followup) followup.hidden = !["WAITING", "NO_RESPONSE", "RECYCLE"].includes(result);
  const concessionMode = rmsCommercialNode(root, "[data-rms-negotiation-concession-mode]", id);
  const concession = rmsCommercialNode(root, "[data-rms-negotiation-concession-wrap]", id);
  if (concession) concession.hidden = concessionMode?.value !== "APPLIES";
  const objectionResolution = rmsCommercialNode(root, "[data-rms-objection-resolution-wrap]", id);
  if (objectionResolution) objectionResolution.hidden = draft.objection_status !== "RESOLVED";
  const healthNode = rmsCommercialNode(root, "[data-rms-negotiation-health]", id);
  if (healthNode) healthNode.innerHTML = rmsNegotiationCleanHealthMarkup(item, draft);
  const actionButton = rmsCommercialNode(root, "[data-rms-negotiation-cta-button]", id);
  const cleanBlocked = result === "ACCEPTED" && commercialRoute === "NEGOTIATION_CLEAN" && !health.canClean;
  if (actionButton) actionButton.disabled = cleanBlocked;
  const help = rmsCommercialNode(root, "[data-rms-negotiation-help]", id);
  if (help) help.innerHTML = cleanBlocked
    ? `<span class="material-symbols-outlined" aria-hidden="true">info</span>Para venta limpia falta: ${escapeHtml(health.blockers.join(", ") || "resolver una señal comercial")}.`
    : `<span class="material-symbols-outlined" aria-hidden="true">verified_user</span>${escapeHtml(result === "ACCEPTED" && commercialRoute === "NEEDS_RISK_REVIEW" ? "El acuerdo irá a Riesgos de fuga para protegerlo antes de atribuir." : "Completa y documenta la decisión antes de guardar.")}`;
}

function rmsNegotiationFieldWrap(root, selector, id) {
  const node = rmsCommercialNode(root, selector, id);
  return node?.closest("label") || node?.parentElement || null;
}

function rmsToggleNegotiationNode(root, selector, id, visible) {
  const node = typeof selector === "string" ? rmsNegotiationFieldWrap(root, selector, id) : selector;
  if (node) node.hidden = !visible;
}

function rmsNegotiationCostMarkup(cost = {}) {
  const totals = Object.entries(cost.totals_by_currency || {});
  const totalMarkup = totals.length
    ? totals.map(([currency, value]) => `<strong>${escapeHtml(new Intl.NumberFormat("es-CO", { style: "currency", currency, maximumFractionDigits: 0 }).format(Number(value || 0)))}</strong>`).join(" ")
    : "<strong>Sin costo monetario registrado</strong>";
  const withoutCost = Number(cost.benefits_without_recorded_cost || 0);
  return `<span class="material-symbols-outlined" aria-hidden="true">analytics</span><div><span class="mono-label">Costo real antes de reciclar</span>${totalMarkup}<p>${escapeHtml(cost.message || "Solo se incluyen beneficios redimidos.")}</p>${withoutCost ? `<small>${withoutCost} beneficio(s) redimido(s) sin costo monetario cargado: Qori no los estima.</small>` : ""}</div>`;
}

async function loadRmsNonConversionCost(item, root) {
  const card = rmsCommercialNode(root, "[data-rms-nonconversion-cost]", item.id);
  if (!card || card.dataset.loaded === "true") return;
  card.hidden = false;
  card.dataset.loaded = "loading";
  try {
    const params = new URLSearchParams({ source_id: item.source_id, source_type: item.source_type || "PLAYER" });
    const cost = await api(`/api/business/rms-machine/unconverted-cost?${params.toString()}`, { headers: authHeaders() });
    card.innerHTML = rmsNegotiationCostMarkup(cost || {});
    card.dataset.loaded = "true";
  } catch (error) {
    card.innerHTML = `<span class="material-symbols-outlined" aria-hidden="true">info</span><div><strong>No se pudo calcular el costo todav\u00eda</strong><p>El costo se recalcular\u00e1 y se guardar\u00e1 al enviar el lead a Reciclaje.</p></div>`;
    card.dataset.loaded = "error";
  }
}

function activateRmsNegotiationTab(root, id, tabKey, item = rmsOpportunityById(id)) {
  const tab = RMS_NEGOTIATION_TABS.find((entry) => entry.key === tabKey) || RMS_NEGOTIATION_TABS[0];
  const result = rmsCommercialNode(root, "[data-rms-negotiation-result]", id);
  const route = rmsCommercialNode(root, "[data-rms-negotiation-route]", id);
  if (result) result.value = tab.result;
  if (route) route.value = tab.route;
  root.querySelectorAll(`[data-rms-negotiation-tab="${CSS.escape(id)}"]`).forEach((button) => {
    const active = button.dataset.rmsNegotiationTabKey === tab.key;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  const conditionBlock = card?.querySelector(".rms-negotiation-condition-block");
  const healthBlock = rmsCommercialNode(root, "[data-rms-negotiation-health]", id);
  if (conditionBlock) {
    const compactCondition = ["recycle", "followup"].includes(tab.key);
    conditionBlock.hidden = false;
    conditionBlock.querySelectorAll("label").forEach((label) => { label.hidden = compactCondition; });
    if (compactCondition) {
      rmsToggleNegotiationNode(root, "[data-rms-negotiation-channel]", id, tab.key === "recycle");
      rmsToggleNegotiationNode(root, "[data-rms-negotiation-next-at]", id, true);
    }
  }
  if (healthBlock) healthBlock.hidden = !["conversion", "risk"].includes(tab.key);
  rmsToggleNegotiationNode(root, "[data-rms-negotiation-result]", id, tab.key === "followup");
  rmsToggleNegotiationNode(root, "[data-rms-negotiation-route]", id, ["conversion", "risk"].includes(tab.key));
  rmsToggleNegotiationNode(root, "[data-rms-negotiation-reprocess]", id, tab.key === "followup" && result?.value === "REPROCESS");
  root.querySelectorAll(`[data-rms-negotiation-recycle-wrap="${CSS.escape(id)}"]`).forEach((node) => { node.hidden = tab.key !== "recycle"; });
  rmsToggleNegotiationNode(root, "[data-rms-negotiation-lost-classification]", id, tab.key === "followup" && result?.value === "LOST");
  if (!["recycle", "followup"].includes(tab.key)) {
    rmsToggleNegotiationNode(root, "[data-rms-negotiation-channel]", id, true);
    rmsToggleNegotiationNode(root, "[data-rms-negotiation-next-at]", id, true);
  }
  const costCard = rmsCommercialNode(root, "[data-rms-nonconversion-cost]", id);
  if (costCard) costCard.hidden = tab.key !== "recycle";
  if (tab.key === "recycle" && item) loadRmsNonConversionCost(item, root);
  updateRmsNegotiationDecisionUi(root, id);
}

function activateRmsRiskTab(root, id, tabKey, item = rmsOpportunityById(id)) {
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  if (!card) return;
  const decision = rmsCommercialNode(root, "[data-rms-risk-decision]", id);
  if (decision) decision.value = tabKey === "recycle" ? "RECYCLE" : "CLEARED";
  card.querySelectorAll(".rms-commercial-info-block label").forEach((label) => { label.hidden = true; });
  const show = (selector) => rmsToggleNegotiationNode(root, selector, id, true);
  if (tabKey === "recycle") {
    show("[data-rms-risk-ticket-action]");
    show("[data-rms-risk-recycle-reason]");
    show("[data-rms-risk-recycle-strategy]");
    show("[data-rms-risk-reason]");
    show("[data-rms-risk-next-at]");
  } else {
    show("[data-rms-risk-decision]");
    show("[data-rms-risk-ticket-action]");
    show("[data-rms-risk-reason]");
  }
  card.querySelectorAll(`[data-rms-risk-tab="${CSS.escape(id)}"]`).forEach((button) => {
    const active = button.dataset.rmsRiskTabKey === tabKey;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  const preview = rmsCommercialNode(root, "[data-rms-risk-preview]", id);
  const action = rmsCommercialNode(root, "[data-rms-save-risk-decision]", id);
  const reason = rmsCommercialNode(root, "[data-rms-risk-reason]", id);
  if (tabKey === "recycle") {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Reciclaje comercial</strong><small>Se conserva el motivo, la estrategia y el costo efectivo de los beneficios redimidos antes de volver a Evaluación.</small>";
    if (action) action.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">autorenew</span>Enviar a Reciclaje comercial';
    if (reason) reason.placeholder = "Explica qué ocurrió, qué se intentó y qué debe cambiar antes de reactivar";
    const costCard = rmsCommercialNode(root, "[data-rms-nonconversion-cost]", id);
    if (costCard) costCard.hidden = false;
    if (item) loadRmsNonConversionCost(item, root);
  } else {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Ventas atribuidas</strong><small>La venta se libera para registrar el pago, costos, ROI y atribución comercial.</small>";
    if (action) action.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">paid</span>Liberar venta y enviar a Ventas atribuidas';
    if (reason) reason.placeholder = "Explica por qué la condición y la evidencia ya pueden atribuirse";
    const costCard = rmsCommercialNode(root, "[data-rms-nonconversion-cost]", id);
    if (costCard) costCard.hidden = true;
  }
}

async function saveRmsNegotiationDecision(item, root) {
  const draft = rmsNegotiationDraft(root, item.id);
  const actionButton = rmsCommercialNode(root, "[data-rms-negotiation-cta-button]", item.id);
  if (!draft.reason) {
    showFeedback("Explica el motivo de esta decisión comercial.", "info", { title: "Negociación" });
    return;
  }
  if (draft.result === "ACCEPTED") {
    const missing = [!draft.customer_condition && "condición acordada", !draft.inventory_product_id && "producto del inventario", draft.amount <= 0 && "valor", !draft.channel && "canal", !(draft.payment_reference || draft.evidence || draft.summary) && "evidencia, referencia o nota", !draft.summary && "resumen", !draft.responsible && "responsable"].filter(Boolean);
    if (missing.length) {
      showFeedback(`Para confirmar el acuerdo falta: ${missing.join(", ")}.`, "info", { title: "Negociación" });
      return;
    }
    const health = rmsNegotiationCleanHealth(item, draft);
    const riskSignals = health.signals;
    if (draft.commercial_route === "NEGOTIATION_CLEAN" && !health.canClean) {
      showFeedback(`Esta venta no puede atribuirse limpia todavía: ${health.blockers.join(", ")}. Envíala a Riesgos de fuga o completa el dato pendiente.`, "info", { title: "Negociación" });
      return;
    }
    if (actionButton) actionButton.disabled = true;
    const confirmationKey = rmsCommercialOperationKey("commercial-confirmation", item, `${draft.commercial_route}|${draft.product_name}|${draft.amount}|${draft.payment_reference}|${draft.evidence}|${draft.responsible}|${draft.summary}|${draft.objection_status}|${draft.objection_resolution}`);
    await api("/api/business/rms-machine/commercial-confirmation", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft, risk_signals: riskSignals, idempotency_key: confirmationKey }) });
    state.rmsMachineLoaded = false;
    const destination = draft.commercial_route === "NEGOTIATION_CLEAN" ? "cierre" : "control_anti_fuga";
    await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
    showFeedback(draft.commercial_route === "NEGOTIATION_CLEAN" ? "Venta limpia confirmada: lista para atribuir." : "Acuerdo confirmado: pasa a Riesgos de fuga para la validación final.", "success", { title: "Negociación" });
    openRmsStation(destination, { source: "negotiation-accepted" });
    return;
  }
  if (["WAITING", "NO_RESPONSE"].includes(draft.result) && !draft.next_action_at) {
    showFeedback("Programa el próximo contacto antes de conservar este caso en Negociación.", "info", { title: "Negociación" });
    return;
  }
  if (draft.result === "RECYCLE" && (!draft.recycle_reason || !draft.recycle_strategy || !draft.recycle_consent || !draft.recycle_responsible || !draft.channel || !draft.next_action_at)) {
    showFeedback("Para Reciclaje define motivo, estrategia, responsable, canal permitido, consentimiento y fecha de reactivación.", "info", { title: "Negociación" });
    return;
  }
  if (draft.result === "LOST" && !draft.lost_classification) {
    showFeedback("Clasifica la pérdida antes de cerrar la oportunidad.", "info", { title: "Negociación" });
    return;
  }
  if (actionButton) actionButton.disabled = true;
  const operationKey = rmsCommercialOperationKey("negotiation", item, `${draft.result}|${draft.reprocess_phase}|${draft.next_action_at || ""}|${draft.reason}|${draft.recycle_reason || ""}|${draft.lost_classification || ""}`);
  await api("/api/business/rms-machine/negotiation-result", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft, idempotency_key: operationKey }) });
  // Inteligencia recibe el evento analítico, pero no es la ubicación física
  // del lead. Una pérdida queda documentada en su estación y se abre como
  // expediente desde Inteligencia, sin moverla artificialmente.
  const destination = draft.result === "REPROCESS" ? draft.reprocess_phase : "accion_correctiva";
  state.rmsMachineLoaded = false;
  if (draft.result === "RECYCLE") {
    setView("recycling");
  } else {
    await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
  }
  showFeedback(draft.result === "LOST" ? "Pérdida documentada sin crear una venta." : draft.result === "RECYCLE" ? "Caso enviado a Reciclaje comercial con fecha y estrategia." : draft.result === "REPROCESS" ? "El caso volvió al punto elegido con su razón e historial." : "Decisión guardada y siguiente acción programada.", "success", { title: "Negociación" });
  if (draft.result !== "RECYCLE") openRmsStation(destination, { source: "negotiation-result" });
}

async function saveRmsRiskReview(item, root, result) {
  const reason = String(rmsCommercialNode(root, "[data-rms-risk-reason]", item.id)?.value || "").trim();
  if (!reason) {
    showFeedback(result === "CLEARED" ? "Explica por qué el acuerdo está listo para atribuir." : "Explica qué debe corregirse antes de volver a confirmación comercial.", "info", { title: "Validación final" });
    return;
  }
  const next_action_at = rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-risk-next-at]", item.id)?.value || "");
  await api("/api/business/rms-machine/risk-review", {
    method: "POST", headers: authHeaders(),
    body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, result, reason, next_action_at }),
  });
  const destination = result === "CLEARED" ? "cierre" : "accion_correctiva";
  state.rmsMachineLoaded = false;
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
  showFeedback(result === "CLEARED" ? "Riesgo controlado. La venta ya está lista para atribuir." : "El caso volvió a confirmación comercial con una tarea de corrección.", "success", { title: "Validación final" });
  openRmsStation(destination, { source: "risk-review" });
}

async function saveRmsRiskDecision(item, root) {
  const result = rmsCommercialNode(root, "[data-rms-risk-decision]", item.id)?.value || "CLEARED";
  const reason = String(rmsCommercialNode(root, "[data-rms-risk-reason]", item.id)?.value || "").trim();
  const next_action_at = rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-risk-next-at]", item.id)?.value || "");
  if (!reason) {
    showFeedback("Explica el motivo de la decisión de riesgo.", "info", { title: "Riesgos de fuga" });
    return;
  }
  if (["WAITING", "RECYCLE"].includes(result) && !next_action_at) {
    showFeedback("Programa la fecha de seguimiento o reactivación.", "info", { title: "Riesgos de fuga" });
    return;
  }
  if (result === "RECYCLE" && (!rmsCommercialNode(root, "[data-rms-risk-recycle-reason]", item.id)?.value || !rmsCommercialNode(root, "[data-rms-risk-recycle-strategy]", item.id)?.value)) {
    showFeedback("Para Reciclaje define el motivo y la estrategia de reactivación.", "info", { title: "Riesgos de fuga" });
    return;
  }
  const payload = {
    source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, result, reason, next_action_at,
    ticket_action: rmsCommercialNode(root, "[data-rms-risk-ticket-action]", item.id)?.value || "NONE",
    recycle_reason: rmsCommercialNode(root, "[data-rms-risk-recycle-reason]", item.id)?.value || null,
    recycle_strategy: rmsCommercialNode(root, "[data-rms-risk-recycle-strategy]", item.id)?.value || null,
    recycle_note: reason,
    responsible: rmsCommercialWorkflow(item).confirmation?.responsible || null,
  };
  await api("/api/business/rms-machine/risk-review", { method: "POST", headers: authHeaders(), body: JSON.stringify(payload) });
  // Una pérdida genera aprendizaje, no una transición física hacia
  // Inteligencia. El expediente analítico se actualiza en segundo plano.
  const destination = result === "CLEARED" ? "cierre" : result === "RETURN_TO_NEGOTIATION" ? "accion_correctiva" : "control_anti_fuga";
  state.rmsMachineLoaded = false;
  if (result === "RECYCLE") {
    setView("recycling");
  } else {
    await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
  }
  showFeedback(result === "CLEARED" ? "Riesgo controlado: la venta fue liberada para atribución." : result === "RECYCLE" ? "Lead enviado a Reciclaje comercial con fecha y estrategia." : result === "LOST" ? "Pérdida definitiva documentada sin reactivación automática." : "Decisión de riesgo guardada con su siguiente acción.", "success", { title: "Riesgos de fuga" });
  if (result !== "RECYCLE") openRmsStation(destination, { source: "risk-decision" });
}

async function reactivateRmsRecycled(item, note, destination = "procesamiento") {
  await api("/api/business/rms-machine/recycling/reactivate", {
    method: "POST", headers: authHeaders(),
    body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, note, destination }),
  });
  state.rmsMachineLoaded = false;
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
  showFeedback(`Lead reactivado: volvió a ${destination === "clasificacion" ? "Activación 1" : "Evaluación"} con su historial preservado.`, "success", { title: "Reciclaje comercial" });
  openRmsStation(destination, { source: "recycling" });
}

function rmsSaleDraftFromDom(root, id) {
  const productSelect = rmsCommercialNode(root, "[data-rms-sale-product]", id);
  const inventoryProduct = findInventoryProductById(productSelect?.value || "");
  const quantity = Math.max(0.01, rmsCommercialNumber(root, "[data-rms-sale-quantity]", id) || 1);
  const unitPrice = Math.max(0, Number(inventoryProduct?.unit_price || 0));
  const saleAmount = Math.max(0, rmsCommercialNumber(root, "[data-rms-sale-amount]", id));
  return {
    inventory_product_id: inventoryProduct?.id || null,
    product_name: inventoryProduct?.name || "",
    quantity,
    unit_price: unitPrice,
    sale_amount: Math.round(saleAmount * 100) / 100,
    currency: rmsCommercialNode(root, "[data-rms-sale-currency]", id)?.value || "COP",
    unit_cost: Math.max(0, rmsCommercialNumber(root, "[data-rms-sale-unit-cost]", id)),
    benefit_type: rmsCommercialNode(root, "[data-rms-sale-benefit-type]", id)?.value || "NONE",
    benefit_cost: Math.max(0, rmsCommercialNumber(root, "[data-rms-sale-benefit-cost]", id)),
    acquisition_cost: Math.max(0, rmsCommercialNumber(root, "[data-rms-sale-acquisition-cost]", id)),
    payment_method: rmsCommercialNode(root, "[data-rms-sale-payment]", id)?.value || "OTHER",
    paid_at: rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-sale-paid-at]", id)?.value || ""),
    notes: String(rmsCommercialNode(root, "[data-rms-sale-notes]", id)?.value || "").trim(),
  };
}

function updateRmsSaleEconomicsPreview(root, id) {
  const preview = rmsCommercialNode(root, "[data-rms-sale-economics]", id);
  if (!preview) return;
  const draft = rmsSaleDraftFromDom(root, id);
  const amountInput = rmsCommercialNode(root, "[data-rms-sale-amount]", id);
  const item = rmsOpportunityById(id) || {};
  const workflow = rmsCommercialWorkflow(item);
  const confirmation = workflow.confirmation || {};
  const saleContext = confirmation.sale_context || {};
  const riskContext = rmsRiskRecoveryPresentation(workflow.risk || {}, item.state_metadata || item.metadata || {});
  const pricing = rmsAttributedSalePricing({ inventoryProduct: findInventoryProductById(draft.inventory_product_id), quantity: draft.quantity, confirmation, saleContext, riskContext, currency: draft.currency });
  if (amountInput?.readOnly) amountInput.value = String(pricing.finalAmount || 0);
  else if (amountInput) amountInput.value = String(draft.sale_amount || pricing.finalAmount || "");
  draft.sale_amount = amountInput?.readOnly ? pricing.finalAmount : (draft.sale_amount || pricing.finalAmount);
  const unitPrice = rmsCommercialNode(root, "[data-rms-sale-unit-price]", id);
  if (unitPrice) unitPrice.textContent = rmsCommercialMoney(pricing.negotiatedUnitPrice || draft.unit_price, draft.currency);
  const total = rmsCommercialNode(root, "[data-rms-sale-calculated-total]", id);
  if (total) total.textContent = rmsCommercialMoney(draft.sale_amount, draft.currency);
  const priceValue = (selector, value) => { const node = rmsCommercialNode(root, selector, id); if (node) node.textContent = value; };
  priceValue("[data-rms-sale-original-price]", rmsCommercialMoney(pricing.originalAmount, draft.currency));
  priceValue("[data-rms-sale-discount]", `-${rmsCommercialMoney(pricing.discountAmount, draft.currency)}`);
  priceValue("[data-rms-sale-discount-detail]", pricing.detail || "Sin beneficio registrado");
  priceValue("[data-rms-sale-final-price]", rmsCommercialMoney(draft.sale_amount || pricing.finalAmount, draft.currency));
  priceValue("[data-rms-sale-final-detail]", pricing.discountPercent > 0 ? `${pricing.discountPercent}% menos` : "Valor confirmado");
  const productHint = root.querySelector?.(`#rms-sale-product-hint-${CSS.escape(id)}`);
  const evaluation = workflow.evaluation || {};
  const inheritedProductId = confirmation.inventory_product_id
    || evaluation.recommended_inventory_product_id
    || rmsOpportunityById(id)?.classified_product_id
    || rmsOpportunityById(id)?.inventory_product_id
    || "";
  const sourceLabel = confirmation.inventory_product_id
    ? "Negociación"
    : evaluation.recommended_inventory_product_id
      ? "Evaluación"
      : "la asignación del lead";
  if (productHint) {
    productHint.textContent = draft.inventory_product_id && inheritedProductId && String(draft.inventory_product_id) !== String(inheritedProductId)
      ? "Producto corregido al cerrar la venta. Se conservará la referencia negociada y esta será la compra real."
      : `Producto preseleccionado desde ${sourceLabel}. Cámbialo solo si la compra real fue otra referencia.`;
  }
  const productCost = draft.quantity * draft.unit_cost;
  const grossProfit = draft.sale_amount - productCost - draft.benefit_cost;
  const netProfit = grossProfit - draft.acquisition_cost;
  const invested = productCost + draft.benefit_cost + draft.acquisition_cost;
  const roi = invested > 0 ? netProfit / invested : null;
  const hasAffiliate = Boolean(item.is_affiliate || item.affiliate_id || item.source_type === "AFFILIATE");
  const points = hasAffiliate ? affiliateReferralPointsEstimateDetail(draft.sale_amount) : null;
  const affiliateBox = rmsCommercialNode(root, "[data-rms-sale-affiliate]", id);
  if (affiliateBox) affiliateBox.innerHTML = hasAffiliate
    ? `<span class="material-symbols-outlined" aria-hidden="true">workspace_premium</span><div><strong>Afiliado o referido vinculado</strong><small>${points?.points ?? 0} puntos estimados. ${escapeHtml(points?.formula || "El cálculo final se confirma al registrar el pago.")}</small></div>`
    : `<span class="material-symbols-outlined" aria-hidden="true">group</span><div><strong>Sin afiliado vinculado</strong><small>Si existe una relación de referido, se detectará al registrar el pago.</small></div>`;
  preview.innerHTML = [["Precio unitario", rmsCommercialMoney(draft.unit_price, draft.currency)], ["Pago calculado", rmsCommercialMoney(draft.sale_amount, draft.currency)], ["Costo producto", rmsCommercialMoney(productCost, draft.currency)], ["Beneficio", rmsCommercialMoney(draft.benefit_cost, draft.currency)], ["Adquisición", rmsCommercialMoney(draft.acquisition_cost, draft.currency)], ["Utilidad neta", rmsCommercialMoney(netProfit, draft.currency)], ["ROI", roi === null ? "Sin base de costo" : `${(roi * 100).toFixed(1)}%`]].map(([label, value]) => `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("");
}

function applyRmsNegotiationContextToAttributedSales(root) {
  root?.querySelectorAll(".rms-sale-work-item[data-rms-station-lead]").forEach((card) => {
    const item = rmsOpportunityById(card.dataset.rmsStationLead || "");
    const workflow = rmsCommercialWorkflow(item || {});
    const context = workflow.confirmation?.sale_context || {};
    const riskContext = rmsRiskRecoveryPresentation(workflow.risk || {}, item?.state_metadata || item?.metadata || {});
    const setValue = (selector, value) => {
      const field = card.querySelector(selector);
      if (field && value !== undefined && value !== null && value !== "") field.value = String(value);
    };
    setValue("[data-rms-sale-quantity]", Number(context.quantity) > 0 ? context.quantity : 1);
    setValue("[data-rms-sale-benefit-type]", context.benefit_type || riskContext.benefitType || "NONE");
    setValue("[data-rms-sale-benefit-cost]", Number(context.benefit_cost ?? riskContext.benefitCost) || 0);
    setValue("[data-rms-sale-acquisition-cost]", Number(context.acquisition_cost) || 0);
    const inventoryProduct = findInventoryProductById(rmsCommercialNode(root, "[data-rms-sale-product]", item?.id || "")?.value || "");
    setValue("[data-rms-sale-unit-cost]", Number(inventoryProduct?.cost_price) || 0);
    const notes = card.querySelector("[data-rms-sale-notes]");
    if (notes && context.benefit_description && !notes.value.includes(context.benefit_description)) {
      notes.value = [notes.value, `Beneficio o esfuerzo comercial: ${context.benefit_description}`].filter(Boolean).join(" · ");
    }
    const riskNotes = [
      riskContext.decision && `Riesgos de fuga: ${riskContext.reason || "venta liberada"}`,
      riskContext.offer?.type && riskContext.offer.type !== "NONE" && `Alternativa extraordinaria aplicada: ${riskContext.label}`,
      riskContext.ticketAction !== "NONE" && `Acción sobre ticket: ${riskContext.ticketActionLabel}`,
      riskContext.resource?.public_ticket_url && `Ticket de recuperación: ${riskContext.resource.public_ticket_url}`,
      riskContext.responsible && `Responsable de liberación: ${riskContext.responsible}`,
    ].filter(Boolean);
    if (notes && riskNotes.length) {
      const missingRiskNotes = riskNotes.filter((entry) => !notes.value.includes(entry));
      if (missingRiskNotes.length) notes.value = [notes.value, ...missingRiskNotes].filter(Boolean).join(" · ");
    }
    const amountInput = card.querySelector("[data-rms-sale-amount]");
    const amountLabel = amountInput?.closest("label")?.querySelector(":scope > span");
    if (amountInput) amountInput.readOnly = true;
    if (amountLabel) amountLabel.textContent = "Valor pagado (calculado)";
    const pricing = rmsAttributedSalePricing({ inventoryProduct, quantity: Number(card.querySelector("[data-rms-sale-quantity]")?.value || context.quantity || 1), confirmation: workflow.confirmation || {}, saleContext: context, riskContext, currency: workflow.confirmation?.currency || "COP" });
    if (amountInput && pricing.finalAmount > 0) amountInput.value = String(pricing.finalAmount);
    if (!card.querySelector("[data-rms-sale-cost-details]")) {
      const details = document.createElement("details");
      details.className = "rms-sale-cost-details";
      details.dataset.rmsSaleCostDetails = item?.id || "sale";
      details.innerHTML = `<summary>Costos y beneficios <small>(opcionales)</small></summary><div class="rms-sale-form-grid"></div>`;
      const extrasGrid = details.querySelector(".rms-sale-form-grid");
      ["[data-rms-sale-unit-cost]", "[data-rms-sale-benefit-type]", "[data-rms-sale-benefit-cost]", "[data-rms-sale-acquisition-cost]"]
        .map((selector) => card.querySelector(selector)?.closest("label"))
        .filter(Boolean)
        .forEach((label) => extrasGrid?.append(label));
      card.querySelector(".rms-sale-form-grid")?.insertAdjacentElement("afterend", details);
    }
    if (!card.querySelector("[data-rms-sale-calculation]")) {
      card.querySelector(".rms-sale-form-grid")?.insertAdjacentHTML("afterend", `<aside class="rms-sale-calculation" data-rms-sale-calculation="${escapeHtml(item?.id || "sale")}" aria-live="polite"><span>Precio del producto</span><strong data-rms-sale-unit-price="${escapeHtml(item?.id || "sale")}">—</strong><span>× cantidad</span><strong data-rms-sale-calculated-total="${escapeHtml(item?.id || "sale")}">—</strong><small>El valor pagado se calcula con el precio confirmado y la cantidad vendida. Registra descuentos o esfuerzos como beneficio.</small></aside>`);
    }
    if (!card.querySelector("[data-rms-affiliate-credit-note]")) {
      card.querySelector(".rms-sale-trust-ribbon")?.insertAdjacentHTML("afterend", `<aside class="rms-affiliate-sale-note" data-rms-affiliate-credit-note="${escapeHtml(item?.id || "sale")}"><span class="material-symbols-outlined" aria-hidden="true">workspace_premium</span><span>Los puntos de afiliado o referido se acreditan una sola vez cuando registres esta venta como pagada.</span></aside>`);
    }
    const affiliateNote = card.querySelector("[data-rms-affiliate-credit-note]");
    if (affiliateNote) affiliateNote.dataset.rmsSaleAffiliate = item?.id || "sale";
    updateRmsSaleEconomicsPreview(root, item?.id || "");
  });
}

function rmsAttributedSaleKey(id) {
  if (!state.rmsAttributedSaleKeys) state.rmsAttributedSaleKeys = {};
  if (!state.rmsAttributedSaleKeys[id]) state.rmsAttributedSaleKeys[id] = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return state.rmsAttributedSaleKeys[id];
}

function rmsCommercialOperationKey(scope = "commercial", item = {}, signature = "") {
  const base = `${scope}|${item.source_type || "PLAYER"}|${item.source_id || item.id || "lead"}|${signature}`;
  let hash = 2166136261;
  for (let index = 0; index < base.length; index += 1) {
    hash ^= base.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${scope}-${Math.abs(hash >>> 0).toString(36)}-${String(item.source_id || item.id || "lead").slice(0, 36)}`.slice(0, 160);
}

async function saveRmsAttributedSale(item, root) {
  const draft = rmsSaleDraftFromDom(root, item.id);
  const productSelect = rmsCommercialNode(root, "[data-rms-sale-product]", item.id);
  if (!draft.inventory_product_id || draft.sale_amount <= 0) {
    if (!draft.inventory_product_id && productSelect) {
      productSelect.setCustomValidity("Selecciona el producto real del inventario antes de atribuir la venta.");
      productSelect.reportValidity();
      productSelect.focus();
    }
    showFeedback("Selecciona el producto confirmado del inventario y el dinero recibido para atribuir la venta.", "info", { title: "Ventas atribuidas" });
    return;
  }
  if (productSelect) productSelect.setCustomValidity("");
  const result = await api("/api/business/rms-machine/attributed-sales", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft, idempotency_key: rmsAttributedSaleKey(item.id) }),
  });
  if (state.rmsAttributedSaleKeys) delete state.rmsAttributedSaleKeys[item.id];
  state.rmsMachineLoaded = false;
  await Promise.all([
    loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: "postventa" }),
    loadAttributedSalesView({ quiet: true }),
    loadDashboardData({ force: true, quiet: true }),
  ]);
  const customerFeedback = result?.customer?.created
    ? ` Además, ${result.customer.name || "el comprador"} fue creado automáticamente como contacto cliente.`
    : "";
  showFeedback(
    `${result?.duplicate ? "Esta venta ya estaba registrada; no se duplicó." : "Venta atribuida registrada con sus costos, utilidad y ROI. El cliente fue enviado a Valorización Clientes; Inteligencia GOS recibió el resultado para análisis."}${customerFeedback}`,
    "success",
    { title: "Ventas atribuidas" }
  );
  if (!result?.duplicate && result?.affiliate?.points_awarded > 0) {
    showFeedback(`Se acreditaron ${result.affiliate.points_awarded} punto(s) a ${result.affiliate.name || "el afiliado"}.`, "success", { title: "Puntos de afiliado" });
  }
  openRmsStation("postventa", { source: "attributed-sale" });
}

function rmsPostSaleActionKey(id) {
  if (!state.rmsPostSaleActionKeys) state.rmsPostSaleActionKeys = {};
  if (!state.rmsPostSaleActionKeys[id]) state.rmsPostSaleActionKeys[id] = globalThis.crypto?.randomUUID?.() || `post-sale-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return state.rmsPostSaleActionKeys[id];
}

function rmsPostSaleDraftFromDom(root, id) {
  const path = rmsPostSaleRefineryPath(root, id);
  if (path === "REFERRAL") {
    const benefit = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-referral-benefit]") || "").trim();
    const channel = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-channel]") || "").trim();
    const name = "";
    const phone = "";
    const email = "";
    const interest = "";
    const consent = false;
    return {
      refinery_path: path,
      action_type: "REFERRAL", execution_mode: "NEW_TICKET", status: "ISSUED",
      contact_channel: channel || null, contact_consent_confirmed: false,
      content: String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-message]") || "").trim() || null,
      result_note: "Activación de referidos creada desde la venta atribuida.",
      ticket: { benefit: { benefit_type: "CUSTOM", benefit_label: benefit, benefit_value: {} }, expires_mode: "30_DAYS" },
      referred_contact: { name: name || null, phone: phone || null, email: email || null, interest: interest || null, preferred_channel: channel || null, note: "Referido capturado desde Valorización Clientes.", contact_consent_confirmed: consent },
      metadata: { refinery_path: path, referral_capture: "public_claim_link", referral_claim_required: true },
    };
  }
  if (path === "REBUY") {
    const benefit = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-rebuy-benefit]") || "").trim();
    const channel = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-channel]") || "").trim();
    return {
      refinery_path: path,
      action_type: "REBUY_TICKET", execution_mode: "NEW_TICKET", status: "ISSUED",
      contact_channel: channel || null, contact_consent_confirmed: false,
      content: String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-message]") || "").trim() || null,
      result_note: "Beneficio de recompra creado desde la venta atribuida.",
      ticket: { benefit: { benefit_type: "CUSTOM", benefit_label: benefit, benefit_value: {} }, expires_mode: "30_DAYS" },
      metadata: { refinery_path: path },
    };
  }
  const loyaltyMode = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-loyalty-mode]") || "POINTS").toUpperCase();
  const affiliateMode = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-affiliate-mode]") || "NONE").toUpperCase();
  const visitNumber = Math.max(1, Number(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-visit-number]") || 1));
  const visitTarget = Math.max(2, Number(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-visit-target]") || 5));
  const visitBenefit = String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-visit-benefit]") || "").trim();
  const deliversVisitBenefit = loyaltyMode === "VISITS" && visitNumber >= visitTarget;
  return {
    refinery_path: path,
    action_type: deliversVisitBenefit ? "REBUY_TICKET" : "REWARD_PASS",
    execution_mode: deliversVisitBenefit ? "NEW_TICKET" : "TASK",
    status: deliversVisitBenefit ? "ISSUED" : "COMPLETED",
    contact_channel: null, contact_consent_confirmed: false,
    content: String(rmsPostSaleRefineryValue(root, id, path, "[data-rms-refinery-loyalty-note]") || "").trim() || null,
    result_note: loyaltyMode === "POINTS" ? "Compra registrada para fidelización por puntos." : `Sello ${visitNumber} de ${visitTarget} registrado.`,
    ticket: deliversVisitBenefit ? { benefit: { benefit_type: "CUSTOM", benefit_label: visitBenefit, benefit_value: {} }, expires_mode: "30_DAYS" } : {},
    metadata: { refinery_path: path, loyalty: { mode: loyaltyMode, affiliate_mode: affiliateMode, visit_number: visitNumber, visit_target: visitTarget, visit_benefit: visitBenefit || null } },
  };
}

async function loadRmsPostSaleActions(options = {}) {
  const maxAge = 45_000;
  const loadedAt = Number(state.rmsPostSaleActionsLoadedAt || 0);
  if (!options.force && Array.isArray(state.rmsPostSaleActions) && Date.now() - loadedAt < maxAge) {
    return state.rmsPostSaleActions;
  }
  if (state.rmsPostSaleActionsLoading) return state.rmsPostSaleActionsLoading;
  const request = apiSafe("/api/business/rms-machine/post-sale-actions?lite=1&limit=48", { headers: authHeaders() }, { actions: [] })
    .then((data) => {
      state.rmsPostSaleActions = Array.isArray(data.actions) ? data.actions : [];
      state.rmsPostSaleActionsLoadedAt = Date.now();
      return state.rmsPostSaleActions;
    })
    .finally(() => { state.rmsPostSaleActionsLoading = null; });
  state.rmsPostSaleActionsLoading = request;
  return request;
}

function rmsIntelligenceSourceFromKey(key = "") {
  const [sourceType, sourceId] = String(key || "").split(":");
  return { source_type: sourceType || "PLAYER", source_id: sourceId || "" };
}

function rmsIntelligenceInsightKey(source = {}) {
  return globalThis.crypto?.randomUUID?.() || `rms-insight-${source.source_id || "pattern"}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

async function loadRmsIntelligenceData(options = {}) {
  const patternParams = new URLSearchParams(Object.entries(state.rmsIntelligenceFilters || {}).filter(([, value]) => String(value || "").trim()));
  const [patterns, insightData, caseData] = await Promise.all([
    apiSafe(`/api/business/rms-machine/intelligence/patterns${patternParams.size ? `?${patternParams.toString()}` : ""}`, { headers: authHeaders() }, null),
    apiSafe("/api/business/rms-machine/intelligence/insights", { headers: authHeaders() }, { insights: [] }),
    apiSafe("/api/business/rms-machine/intelligence/cases", { headers: authHeaders() }, { cases: [] }),
  ]);
  state.rmsIntelligencePatterns = patterns;
  state.rmsIntelligenceInsights = Array.isArray(insightData?.insights) ? insightData.insights : [];
  state.rmsIntelligenceCases = Array.isArray(caseData?.cases) ? caseData.cases : [];
  return { patterns, insights: state.rmsIntelligenceInsights, cases: state.rmsIntelligenceCases };
}

async function loadRmsIntelligenceCase(itemOrKey) {
  const key = typeof itemOrKey === "string" ? itemOrKey : rmsIntelligenceCaseKey(itemOrKey || {});
  const source = rmsIntelligenceSourceFromKey(key);
  if (!source.source_id) return null;
  state.rmsIntelligenceCaseKey = key;
  state.rmsIntelligenceCase = await api(`/api/business/rms-machine/intelligence/case?source_id=${encodeURIComponent(source.source_id)}&source_type=${encodeURIComponent(source.source_type)}`, { headers: authHeaders() });
  return state.rmsIntelligenceCase;
}

function rmsIntelligenceDraftFromDom(root, key) {
  const value = (selector) => root.querySelector(selector)?.value || "";
  const source = rmsIntelligenceSourceFromKey(key);
  const evidence = String(value("[data-rms-intelligence-evidence]") || "").trim();
  return {
    source_type: source.source_type,
    source_id: source.source_id,
    insight_scope: "CASE",
    observation: String(value("[data-rms-intelligence-observation]") || "").trim(),
    hypothesis: String(value("[data-rms-intelligence-hypothesis]") || "").trim() || null,
    recommendation: String(value("[data-rms-intelligence-recommendation]") || "").trim(),
    evidence_refs: evidence ? evidence.split(/\n|,/).map((item) => item.trim()).filter(Boolean).slice(0, 40) : [],
    evidence_note: evidence || null,
    owner_name: String(value("[data-rms-intelligence-owner]") || "").trim() || null,
    priority: value("[data-rms-intelligence-priority]") || "MEDIUM",
    status: value("[data-rms-intelligence-status]") || "PENDING",
    expected_metric: String(value("[data-rms-intelligence-metric]") || "").trim() || null,
    review_at: rmsCommercialLocalToIso(value("[data-rms-intelligence-review-at]")) || null,
    idempotency_key: rmsIntelligenceInsightKey(source),
  };
}

async function saveRmsIntelligenceInsight(root, key) {
  const draft = rmsIntelligenceDraftFromDom(root, key);
  if (!draft.observation || !draft.recommendation) {
    throw new Error("Registra una observación y una recomendación concreta respaldada por hechos.");
  }
  state.rmsIntelligenceSaving = true;
  try {
    const result = await api("/api/business/rms-machine/intelligence/insights", {
      method: "POST", headers: authHeaders(), body: JSON.stringify(draft),
    });
    await loadRmsIntelligenceData({ force: true });
    showFeedback(result?.duplicate ? "Ese aprendizaje ya estaba guardado; no se duplicó." : "Aprendizaje guardado. No se creó ninguna campaña, venta ni lead.", "success", { title: "Inteligencia GOS" });
  } finally {
    state.rmsIntelligenceSaving = false;
  }
}

async function createRmsIntelligenceAgendaTask(insightId) {
  const result = await api("/api/business/rms-machine/intelligence/agenda-task", {
    method: "POST", headers: authHeaders(), body: JSON.stringify({ insight_id: insightId, confirm: true }),
  });
  await loadRmsIntelligenceData({ force: true });
  showFeedback(result?.task ? "Tarea creada por tu confirmación explícita." : "No se pudo crear la tarea.", "success", { title: "Inteligencia GOS" });
}

async function applyRmsPostSaleLoyalty(item, result, draft) {
  if (draft.refinery_path !== "LOYALTY" || result?.duplicate || !session?.user?.business_id) return null;
  const loyalty = draft.metadata?.loyalty || {};
  const affiliateMode = String(loyalty.affiliate_mode || "NONE").toUpperCase();
  if (affiliateMode === "NONE") return null;
  if (!state.affiliatesLoaded) await loadAffiliatesData();
  let affiliate = rmsPostSaleAffiliateFor(item);
  if (!affiliate && affiliateMode === "ENROLL") {
    const created = await api(`/api/portal/businesses/${session.user.business_id}/affiliates`, {
      method: "POST", headers: authHeaders(),
      body: JSON.stringify({
        full_name: item.name || "Cliente Qori", phone: item.phone || null, email: item.email || null,
        notes: "Afiliado desde Valorización Clientes tras una venta atribuida.",
        card_metadata: { source: "rms_activation_2", source_id: item.source_id, sale_id: result?.sale?.id || null },
      }),
    });
    affiliate = created?.affiliate || null;
    if (affiliate) state.affiliates = [affiliate, ...(state.affiliates || []).filter((entry) => entry.id !== affiliate.id)];
  }
  if (!affiliate || String(loyalty.mode || "").toUpperCase() !== "POINTS") return affiliate;
  const amount = Number(item.state_metadata?.rms_sale_amount || item.total_spent || result?.sale?.sale_amount || 0);
  if (!Number.isFinite(amount) || amount <= 0) return affiliate;
  const points = await api(`/api/portal/businesses/${session.user.business_id}/affiliates/${affiliate.id}/points`, {
    method: "POST", headers: authHeaders(),
    body: JSON.stringify({
      amount, reason: "RMS_POST_SALE_PURCHASE",
      metadata: { source: "rms_activation_2", post_sale_action_id: result?.action?.id || null, sale_id: result?.sale?.id || null },
    }),
  });
  await loadAffiliatesData();
  return { ...affiliate, awarded: Number(points?.awarded || 0) };
}

async function saveRmsPostSaleAction(item, root) {
  const draft = rmsPostSaleDraftFromDom(root, item.id);
  const requiredFeature = draft.refinery_path === "REFERRAL"
    ? "referrals"
    : draft.refinery_path === "LOYALTY"
      ? "affiliates"
      : null;
  if (requiredFeature && !hasPlanFeature(requiredFeature)) {
    showFeatureUpgradeInterstitial(requiredFeature, { requestedView: "rms-machine" });
    return;
  }
  if (draft.execution_mode === "NEW_TICKET" && !draft.ticket.benefit.benefit_label) {
    throw new Error(draft.refinery_path === "REFERRAL" ? "Indica el beneficio antes de crear el QR de referidos." : "Indica el beneficio antes de crear el ticket de recompra.");
  }
  if (draft.refinery_path === "REFERRAL") {
    const referred = draft.referred_contact || {};
    const hasContact = Boolean(referred.name || referred.phone || referred.email);
    if (hasContact && (!referred.name || (!referred.phone && !referred.email))) throw new Error("Para crear el lead referido registra su nombre y al menos WhatsApp o correo.");
    if (hasContact && !referred.contact_consent_confirmed) throw new Error("Confirma la autorización del referido antes de guardar sus datos.");
  }
  if (draft.refinery_path === "LOYALTY" && draft.metadata?.loyalty?.mode === "VISITS" && Number(draft.metadata?.loyalty?.visit_number || 0) >= Number(draft.metadata?.loyalty?.visit_target || 0) && !draft.ticket.benefit.benefit_label) {
    throw new Error("Indica el beneficio que recibirá al completar los sellos.");
  }
  const saleId = item.state_metadata?.rms_attributed_sale_id || null;
  const result = await api("/api/business/rms-machine/post-sale-actions", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({
      source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null,
      sale_id: saleId, ...draft, send_to_intelligence: true, idempotency_key: rmsPostSaleActionKey(item.id),
    }),
  });
  if (result?.resource && result?.action?.id) {
    state.rmsPostSaleGeneratedResources ||= {};
    state.rmsPostSaleGeneratedResources[result.action.id] = result.resource;
  }
  if (state.rmsPostSaleActionKeys) delete state.rmsPostSaleActionKeys[item.id];
  let loyaltyResult = null;
  try { loyaltyResult = await applyRmsPostSaleLoyalty(item, result, draft); }
  catch (error) { showFeedback(`La acción postventa quedó registrada, pero no pudimos actualizar afiliación o puntos: ${error.message}`, "error", { title: "Fidelización" }); }
  await Promise.all([
    loadRmsPostSaleActions({ force: true }),
    loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: "postventa" }),
  ]);
  const loyaltyMessage = loyaltyResult?.awarded
    ? ` Se acreditaron ${loyaltyResult.awarded.toLocaleString("es-CO")} puntos al afiliado.`
    : draft.refinery_path === "LOYALTY" && loyaltyResult ? " La afiliación quedó vinculada a esta compra." : "";
  showFeedback(result?.duplicate ? "Esta acción ya estaba registrada; no se duplicó el recurso ni la venta." : `Acción de Valorización registrada y resultado enviado a Inteligencia GOS.${loyaltyMessage}`, "success", { title: "Valorización Clientes" });
  openRmsStation("postventa", { source: "post-sale-action" });
}

async function sendRmsPostSaleToIntelligence(item, root) {
  const resultInput = rmsCommercialNode(root, "[data-rms-post-sale-result]", item.id);
  const typeInput = rmsCommercialNode(root, "[data-rms-post-sale-type]", item.id);
  const modeInput = rmsCommercialNode(root, "[data-rms-post-sale-mode]", item.id);
  const statusInput = rmsCommercialNode(root, "[data-rms-post-sale-status]", item.id);
  const channelInput = rmsCommercialNode(root, "[data-rms-post-sale-channel]", item.id);
  const saleId = item.state_metadata?.rms_attributed_sale_id || null;
  const reason = String(resultInput?.value || "").trim() || "No se realizará una acción postventa para este cliente en este momento.";
  if (resultInput && !resultInput.value.trim()) resultInput.value = reason;
  if (typeInput) typeInput.value = "NO_ACTION_NEEDED";
  if (modeInput) modeInput.value = "TASK";
  if (statusInput) statusInput.value = "NOT_APPLICABLE";
  if (channelInput) channelInput.value = "";
  const button = rmsCommercialNode(root, "[data-rms-post-sale-skip-to-intelligence]", item.id);
  if (button) button.disabled = true;
  try {
    const result = await api("/api/business/rms-machine/post-sale-actions", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        source_id: item.source_id,
        source_type: item.source_type || "PLAYER",
        lead_id: item.lead_id || null,
        sale_id: saleId,
        action_type: "NO_ACTION_NEEDED",
        execution_mode: "TASK",
        status: "NOT_APPLICABLE",
        result_note: reason,
        send_to_intelligence: true,
        idempotency_key: rmsPostSaleActionKey(item.id),
      }),
    });
    if (state.rmsPostSaleActionKeys) delete state.rmsPostSaleActionKeys[item.id];
    await Promise.all([
      loadRmsPostSaleActions({ force: true }),
      loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: "postventa" }),
      loadRmsIntelligenceData({ force: true }),
    ]);
    showFeedback(result?.duplicate ? "Esta decisión ya estaba registrada; no se duplicó." : "Sin activación adicional: la decisión quedó registrada y enviada a Inteligencia GOS.", "success", { title: "Valorización Clientes" });
    openRmsStation("postventa", { source: "post-sale-intelligence" });
  } catch (error) {
    if (button) button.disabled = false;
    throw error;
  }
}

function rmsActivationDelivery(item = {}) {
  const metadata = item.state_metadata || item.metadata || item.rms_metadata || {};
  return {
    sentAt: item.activation_offer_sent_at || metadata.activation_offer_sent_at || "",
    firstContactAt: item.activation_first_contact_at || metadata.activation_first_contact_at || item.activation_offer_sent_at || metadata.activation_offer_sent_at || "",
    contactCount: Number(item.activation_contact_count || metadata.activation_contact_count || (item.activation_offer_sent_at || metadata.activation_offer_sent_at ? 1 : 0)),
    channel: item.activation_delivery_channel || metadata.activation_delivery_channel || (item.phone ? "whatsapp" : "email"),
    offer: item.activation_offer_name || metadata.activation_offer_name || rmsClassifiedProductName(item) || item.product_interest || "Oferta comercial",
    note: item.activation_offer_note || metadata.activation_offer_note || "",
    message: item.activation_message || metadata.activation_message || "",
    followUpAt: item.activation_follow_up_at || metadata.activation_follow_up_at || "",
    outcome: item.activation_outcome || metadata.activation_outcome || "PENDING",
    outcomeNote: item.activation_outcome_note || metadata.activation_outcome_note || "",
  };
}

function rmsActivationReady(item = {}) {
  const delivery = rmsActivationDelivery(item);
  return Boolean(delivery.sentAt && delivery.followUpAt);
}

function rmsActivationEvaluationMovePayload(item = {}) {
  const delivery = rmsActivationDelivery(item);
  return {
    source_id: item.source_id,
    source_type: item.source_type || "PLAYER",
    lead_id: item.lead_id || null,
    to_phase: "procesamiento",
    priority: rmsPriorityCode(item),
    recommended_action: "Evaluar la respuesta y definir el siguiente paso comercial",
    last_operation: "activation_sent_to_evaluation",
    last_material_sent: delivery.offer,
    revenue_potential: Number(item.revenue_potential || 0),
    reason: `Activación 1 completada: ${rmsActivationOutcomeLabel(delivery.outcome)}.`,
    metadata: {
      source_module: "rms_machine",
      source_flow: "activation_to_evaluation",
      from_phase: "clasificacion",
      activation_offer_sent_at: delivery.sentAt,
      activation_delivery_channel: delivery.channel,
      activation_offer_name: delivery.offer,
      activation_offer_note: delivery.note,
      activation_message: delivery.message,
      activation_follow_up_at: delivery.followUpAt,
      activation_outcome: delivery.outcome,
      activation_outcome_updated_at: new Date().toISOString(),
    },
  };
}

async function moveSelectedRmsActivationsToEvaluation() {
  const selectedIds = new Set(state.rmsMachineSelectedIds || []);
  const selectedRows = rmsStationRows("clasificacion", state.rmsMachine?.opportunities || [])
    .filter((item) => selectedIds.has(item.id));
  if (!selectedRows.length) {
    showFeedback("Selecciona al menos un lead de Activación 1.", "info", { title: "Activación 1" });
    return;
  }
  const readyRows = selectedRows.filter((item) => rmsActivationReadyForEvaluation(item));
  const blockedRows = selectedRows.filter((item) => !readyRows.includes(item));
  if (!readyRows.length) {
    showFeedback("Los leads seleccionados necesitan contacto, seguimiento y una respuesta guardada antes de pasar a Evaluación.", "info", { title: "Activación 1" });
    return;
  }
  showFeedback(`Enviando ${readyRows.length.toLocaleString("es-CO")} lead${readyRows.length === 1 ? "" : "s"} a Evaluación…`, "loading", { title: "Activación 1", timeout: 0 });
  const results = await runBulkRequests(readyRows, (item) => api("/api/business/rms-machine/lead/phase", {
    method: "PATCH",
    headers: authHeaders(),
    body: JSON.stringify(rmsActivationEvaluationMovePayload(item)),
  }), { concurrency: 6 });
  const movedIds = results.filter((result) => result.ok).map((result) => result.item.id);
  const failedIds = results.filter((result) => !result.ok).map((result) => result.item.id);
  state.rmsMachineSelectedIds = [...blockedRows.map((item) => item.id), ...failedIds];
  if (movedIds.includes(state.rmsActivationWorkId)) state.rmsActivationWorkId = "";
  state.rmsMachineLoaded = false;
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: movedIds.length ? "procesamiento" : "clasificacion" });
  if (movedIds.length) openRmsStation("procesamiento", { source: "activation-bulk-evaluation" });
  const omitted = blockedRows.length;
  const failed = failedIds.length;
  const detail = [
    omitted ? `${omitted} sin requisitos completos` : "",
    failed ? `${failed} con error` : "",
  ].filter(Boolean).join(" · ");
  showFeedback(
    movedIds.length
      ? `${movedIds.length.toLocaleString("es-CO")} lead${movedIds.length === 1 ? "" : "s"} enviado${movedIds.length === 1 ? "" : "s"} conjuntamente a Evaluación${detail ? ` · ${detail}` : ""}.`
      : `No se movieron leads${detail ? ` · ${detail}` : ""}.`,
    failed || omitted ? "info" : "success",
    { title: "Activación 1" }
  );
}

async function moveRmsActivationToEvaluation(item = {}) {
  if (!item?.source_id) return;
  if (!rmsActivationReady(item)) {
    showFeedback("Confirma el contacto y agenda el seguimiento antes de pasar el lead a Evaluación.", "info", { title: "Activación 1" });
    return;
  }
  if (!rmsActivationReadyForEvaluation(item)) {
    showFeedback("Guarda una respuesta del lead antes de pasarlo a Evaluación.", "info", { title: "Activación 1" });
    return;
  }
  try {
    showFeedback("Enviando el lead a Evaluación…", "loading", { title: "Activación 1", timeout: 0 });
    await api("/api/business/rms-machine/lead/phase", {
      method: "PATCH",
      headers: authHeaders(),
      body: JSON.stringify(rmsActivationEvaluationMovePayload(item)),
    });
    state.rmsMachineSelectedIds = (state.rmsMachineSelectedIds || []).filter((id) => id !== item.id);
    state.rmsMachineLoaded = false;
    if (state.rmsActivationWorkId === item.id) state.rmsActivationWorkId = "";
    await refreshRmsOpenStation("clasificacion");
    showFeedback("Lead enviado a Evaluación con su contacto y respuesta registrados.", "success", { title: "Activación 1" });
  } catch (error) {
    showFeedback(error.message || "No se pudo enviar el lead a Evaluación.", "error", { title: "Activación 1" });
  }
}

function rmsActivationReadyForEvaluation(item = {}) {
  const delivery = rmsActivationDelivery(item);
  return rmsActivationReady(item) && Boolean(delivery.outcome && delivery.outcome !== "PENDING");
}

const RMS_ACTIVATION_OUTCOMES = [
  { value: "PENDING", label: "Aún sin respuesta" },
  { value: "INTERESTED", label: "Respondió con interés" },
  { value: "NEEDS_HELP", label: "Pidió más información" },
  { value: "APPOINTMENT", label: "Aceptó llamada o cita" },
  { value: "NO_RESPONSE", label: "Sin respuesta" },
  { value: "NOT_INTERESTED", label: "No le interesa ahora" },
];

function rmsActivationOutcomeLabel(value = "PENDING") {
  return RMS_ACTIVATION_OUTCOMES.find((option) => option.value === value)?.label || "Aún sin respuesta";
}

function rmsActivationMessage(item = {}, delivery = rmsActivationDelivery(item)) {
  if (delivery.message) return delivery.message;
  const offer = delivery.offer || "nuestra oferta";
  const strategy = item.campaign_name || item.coverage_type || "una propuesta pensada para ti";
  return [
    `Hola ${item.first_name || item.name || ""}`.trim(),
    `Vi tu interés y preparé ${offer}.`,
    `La propuesta está pensada para ${strategy}.`,
    "¿Te la comparto y resolvemos juntos el siguiente paso?",
  ].filter(Boolean).join("\n\n");
}

function rmsActivationDatetimeLocal(value = "", daysFromNow = 1) {
  const date = value ? new Date(value) : new Date(Date.now() + daysFromNow * 24 * 60 * 60 * 1000);
  if (Number.isNaN(date.getTime())) return "";
  if (!value) date.setHours(10, 0, 0, 0);
  const timezoneOffset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - timezoneOffset).toISOString().slice(0, 16);
}

