function enforceRmsFactorySpacing() {
  const consoleShell = document.querySelector(
    "#workspace.app-shell .content-shell > .view-section.active[data-view=\"rms-machine\"] > .rms-factory-console"
  );
  if (!consoleShell) return;

  const compact = window.matchMedia?.("(max-width: 680px)").matches;
  const medium = window.matchMedia?.("(max-width: 1180px)").matches;
  const outerPadding = compact ? "22px 18px" : "clamp(32px, 4vw, 60px)";
  const sectionPadding = compact ? "22px 0" : "clamp(28px, 3.2vw, 44px) 0";

  consoleShell.style.setProperty("display", "flex", "important");
  consoleShell.style.setProperty("flex-direction", "column", "important");
  consoleShell.style.setProperty("gap", compact ? "28px" : "clamp(32px, 4vw, 56px)", "important");
  consoleShell.style.setProperty("padding", outerPadding, "important");
  consoleShell.style.setProperty("box-sizing", "border-box", "important");

  const boardTools = consoleShell.querySelector(":scope > .rms-board-tools");
  if (boardTools) {
    boardTools.style.setProperty("padding", sectionPadding, "important");
    boardTools.style.setProperty("margin", "0", "important");
    boardTools.style.setProperty("box-sizing", "border-box", "important");
  }

  const stageSlider = consoleShell.querySelector(":scope > .rms-stage-slider-shell");
  if (stageSlider) {
    stageSlider.style.setProperty("padding", sectionPadding, "important");
    stageSlider.style.setProperty("margin", "0", "important");
    stageSlider.style.setProperty("box-sizing", "border-box", "important");
  }

  const operatorToolbar = boardTools?.querySelector(".rms-operator-toolbar");
  const bulkToolbar = boardTools?.querySelector(".rms-bulk-toolbar");
  [operatorToolbar, bulkToolbar].filter(Boolean).forEach((toolbar) => {
    toolbar.style.setProperty("display", "grid", "important");
    toolbar.style.setProperty(
      "grid-template-columns",
      compact ? "minmax(0, 1fr)" : medium ? "repeat(2, minmax(0, 1fr))" : "minmax(220px, 1fr) minmax(175px, .78fr) auto auto auto",
      "important"
    );
    toolbar.style.setProperty("gap", compact ? "12px" : "clamp(14px, 1.8vw, 24px)", "important");
    toolbar.style.setProperty("padding", compact ? "20px 0 0" : "28px 0 0", "important");
  });
}

function sortMissionLeaderboardRows(rows = []) {
  const order = missionLeaderboardOrder?.value || "total_spent_desc";
  const numberValue = (row, field) => Number(row?.[field] || 0);
  const dateValue = (row) => new Date(row?.last_activity_at || 0).getTime() || 0;
  return [...(Array.isArray(rows) ? rows : [])].sort((left, right) => {
    if (order === "purchases_desc") return numberValue(right, "purchases_count") - numberValue(left, "purchases_count");
    if (order === "average_ticket_desc") return numberValue(right, "average_ticket") - numberValue(left, "average_ticket");
    if (order === "recent_desc") return dateValue(right) - dateValue(left);
    return numberValue(right, "total_spent") - numberValue(left, "total_spent");
  });
}

function renderMissionsView() {
  ensureMissionsUxStyles();
  const period = normalizeMissionPeriod(state.missionSeasonFilter || "week");
  state.missionSeasonFilter = period;
  syncMissionPeriodControls();
  state.missionLeaderboardRows = sortMissionLeaderboardRows(state.missionLeaderboardRows || []);
  renderMissionsKpis();
  renderMissionActiveList(state.missions?.seasons || []);
  renderMissionRewards(state.missions?.rewards || []);
  renderMissionLeaderboard(state.missionLeaderboardRows || [], "PURCHASES");
  if (state.missionLeaderboardLoadedPeriod !== period && !state.missionLeaderboardLoading) {
    loadMissionPurchaseLeaderboard(period).catch((error) => {
      renderMissionLeaderboard([], "PURCHASES");
      showFeedback(error.message || "No se pudo cargar el leaderboard de compras.", "error", { title: "Temporadas" });
    });
  }
}

function renderMissionsKpis() {
  if (!missionsKpiGrid) return;
  const summary = state.missionLeaderboardSummary || {};
  const period = normalizeMissionPeriod(state.missionSeasonFilter || "week");
  const dateRange = [summary.start_date || state.missionLeaderboardStartDate, summary.end_date || state.missionLeaderboardEndDate]
    .filter(Boolean)
    .map((date) => formatDate(date))
    .join(" a ");
  const cards = [
    ["Periodo", missionPeriodLabel(period), dateRange || "Filtro activo"],
    ["Clientes", Number(summary.customers_count || 0).toLocaleString("es-CO"), "Compradores identificados"],
    ["Compras", Number(summary.purchases_count || 0).toLocaleString("es-CO"), "Ventas en el periodo"],
    ["Valor comprado", money(summary.total_spent || 0), "Revenue del leaderboard"],
    ["Ticket promedio", money(summary.average_ticket || 0), "Promedio por compra"],
    ["Top #1", summary.top_customer || "Sin ventas aún", "Cliente líder del ranking"],
  ];
  missionsKpiGrid.innerHTML = cards.map(([label, value, meta]) => `
    <article class="rms-kpi-card mission-kpi-card">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(meta)}</small>
    </article>
  `).join("");
}

function renderMissionTemplates() {
  if (!missionTemplateGrid) return;
  missionTemplateGrid.innerHTML = missionTemplates().map((template) => `
    <article class="mission-template-card">
      <span class="mission-type">${escapeHtml(template.type || "TEMPORADA_MG")}</span>
      <h4>${escapeHtml(template.name)}</h4>
      <p>${escapeHtml(template.description || "")}</p>
      <div class="mission-template-meta">
        <span>${escapeHtml(template.channel || "mixto")}</span>
        <span>Top ${Number(template.ranking?.top_limit || 10).toLocaleString("es-CO")}</span>
      </div>
      <button class="solid-button compact" type="button" data-open-mission-wizard="${escapeHtml(template.key)}">Usar plantilla</button>
    </article>
  `).join("");
  bindMissionWizardOpeners(missionTemplateGrid);
}

function filteredMissionSeasons(seasons = []) {
  return Array.isArray(seasons) ? seasons : [];
}

function renderMissionActiveList(seasons = []) {
  if (!missionActiveList) return;
  const rows = filteredMissionSeasons(seasons);
  missionActiveList.innerHTML = rows.map((season) => {
    const isPurchaseCompetition = String(season.settings_json?.ranking?.ranking_type || "").toUpperCase() === "PURCHASES";
    const participants = isPurchaseCompetition ? season.purchase_customers_count : season.participants_count;
    const mainMetricLabel = isPurchaseCompetition ? "Ventas del periodo" : "Puntos";
    const mainMetricValue = isPurchaseCompetition ? money(season.purchase_amount || 0) : Number(season.points_total || 0).toLocaleString("es-CO");
    const progress = missionDateProgress(season);
    const active = String(season.status || "").toUpperCase() === "ACTIVE";
    return `
    <article class="mission-active-card ${active ? "is-active" : ""} ${isPurchaseCompetition ? "is-purchase" : ""}">
      <div class="mission-active-head">
        <div>
          <span class="mono-label">${escapeHtml(missionRankingLabel(season))}</span>
          <h4>${escapeHtml(season.name || "Dinámica Qori")}</h4>
          <p>${escapeHtml(season.description || "Dinámica comercial gamificada.")}</p>
        </div>
        <span class="status-chip ${missionStatusClass(season.status)}">${escapeHtml(missionStatusLabel(season.status))}</span>
      </div>
      <div class="mission-date-row">
        <span class="pill muted">Inicio ${season.start_date ? escapeHtml(formatDate(season.start_date)) : "sin fecha"}</span>
        <span class="pill muted">Final ${season.end_date ? escapeHtml(formatDate(season.end_date)) : "sin fecha"}</span>
        <span class="pill muted">${progress}% recorrido</span>
      </div>
      <div class="mission-progress-track" aria-label="Progreso de temporada"><span style="width:${progress}%"></span></div>
      <div class="mission-type-row">
        <span class="pill muted">${escapeHtml(season.type || "Temporada")}</span>
        <span class="pill muted">${escapeHtml(season.channel || "Canal mixto")}</span>
      </div>
      <dl>
        <div><dt>${isPurchaseCompetition ? "Clientes" : "Participantes"}</dt><dd>${Number(participants || 0).toLocaleString("es-CO")}</dd></div>
        <div><dt>${escapeHtml(mainMetricLabel)}</dt><dd>${escapeHtml(mainMetricValue)}</dd></div>
        <div><dt>${isPurchaseCompetition ? "Compras" : "Top"}</dt><dd>${isPurchaseCompetition ? Number(season.purchases_count || 0).toLocaleString("es-CO") : Number(season.settings_json?.ranking?.top_limit || 0).toLocaleString("es-CO")}</dd></div>
      </dl>
      <div class="button-row">
        <button class="ghost-button" type="button" data-mission-agenda="${escapeHtml(season.id)}">Crear tareas</button>
        <button class="ghost-button" type="button" data-mission-leaderboard="${escapeHtml(season.id)}">Ver ranking</button>
        ${String(season.status || "").toUpperCase() === "ACTIVE"
          ? `<button class="ghost-button" type="button" data-mission-status="PAUSED" data-mission-id="${escapeHtml(season.id)}">Pausar</button>`
          : String(season.status || "").toUpperCase() === "CLOSED"
            ? ""
            : `<button class="solid-button compact" type="button" data-mission-status="ACTIVE" data-mission-id="${escapeHtml(season.id)}">Activar</button>`}
        ${["ACTIVE", "PAUSED", "DRAFT"].includes(String(season.status || "").toUpperCase())
          ? `<button class="ghost-button compact" type="button" data-mission-status="CLOSED" data-mission-id="${escapeHtml(season.id)}">Cerrar</button>`
          : ""}
      </div>
    </article>
  `;
  }).join("") || `
    <div class="empty-state">
      ${seasons.length ? "No hay temporadas con el filtro seleccionado." : "Aún no hay dinámicas activas. Crea una temporada, un ranking de clientes o una racha de recompra para empezar."}
    </div>
  `;
  missionActiveList.querySelectorAll("[data-mission-agenda]").forEach((button) => {
    button.addEventListener("click", () => createMissionAgendaTasks(button.dataset.missionAgenda));
  });
  missionActiveList.querySelectorAll("[data-mission-leaderboard]").forEach((button) => {
    button.addEventListener("click", () => loadMissionLeaderboard(button.dataset.missionLeaderboard));
  });
  missionActiveList.querySelectorAll("[data-mission-status]").forEach((button) => {
    button.addEventListener("click", () => updateMissionSeasonStatus(button.dataset.missionId, button.dataset.missionStatus));
  });
}

async function updateMissionSeasonStatus(seasonId, status) {
  if (!seasonId || !status) return;
  const endpoint = { ACTIVE: "activate", PAUSED: "pause", CLOSED: "close" }[String(status).toUpperCase()];
  if (!endpoint) return;
  try {
    await api(`/api/business/gamification/seasons/${encodeURIComponent(seasonId)}/${endpoint}`, {
      method: "POST",
      headers: authHeaders(),
    });
    state.missionsLoaded = false;
    await loadGamificationDashboard({ force: true, quiet: true });
    renderMissionsView();
    showFeedback(`Temporada ${missionStatusLabel(status).toLowerCase()}.`, "success", { title: "Temporadas" });
  } catch (error) {
    showFeedback(error.message || "No se pudo actualizar el estado de la temporada.", "error", { title: "Temporadas" });
  }
}

async function loadMissionLeaderboard(seasonId) {
  if (!seasonId) {
    renderMissionLeaderboard([]);
    return;
  }
  const data = await api(`/api/business/gamification/leaderboards/${encodeURIComponent(seasonId)}`, { headers: authHeaders() });
  renderMissionLeaderboard(data.leaderboard || [], data.ranking_type || "POINTS");
}

async function loadMissionPurchaseLeaderboard(period = "week") {
  const normalizedPeriod = normalizeMissionPeriod(period);
  state.missionLeaderboardLoading = true;
  state.missionSeasonFilter = normalizedPeriod;
  syncMissionPeriodControls();
  if (missionLeaderboard) {
    missionLeaderboard.innerHTML = '<div class="empty-state compact">Cargando leaderboard de compras...</div>';
  }
  try {
    const data = await api(`/api/business/gamification/purchase-leaderboard?period=${encodeURIComponent(normalizedPeriod)}&limit=50`, { headers: authHeaders() });
    state.missionLeaderboardRows = sortMissionLeaderboardRows(data.leaderboard || []);
    state.missionLeaderboardSummary = {
      ...(data.summary || {}),
      start_date: data.start_date || null,
      end_date: data.end_date || null,
    };
    state.missionLeaderboardLoadedPeriod = normalizedPeriod;
    renderMissionsKpis();
    renderMissionLeaderboard(state.missionLeaderboardRows, "PURCHASES");
    return data;
  } finally {
    state.missionLeaderboardLoading = false;
  }
}

function missionLeaderboardLeadRef(row = {}) {
  const sourceType = String(row.source_type || "").toUpperCase();
  const sourceId = row.source_id || row.lead_id || row.contact_id || "";
  if (!sourceId || !["PLAYER", "MANUAL"].includes(sourceType)) return null;
  return { id: sourceId, source_type: sourceType };
}

function openMissionLeaderboardContact(index) {
  const row = state.missionLeaderboardRows?.[Number(index)] || null;
  const leadRef = missionLeaderboardLeadRef(row || {});
  if (!leadRef) {
    showFeedback("Este comprador no está conectado a un contacto del directorio todavía. Regístralo con teléfono o email para poder abrir su ficha.", "info", { title: "Leaderboard" });
    return;
  }
  openLeadDetail(leadRef, { tab: "summary" });
}

function sendTicketToMissionLeader(index) {
  const row = state.missionLeaderboardRows?.[Number(index)] || null;
  const leadRef = missionLeaderboardLeadRef(row || {});
  if (!leadRef) {
    showFeedback("Este comprador no tiene contacto conectado. Primero debe existir en el directorio con el mismo teléfono o email de la venta.", "info", { title: "Enviar ticket" });
    return;
  }
  openLeadActivationModal(leadRef, "TICKET");
  const period = missionPeriodLabel(state.missionSeasonFilter || "week").toLowerCase();
  if (leadActivationNameInput) leadActivationNameInput.value = `Ticket premio Top ${Number(row.rank || Number(index) + 1).toLocaleString("es-CO")} · ${missionPeriodLabel(state.missionSeasonFilter || "week")}`;
  if (leadActivationBenefitValueInput) leadActivationBenefitValueInput.value = `Reconocimiento por estar en el Top ${Number(row.rank || Number(index) + 1).toLocaleString("es-CO")} de compradores del periodo ${period}.`;
  if (leadActivationMessageInput) leadActivationMessageInput.value = `Gracias por comprar con nosotros. Estás en el leaderboard de mejores compradores de ${period}; te enviamos este ticket especial como reconocimiento.`;
  showFeedback("Completa y envía el ticket desde la ventana de entrega.", "success", { title: "Ticket para comprador top" });
}

function renderMissionLeaderboard(rows = [], rankingType = "") {
  if (!missionLeaderboard) return;
  const isPurchaseRanking = String(rankingType || "").toUpperCase() === "PURCHASES"
    || rows.some((row) => String(row.ranking_type || "").toUpperCase() === "PURCHASES");
  if (isPurchaseRanking) {
    missionLeaderboard.innerHTML = rows.length ? `
      <div class="mission-leaderboard-table-wrap">
        <table class="mission-leaderboard-table">
          <thead>
            <tr>
              <th>Top</th>
              <th>Contacto</th>
              <th>Total comprado</th>
              <th>Compras</th>
              <th>Ticket promedio</th>
              <th>Última compra</th>
              <th>Acción</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map((row, index) => {
              const leadRef = missionLeaderboardLeadRef(row);
              const contactMeta = row.phone || row.email || row.document_id || "Venta sin contacto conectado";
              return `
                <tr>
                  <td><span class="mission-rank-badge">#${Number(index + 1).toLocaleString("es-CO")}</span></td>
                  <td>
                    <button class="link-button mission-contact-link" type="button" data-mission-open-contact="${index}">
                      <strong>${escapeHtml(row.name || "Cliente")}</strong>
                      <small>${escapeHtml(contactMeta)}</small>
                    </button>
                  </td>
                  <td><strong>${money(row.total_spent || 0)}</strong></td>
                  <td>${Number(row.purchases_count || 0).toLocaleString("es-CO")}</td>
                  <td>${money(row.average_ticket || 0)}</td>
                  <td>${row.last_activity_at ? escapeHtml(formatDate(row.last_activity_at)) : "Sin fecha"}</td>
                  <td>
                    <button class="${leadRef ? "solid-button" : "ghost-button"} compact" type="button" data-mission-send-ticket="${index}">${leadRef ? "Enviar ticket" : "Conectar contacto"}</button>
                  </td>
                </tr>
              `;
            }).join("")}
          </tbody>
        </table>
      </div>
    ` : `<div class="empty-state compact">Todavía no hay ventas registradas para ${escapeHtml(missionPeriodLabel(state.missionSeasonFilter || "week").toLowerCase())}.</div>`;
    missionLeaderboard.querySelectorAll("[data-mission-open-contact]").forEach((button) => {
      button.addEventListener("click", () => openMissionLeaderboardContact(button.dataset.missionOpenContact));
    });
    missionLeaderboard.querySelectorAll("[data-mission-send-ticket]").forEach((button) => {
      button.addEventListener("click", () => sendTicketToMissionLeader(button.dataset.missionSendTicket));
    });
    return;
  }
  missionLeaderboard.innerHTML = rows.map((row, index) => `
    <div class="mission-rank-row">
      <span>#${index + 1}</span>
      <strong>${escapeHtml(row.name || "Cliente")}</strong>
      <small>${Number(row.points || 0).toLocaleString("es-CO")} pts</small>
    </div>
  `).join("") || `<div class="empty-state compact">El ranking se llenará cuando los clientes empiecen a sumar puntos.</div>`;
}

function openPurchaseCompetition(period = "month") {
  const normalizedPeriod = normalizeMissionPeriod(period);
  state.missionSeasonFilter = normalizedPeriod;
  state.missionLeaderboardLoadedPeriod = "";
  loadMissionPurchaseLeaderboard(normalizedPeriod).catch((error) => {
    showFeedback(error.message || "No se pudo cargar el leaderboard de compras.", "error", { title: "Temporadas" });
  });
}

function renderMissionRewards(rewards = []) {
  if (!missionRewardsPending) return;
  missionRewardsPending.innerHTML = rewards.map((reward) => `
    <article class="mission-reward-card">
      <div>
        <strong>${escapeHtml(reward.reward_name || "Recompensa")}</strong>
        <small>${escapeHtml(reward.season_name || "Misión Qori")}</small>
      </div>
      <button class="ghost-button" type="button" data-mission-deliver-reward="${escapeHtml(reward.id)}">Marcar entregado</button>
    </article>
  `).join("") || '<div class="empty-state compact">Sin recompensas pendientes por entregar.</div>';
  missionRewardsPending.querySelectorAll("[data-mission-deliver-reward]").forEach((button) => {
    button.addEventListener("click", () => deliverMissionReward(button.dataset.missionDeliverReward));
  });
}

function bindMissionWizardOpeners(root = document) {
  root.querySelectorAll("[data-open-mission-wizard]").forEach((button) => {
    button.addEventListener("click", () => openMissionWizard(button.dataset.openMissionWizard || "weekly_trivia"));
  });
}

function fillMissionWizardOptions() {
  if (missionTemplateInput) {
    missionTemplateInput.innerHTML = missionTemplates().map((template) => `
      <option value="${escapeHtml(template.key)}">${escapeHtml(template.name)}</option>
    `).join("");
  }
  if (missionCampaignInput) {
    missionCampaignInput.innerHTML = '<option value="">Sin campaña asociada</option>' + (state.campaigns || []).map((campaign) => `
      <option value="${escapeHtml(campaign.id)}">${escapeHtml(campaign.name || campaign.slug || "Campaña")}</option>
    `).join("");
  }
}

function templateTextLines(items = [], mapper) {
  return items.map(mapper).filter(Boolean).join("\n");
}

function openMissionWizard(templateKey = "weekly_trivia") {
  if (missionWizardModal?.parentElement !== document.body) {
    document.body.appendChild(missionWizardModal);
  }
  fillMissionWizardOptions();
  const template = missionTemplateByKey(templateKey);
  state.missionWizardTemplateKey = template.key;
  if (missionTemplateInput) missionTemplateInput.value = template.key;
  if (missionNameInput) missionNameInput.value = template.name || "";
  if (missionDescriptionInput) missionDescriptionInput.value = template.description || "";
  if (missionChannelInput) missionChannelInput.value = template.channel || missionChannelInput.value;
  if (missionStartInput && !missionStartInput.value) missionStartInput.value = dateInputValue(new Date());
  if (missionEndInput && !missionEndInput.value) missionEndInput.value = dateInputValue(new Date(Date.now() + 30 * 86400000));
  if (missionRankingInput) missionRankingInput.value = template.ranking?.ranking_type || "POINTS";
  if (missionTopLimitInput) missionTopLimitInput.value = String(template.ranking?.top_limit || 5);
  if (missionPointsInput) {
    missionPointsInput.value = templateTextLines(template.points_rules || [], (rule) => `${rule.label || rule.action_type}: +${rule.points || 0}`);
  }
  if (missionRewardsInput) {
    missionRewardsInput.value = templateTextLines(template.rewards || [], (reward) => `${reward.position || reward.condition || "Condición"}: ${reward.reward_name || "Recompensa"} (${reward.reward_type || "CUSTOM"})`);
  }
  if (missionWizardMessage) missionWizardMessage.textContent = "";
  missionWizardModal?.classList.remove("hidden");
  document.body.classList.add("mission-wizard-open");
  window.requestAnimationFrame(() => {
    missionWizardModal?.querySelector(".mission-wizard-card")?.scrollTo({ top: 0 });
    missionNameInput?.focus({ preventScroll: true });
  });
}

function closeMissionWizard() {
  missionWizardModal?.classList.add("hidden");
  document.body.classList.remove("mission-wizard-open");
}

function parseMissionPoints(text = "") {
  return String(text || "").split(/\n+/).map((line) => line.trim()).filter(Boolean).map((line) => {
    const match = line.match(/^(.*?):\s*\+?(-?\d+)/);
    return {
      label: match ? match[1].trim() : line,
      action_type: slugify(match ? match[1] : line).toUpperCase().replace(/-/g, "_"),
      points: match ? Number(match[2]) : 0,
    };
  });
}

function parseMissionRewards(text = "") {
  return String(text || "").split(/\n+/).map((line) => line.trim()).filter(Boolean).map((line) => {
    const [condition, reward] = line.split(":");
    return {
      condition: (condition || "condicion").trim(),
      reward_name: (reward || line).replace(/\([^)]*\)/g, "").trim(),
      reward_type: (reward?.match(/\(([^)]+)\)/)?.[1] || "CUSTOM").trim().toUpperCase(),
    };
  });
}

async function submitMissionWizard(event) {
  event.preventDefault();
  const template = missionTemplateByKey(missionTemplateInput?.value || state.missionWizardTemplateKey);
  const startDate = missionStartInput?.value || null;
  const endDate = missionEndInput?.value || null;
  if (startDate && endDate && new Date(endDate).getTime() < new Date(startDate).getTime()) {
    const message = "La fecha final debe ser posterior o igual a la fecha de inicio.";
    if (missionWizardMessage) missionWizardMessage.textContent = message;
    showFeedback(message, "info", { title: "Temporadas" });
    return;
  }
  const body = {
    template_key: template.key,
    campaign_id: missionCampaignInput?.value || null,
    name: missionNameInput?.value?.trim() || template.name,
    description: missionDescriptionInput?.value?.trim() || template.description,
    type: template.type || "TEMPORADA_MG",
    status: "ACTIVE",
    start_date: startDate,
    end_date: endDate,
    channel: missionChannelInput?.value || template.channel || "mixto",
    points_rules: parseMissionPoints(missionPointsInput?.value || ""),
    ranking: {
      ranking_type: missionRankingInput?.value || template.ranking?.ranking_type || "POINTS",
      top_limit: Number(missionTopLimitInput?.value || template.ranking?.top_limit || 5),
      privacy_mode: "ALIAS",
    },
    rewards: parseMissionRewards(missionRewardsInput?.value || ""),
    settings: {
      ux_goal: "mantener recordacion, participacion, recompra y revenue",
      source_module: "gamification_missions",
    },
  };
  try {
    if (missionWizardMessage) missionWizardMessage.textContent = "Guardando dinámica...";
    const data = await api("/api/business/gamification/seasons", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify(body),
    });
    if (missionCreateAgendaInput?.checked && data?.season?.id) {
      await createMissionAgendaTasks(data.season.id, { quiet: true });
    }
    state.missionsLoaded = false;
    await loadGamificationDashboard({ force: true, quiet: true });
    renderMissionsView();
    closeMissionWizard();
    showFeedback("Dinámica Qori creada y conectada con el portal.", "success", { title: "Misiones Qori" });
  } catch (error) {
    if (missionWizardMessage) missionWizardMessage.textContent = error.message || "No se pudo crear la dinámica.";
    showFeedback(error.message || "No se pudo crear la dinámica.", "error", { title: "Misiones Qori" });
  }
}

async function createMissionAgendaTasks(seasonId, options = {}) {
  if (!seasonId) return;
  try {
    await api("/api/business/gamification/agenda/create-tasks", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({ season_id: seasonId }),
    });
    state.leadAgendaLoaded = false;
    if (!options.quiet) showFeedback("Tareas de Misiones Qori creadas en la agenda.", "success", { title: "Agenda" });
  } catch (error) {
    if (!options.quiet) showFeedback(error.message || "No se pudieron crear las tareas.", "error", { title: "Agenda" });
  }
}

async function deliverMissionReward(rewardId) {
  if (!rewardId) return;
  try {
    await api(`/api/business/gamification/rewards/${encodeURIComponent(rewardId)}/deliver`, {
      method: "POST",
      headers: authHeaders(),
    });
    state.missionsLoaded = false;
    await loadGamificationDashboard({ force: true, quiet: true });
    renderMissionsView();
    showFeedback("Recompensa marcada como entregada.", "success", { title: "Misiones Qori" });
  } catch (error) {
    showFeedback(error.message || "No se pudo entregar la recompensa.", "error", { title: "Misiones Qori" });
  }
}

function openRmsCollectorModal() {
  renderRmsCollectorSummary();
  updateRmsCollectorSubmitButtons();
  if (rmsCollectorModal && rmsCollectorModal.parentElement !== document.body) {
    document.body.appendChild(rmsCollectorModal);
  }
  rmsCollectorModal?.classList.remove("hidden");
  document.body.classList.add("has-rms-collector-modal");
  window.setTimeout(() => {
    if (rmsCollectorModal) rmsCollectorModal.scrollTop = 0;
    if (rmsCollectorForm) rmsCollectorForm.scrollTop = 0;
    (rmsCollectorLeadNameInput || rmsCollectorSourceInput)?.focus?.({ preventScroll: true });
  }, 40);
}

function closeRmsCollectorModal() {
  rmsCollectorModal?.classList.add("hidden");
  document.body.classList.remove("has-rms-collector-modal");
}

function openRmsHowModal() {
  rmsHowModal?.classList.remove("hidden");
}

function closeRmsHowModal() {
  rmsHowModal?.classList.add("hidden");
}

function rmsCollectorHasLeadDraft() {
  return Boolean(
    String(rmsCollectorLeadNameInput?.value || "").trim()
    || String(rmsCollectorLeadPhoneInput?.value || "").trim()
    || String(rmsCollectorLeadEmailInput?.value || "").trim()
    || String(rmsCollectorLeadInterestInput?.value || "").trim()
  );
}

function updateRmsCollectorSubmitButtons() {
  const hasLeadDraft = rmsCollectorHasLeadDraft();
  const isBusy = Boolean(state.rmsCollectorSubmitting);
  rmsCollectorModal?.classList.toggle("has-lead-draft", hasLeadDraft);
  if (rmsCollectorSubmitButton) {
    rmsCollectorSubmitButton.disabled = isBusy;
    rmsCollectorSubmitButton.textContent = hasLeadDraft ? "Guardar y actualizar estación" : "Activar solo captura";
  }
  if (rmsCollectorLeadSubmitButton) {
    rmsCollectorLeadSubmitButton.disabled = isBusy || !hasLeadDraft;
    rmsCollectorLeadSubmitButton.textContent = hasLeadDraft ? "Guardar lead" : "Completa datos del lead";
  }
  if (rmsCollectorLeadSubmitButton) rmsCollectorLeadSubmitButton.classList.toggle("is-waiting-lead", !hasLeadDraft);
}

function renderRmsCollectorSummary() {
  if (!rmsCollectorSummary) return;
  const source = rmsCollectorSourceInput?.selectedOptions?.[0]?.textContent || "Fuente de clientes";
  const capture = rmsCollectorCaptureInput?.selectedOptions?.[0]?.textContent || "Captura";
  const coverage = rmsCollectorCoverageInput?.selectedOptions?.[0]?.textContent || "Cobertura";
  const leadName = String(rmsCollectorLeadNameInput?.value || "").trim();
  const leadContact = [rmsCollectorLeadPhoneInput?.value, rmsCollectorLeadEmailInput?.value].map((value) => String(value || "").trim()).filter(Boolean).join(" / ");
  const leadDocument = String(rmsCollectorLeadDocumentInput?.value || "").trim();
  const leadDocumentType = rmsCollectorLeadDocumentTypeInput?.selectedOptions?.[0]?.textContent || "";
  rmsCollectorSummary.innerHTML = `
    <strong>Resumen de captura</strong>
    <p>Fuente: ${escapeHtml(source)} · Captura: ${escapeHtml(capture)} · Cobertura: ${escapeHtml(coverage)}</p>
    ${leadName ? `<p>Lead: ${escapeHtml(leadName)}${leadContact ? ` · ${escapeHtml(leadContact)}` : ""}${leadDocument ? ` · ${escapeHtml(leadDocumentType)} ${escapeHtml(leadDocument)}` : ""} · Entrada: Leads recolectados</p>` : '<p>Sin lead manual cargado. Puedes activar solo el flujo o ingresar una persona ahora.</p>'}
  `;
  updateRmsCollectorSubmitButtons();
}

function renderRmsCollectorActivation() {
  if (!rmsCollectorActiveCard) return;
  const activation = state.rmsCollectorActivation;
  if (!activation) {
    rmsCollectorActiveCard.classList.add("hidden");
    rmsCollectorActiveCard.innerHTML = "";
    return;
  }
  const source = activation.source_label || activation.source || "Fuente de clientes";
  const capture = activation.capture_label || activation.capture || "Captura";
  const coverage = activation.coverage_label || activation.coverage || "Cobertura";
  rmsCollectorActiveCard.classList.remove("hidden");
  rmsCollectorActiveCard.innerHTML = `
    <div>
      <span class="mono-label">Captura activa</span>
      <h4>${escapeHtml(capture)} + ${escapeHtml(coverage)}</h4>
      <p>La captura queda lista para recibir leads. Cada lead ingresado aparece dentro de la estación Leads recolectados, sin crear tarea de agenda.</p>
    </div>
    <dl>
      <div><dt>Fuente</dt><dd>${escapeHtml(source)}</dd></div>
      <div><dt>Entrada</dt><dd>${escapeHtml(capture)}</dd></div>
      <div><dt>Verificación</dt><dd>Máquina RMS > Leads recolectados</dd></div>
    </dl>
    <div class="button-row">
      <button class="solid-button compact" type="button" data-rms-open-station="recoleccion">Ver recolectados</button>
      <button class="ghost-button" type="button" data-rms-empty-action="contacts-manual">Importar contactos</button>
      <button class="ghost-button" type="button" data-rms-empty-action="campaigns">Crear campaña/QR</button>
    </div>
  `;
  bindRmsMachineActions(rmsCollectorActiveCard);
}

async function submitRmsCollector(event) {
  event.preventDefault();
  const submitter = event.submitter || document.activeElement;
  const isLeadSubmit = submitter?.id === "rmsCollectorLeadSubmitButton";
  const source = rmsCollectorSourceInput?.value || "store_visitors";
  const capture = rmsCollectorCaptureInput?.value || "qr_ticket_capture";
  const coverage = rmsCollectorCoverageInput?.value || "ticket_expiring";
  const sourceLabel = rmsCollectorSourceInput?.selectedOptions?.[0]?.textContent || source;
  const captureLabel = rmsCollectorCaptureInput?.selectedOptions?.[0]?.textContent || capture;
  const coverageLabel = rmsCollectorCoverageInput?.selectedOptions?.[0]?.textContent || coverage;
  const leadName = String(rmsCollectorLeadNameInput?.value || "").trim();
  const leadPhone = String(rmsCollectorLeadPhoneInput?.value || "").trim();
  const leadEmail = String(rmsCollectorLeadEmailInput?.value || "").trim();
  const leadDocumentType = String(rmsCollectorLeadDocumentTypeInput?.value || "").trim();
  const leadDocument = String(rmsCollectorLeadDocumentInput?.value || "").trim();
  const leadInterest = String(rmsCollectorLeadInterestInput?.value || "").trim();
  const requestedLeadPriority = String(rmsCollectorLeadPriorityInput?.value || "HIGH").toUpperCase();
  const leadPriority = ["LOW", "MEDIUM", "HIGH"].includes(requestedLeadPriority) ? requestedLeadPriority : "HIGH";
  const hasLeadDraft = rmsCollectorHasLeadDraft();
  if (isLeadSubmit && !hasLeadDraft) {
    showFeedback("Completa los datos del lead antes de guardarlo.", "info", { title: "Nuevo lead" });
    rmsCollectorLeadNameInput?.focus?.({ preventScroll: false });
    updateRmsCollectorSubmitButtons();
    return;
  }
  if (hasLeadDraft && (!leadName || (!leadPhone && !leadEmail) || !leadDocumentType || !leadDocument)) {
    const missingIdentity = !leadDocumentType || !leadDocument;
    showFeedback(
      missingIdentity
        ? "Selecciona el tipo y escribe el nÃºmero de documento para identificar este lead antes de guardarlo."
        : "Para ingresar un lead a recolectados agrega nombre y al menos WhatsApp o correo.",
      "error",
      { title: missingIdentity ? "Documento requerido" : "Lead incompleto" }
    );
    (!leadName
      ? rmsCollectorLeadNameInput
      : (!leadDocumentType ? rmsCollectorLeadDocumentTypeInput : (!leadDocument ? rmsCollectorLeadDocumentInput : (rmsCollectorLeadPhoneInput || rmsCollectorLeadEmailInput)))
    )?.focus?.({ preventScroll: false });
    return;
  }
  if (leadDocument && !leadDocumentType) {
    showFeedback("Selecciona el tipo de identificación para guardar el número de documento.", "error", { title: "Identificación incompleta" });
    rmsCollectorLeadDocumentTypeInput?.focus?.({ preventScroll: false });
    return;
  }
  if (leadDocumentType && !leadDocument) {
    showFeedback("Escribe el número de identificación o deja el tipo sin seleccionar.", "error", { title: "Identificación incompleta" });
    rmsCollectorLeadDocumentInput?.focus?.({ preventScroll: false });
    return;
  }
  if (state.rmsCollectorSubmitting) return;
  state.rmsCollectorSubmitting = true;
  [rmsCollectorSubmitButton, rmsCollectorLeadSubmitButton].forEach((button) => {
    if (button) button.disabled = true;
  });
  try {
    showFeedback(hasLeadDraft ? "Ingresando lead a Leads recolectados..." : "Activando captura...", "loading", { title: "Máquina RMS", timeout: 0 });
    let createdLead = null;
    if (hasLeadDraft) {
      const leadResult = await api("/api/business/contacts/manual", {
        method: "POST",
        headers: authHeaders(),
        body: JSON.stringify({
          name: leadName,
          phone: leadPhone || null,
          email: leadEmail || null,
          document_type: leadDocumentType || null,
          document_id: leadDocument || null,
          source: "Maquina RMS",
          source_detail: `${sourceLabel} · ${captureLabel}`,
          priority: leadPriority,
          status: "NEW",
          preferred_channel: leadPhone ? "WhatsApp" : "Email",
          interest: leadInterest || captureLabel,
          importance_reason: `Lead ingresado desde Leads recolectados RMS. Fuente: ${sourceLabel}. Cobertura: ${coverageLabel}.`,
          notes: rmsCollectorExpectedInput?.value || "Lead ingresado a Leads recolectados.",
        }),
      });
      createdLead = leadResult?.lead || null;
      if (!createdLead?.id) {
        throw new Error("El lead se guardó sin identificador. Actualiza la estación para verificarlo.");
      }
      if (createdLead?.id) {
        closeRmsCollectorModal();
        showFeedback(`${createdLead?.name || leadName} fue ingresado. Actualizando Leads recolectados...`, "loading", { title: "Máquina RMS", timeout: 0 });
        await api("/api/business/rms-machine/lead/phase", {
          method: "PATCH",
          headers: authHeaders(),
          body: JSON.stringify({
            source_id: createdLead.id,
            source_type: createdLead.source_type || "MANUAL",
            lead_id: createdLead.lead_id || createdLead.id,
            to_phase: "recoleccion",
            priority: leadPriority,
            recommended_action: "",
            last_operation: "",
            last_material_sent: coverage,
            reason: "Lead ingresado manualmente desde Leads recolectados RMS.",
            metadata: {
              source_module: "rms_machine",
              source_flow: "collector_manual_lead",
              collector_type: capture,
              customer_source: source,
              coverage_type: coverage,
            },
          }),
        }).catch(() => null);
      }
    }
    state.rmsCollectorActivation = {
      id: createdLead?.id || `${source}:${capture}:${Date.now()}`,
      source,
      source_label: sourceLabel,
      capture,
      capture_label: captureLabel,
      coverage,
      coverage_label: coverageLabel,
      created_at: new Date().toISOString(),
    };
    if (hasLeadDraft) {
      [rmsCollectorLeadNameInput, rmsCollectorLeadPhoneInput, rmsCollectorLeadEmailInput, rmsCollectorLeadDocumentInput, rmsCollectorLeadInterestInput].forEach((input) => {
        if (input) input.value = "";
      });
      if (rmsCollectorLeadDocumentTypeInput) rmsCollectorLeadDocumentTypeInput.value = "";
      if (rmsCollectorLeadPriorityInput) rmsCollectorLeadPriorityInput.value = "HIGH";
      state.contactFeedLoaded = false;
      state.leadCrmLoaded = false;
      state.manualContactsLoaded = false;
      state.leadCrmPagination.offset = 0;
    }
    state.rmsMachineLoaded = false;
    if (hasLeadDraft && createdLead?.id) {
      state.rmsMachineFilters.search = "";
      state.rmsMachineFilters.priority = "";
      state.rmsMachineFilters.phase = "recoleccion";
      if (rmsMachineSearchInput) rmsMachineSearchInput.value = "";
      if (rmsMachinePriorityFilter) rmsMachinePriorityFilter.value = "";
      if (rmsMachinePhaseFilter) rmsMachinePhaseFilter.value = "recoleccion";
    }
    closeRmsCollectorModal();
    await Promise.all([
      loadRmsMachineData({ force: true, quiet: true }).catch(() => null),
      hasLeadDraft ? loadLeadCrmData({ force: true, quiet: true }).catch(() => null) : Promise.resolve(null),
      hasLeadDraft ? loadManualContactsData({ force: true, quiet: true }).catch(() => null) : Promise.resolve(null),
    ]);
    renderRmsCollectorActivation();
    renderRmsMachineView();
    showFeedback(
      hasLeadDraft
        ? `${createdLead?.name || leadName} entró a Leads recolectados.`
        : "Captura activa. Ingresa leads, importa CSV o conecta una campaña/QR para alimentar Leads recolectados.",
      "success",
      { title: "Máquina RMS" }
    );
  } catch (error) {
    showFeedback(error.message || "No se pudo activar la captura.", "error", { title: "Máquina RMS" });
  } finally {
    state.rmsCollectorSubmitting = false;
    [rmsCollectorSubmitButton, rmsCollectorLeadSubmitButton].forEach((button) => {
      if (button) button.disabled = false;
    });
    updateRmsCollectorSubmitButtons();
  }
}

function handleRmsEmptyAction(action = "") {
  const target = String(action || "");
  if (target === "gaming") {
    setView("strategic-qr");
    return;
  }
  if (target === "campaigns") {
    setView("campaigns");
    return;
  }
  if (target === "reward-passes") {
    setView("reward-passes");
    return;
  }
  if (target === "contacts" || target === "contacts-manual") {
    setContactCenterTab(target === "contacts-manual" ? "manual" : "directory");
    setView("leads");
    return;
  }
  if (target === "agenda") {
    setContactCenterTab("agenda");
    setView("leads");
    return;
  }
  if (target === "sales") {
    setView("sales");
    return;
  }
  if (target === "redemptions") {
    setView("redemptions");
    return;
  }
  if (target === "validator") {
    setView("validator");
    return;
  }
  if (target === "affiliates") {
    setView("affiliates");
    return;
  }
  openRmsCollectorModal();
}

function renderAdminView() {
  if (!isAdmin()) {
    adminKpiGrid.innerHTML = "";
    adminCampaignTable.innerHTML = '<tr><td colspan="4">Sin acceso admin.</td></tr>';
    adminReportKpiGrid.innerHTML = "";
    adminReportCampaignTable.innerHTML = '<tr><td colspan="6">Sin acceso admin.</td></tr>';
    adminPanelMessage.textContent = "Tu rol actual es de negocio. La gestión global sigue disponible solo para admins en `/admin`.";
    return;
  }

  const campaigns = filterRows(state.adminCampaigns, ["name", "business_name", "status", "type"]);
  adminKpiGrid.innerHTML = [
    ["Campañas globales", state.adminCampaigns.length, "Todas las empresas"],
    ["Campañas visibles", campaigns.length, `Filtro ${state.filter ? "activo" : "general"}`],
    ["Rol actual", session.user.role, "Acceso a crear y editar campañas"],
  ].map(([label, value, meta]) => `
    <article class="kpi-card">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
      <div class="kpi-meta">${escapeHtml(meta)}</div>
    </article>
  `).join("");

  adminCampaignTable.innerHTML = campaigns.map((campaign) => `
    <tr data-admin-campaign-id="${escapeHtml(campaign.id)}">
      <td>${escapeHtml(campaign.name || "-")}</td>
      <td>${escapeHtml(campaign.business_name || "-")}</td>
      <td>${escapeHtml(campaign.status || "-")}</td>
      <td>${escapeHtml(campaign.type || "-")}</td>
    </tr>
  `).join("") || '<tr><td colspan="4">Sin campañas para este filtro.</td></tr>';
  adminCampaignTable.querySelectorAll("[data-admin-campaign-id]").forEach((row) => {
    row.addEventListener("click", () => loadAdminCampaignWorkspace(row.dataset.adminCampaignId));
  });

  adminPanelMessage.textContent = "Este usuario puede crear y editar campañas desde el modal del portal y también operar `/admin`.";
}

function handleRangeToggle() {
  if (state.rangeDays === 30) {
    state.rangeDays = 90;
  } else if (state.rangeDays === 90) {
    state.rangeDays = 0;
  } else {
    state.rangeDays = 30;
  }

  rangeButton.textContent = state.rangeDays ? `Últimos ${state.rangeDays} días` : "Todo el historial";
  if (state.dashboard) renderDashboard();
  if (state.selectedCampaign) {
    renderCampaignView();
    renderLeadsView();
    renderRedemptionsView();
    renderSalesView();
    renderBranchesView();
  }
  if (state.currentView === "validator") {
    loadValidatorHistory();
  }
  if (state.currentView === "channels") {
    state.acquisitionChannelsLoaded = false;
    state.acquisitionChannelEffortsLoaded = false;
    Promise.all([
      loadAcquisitionChannels({ force: true, quiet: true }),
      loadChannelEfforts({ force: true, quiet: true }),
    ]).then(renderAcquisitionChannelsView);
  }
  if (isAdmin()) renderAdminView();
}

