document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !document.getElementById("gamingActivationBuilderModal")?.classList.contains("hidden")) {
    closeGamingActivationBuilderModal();
    return;
  }
  if (event.key === "Escape" && !document.getElementById("gamingActivationDetailModal")?.classList.contains("hidden")) {
    closeGamingActivationDetail();
    return;
  }
  if (event.key === "Escape" && !document.getElementById("activationEditModal")?.classList.contains("hidden")) {
    closeActivationEditModal();
    return;
  }
  if (event.key === "Escape" && !document.getElementById("rmsCaptureReviewModal")?.classList.contains("hidden")) {
    closeRmsCaptureReview();
    return;
  }
  if (event.key === "Escape" && state.chartFocus.open) {
    closeChartFocusMode();
    return;
  }
  if (event.key === "Escape" && !leadActivationModal?.classList.contains("hidden")) {
    closeLeadActivationModal();
    return;
  }
  if (event.key === "Escape" && !activationShareModal?.classList.contains("hidden")) {
    closeActivationShareModal();
    return;
  }
  if (event.key === "Escape" && !featureUpgradeModal?.classList.contains("hidden")) {
    closeFeatureUpgradeInterstitial();
    return;
  }
  if (event.key === "Escape" && !leadDetailModal?.classList.contains("hidden")) {
    closeLeadDetail();
    return;
  }
  if (event.key === "Escape" && !leadAgendaCreateModal?.classList.contains("hidden")) {
    closeLeadAgendaCreateModal();
    return;
  }
  if (event.key === "Escape" && !inventoryProductModal?.classList.contains("hidden")) {
    closeInventoryProductModal();
    return;
  }
  if (event.key === "Escape" && !inventoryTaxonomyModal?.classList.contains("hidden")) {
    closeInventoryTaxonomyModal();
    return;
  }
  const inventoryDetailModal = document.getElementById("inventoryProductDetailModal");
  if (event.key === "Escape" && inventoryDetailModal && !inventoryDetailModal.classList.contains("hidden")) {
    inventoryDetailModal.classList.add("hidden");
    inventoryDetailModal.setAttribute("aria-hidden", "true");
    return;
  }
  if (event.key === "Escape") closePortalMenu();
});
