/* Negociación compacta: conserva los contratos RMS y reduce la operación a una ruta activa. */
function rmsNegotiationCompactPaths() {
  return [
    { key: "send", label: "Enviar y esperar", icon: "send", result: "WAITING", route: "" },
    { key: "response", label: "Registrar respuesta", icon: "reply", result: "ACCEPTED", route: "" },
  ];
}

function rmsNegotiationDraftStorageKey(id) {
  return `marketgames:rms:negotiation-draft:${session?.user?.business_id || state.loadedBusinessId || "business"}:${id}`;
}

function rmsReadNegotiationDraft(id) {
  try { return JSON.parse(localStorage.getItem(rmsNegotiationDraftStorageKey(id)) || "null") || {}; } catch { return {}; }
}

function rmsCompactField(label, control, extra = "") {
  return `<label><span>${escapeHtml(label)}</span>${control}${extra}</label>`;
}

function rmsNegotiationDispatchUrl(item = {}, channel = "WHATSAPP", message = "") {
  const copy = String(message || "").trim();
  if (channel === "EMAIL") return item.email
    ? `mailto:${encodeURIComponent(item.email)}?subject=${encodeURIComponent("Información comercial")}&body=${encodeURIComponent(copy)}`
    : "";
  const rawPhone = String(item.phone || "").replace(/\D/g, "");
  const phone = rawPhone.length === 10 && rawPhone.startsWith("3") ? `57${rawPhone}` : rawPhone;
  return phone ? `https://wa.me/${encodeURIComponent(phone)}?text=${encodeURIComponent(copy)}` : "";
}

const RMS_NEGOTIATION_ATTACHMENT_TYPES = [
  "application/pdf",
  "application/msword",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "image/png",
  "image/jpeg",
  "image/webp",
];
const RMS_NEGOTIATION_ATTACHMENT_MAX_BYTES = 5 * 1024 * 1024;
const rmsNegotiationUploadedAssets = new Map();

function rmsNegotiationAttachmentPreviewMarkup(items = [], options = {}) {
  const attachments = Array.isArray(items) ? items : [];
  if (!attachments.length) return '<small class="rms-negotiation-attachments-empty">Aún no hay documentos adjuntos.</small>';
  return `<div class="rms-negotiation-attachment-list">${attachments.map((attachment) => {
    const name = attachment.name || attachment.file_name || attachment.title || "Documento comercial";
    const meta = attachment.size ? `${Math.max(1, Math.ceil(Number(attachment.size) / 1024))} KB` : attachment.file_type || attachment.type || "Listo para compartir";
    const link = attachment.url ? `<a href="${escapeHtml(attachment.url)}" target="_blank" rel="noopener">Abrir</a>` : "";
    return `<span><span class="material-symbols-outlined" aria-hidden="true">attach_file</span><strong>${escapeHtml(name)}</strong><small>${escapeHtml(meta)}</small>${link}</span>`;
  }).join("")}</div>${options.pending ? "<small>Se subirán de forma segura cuando confirmes el envío.</small>" : ""}`;
}

function rmsNegotiationFilesFor(root, id) {
  return Array.from(rmsCompactActiveNode(root, id, "[data-rms-negotiation-files]")?.files || []).slice(0, 4);
}

function renderRmsNegotiationAttachmentPreview(root, id) {
  const preview = rmsCommercialNode(root, "[data-rms-negotiation-attachments-preview]", id);
  if (!preview) return;
  const files = rmsNegotiationFilesFor(root, id).map((file) => ({ name: file.name, type: file.type, size: file.size }));
  preview.innerHTML = rmsNegotiationAttachmentPreviewMarkup(files, { pending: files.length > 0 });
}

async function uploadRmsNegotiationAttachments(item, files = []) {
  const incoming = Array.isArray(files) ? files.slice(0, 4) : [];
  if (!incoming.length) return [];
  const invalid = incoming.find((file) => !RMS_NEGOTIATION_ATTACHMENT_TYPES.includes(String(file.type || "").toLowerCase()) || Number(file.size || 0) > RMS_NEGOTIATION_ATTACHMENT_MAX_BYTES);
  if (invalid) throw new Error("Cada adjunto debe ser PDF, Word o imagen y pesar hasta 5 MB.");
  const saved = rmsNegotiationUploadedAssets.get(item.id) || [];
  const assetIds = [];
  for (const file of incoming) {
    const fileKey = `${file.name}:${file.size}:${file.type}`;
    const existing = saved.find((asset) => asset.file_key === fileKey);
    if (existing?.id) {
      assetIds.push(existing.id);
      continue;
    }
    const uploaded = await api("/api/business/digital-assets", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        title: file.name.replace(/\.[^.]+$/, "") || "Documento de negociación",
        description: `Adjunto comercial de Negociación para ${item.name || "lead"}.`,
        category: "comercial",
        file_name: file.name,
        file_data_url: await readFileAsDataUrl(file, RMS_NEGOTIATION_ATTACHMENT_MAX_BYTES, RMS_NEGOTIATION_ATTACHMENT_TYPES),
        download_button_text: "Descargar documento",
      }),
    });
    if (!uploaded?.asset?.id) throw new Error("No pudimos preparar uno de los adjuntos.");
    saved.push({ id: uploaded.asset.id, file_key: fileKey });
    assetIds.push(uploaded.asset.id);
  }
  rmsNegotiationUploadedAssets.set(item.id, saved);
  return [...new Set(assetIds)];
}

// Renderizador canónico de Negociación: una decisión y un formulario por ruta.
function rmsCommercialConfirmationStationCardMarkup(item = {}) {
  {
    const negotiation = (item.state_metadata || {}).negotiation_current || {};
    const saved = rmsReadNegotiationDraft(item.id);
    const legacyPath = String(saved.path || "");
    const current = rmsNegotiationCompactPaths().find((path) => path.key === legacyPath)
      || (legacyPath === "recycle" || saved.result === "RECYCLE" ? rmsNegotiationCompactPaths()[1] : rmsNegotiationCompactPaths()[0]);
    const channel = saved.channel || negotiation.channel || "WHATSAPP";
    const material = saved.delivery_material || negotiation.delivery?.material || "QUOTE";
    const message = saved.delivery_message || negotiation.delivery?.message || "";
    const link = saved.delivery_link || negotiation.delivery?.link || "";
    const existingAttachments = Array.isArray(negotiation.delivery?.attachments) ? negotiation.delivery.attachments : [];
    const nextAt = rmsActivationDatetimeLocal(saved.next_action_at || negotiation.next_action_at || "", 2);
    const response = saved.result === "RECYCLE" ? "RECYCLE" : "ACCEPTED";
    const responseReason = saved.reason || "";
    const dispatchUrl = rmsNegotiationDispatchUrl(item, channel, message || `Hola ${item.name || ""}, te compartimos información comercial.`);
    return `<article class="rms-commercial-work-item rms-confirmation-work-item rms-negotiation-compact" data-rms-station-lead="${escapeHtml(item.id)}">
      <section class="rms-commercial-work-console">
        <header class="rms-negotiation-compact-head"><div><span class="mono-label">Negociación · seguimiento activo</span><h4>${escapeHtml(item.name || "Contacto")}</h4><p>${escapeHtml(item.product_interest || item.classified_product_name || "Oferta por definir")} · ${escapeHtml(channel === "EMAIL" ? "Email" : "WhatsApp")} · ${escapeHtml(negotiation.next_action_at ? `Seguimiento ${formatDate(negotiation.next_action_at)}` : "Sin respuesta registrada")}</p></div><details class="rms-negotiation-context-drawer"><summary><span class="material-symbols-outlined" aria-hidden="true">history</span> Contexto e historial</summary><div>${rmsNegotiationTimelineMarkup(item, Array.isArray((item.state_metadata || {}).negotiation_history) ? (item.state_metadata || {}).negotiation_history.slice(-6).reverse() : [], (item.state_metadata || {}).rms_evaluation || {}, (item.state_metadata || {}).commercial_confirmation || {}, (item.state_metadata || {}).risk_review || {})}</div></details></header>
        <section class="rms-negotiation-choice-panel" data-rms-negotiation-tabs="${escapeHtml(item.id)}" aria-label="Operación de Negociación"><span class="mono-label">Opera en dos pasos</span><div role="tablist">${rmsNegotiationCompactPaths().map((path) => `<button type="button" role="tab" class="${path.key === current.key ? "is-active" : ""}" aria-selected="${path.key === current.key}" data-rms-negotiation-tab="${escapeHtml(item.id)}" data-rms-negotiation-tab-key="${path.key}"><span class="material-symbols-outlined" aria-hidden="true">${path.icon}</span><strong>${escapeHtml(path.label)}</strong></button>`).join("")}</div></section>
        <input type="hidden" data-rms-negotiation-result="${escapeHtml(item.id)}" value="${current.result}"><input type="hidden" data-rms-negotiation-route="${escapeHtml(item.id)}" value="">
        <section class="rms-negotiation-active-form" data-rms-negotiation-active-form="${escapeHtml(item.id)}">
          <div data-rms-negotiation-path="send" ${current.key === "send" ? "" : "hidden"}><header><h5>Envía material y espera su respuesta</h5><p>Comparte una activación, atención, archivo o cotización. El lead se queda en Negociación hasta que respondan.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Canal", `<select data-rms-negotiation-channel="${escapeHtml(item.id)}"><option value="WHATSAPP" ${channel === "WHATSAPP" ? "selected" : ""}>WhatsApp</option><option value="EMAIL" ${channel === "EMAIL" ? "selected" : ""}>Email</option></select>`)}${rmsCompactField("Qué enviarás", `<select data-rms-negotiation-delivery-material="${escapeHtml(item.id)}"><option value="ACTIVATION" ${material === "ACTIVATION" ? "selected" : ""}>Activación</option><option value="ATTENTION" ${material === "ATTENTION" ? "selected" : ""}>Atención o información</option><option value="FILE" ${material === "FILE" ? "selected" : ""}>Archivo</option><option value="QUOTE" ${material === "QUOTE" ? "selected" : ""}>Cotización</option><option value="OTHER" ${material === "OTHER" ? "selected" : ""}>Otro</option></select>`)}${rmsCompactField("Próximo seguimiento", `<input type="datetime-local" value="${escapeHtml(nextAt)}" data-rms-negotiation-next-at="${escapeHtml(item.id)}">`)}</div>${rmsCompactField("Mensaje o contexto", `<textarea rows="3" data-rms-negotiation-delivery-message="${escapeHtml(item.id)}" placeholder="Qué le envías y qué esperas que responda">${escapeHtml(message)}</textarea>`)}${rmsCompactField("Enlace de archivo o cotización", `<input type="url" value="${escapeHtml(link)}" data-rms-negotiation-delivery-link="${escapeHtml(item.id)}" placeholder="https://…">`, "<small>Opcional. Pega un enlace si compartes un archivo o una cotización.</small>")}</div>
          <div data-rms-negotiation-path="response" ${current.key === "response" ? "" : "hidden"}><header><h5>Registra la respuesta del cliente</h5><p>Justifica la decisión. Aquí no se registra el pago: ese detalle se completa en Ventas atribuidas.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Respuesta", `<select data-rms-negotiation-response-outcome="${escapeHtml(item.id)}"><option value="ACCEPTED" ${response === "ACCEPTED" ? "selected" : ""}>Compró o confirmó compra → Ventas atribuidas</option><option value="RECYCLE" ${response === "RECYCLE" ? "selected" : ""}>No compra por ahora → Reciclaje</option></select>`)}</div>${rmsCompactField("Por qué tomas esta decisión", `<textarea rows="4" data-rms-negotiation-reason="${escapeHtml(item.id)}" placeholder="Resume lo que respondió el cliente y por qué lo envías a la siguiente etapa">${escapeHtml(responseReason)}</textarea>`, "<small>Este motivo queda en el historial del lead.</small>")}</div>
          <section class="rms-negotiation-attachments-field" data-rms-negotiation-path="send" ${current.key === "send" ? "" : "hidden"}>
            ${rmsCompactField("Adjuntar documentos", `<input type="file" multiple accept="application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,image/png,image/jpeg,image/webp" data-rms-negotiation-files="${escapeHtml(item.id)}">`, `<small>PDF, Word o imagen · hasta 4 archivos de 5 MB cada uno. Qori crea enlaces seguros para enviarlos por email o WhatsApp.</small><div class="rms-negotiation-attachments-preview" data-rms-negotiation-attachments-preview="${escapeHtml(item.id)}">${rmsNegotiationAttachmentPreviewMarkup(existingAttachments)}</div>`)}
          </section>
        </section>
        <aside class="rms-negotiation-health-compact" data-rms-negotiation-health="${escapeHtml(item.id)}"></aside>
        <footer class="rms-negotiation-compact-actions"><small data-rms-negotiation-help="${escapeHtml(item.id)}"></small><div><button class="ghost-button compact" type="button" data-rms-save-negotiation-draft="${escapeHtml(item.id)}">Guardar borrador</button><a class="ghost-button compact" data-rms-negotiation-dispatch="${escapeHtml(item.id)}" href="#" target="_blank" rel="noopener" hidden><span class="material-symbols-outlined" aria-hidden="true">open_in_new</span><span data-rms-negotiation-dispatch-label="${escapeHtml(item.id)}">Abrir ${channel === "EMAIL" ? "email" : "WhatsApp"}</span></a><button class="solid-button compact" type="button" data-rms-save-negotiation-decision="${escapeHtml(item.id)}" data-rms-negotiation-cta-button="${escapeHtml(item.id)}"><span data-rms-negotiation-cta="${escapeHtml(item.id)}"></span></button></div></footer>
      </section>
    </article>`;
  }
  const workflow = rmsCommercialWorkflow(item);
  const evaluation = workflow.evaluation || {};
  const confirmation = workflow.confirmation || {};
  const negotiation = (item.state_metadata || {}).negotiation_current || {};
  const saved = rmsReadNegotiationDraft(item.id);
  const productId = saved.inventory_product_id || confirmation.inventory_product_id || evaluation.recommended_inventory_product_id || item.classified_product_id || "";
  const product = confirmation.product_name || evaluation.recommended_product || rmsClassifiedProductName(item) || item.product_interest || "";
  const amount = saved.amount ?? confirmation.amount ?? evaluation.budget_amount ?? "";
  const currency = saved.currency || confirmation.currency || evaluation.currency || "COP";
  const channel = saved.channel || negotiation.channel || confirmation.negotiation?.channel || "WHATSAPP";
  const responsible = saved.responsible || confirmation.responsible || "";
  const condition = saved.customer_condition || negotiation.customer_condition || confirmation.negotiation?.customer_condition || "";
  const evidence = saved.evidence || confirmation.evidence || "";
  const reference = saved.payment_reference || confirmation.payment_reference || "";
  const note = saved.note || confirmation.note || negotiation.summary || "";
  const history = Array.isArray((item.state_metadata || {}).negotiation_history) ? (item.state_metadata || {}).negotiation_history.slice(-6).reverse() : [];
  const current = rmsNegotiationCompactPaths().find((path) => path.key === saved.path) || rmsNegotiationCompactPaths()[0];
  const prefill = { inventory_product_id: productId, product_name: product, amount: Number(amount || 0), channel, responsible, customer_condition: condition, evidence, payment_reference: reference, summary: note, objection_type: "OTHER", objection_status: "NOT_APPLICABLE" };
  const ticket = rmsNegotiationTicketContext(item);
  return `<article class="rms-commercial-work-item rms-confirmation-work-item rms-negotiation-compact" data-rms-station-lead="${escapeHtml(item.id)}">
    <section class="rms-commercial-work-console">
      <header class="rms-negotiation-compact-head"><div><span class="mono-label">Negociación</span><h4>${escapeHtml(item.name || "Contacto")}</h4><p>${escapeHtml(product || "Sin producto confirmado")} · ${escapeHtml(channel)} · Próximo contacto: ${escapeHtml(negotiation.next_action_at ? formatDate(negotiation.next_action_at) : "por definir")}</p></div><details class="rms-negotiation-context-drawer"><summary><span class="material-symbols-outlined" aria-hidden="true">history</span> Contexto e historial</summary><div><dl><div><dt>Oferta conocida</dt><dd>${escapeHtml(product || "Sin producto confirmado")}</dd></div><div><dt>Canal anterior</dt><dd>${escapeHtml(channel || "Sin canal")}</dd></div><div><dt>Beneficio</dt><dd>${escapeHtml(ticket.label)}</dd></div><div><dt>Origen</dt><dd>${escapeHtml(item.campaign_name || item.source_detail || "Sin origen")}</dd></div></dl><section class="rms-negotiation-history"><h5>Historial</h5>${rmsNegotiationTimelineMarkup(item, history, evaluation, confirmation, workflow.risk || {})}</section></div></details></header>
      <section class="rms-negotiation-choice-panel" data-rms-negotiation-tabs="${escapeHtml(item.id)}" aria-label="Decisión de negociación"><span class="mono-label">¿Qué pasó con este lead?</span><div role="tablist">${rmsNegotiationCompactPaths().map((path) => `<button type="button" role="tab" class="${path.key === current.key ? "is-active" : ""}" aria-selected="${path.key === current.key}" data-rms-negotiation-tab="${escapeHtml(item.id)}" data-rms-negotiation-tab-key="${path.key}"><span class="material-symbols-outlined" aria-hidden="true">${path.icon}</span><strong>${escapeHtml(path.label)}</strong></button>`).join("")}</div></section>
      <input type="hidden" data-rms-negotiation-result="${escapeHtml(item.id)}" value="${current.result}"><input type="hidden" data-rms-negotiation-route="${escapeHtml(item.id)}" value="${current.route}">
      <section class="rms-negotiation-active-form" data-rms-negotiation-active-form="${escapeHtml(item.id)}">
        <div data-rms-negotiation-path="conversion" ${current.key === "conversion" ? "" : "hidden"}><header><h5>Confirma la venta</h5><p>Solo lo necesario para atribuirla correctamente.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Producto o servicio activo", `<select data-rms-confirm-product="${escapeHtml(item.id)}">${rmsInventoryProductPickerOptions(productId, product)}</select>`, product ? `<small>Referencia anterior: ${escapeHtml(product)}</small>` : "")}${rmsCompactField("Valor final esperado", `<input type="number" min="1" step="0.01" value="${escapeHtml(amount)}" data-rms-confirm-amount="${escapeHtml(item.id)}" placeholder="0">`)}${rmsCompactField("Canal", `<select data-rms-negotiation-channel="${escapeHtml(item.id)}"><option value="WHATSAPP" ${channel === "WHATSAPP" ? "selected" : ""}>WhatsApp</option><option value="EMAIL" ${channel === "EMAIL" ? "selected" : ""}>Email</option><option value="CALL" ${channel === "CALL" ? "selected" : ""}>Llamada</option><option value="MEETING" ${channel === "MEETING" ? "selected" : ""}>Reunión</option><option value="OTHER" ${channel === "OTHER" ? "selected" : ""}>Otro</option></select>`)}${rmsCompactField("Responsable", `<input type="text" value="${escapeHtml(responsible)}" data-rms-confirm-responsible="${escapeHtml(item.id)}" placeholder="Quién confirma">`)}${rmsCompactField("Condición comercial acordada", `<input type="text" value="${escapeHtml(condition)}" data-rms-negotiation-condition="${escapeHtml(item.id)}" placeholder="Qué aceptó el cliente">`)}${rmsCompactField("Referencia o comprobante", `<input type="text" value="${escapeHtml(reference)}" data-rms-confirm-reference="${escapeHtml(item.id)}" placeholder="Factura, enlace o referencia">`)}</div>${rmsCompactField("Evidencia o nota comercial", `<textarea rows="3" data-rms-confirm-evidence="${escapeHtml(item.id)}" placeholder="Qué se acordó y cómo se puede verificar">${escapeHtml(evidence || note)}</textarea>`)}</div>
        <div data-rms-negotiation-path="risk" ${current.key === "risk" ? "" : "hidden"}><header><h5>Protege el acuerdo</h5><p>Documenta la condición frágil antes de enviarla a Riesgos de fuga.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Producto activo", `<select data-rms-confirm-product="${escapeHtml(item.id)}">${rmsInventoryProductPickerOptions(productId, product)}</select>`)}${rmsCompactField("Valor esperado", `<input type="number" min="1" step="0.01" value="${escapeHtml(amount)}" data-rms-confirm-amount="${escapeHtml(item.id)}">`)}${rmsCompactField("Canal", `<select data-rms-negotiation-channel="${escapeHtml(item.id)}"><option value="WHATSAPP" ${channel === "WHATSAPP" ? "selected" : ""}>WhatsApp</option><option value="EMAIL" ${channel === "EMAIL" ? "selected" : ""}>Email</option><option value="CALL" ${channel === "CALL" ? "selected" : ""}>Llamada</option><option value="MEETING" ${channel === "MEETING" ? "selected" : ""}>Reunión</option></select>`)}${rmsCompactField("Responsable", `<input type="text" value="${escapeHtml(responsible)}" data-rms-confirm-responsible="${escapeHtml(item.id)}" placeholder="Responsable">`)}${rmsCompactField("Condición acordada", `<input type="text" value="${escapeHtml(condition)}" data-rms-negotiation-condition="${escapeHtml(item.id)}" placeholder="Condición a proteger">`)}</div>${rmsCompactField("Evidencia o explicación de la fragilidad", `<textarea rows="3" data-rms-confirm-evidence="${escapeHtml(item.id)}" placeholder="Qué debe validar Riesgos de fuga">${escapeHtml(evidence || note)}</textarea>`)}</div>
        <div data-rms-negotiation-path="followup" ${current.key === "followup" ? "" : "hidden"}><header><h5>Espera o pérdida</h5><p>Registra solo el resultado y el siguiente movimiento.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Resultado", `<select data-rms-negotiation-result-choice="${escapeHtml(item.id)}"><option value="WAITING">Esperar respuesta</option><option value="NO_RESPONSE">Sin respuesta</option><option value="LOST">Pérdida definitiva</option></select>`)}${rmsCompactField("Responsable", `<input type="text" value="${escapeHtml(responsible)}" data-rms-confirm-responsible="${escapeHtml(item.id)}" placeholder="Responsable">`)}${rmsCompactField("Próximo contacto", `<input type="datetime-local" value="${escapeHtml(rmsActivationDatetimeLocal(negotiation.next_action_at || "", 2))}" data-rms-negotiation-next-at="${escapeHtml(item.id)}">`)}${rmsCompactField("Clasificación de pérdida", `<select data-rms-negotiation-lost-classification="${escapeHtml(item.id)}"><option value="DEFINITIVE">Rechazo definitivo</option><option value="NOT_NOW">No es el momento</option><option value="NO_BUDGET">Sin presupuesto</option><option value="PROLONGED_NO_RESPONSE">Sin respuesta prolongada</option><option value="NO_CONSENT">Sin consentimiento</option><option value="OTHER">Otro</option></select>`)}</div>${rmsCompactField("Motivo", `<textarea rows="3" data-rms-negotiation-reason="${escapeHtml(item.id)}" placeholder="Qué pasó y qué debe saber el equipo">${escapeHtml(saved.reason || "")}</textarea>`)}</div>
        <div data-rms-negotiation-path="recycle" ${current.key === "recycle" ? "" : "hidden"}><header><h5>Programar Reciclaje</h5><p>Se conserva el historial y la reactivación vuelve a Evaluación.</p></header><div class="rms-sale-form-grid">${rmsCompactField("Motivo", `<select data-rms-negotiation-recycle-reason="${escapeHtml(item.id)}"><option value="TIMING">Momento inadecuado</option><option value="BUDGET">Presupuesto</option><option value="NO_RESPONSE">Sin respuesta</option><option value="WAITING_DECISION">Espera de decisión</option><option value="NOT_VIABLE_NOW">Condición no viable hoy</option><option value="OTHER">Otro</option></select>`)}${rmsCompactField("Estrategia", `<select data-rms-negotiation-recycle-strategy="${escapeHtml(item.id)}"><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva activación</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option><option value="NURTURE">Nutrición comercial</option></select>`)}${rmsCompactField("Fecha de reactivación", `<input type="datetime-local" value="${escapeHtml(rmsActivationDatetimeLocal("", 7))}" data-rms-negotiation-next-at="${escapeHtml(item.id)}">`)}${rmsCompactField("Canal permitido", `<select data-rms-negotiation-channel="${escapeHtml(item.id)}"><option value="WHATSAPP">WhatsApp</option><option value="EMAIL">Email</option><option value="CALL">Llamada</option><option value="OTHER">Otro</option></select>`)}${rmsCompactField("Responsable de reactivación", `<input type="text" value="${escapeHtml(responsible)}" data-rms-negotiation-recycle-responsible="${escapeHtml(item.id)}" placeholder="Responsable">`)}${rmsCompactField("Consentimiento", `<select data-rms-negotiation-recycle-consent="${escapeHtml(item.id)}"><option value="CONFIRMED">Confirmado</option><option value="NOT_REQUIRED">No requiere nuevo contacto</option></select>`)}<input type="hidden" data-rms-negotiation-recycle-target="${escapeHtml(item.id)}" value="procesamiento"></div>${rmsCompactField("Contexto para reactivar", `<textarea rows="3" data-rms-negotiation-reason="${escapeHtml(item.id)}" placeholder="Qué debe cambiar al retomar">${escapeHtml(saved.reason || "")}</textarea>`)}</div>
      </section>
      <aside class="rms-negotiation-health-compact" data-rms-negotiation-health="${escapeHtml(item.id)}">${rmsNegotiationCompactHealthMarkup(item, prefill, current.key)}</aside>
      <footer class="rms-negotiation-compact-actions"><small data-rms-negotiation-help="${escapeHtml(item.id)}"></small><div><button class="ghost-button compact" type="button" data-rms-save-negotiation-draft="${escapeHtml(item.id)}">Guardar borrador</button><button class="solid-button compact" type="button" data-rms-save-negotiation-decision="${escapeHtml(item.id)}" data-rms-negotiation-cta-button="${escapeHtml(item.id)}"><span data-rms-negotiation-cta="${escapeHtml(item.id)}">Confirmar venta limpia y enviar a Ventas atribuidas</span></button></div></footer>
    </section>
  </article>`;
}

function rmsNegotiationCompactHealthMarkup(item, draft, path) {
  const health = rmsNegotiationCleanHealth(item, draft);
  if (path === "risk") return `<span class="material-symbols-outlined" aria-hidden="true">shield</span><strong>Enviar a Riesgos de fuga es una decisión manual.</strong><small>Úsala solo si el acuerdo es frágil; esta ruta no se activa automáticamente.</small>`;
  if (path !== "conversion") return `<span class="material-symbols-outlined" aria-hidden="true">edit_note</span><strong>La decisión quedará registrada en el historial.</strong>`;
  const minimumMissing = [!draft.inventory_product_id && "Producto vendido", Number(draft.amount) <= 0 && "valor pagado"].filter(Boolean);
  if (minimumMissing.length) return `<span class="material-symbols-outlined" aria-hidden="true">pending</span><strong>Para enviar la venta falta: ${escapeHtml(minimumMissing.join(" y "))}.</strong><small>Los demás datos son opcionales y puedes completarlos después.</small>`;
  const missing = health.checks.filter((check) => !check.ready).map((check) => check.label.replace("Producto o servicio definido", "Producto").replace("Valor final definido", "valor").replace("Condición comercial confirmada", "condición").replace("Canal y responsable", "canal y responsable").replace("Evidencia, referencia o nota verificable", "evidencia"));
  if (health.requiresRisk) return `<span class="material-symbols-outlined" aria-hidden="true">info</span><strong>Venta lista para enviar; faltan datos opcionales de soporte.</strong><small>Registra evidencia, responsable o condición si los tienes. Usa Riesgos de fuga solo si el acuerdo es frágil.</small>`;
  return health.canClean ? `<span class="material-symbols-outlined" aria-hidden="true">verified</span><strong>Listo para atribuir</strong><small>Producto, valor, condición, canal, responsable y evidencia completos.</small>` : `<span class="material-symbols-outlined" aria-hidden="true">pending</span><strong>Faltan: ${escapeHtml(missing.join(" y ") || "datos comerciales")}</strong><small>Completa el primer campo pendiente para confirmar la venta.</small>`;
}

function rmsCompactNegotiationFocus(root, id, key) {
  const aliases = { producto: "product", valor: "amount", canal: "channel", responsable: "owner", condición: "condition", evidencia: "support" };
  const selectors = { product: "[data-rms-confirm-product]", amount: "[data-rms-confirm-amount]", channel: "[data-rms-negotiation-channel]", condition: "[data-rms-negotiation-condition]", owner: "[data-rms-confirm-responsible]", support: "[data-rms-confirm-evidence]" };
  const node = rmsCommercialNode(root, selectors[aliases[key] || key] || selectors.product, id);
  node?.scrollIntoView({ behavior: "smooth", block: "center" });
  node?.focus({ preventScroll: true });
}

function activateRmsNegotiationTab(root, id, tabKey, item = rmsOpportunityById(id)) {
  const path = rmsNegotiationCompactPaths().find((entry) => entry.key === tabKey) || rmsNegotiationCompactPaths()[0];
  const result = rmsCommercialNode(root, "[data-rms-negotiation-result]", id);
  const route = rmsCommercialNode(root, "[data-rms-negotiation-route]", id);
  if (result) result.value = path.result;
  if (route) route.value = path.route;
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  card?.querySelectorAll("[data-rms-negotiation-path]").forEach((node) => { node.hidden = node.dataset.rmsNegotiationPath !== path.key; });
  card?.querySelectorAll(`[data-rms-negotiation-tab="${CSS.escape(id)}"]`).forEach((button) => { const active = button.dataset.rmsNegotiationTabKey === path.key; button.classList.toggle("is-active", active); button.setAttribute("aria-selected", String(active)); });
  if (path.key === "recycle" && item) loadRmsNonConversionCost(item, root);
  updateRmsNegotiationDecisionUi(root, id);
}

function updateRmsNegotiationDecisionUi(root, id) {
  {
    const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
    if (!card) return;
    const active = card.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "send";
    const result = rmsCommercialNode(root, "[data-rms-negotiation-result]", id);
    const response = rmsCommercialNode(root, "[data-rms-negotiation-response-outcome]", id)?.value || "ACCEPTED";
    if (result) result.value = active === "response" ? response : "WAITING";
    const channel = rmsCompactActiveNode(root, id, "[data-rms-negotiation-channel]")?.value || "WHATSAPP";
    const material = rmsCompactActiveNode(root, id, "[data-rms-negotiation-delivery-material]")?.value || "QUOTE";
    const materialLabel = ({ ACTIVATION: "activación", ATTENTION: "atención", FILE: "archivo", QUOTE: "cotización", OTHER: "material" })[material] || "material";
    const message = rmsCompactActiveNode(root, id, "[data-rms-negotiation-delivery-message]")?.value || `Hola ${rmsOpportunityById(id)?.name || ""}, te compartimos ${materialLabel}.`;
    const dispatch = rmsCommercialNode(root, "[data-rms-negotiation-dispatch]", id);
    const dispatchLabel = rmsCommercialNode(root, "[data-rms-negotiation-dispatch-label]", id);
    const dispatchUrl = rmsNegotiationDispatchUrl(rmsOpportunityById(id) || {}, channel, message);
    if (dispatch) {
      dispatch.hidden = true;
      dispatch.href = dispatchUrl || "#";
    }
    if (dispatchLabel) dispatchLabel.textContent = `Abrir ${channel === "EMAIL" ? "email" : "WhatsApp"}`;
    const health = rmsCommercialNode(root, "[data-rms-negotiation-health]", id);
    const reason = rmsCompactActiveNode(root, id, "[data-rms-negotiation-reason]")?.value.trim() || "";
    if (health) health.innerHTML = active === "send"
      ? `<span class="material-symbols-outlined" aria-hidden="true">schedule</span><strong>El lead permanece en Negociación.</strong><small>Registra su respuesta cuando llegue; el seguimiento se conserva en el historial.</small>`
      : reason
        ? `<span class="material-symbols-outlined" aria-hidden="true">check_circle</span><strong>Decisión lista para registrar.</strong><small>${response === "ACCEPTED" ? "Se abrirá Ventas atribuidas para registrar el pago." : "Se programará Reciclaje con el contexto que escribiste."}</small>`
        : `<span class="material-symbols-outlined" aria-hidden="true">edit_note</span><strong>Falta explicar la respuesta.</strong><small>Escribe por qué el lead avanza a la siguiente etapa.</small>`;
    const cta = rmsCommercialNode(root, "[data-rms-negotiation-cta]", id);
    if (cta) cta.textContent = active === "send" ? `Enviar material y abrir ${channel === "EMAIL" ? "email" : "WhatsApp"}` : response === "ACCEPTED" ? "Enviar a Ventas atribuidas" : "Enviar a Reciclaje";
    const help = rmsCommercialNode(root, "[data-rms-negotiation-help]", id);
    if (help) help.textContent = active === "send" ? "Al confirmar, Qori guarda el envío, adjunta enlaces seguros y abre el canal elegido con todo el material." : "La justificación es el dato mínimo para mover al lead.";
    return;
  }
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  const active = card?.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "conversion";
  ensureRmsNegotiationSaleContextFields(card, id);
  const conversionMinimumControls = new Set(["[data-rms-confirm-product]", "[data-rms-confirm-amount]"]);
  card?.querySelectorAll('[data-rms-negotiation-path="conversion"] label').forEach((label) => {
    const fieldLabel = label.querySelector(":scope > span");
    const isMinimum = Array.from(conversionMinimumControls).some((selector) => label.querySelector(selector));
    if (!fieldLabel || isMinimum || fieldLabel.dataset.rmsOptionalLabel === "true") return;
    fieldLabel.dataset.rmsOptionalLabel = "true";
    fieldLabel.textContent = `${fieldLabel.textContent} (opcional)`;
  });
  const paidAmountLabel = card?.querySelector('[data-rms-negotiation-path="conversion"] [data-rms-confirm-amount]')?.closest("label")?.querySelector(":scope > span");
  if (paidAmountLabel) paidAmountLabel.textContent = "Valor pagado";
  const item = rmsOpportunityById(id) || {};
  const draft = rmsNegotiationDraft(root, id);
  const paidAmountInput = rmsCompactActiveNode(root, id, "[data-rms-confirm-amount]");
  if (paidAmountInput) {
    paidAmountInput.readOnly = true;
    paidAmountInput.value = draft.amount > 0 ? String(draft.amount) : "";
    paidAmountInput.closest("label")?.querySelector(":scope > span")?.replaceChildren("Valor pagado (calculado)");
  }
  const choice = rmsCommercialNode(root, "[data-rms-negotiation-result-choice]", id);
  if (active === "followup" && choice) draft.result = choice.value;
  const health = rmsNegotiationCleanHealth(item, draft);
  const healthNode = rmsCommercialNode(root, "[data-rms-negotiation-health]", id);
  if (healthNode) {
    healthNode.innerHTML = rmsNegotiationCompactHealthMarkup(item, draft, active);
    if (active === "conversion" && health.canClean) {
      healthNode.querySelector("strong")?.replaceChildren("Venta confirmada: lista para enviar a Ventas atribuidas");
    }
  }
  const followupAt = rmsCompactActiveNode(root, id, "[data-rms-negotiation-next-at]")?.closest("label");
  const lossClassification = rmsCompactActiveNode(root, id, "[data-rms-negotiation-lost-classification]")?.closest("label");
  if (active === "followup") {
    const isLoss = choice?.value === "LOST";
    if (followupAt) followupAt.hidden = isLoss;
    if (lossClassification) lossClassification.hidden = !isLoss;
  }
  const ctas = { conversion: "Enviar venta a Ventas atribuidas", risk: "Enviar a Riesgos de fuga", followup: choice?.value === "LOST" ? "Registrar pérdida" : "Programar seguimiento", recycle: "Enviar a Reciclaje" };
  const cta = rmsCommercialNode(root, "[data-rms-negotiation-cta]", id);
  if (cta) cta.textContent = ctas[active];
  const help = rmsCommercialNode(root, "[data-rms-negotiation-help]", id);
  if (help) help.textContent = active === "risk" ? "La condición será revisada antes de atribuir la venta." : "";
}

async function saveRmsNegotiationDecision(item, root) {
  {
    const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(item.id)}"]`);
    if (!card) return;
    const active = card.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "send";
    const draft = rmsNegotiationDraft(root, item.id);
    const button = rmsCommercialNode(root, "[data-rms-negotiation-cta-button]", item.id);
    if (active === "send") {
      if (!draft.next_action_at) {
        rmsCompactActiveNode(root, item.id, "[data-rms-negotiation-next-at]")?.focus();
        showFeedback("Programa cuándo revisar la respuesta.", "info", { title: "Negociación" });
        return;
      }
      const material = ({ ACTIVATION: "activación", ATTENTION: "atención", FILE: "archivo", QUOTE: "cotización", OTHER: "material" })[draft.delivery_material] || "material";
      draft.result = "WAITING";
      draft.reason = draft.reason || `Se compartió ${material} por ${draft.channel === "EMAIL" ? "email" : "WhatsApp"}; se espera respuesta.`;
    } else {
      draft.result = rmsCommercialNode(root, "[data-rms-negotiation-response-outcome]", item.id)?.value || "ACCEPTED";
      if (draft.reason.trim().length < 4) {
        rmsCompactActiveNode(root, item.id, "[data-rms-negotiation-reason]")?.focus();
        showFeedback("Explica qué respondió el cliente y por qué lo envías a esa etapa.", "info", { title: "Negociación" });
        return;
      }
      if (draft.result === "RECYCLE") {
        draft.recycle_reason = "OTHER";
        draft.recycle_strategy = "NURTURE";
        draft.recycle_consent = "NOT_REQUIRED";
        draft.recycle_responsible = draft.responsible || "Responsable de negociación";
        draft.next_action_at = rmsCommercialLocalToIso(rmsActivationDatetimeLocal("", 14));
      }
    }
    if (button) button.disabled = true;
    const emailRoute = active === "send" && draft.channel === "EMAIL" ? await portalEmailDeliveryRoute() : null;
    if (active === "send" && draft.channel === "EMAIL" && !["qori", "external"].includes(emailRoute)) {
      if (button) button.disabled = false;
      return;
    }
    const deliveryWindow = active === "send" && (draft.channel !== "EMAIL" || emailRoute === "external") ? window.open("", "_blank") : null;
    if (deliveryWindow) deliveryWindow.opener = null;
    try {
      if (active === "send") {
        showFeedback("Preparando documentos y registrando el envío…", "loading", { title: "Negociación", timeout: 0 });
        draft.delivery_attachment_asset_ids = await uploadRmsNegotiationAttachments(item, draft.delivery_files || []);
      }
      const { delivery_files: _deliveryFiles, ...requestDraft } = draft;
      const attachmentKey = (draft.delivery_files || []).map((file) => `${file.name}:${file.size}`).join(",");
      const key = rmsCommercialOperationKey("negotiation", item, `${draft.result}|${draft.reason}|${draft.next_action_at || ""}|${draft.delivery_material || ""}|${attachmentKey}`);
      const savedResult = await api("/api/business/rms-machine/negotiation-result", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...requestDraft, idempotency_key: key }) });
      if (active === "send") {
        const deliveryMessage = savedResult?.round?.delivery?.message || [draft.delivery_message, draft.delivery_link].filter(Boolean).join("\n\n");
        if (draft.channel === "EMAIL" && emailRoute === "qori") {
          if (!item.email) throw new Error("Este lead no tiene correo para enviar el material.");
          await sendPortalEmailFromQori({
            recipients: [item],
            subject: "Información comercial",
            body: deliveryMessage,
            actionUrl: draft.delivery_link || null,
            title: `Negociación · ${item.name || item.email}`,
            metadata: { source_module: "rms_negotiation", rms_opportunity_id: item.id || null },
          });
        } else {
          const dispatchUrl = rmsNegotiationDispatchUrl(item, draft.channel, deliveryMessage);
          if (!dispatchUrl) {
            deliveryWindow?.close();
            throw new Error(draft.channel === "EMAIL" ? "Este lead no tiene correo para enviar el material." : "Este lead no tiene WhatsApp para enviar el material.");
          }
          if (deliveryWindow) deliveryWindow.location.href = dispatchUrl;
          else window.open(dispatchUrl, "_blank", "noopener");
        }
        rmsNegotiationUploadedAssets.delete(item.id);
      }
    } catch (error) {
      deliveryWindow?.close();
      if (button) button.disabled = false;
      throw error;
    }
    localStorage.removeItem(rmsNegotiationDraftStorageKey(item.id));
    state.rmsMachineLoaded = false;
    if (draft.result === "RECYCLE") {
      setView("recycling");
      showFeedback("Respuesta registrada y lead enviado a Reciclaje.", "success", { title: "Negociación" });
      return;
    }
    const destination = draft.result === "ACCEPTED" ? "cierre" : "accion_correctiva";
    await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
    showFeedback(draft.result === "ACCEPTED" ? "Respuesta de compra registrada. Completa el pago en Ventas atribuidas." : "Envío y seguimiento registrados. El lead permanece en Negociación.", "success", { title: "Negociación" });
    openRmsStation(destination, { source: "negotiation-follow-up" });
    return;
  }
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(item.id)}"]`);
  const active = card?.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "conversion";
  const draft = rmsNegotiationDraft(root, item.id);
  const resultChoice = rmsCommercialNode(root, "[data-rms-negotiation-result-choice]", item.id);
  if (active === "followup" && resultChoice) draft.result = resultChoice.value;
  if (active === "conversion") draft.commercial_route = "NEGOTIATION_CLEAN";
  if (active === "risk") draft.commercial_route = "NEEDS_RISK_REVIEW";
  const button = rmsCommercialNode(root, "[data-rms-negotiation-cta-button]", item.id);
  const focusMissing = (missing) => { const first = missing[0]; rmsCompactNegotiationFocus(root, item.id, first); showFeedback(`Para continuar falta ${missing.join(", ")}.`, "info", { title: "Negociación" }); };
  if (["conversion", "risk"].includes(active)) {
    const missing = [!draft.inventory_product_id && "producto", draft.amount <= 0 && "valor pagado"].filter(Boolean);
    if (missing.length) return focusMissing(missing);
    const health = rmsNegotiationCleanHealth(item, draft);
    if (button) button.disabled = true;
    const key = rmsCommercialOperationKey("commercial-confirmation", item, `${draft.commercial_route}|${draft.inventory_product_id}|${draft.amount}|${draft.evidence}|${draft.responsible}|${draft.customer_condition}`);
    await api("/api/business/rms-machine/commercial-confirmation", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft, risk_signals: health.signals, idempotency_key: key }) });
    state.rmsMachineLoaded = false;
    const destination = draft.commercial_route === "NEGOTIATION_CLEAN" ? "cierre" : "control_anti_fuga";
    await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: destination });
    showFeedback(destination === "cierre" ? "Venta limpia confirmada y lista para atribuir." : "Acuerdo enviado a Riesgos de fuga para su protección.", "success", { title: "Negociación" });
    openRmsStation(destination, { source: "negotiation-compact" });
    return;
  }
  if (!draft.reason) draft.reason = "Decisión registrada sin detalle adicional.";
  if (["WAITING", "NO_RESPONSE"].includes(draft.result) && !draft.next_action_at) { rmsCommercialNode(root, "[data-rms-negotiation-next-at]", item.id)?.focus(); showFeedback("Programa el próximo contacto.", "info", { title: "Negociación" }); return; }
  if (draft.result === "LOST" && !draft.lost_classification) { showFeedback("Selecciona la clasificación de pérdida.", "info", { title: "Negociación" }); return; }
  if (draft.result === "RECYCLE" && (!draft.recycle_reason || !draft.recycle_strategy || !draft.recycle_consent || !draft.channel || !draft.next_action_at)) { showFeedback("Para Reciclaje define motivo, estrategia, canal, consentimiento y fecha.", "info", { title: "Negociación" }); return; }
  if (button) button.disabled = true;
  showFeedback(draft.result === "RECYCLE" ? "Registrando la respuesta y enviando el lead a Reciclaje…" : "Guardando la respuesta de Negociación…", "loading", { title: "Negociación", timeout: 0 });
  const key = rmsCommercialOperationKey("negotiation", item, `${draft.result}|${draft.reason}|${draft.next_action_at || ""}`);
  await api("/api/business/rms-machine/negotiation-result", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, ...draft, idempotency_key: key }) });
  localStorage.removeItem(rmsNegotiationDraftStorageKey(item.id));
  state.rmsMachineLoaded = false;
  if (draft.result === "RECYCLE") { setView("recycling"); showFeedback("Caso enviado a Reciclaje; al reactivarlo volverá a Evaluación.", "success", { title: "Negociación" }); return; }
  await loadRmsMachineData({ force: true, quiet: true, lite: true, stationPhase: "accion_correctiva" });
  showFeedback(draft.result === "LOST" ? "Pérdida registrada sin crear una venta." : "Seguimiento programado.", "success", { title: "Negociación" });
  openRmsStation("accion_correctiva", { source: "negotiation-compact" });
}

function rmsCompactActiveNode(root, id, selector) {
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  return card?.querySelector(`[data-rms-negotiation-path]:not([hidden]) ${selector}`) || rmsCommercialNode(root, selector, id);
}

function rmsCommercialConfirmationDraft(root, id) {
  const product = findInventoryProductById(rmsCompactActiveNode(root, id, "[data-rms-confirm-product-id]")?.value || rmsCompactActiveNode(root, id, "[data-rms-confirm-product]")?.value || "");
  const value = (selector, fallback = "") => rmsCompactActiveNode(root, id, selector)?.value ?? fallback;
  const saleQuantity = Math.max(0.01, Number(value("[data-rms-confirm-quantity]", 1) || 1));
  const unitPrice = Math.max(0, Number(product?.unit_price || 0));
  return {
    inventory_product_id: product?.id || null,
    product_name: product?.name || "",
    amount: Math.round(unitPrice * saleQuantity * 100) / 100,
    currency: value("[data-rms-confirm-currency]", "COP") || "COP",
    payment_reference: String(value("[data-rms-confirm-reference]") || "").trim(),
    evidence: String(value("[data-rms-confirm-evidence]") || "").trim(),
    responsible: String(value("[data-rms-confirm-responsible]") || "").trim(),
    confirmed_at: null,
    note: String(value("[data-rms-confirm-note]") || "").trim(),
    sale_quantity: saleQuantity,
    benefit_type: String(value("[data-rms-confirm-benefit-type]", "NONE") || "NONE").trim().toUpperCase(),
    benefit_cost: Math.max(0, Number(value("[data-rms-confirm-benefit-cost]", 0) || 0)),
    acquisition_cost: Math.max(0, Number(value("[data-rms-confirm-acquisition-cost]", 0) || 0)),
    benefit_description: String(value("[data-rms-confirm-benefit-description]") || "").trim(),
  };
}

function ensureRmsNegotiationSaleContextFields(card, id) {
  const conversion = card?.querySelector('[data-rms-negotiation-path="conversion"]');
  const grid = conversion?.querySelector(".rms-sale-form-grid");
  if (!conversion || !grid) return;
  const header = conversion.querySelector(":scope > header");
  const title = header?.querySelector("h5");
  const copy = header?.querySelector("p");
  if (title) title.textContent = "Venta realizada";
  if (copy) copy.textContent = "Registra qué se vendió y qué costó lograrla. La venta se atribuye en el siguiente paso.";
  const productLabel = grid.querySelector("[data-rms-confirm-product]")?.closest("label")?.querySelector(":scope > span");
  const amountLabel = grid.querySelector("[data-rms-confirm-amount]")?.closest("label")?.querySelector(":scope > span");
  const saved = rmsReadNegotiationDraft(id);
  if (productLabel) productLabel.textContent = "Producto vendido";
  if (amountLabel) amountLabel.textContent = "Valor pagado";
  if (!grid.querySelector("[data-rms-confirm-quantity]")) {
    const numberValue = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
    const benefitType = String(saved.benefit_type || "NONE").toUpperCase();
    const fields = `
      <label><span>Cantidad vendida</span><input type="number" min="0.01" step="0.01" value="${escapeHtml(String(numberValue(saved.sale_quantity, 1)))}" data-rms-confirm-quantity="${escapeHtml(id)}"></label>
      <label><span>Beneficio usado</span><select data-rms-confirm-benefit-type="${escapeHtml(id)}"><option value="NONE" ${benefitType === "NONE" ? "selected" : ""}>Sin beneficio</option><option value="DISCOUNT" ${benefitType === "DISCOUNT" ? "selected" : ""}>Descuento</option><option value="GIFT" ${benefitType === "GIFT" ? "selected" : ""}>Obsequio</option><option value="BONUS" ${benefitType === "BONUS" ? "selected" : ""}>Bono o incentivo</option><option value="OTHER" ${benefitType === "OTHER" ? "selected" : ""}>Otro</option></select></label>
      <label><span>Costo del beneficio</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(numberValue(saved.benefit_cost, 0)))}" data-rms-confirm-benefit-cost="${escapeHtml(id)}"></label>
      <label><span>Costo de captación</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(numberValue(saved.acquisition_cost, 0)))}" data-rms-confirm-acquisition-cost="${escapeHtml(id)}"></label>
    `;
    grid.querySelector("[data-rms-confirm-amount]")?.closest("label")?.insertAdjacentHTML("afterend", fields);
  }
  if (!conversion.querySelector("[data-rms-negotiation-sale-extras]")) {
    const extras = document.createElement("details");
    extras.className = "rms-negotiation-sale-extras";
    extras.dataset.rmsNegotiationSaleExtras = id;
    extras.innerHTML = `<summary>Detalles de negociación (opcionales)</summary><div class="rms-sale-form-grid"></div><label><span>Descripción del beneficio o esfuerzo</span><textarea rows="2" data-rms-confirm-benefit-description="${escapeHtml(id)}" placeholder="Descuento, pauta, comisión, activación o esfuerzo comercial"></textarea></label></details>`;
    const extrasGrid = extras.querySelector(".rms-sale-form-grid");
    Array.from(grid.querySelectorAll("label")).filter((label) => !label.querySelector("[data-rms-confirm-product], [data-rms-confirm-amount], [data-rms-confirm-quantity], [data-rms-confirm-benefit-type], [data-rms-confirm-benefit-cost], [data-rms-confirm-acquisition-cost]")).forEach((label) => extrasGrid?.append(label));
    const evidence = conversion.querySelector(":scope > label:not(.rms-negotiation-sale-extras)");
    if (evidence) extras.append(evidence);
    conversion.append(extras);
  }
  const benefitDescription = conversion.querySelector("[data-rms-confirm-benefit-description]");
  if (benefitDescription && !benefitDescription.value && saved.benefit_description) benefitDescription.value = saved.benefit_description;
  if (!conversion.querySelector("[data-rms-affiliate-sale-note]")) {
    conversion.querySelector("[data-rms-negotiation-sale-extras]")?.insertAdjacentHTML("afterend", `<aside class="rms-affiliate-sale-note" data-rms-affiliate-sale-note="${escapeHtml(id)}"><span class="material-symbols-outlined" aria-hidden="true">workspace_premium</span><span>Si la compra corresponde a un afiliado o referido, sus puntos se acreditarán solo al registrar la venta pagada en Ventas atribuidas.</span></aside>`);
  }
}

function rmsNegotiationDraft(root, id) {
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  if (!card?.classList.contains("rms-negotiation-compact")) {
    const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
    const active = card?.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "send";
    const activeValue = (selector, fallback = "") => String(rmsCompactActiveNode(root, id, selector)?.value || fallback).trim();
    const outcome = activeValue("[data-rms-negotiation-response-outcome]", "ACCEPTED");
    return {
      result: active === "response" ? outcome : "WAITING",
      reason: activeValue("[data-rms-negotiation-reason]"),
      channel: activeValue("[data-rms-negotiation-channel]", "WHATSAPP"),
      next_action_at: rmsCommercialLocalToIso(rmsCompactActiveNode(root, id, "[data-rms-negotiation-next-at]")?.value || ""),
      delivery_material: activeValue("[data-rms-negotiation-delivery-material]", "QUOTE"),
      delivery_message: activeValue("[data-rms-negotiation-delivery-message]"),
      delivery_link: activeValue("[data-rms-negotiation-delivery-link]"),
      delivery_files: rmsNegotiationFilesFor(root, id),
      summary: activeValue("[data-rms-negotiation-delivery-message]"),
      recycle_reason: null,
      recycle_strategy: null,
      recycle_consent: null,
      recycle_responsible: "",
      recycle_target_phase: "procesamiento",
      responsible: "",
      objective: "",
      objection_type: "OTHER",
      customer_condition: "",
      proposal: "",
      concession: "",
    };
  }
  const confirmation = rmsCommercialConfirmationDraft(root, id);
  const active = card.querySelector("[data-rms-negotiation-tab].is-active")?.dataset.rmsNegotiationTabKey || "conversion";
  const activeValue = (selector, fallback = "") => String(rmsCompactActiveNode(root, id, selector)?.value || fallback).trim();
  const resultChoice = activeValue("[data-rms-negotiation-result-choice]", "WAITING");
  return {
    ...confirmation,
    result: active === "followup" ? resultChoice : rmsCommercialNode(root, "[data-rms-negotiation-result]", id)?.value || "ACCEPTED",
    objective: "",
    objection_type: "OTHER",
    objection_status: "NOT_APPLICABLE",
    objection_resolution: "",
    customer_condition: activeValue("[data-rms-negotiation-condition]"),
    proposal: "",
    concession: "",
    channel: activeValue("[data-rms-negotiation-channel]", "OTHER"),
    summary: confirmation.note || confirmation.evidence,
    reason: activeValue("[data-rms-negotiation-reason]"),
    next_action_at: rmsCommercialLocalToIso(rmsCompactActiveNode(root, id, "[data-rms-negotiation-next-at]")?.value || ""),
    reprocess_phase: "procesamiento",
    commercial_route: rmsCommercialNode(root, "[data-rms-negotiation-route]", id)?.value || "NEGOTIATION_CLEAN",
    recycle_reason: activeValue("[data-rms-negotiation-recycle-reason]") || null,
    recycle_strategy: activeValue("[data-rms-negotiation-recycle-strategy]") || null,
    recycle_consent: activeValue("[data-rms-negotiation-recycle-consent]") || null,
    recycle_responsible: activeValue("[data-rms-negotiation-recycle-responsible]") || confirmation.responsible,
    recycle_target_phase: "procesamiento",
    lost_classification: activeValue("[data-rms-negotiation-lost-classification]") || null,
  };
}

document.addEventListener("click", (event) => {
  const draftButton = event.target.closest("[data-rms-save-negotiation-draft]");
  const protectButton = event.target.closest("[data-rms-protect-agreement]");
  if (draftButton) {
    const id = draftButton.dataset.rmsSaveNegotiationDraft || "";
    const root = document;
    const draft = rmsNegotiationDraft(root, id);
    const active = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"] [data-rms-negotiation-tab].is-active`)?.dataset.rmsNegotiationTabKey || "conversion";
    localStorage.setItem(rmsNegotiationDraftStorageKey(id), JSON.stringify({ ...draft, path: active, saved_at: new Date().toISOString() }));
    showFeedback("Borrador guardado en este navegador. Puedes continuar sin perder la información escrita.", "success", { title: "Negociación" });
  }
  if (protectButton) {
    const id = protectButton.dataset.rmsProtectAgreement || "";
    activateRmsNegotiationTab(document, id, "risk", rmsOpportunityById(id));
  }
});

document.addEventListener("input", (event) => {
  const card = event.target.closest?.(".rms-negotiation-compact[data-rms-station-lead]");
  if (card) updateRmsNegotiationDecisionUi(document, card.dataset.rmsStationLead || "");
});

document.addEventListener("change", (event) => {
  const card = event.target.closest?.(".rms-negotiation-compact[data-rms-station-lead]");
  if (card) updateRmsNegotiationDecisionUi(document, card.dataset.rmsStationLead || "");
});

// Riesgos de fuga es una recuperación excepcional: las autorizaciones viven en
// Cuenta por empresa y la estación conserva únicamente sus dos salidas canónicas.
function rmsRiskRecoveryAuthorizations(raw = state.businessProfile?.rms_risk_recovery_authorizations || {}) {
  const value = raw && typeof raw === "object" ? raw : {};
  return {
    discount: {
      enabled: Boolean(value.discount?.enabled),
      max_percent: Math.min(100, Math.max(0, Number(value.discount?.max_percent || 0))),
    },
    two_for_one: { enabled: Boolean(value.two_for_one?.enabled), label: String(value.two_for_one?.label || "").trim() },
    gift: { enabled: Boolean(value.gift?.enabled), label: String(value.gift?.label || "").trim() },
    benefits: Array.isArray(value.benefits) ? value.benefits.map((benefit, index) => ({
      id: String(benefit?.id || `benefit-${index + 1}`).trim(),
      enabled: benefit?.enabled !== false,
      type: String(benefit?.type || "OTHER").trim().toUpperCase(),
      label: String(benefit?.label || "").trim(),
      value: Math.max(0, Number(benefit?.value || 0)),
      detail: String(benefit?.detail || "").trim(),
    })).filter((benefit) => benefit.label) : [],
  };
}

function rmsRiskRecoveryOfferOptions() {
  const permissions = rmsRiskRecoveryAuthorizations();
  const options = ['<option value="NONE">Sin concesión extraordinaria</option>'];
  if (permissions.discount.enabled && permissions.discount.max_percent > 0) options.push(`<option value="DISCOUNT">Descuento autorizado · hasta ${escapeHtml(String(permissions.discount.max_percent))}%</option>`);
  if (permissions.two_for_one.enabled) options.push(`<option value="TWO_FOR_ONE">2x1 autorizado${permissions.two_for_one.label ? ` · ${escapeHtml(permissions.two_for_one.label)}` : ""}</option>`);
  if (permissions.gift.enabled) options.push(`<option value="GIFT">Obsequio autorizado${permissions.gift.label ? ` · ${escapeHtml(permissions.gift.label)}` : ""}</option>`);
  permissions.benefits.filter((benefit) => benefit.enabled).forEach((benefit) => {
    options.push(`<option value="BENEFIT:${escapeHtml(benefit.id)}">${escapeHtml(benefit.label)}${benefit.value ? ` · ${escapeHtml(String(benefit.value))}${benefit.type === "DISCOUNT" ? "%" : ""}` : ""}</option>`);
  });
  return options.join("");
}

function rmsRiskRecoveryAvailabilityMarkup() {
  const permissions = rmsRiskRecoveryAuthorizations();
  const enabled = [permissions.discount.enabled && permissions.discount.max_percent > 0 && `Descuento hasta ${permissions.discount.max_percent}%`, permissions.two_for_one.enabled && "2x1", permissions.gift.enabled && "Obsequio", ...permissions.benefits.filter((benefit) => benefit.enabled).map((benefit) => benefit.label)].filter(Boolean);
  return enabled.length
    ? `<aside class="rms-risk-authorization-note"><span class="material-symbols-outlined" aria-hidden="true">verified_user</span><div><strong>Alternativas autorizadas para este riesgo</strong><small>${escapeHtml(enabled.join(" · "))}. Solo estas opciones pueden quedar registradas.</small></div></aside>`
    : `<aside class="rms-risk-authorization-note is-empty"><span class="material-symbols-outlined" aria-hidden="true">tune</span><div><strong>No hay concesiones extraordinarias autorizadas</strong><small>Puedes cerrar la venta sin una concesión o configurar permisos en Cuenta antes de ofrecer una alternativa.</small></div><button type="button" class="ghost-button compact" data-rms-open-risk-settings>Configurar en Cuenta</button></aside>`;
}

function rmsRiskTabsMarkup(item = {}) {
  return `<section class="rms-risk-tabs" data-rms-risk-tabs="${escapeHtml(item.id)}" aria-label="Elige el resultado de la recuperación"><div role="tablist"><button class="is-active" type="button" role="tab" aria-selected="true" data-rms-risk-tab="${escapeHtml(item.id)}" data-rms-risk-tab-key="sale"><span class="material-symbols-outlined" aria-hidden="true">paid</span><span><strong>Venta lograda</strong><small>Enviar a Ventas atribuidas.</small></span></button><button type="button" role="tab" aria-selected="false" data-rms-risk-tab="${escapeHtml(item.id)}" data-rms-risk-tab-key="recycle"><span class="material-symbols-outlined" aria-hidden="true">autorenew</span><span><strong>Enviar a Reciclaje</strong><small>No fue viable continuar ahora.</small></span></button></div></section>`;
}

function rmsRiskRecoveryResourceFor(item = {}) {
  const metadata = rmsQualityMetadata(item);
  return state.rmsRiskGeneratedResources?.[item.id] || metadata.risk_recovery_resource || metadata.risk_review?.recovery_resource || null;
}

function rmsRiskRecoveryResourceMarkup(item = {}) {
  const resource = rmsRiskRecoveryResourceFor(item);
  if (!resource?.public_ticket_url) {
    return `<div class="rms-risk-resource-empty"><span class="material-symbols-outlined" aria-hidden="true">qr_code_2_add</span><div><strong>Aún no has generado el activo</strong><small>Selecciona una alternativa autorizada. Qori creará un ticket redimible y descargable sin sacar al lead de esta estación.</small></div></div>`;
  }
  const label = resource.recovery_offer?.label || resource.benefit?.label || "Beneficio extraordinario";
  return `<article class="rms-risk-resource-ready"><span class="material-symbols-outlined" aria-hidden="true">verified</span><div><span class="mono-label">Activo listo</span><strong>${escapeHtml(label)}</strong><small>Vigente hasta ${escapeHtml(resource.expires_at ? formatDate(resource.expires_at) : "sin vencimiento")}. El lead continúa en Riesgos hasta que registres su respuesta.</small></div><a class="ghost-button compact" href="${escapeHtml(resource.public_ticket_url)}" target="_blank" rel="noopener">Abrir ticket</a></article>`;
}

function rmsRiskOperatingFlowMarkup(item = {}) {
  return `<section class="rms-risk-operating-flow" aria-label="Operación de recuperación">
    <header><span class="mono-label">RECUPERACIÓN EN 3 PASOS</span><strong>Prepara, entrega y registra la respuesta</strong></header>
    <div class="rms-risk-flow-steps"><span class="is-active"><b>1</b>Beneficio</span><span><b>2</b>Ticket y activo</span><span><b>3</b>Respuesta</span></div>
    <div class="rms-risk-resource-builder">
      <div class="rms-risk-resource-fields"><label><span>Vigencia del ticket</span><select data-rms-risk-expiration-days="${escapeHtml(item.id)}"><option value="3">3 días</option><option value="7" selected>7 días</option><option value="15">15 días</option><option value="30">30 días</option></select></label></div>
      <div class="rms-risk-resource-actions"><button class="solid-button compact" type="button" data-rms-generate-risk-resource="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">qr_code_2</span>Generar ticket y activo</button><small>Consume un crédito QR solo la primera vez. Los reintentos no duplican el beneficio.</small></div>
      <div data-rms-risk-resource-status="${escapeHtml(item.id)}">${rmsRiskRecoveryResourceMarkup(item)}</div>
      <div class="rms-risk-delivery-bar"><label class="checkbox-row"><input type="checkbox" data-rms-risk-consent="${escapeHtml(item.id)}"> Confirmo que el lead autorizó contacto comercial.</label><div><button class="ghost-button compact" type="button" data-rms-risk-whatsapp="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">chat</span>WhatsApp</button><button class="ghost-button compact" type="button" data-rms-risk-email="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">mail</span>Email</button><button class="ghost-button compact" type="button" data-rms-risk-copy-ticket="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span>Copiar enlace</button><button class="ghost-button compact" type="button" data-rms-risk-download-ticket="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar activo</button></div></div>
    </div>
  </section>`;
}

function mountRmsRiskOperatingFlow(card, item) {
  if (!card || card.querySelector(".rms-risk-operating-flow")) return;
  const authorization = card.querySelector(".rms-risk-authorization-note");
  const form = card.querySelector(".rms-risk-recovery-form");
  (authorization || form)?.insertAdjacentHTML(authorization ? "afterend" : "beforebegin", rmsRiskOperatingFlowMarkup(item));
  const fields = card.querySelector(".rms-risk-resource-fields");
  const offer = card.querySelector(`[data-rms-risk-recovery-offer="${CSS.escape(item.id)}"]`)?.closest("label");
  const discount = card.querySelector(`[data-rms-risk-discount-wrap="${CSS.escape(item.id)}"]`);
  const detail = card.querySelector(`[data-rms-risk-detail-wrap="${CSS.escape(item.id)}"]`);
  const existingResource = rmsRiskRecoveryResourceFor(item);
  const offerSelect = offer?.querySelector("select");
  const existingOffer = existingResource?.recovery_offer || {};
  const restoredValue = existingOffer.benefit_id ? `BENEFIT:${existingOffer.benefit_id}` : existingOffer.type;
  if (offerSelect && restoredValue && Array.from(offerSelect.options).some((option) => option.value === restoredValue)) offerSelect.value = restoredValue;
  const discountInput = discount?.querySelector("input");
  if (discountInput && existingOffer.discount_percent) discountInput.value = existingOffer.discount_percent;
  const detailInput = detail?.querySelector("input");
  if (detailInput && existingOffer.detail) detailInput.value = existingOffer.detail;
  if (fields && offer) fields.prepend(offer);
  if (fields && discount) fields.append(discount);
  if (fields && detail) fields.append(detail);
  const title = card.querySelector(".rms-commercial-console-head h4");
  const copy = card.querySelector(".rms-commercial-console-head p");
  if (title) title.textContent = "Recupera la oportunidad con una alternativa autorizada";
  if (copy) copy.textContent = "Genera un beneficio redimible, compártelo y espera la respuesta. El lead permanece aquí hasta que confirmes el resultado.";
}

function syncRmsRiskRecoveryPhases(card, item) {
  if (!card || !item) return;
  const hasResource = Boolean(rmsRiskRecoveryResourceFor(item)?.public_ticket_url);
  const tabs = card.querySelector("[data-rms-risk-tabs]");
  const form = card.querySelector(".rms-risk-recovery-form");
  [tabs, form].filter(Boolean).forEach((node) => {
    node.classList.toggle("rms-risk-phase-locked", !hasResource);
    node.setAttribute("aria-disabled", hasResource ? "false" : "true");
  });
  let phaseLabel = card.querySelector(".rms-risk-phase-response-label");
  if (!phaseLabel && tabs) {
    phaseLabel = document.createElement("div");
    phaseLabel.className = "rms-risk-phase-response-label";
    tabs.parentNode.insertBefore(phaseLabel, tabs);
  }
  if (phaseLabel) {
    phaseLabel.innerHTML = hasResource
      ? '<span class="mono-label">FASE 2 · RESPUESTA Y CIERRE</span><strong>El ticket está listo. Ahora registra qué respondió el cliente.</strong><small>Selecciona Venta lograda o Reciclaje y completa la justificación.</small>'
      : '<span class="mono-label">FASE 2 · BLOQUEADA</span><strong>Primero genera y entrega el ticket.</strong><small>La respuesta se habilita cuando exista un activo QR válido para este lead.</small>';
    phaseLabel.classList.toggle("is-ready", hasResource);
  }
  const flow = card.querySelector(".rms-risk-operating-flow");
  const builder = flow?.querySelector(".rms-risk-builder-final");
  if (builder && !flow.querySelector(".rms-risk-phase-ticket-label")) {
    builder.insertAdjacentHTML("beforebegin", '<div class="rms-risk-phase-ticket-label"><span class="mono-label">FASE 1 · NEGOCIACIÓN EXTRAORDINARIA</span><strong>Prepara la concesión, genera el ticket y entrégalo al cliente.</strong><small>El lead permanece en Riesgos de fuga mientras esperas la respuesta.</small></div>');
  }
}

// Riesgos de fuga: una consola por fases. El ticket se prepara primero, la
// respuesta se registra después y la salida usa exactamente la concesión que
// se entregó. Conserva los mismos endpoints y contratos del flujo RMS.
function rmsRiskResourceOfferValue(resource = {}) {
  const offer = resource.recovery_offer || resource.benefit || {};
  const benefitId = offer.benefit_id || resource.recovery_benefit_id || resource.benefit_id;
  if (benefitId) return `BENEFIT:${benefitId}`;
  return offer.type || resource.recovery_offer_type || resource.benefit_type || "NONE";
}

function rmsRiskOutcomeOfferUi(card, id) {
  const form = card?.querySelector(".rms-risk-recovery-form");
  const offer = form?.querySelector(`[data-rms-risk-outcome-offer="${CSS.escape(id)}"]`)?.value || "NONE";
  const discount = form?.querySelector(`[data-rms-risk-outcome-discount-percent="${CSS.escape(id)}"]`)?.closest("label");
  const detail = form?.querySelector(`[data-rms-risk-outcome-detail="${CSS.escape(id)}"]`)?.closest("label");
  if (discount) discount.hidden = offer !== "DISCOUNT";
  if (detail) detail.hidden = !["TWO_FOR_ONE", "GIFT"].includes(offer);
}

function setRmsRiskRecoveryPhase(card, id, requestedPhase, { focus = true } = {}) {
  if (!card) return;
  const resource = rmsRiskRecoveryResourceFor(rmsOpportunityById(id) || {});
  const hasResource = Boolean(resource?.public_ticket_url);
  const phase = requestedPhase === "deliver" && !hasResource ? "prepare" : requestedPhase;
  if (requestedPhase === "deliver" && !hasResource) {
    showFeedback("Genera primero el ticket para habilitar la entrega. Puedes registrar la respuesta sin crear un ticket.", "info", { title: "Riesgos de fuga" });
  }
  card.dataset.rmsRiskActivePhase = phase;
  const order = ["prepare", "deliver", "result"];
  const activeIndex = order.indexOf(phase);
  card.querySelectorAll("[data-rms-risk-phase]").forEach((button) => {
    const key = button.dataset.rmsRiskPhaseKey;
    const index = order.indexOf(key);
    const active = key === phase;
    const complete = index < activeIndex && (key === "prepare" ? hasResource : true);
    button.classList.toggle("is-active", active);
    button.classList.toggle("is-complete", complete);
    button.setAttribute("aria-current", active ? "step" : "false");
    const item = button.closest("li");
    item?.classList.toggle("is-active", active);
    item?.classList.toggle("is-complete", complete);
    item?.classList.toggle("is-pending", !active && !complete);
  });
  card.querySelectorAll("[data-rms-risk-phase-panel]").forEach((panel) => {
    const active = panel.dataset.rmsRiskPhasePanel === phase;
    panel.hidden = !active;
    panel.classList.toggle("is-active", active);
  });
  const status = card.querySelector("[data-rms-risk-phase-status]");
  if (status) {
    const copy = {
      prepare: ["Fase 1 activa", "Define la concesión que se puede ofrecer y genera un único ticket."],
      deliver: ["Fase 2 activa", "Comparte el QR o la imagen; el caso sigue en Riesgos mientras esperas."],
      result: ["Fase 3 activa", "Registra una sola respuesta y envía el caso al destino correcto."],
    }[phase];
    status.innerHTML = `<strong>${copy[0]}</strong><small>${copy[1]}</small>`;
  }
  if (focus) card.querySelector(`[data-rms-risk-phase-panel="${phase}"]`)?.scrollIntoView({ behavior: "smooth", block: "start" });
}

rmsRiskOperatingFlowMarkup = function rmsRiskOperatingFlowMarkupUnified(item = {}) {
  const id = escapeHtml(item.id);
  const resource = rmsRiskRecoveryResourceFor(item);
  const hasResource = Boolean(resource?.public_ticket_url);
  const current = hasResource ? "deliver" : "prepare";
  const step = (key, number, title, detail, disabled = false) => `<li class="${key === current ? "is-active" : key === "prepare" && hasResource ? "is-complete" : "is-pending"}"><button type="button" data-rms-risk-phase="${id}" data-rms-risk-phase-key="${key}" ${key === current ? 'aria-current="step"' : ""} ${disabled ? 'disabled aria-disabled="true"' : ""}><b>${number}</b><span><strong>${title}</strong><small>${detail}</small></span></button></li>`;
  return `<section class="rms-risk-operating-flow rms-risk-flow-phased" aria-label="Flujo de recuperación extraordinaria">
    <header class="rms-risk-phased-head"><span class="mono-label">RECUPERACIÓN EXTRAORDINARIA</span><h5>Negocia, entrega y cierra sin perder el contexto</h5><p>Una concesión autorizada, un ticket reutilizable y una única salida para el caso.</p></header>
    <ol class="rms-risk-phase-rail" aria-label="Fases de recuperación">${step("prepare", "1", "Preparar", "Beneficio opcional")}${step("deliver", "2", "Entregar", hasResource ? "QR y contacto" : "Requiere ticket", !hasResource)}${step("result", "3", "Responder", "Venta o Reciclaje")}</ol>
    <div class="rms-risk-phase-status" data-rms-risk-phase-status><strong>${hasResource ? "Fase 2 activa" : "Fase 1 activa"}</strong><small>${hasResource ? "Comparte el activo y registra la respuesta cuando el cliente confirme." : "Define una alternativa autorizada antes de generar el ticket."}</small></div>
    <section class="rms-risk-phase-card rms-risk-phase-ticket" data-rms-risk-phase-panel="prepare"><header><span class="rms-risk-phase-number">01</span><div><span class="mono-label">NEGOCIACIÓN EXTRAORDINARIA</span><h6>Prepara una concesión solo si hace falta</h6><small>El ticket es opcional. Si ya conoces la respuesta, regístrala directamente.</small></div></header><div class="rms-risk-builder-config"><label><span>Alternativa de recuperación</span><select data-rms-risk-recovery-offer="${id}">${rmsRiskRecoveryOfferOptions()}</select><small>Solo aparecen opciones válidas de Qori.</small></label><label><span>Vigencia del ticket</span><select data-rms-risk-expiration-days="${id}"><option value="3">3 días</option><option value="7" selected>7 días</option><option value="15">15 días</option><option value="30">30 días</option></select></label><label data-rms-risk-discount-wrap="${id}" hidden><span>Descuento aplicado</span><input type="number" min="0.01" max="100" step="0.01" data-rms-risk-discount-percent="${id}" placeholder="0"></label><label data-rms-risk-detail-wrap="${id}" hidden><span>Detalle autorizado</span><input type="text" maxlength="1000" data-rms-risk-recovery-detail="${id}" placeholder="Describe el 2x1 u obsequio autorizado"></label></div><div class="rms-risk-phase-actions"><button class="solid-button" type="button" data-rms-generate-risk-resource="${id}"><span class="material-symbols-outlined" aria-hidden="true">qr_code_2</span>Generar ticket y QR</button><button class="ghost-button" type="button" data-rms-risk-phase="${id}" data-rms-risk-phase-key="result"><span class="material-symbols-outlined" aria-hidden="true">edit_note</span>Registrar respuesta sin ticket</button><small>El mismo beneficio reutiliza el activo: los reintentos no consumen otro crédito.</small></div></section>
    <section class="rms-risk-phase-card rms-risk-phase-delivery" data-rms-risk-phase-panel="deliver" ${hasResource ? "" : "hidden"}><header><span class="rms-risk-phase-number">02</span><div><span class="mono-label">ENTREGA Y CONTACTO</span><h6>Comparte el activo y espera la respuesta</h6><small>El lead permanece en Riesgos de fuga hasta que el resultado quede registrado.</small></div></header><div class="rms-risk-resource-status-final" data-rms-risk-resource-status="${id}">${rmsRiskRecoveryResourceMarkup(item)}</div><div class="rms-risk-delivery-bar"><label class="checkbox-row"><input type="checkbox" data-rms-risk-consent="${id}"> Confirmo que el lead autorizó contacto comercial.</label><div><button class="ghost-button compact" type="button" data-rms-risk-whatsapp="${id}"><span class="material-symbols-outlined" aria-hidden="true">chat</span>WhatsApp</button><button class="ghost-button compact" type="button" data-rms-risk-email="${id}"><span class="material-symbols-outlined" aria-hidden="true">mail</span>Email</button><button class="ghost-button compact" type="button" data-rms-risk-copy-ticket="${id}"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span>Copiar enlace</button><button class="ghost-button compact" type="button" data-rms-risk-download-ticket="${id}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar activo</button></div></div><div class="rms-risk-phase-actions rms-risk-result-cta"><button class="solid-button compact" type="button" data-rms-risk-open-result="${id}"><span class="material-symbols-outlined" aria-hidden="true">edit_note</span>Registrar respuesta</button><small>Solo después de conocer la respuesta decide Venta lograda o Reciclaje.</small></div></section>
    <section class="rms-risk-phase-card rms-risk-phase-response" data-rms-risk-phase-panel="result" hidden><header><span class="rms-risk-phase-number">03</span><div><span class="mono-label">RESULTADO DE LA RECUPERACIÓN</span><h6>Registra una sola salida</h6><small>El beneficio usado se conserva para que Ventas reciba la condición correcta.</small></div></header><div class="rms-risk-phase-response-note">Selecciona el resultado, explica qué ocurrió y guarda. No se crean copias del lead.</div></section>
  </section>`;
};

syncRmsRiskRecoveryPhases = function syncRmsRiskRecoveryPhasesUnified(card, item) {
  if (!card || !item) return;
  const id = item.id;
  const flow = card.querySelector(".rms-risk-flow-phased");
  const form = card.querySelector(".rms-risk-recovery-form");
  const tabs = card.querySelector("[data-rms-risk-tabs]");
  const responsePanel = flow?.querySelector('[data-rms-risk-phase-panel="result"]');
  const preview = card.querySelector("[data-rms-risk-preview]");
  const actionRow = card.querySelector(".rms-commercial-action-row");
  if (responsePanel) [tabs, form, preview, actionRow].filter(Boolean).forEach((node) => responsePanel.appendChild(node));
  const tabsHeader = tabs?.querySelector("header");
  if (tabsHeader) tabsHeader.hidden = true;
  if (form) {
    const rename = (from, to) => {
      const field = form.querySelector(`[${from}="${CSS.escape(id)}"]`);
      if (field) { field.setAttribute(to, id); field.removeAttribute(from); }
      return field;
    };
    const outcomeOffer = rename("data-rms-risk-recovery-offer", "data-rms-risk-outcome-offer");
    const outcomeDiscount = rename("data-rms-risk-discount-percent", "data-rms-risk-outcome-discount-percent");
    const outcomeDetail = rename("data-rms-risk-recovery-detail", "data-rms-risk-outcome-detail");
    const resource = rmsRiskRecoveryResourceFor(item);
    const offerValue = rmsRiskResourceOfferValue(resource);
    if (resource?.public_ticket_url && outcomeOffer && !outcomeOffer.dataset.rmsRiskOutcomeUserChanged && Array.from(outcomeOffer.options).some((option) => option.value === offerValue)) {
      outcomeOffer.value = offerValue;
      const offer = resource.recovery_offer || resource.benefit || {};
      if (outcomeDiscount && offer.discount_percent) outcomeDiscount.value = offer.discount_percent;
      if (outcomeDetail && !outcomeDetail.value) outcomeDetail.value = offer.detail || `Ticket generado: ${offer.label || resource.benefit?.label || "beneficio autorizado"}`;
    }
    if (outcomeOffer && !outcomeOffer.dataset.rmsRiskOutcomeBound) {
      outcomeOffer.dataset.rmsRiskOutcomeBound = "true";
      outcomeOffer.addEventListener("change", () => { outcomeOffer.dataset.rmsRiskOutcomeUserChanged = "true"; rmsRiskOutcomeOfferUi(card, id); });
    }
    rmsRiskOutcomeOfferUi(card, id);
  }
  const hasResource = Boolean(rmsRiskRecoveryResourceFor(item)?.public_ticket_url);
  const deliverButton = card.querySelector('[data-rms-risk-phase-key="deliver"]');
  if (deliverButton) {
    deliverButton.disabled = !hasResource;
    deliverButton.setAttribute("aria-disabled", String(!hasResource));
    const detail = deliverButton.querySelector("small");
    if (detail) detail.textContent = hasResource ? "QR y contacto" : "Requiere ticket";
  }
  card.querySelectorAll("[data-rms-risk-phase]").forEach((button) => {
    if (button.dataset.rmsRiskPhaseBound) return;
    button.dataset.rmsRiskPhaseBound = "true";
    button.addEventListener("click", () => setRmsRiskRecoveryPhase(card, id, button.dataset.rmsRiskPhaseKey));
  });
  const resultButton = card.querySelector("[data-rms-risk-open-result]");
  if (resultButton && !resultButton.dataset.rmsRiskPhaseBound) {
    resultButton.dataset.rmsRiskPhaseBound = "true";
    resultButton.addEventListener("click", () => setRmsRiskRecoveryPhase(card, id, "result"));
  }
  const phase = card.dataset.rmsRiskActivePhase || (hasResource ? "deliver" : "prepare");
  setRmsRiskRecoveryPhase(card, id, phase, { focus: false });
};

activateRmsRiskTab = function activateRmsRiskTabUnified(root, id, tabKey) {
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  if (!card) return;
  const isRecycle = tabKey === "recycle";
  const decision = rmsCommercialNode(root, "[data-rms-risk-decision]", id);
  if (decision) decision.value = isRecycle ? "RECYCLE" : "CLEARED";
  const salePanel = rmsCommercialNode(root, "[data-rms-risk-sale-panel]", id);
  const recyclePanel = rmsCommercialNode(root, "[data-rms-risk-recycle-panel]", id);
  if (salePanel) salePanel.hidden = isRecycle;
  if (recyclePanel) recyclePanel.hidden = !isRecycle;
  card.querySelectorAll(`[data-rms-risk-tab="${CSS.escape(id)}"]`).forEach((button) => {
    const active = button.dataset.rmsRiskTabKey === (isRecycle ? "recycle" : "sale");
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  const preview = rmsCommercialNode(root, "[data-rms-risk-preview]", id);
  const submit = rmsCommercialNode(root, "[data-rms-save-risk-decision]", id);
  const help = rmsCommercialNode(root, "[data-rms-risk-help]", id);
  if (isRecycle) {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Reciclaje comercial</strong><small>El caso sale de Riesgos con motivo y estrategia conservados para una reactivación responsable.</small>";
    if (submit) submit.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">autorenew</span>Enviar a Reciclaje';
    if (help) help.textContent = "Reciclaje conserva el contexto; no vuelve automáticamente a Negociación.";
  } else {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Ventas atribuidas</strong><small>Ventas recibe la condición aplicada, luego registra pago y productos.</small>";
    if (submit) submit.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas';
    if (help) help.textContent = "La alternativa entregada ya está precargada. Confirma solo lo que el cliente aceptó.";
    rmsRiskOutcomeOfferUi(card, id);
  }
};

saveRmsRiskDecision = async function saveRmsRiskDecisionUnified(item, root) {
  const result = rmsCommercialNode(root, "[data-rms-risk-decision]", item.id)?.value || "CLEARED";
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(item.id)}"]`);
  const form = card?.querySelector(".rms-risk-recovery-form");
  const reasonNode = rmsCommercialNode(root, "[data-rms-risk-reason]", item.id);
  const recycleReasonNode = rmsCommercialNode(root, "[data-rms-risk-recycle-reason]", item.id);
  const recycleReason = String(recycleReasonNode?.value || "").trim();
  const recycleReasonLabel = recycleReasonNode?.selectedOptions?.[0]?.textContent?.trim() || recycleReason;
  const typedReason = String(reasonNode?.value || "").trim();
  const outcomeOfferNode = form?.querySelector(`[data-rms-risk-outcome-offer="${CSS.escape(item.id)}"]`);
  const recoveryOfferValue = outcomeOfferNode?.value || "NONE";
  const recoveryBenefitId = recoveryOfferValue.startsWith("BENEFIT:") ? recoveryOfferValue.slice(8) : null;
  const selectedBenefit = recoveryBenefitId ? rmsRiskRecoveryAuthorizations().benefits.find((benefit) => benefit.id === recoveryBenefitId) : null;
  const reason = typedReason || (result === "RECYCLE" && recycleReason ? `Motivo de reciclaje: ${recycleReasonLabel}` : result === "CLEARED" && selectedBenefit ? `Beneficio extraordinario aplicado: ${selectedBenefit.label}` : "");
  if (!reason) { showFeedback(result === "RECYCLE" ? "Explica por qué este caso debe ir a Reciclaje." : "Explica por qué la recuperación logró la venta.", "info", { title: "Riesgos de fuga" }); return; }
  const recoveryOffer = recoveryBenefitId ? "CUSTOM" : recoveryOfferValue;
  const discountPercent = Number(form?.querySelector(`[data-rms-risk-outcome-discount-percent="${CSS.escape(item.id)}"]`)?.value || 0);
  const recoveryDetail = String(form?.querySelector(`[data-rms-risk-outcome-detail="${CSS.escape(item.id)}"]`)?.value || "").trim();
  const permissions = rmsRiskRecoveryAuthorizations();
  if (result === "CLEARED" && recoveryOffer === "DISCOUNT" && (!permissions.discount.enabled || discountPercent <= 0 || discountPercent > permissions.discount.max_percent)) { showFeedback(`El descuento debe respetar la autorización de Cuenta (máximo ${permissions.discount.max_percent || 0}%).`, "info", { title: "Riesgos de fuga" }); return; }
  if (result === "CLEARED" && ["TWO_FOR_ONE", "GIFT"].includes(recoveryOffer) && !recoveryDetail) { showFeedback("Describe la alternativa autorizada que aceptó el cliente.", "info", { title: "Riesgos de fuga" }); return; }
  if (result === "RECYCLE" && !recycleReason) { showFeedback("Selecciona el motivo principal para enviar a Reciclaje.", "info", { title: "Riesgos de fuga" }); return; }
  const button = rmsCommercialNode(root, "[data-rms-save-risk-decision]", item.id);
  setButtonLoading(button, true, result === "RECYCLE" ? "Enviando..." : "Confirmando...");
  try {
    const review = await api("/api/business/rms-machine/risk-review", { method: "POST", headers: authHeaders(), body: JSON.stringify({ source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null, result, reason, recovery_offer: result === "CLEARED" ? recoveryOffer : "NONE", recovery_benefit_id: result === "CLEARED" ? recoveryBenefitId : null, discount_percent: result === "CLEARED" ? discountPercent : 0, recovery_detail: result === "CLEARED" ? recoveryDetail || null : null, recycle_reason: result === "RECYCLE" ? recycleReason : null, recycle_strategy: result === "RECYCLE" ? (rmsCommercialNode(root, "[data-rms-risk-recycle-strategy]", item.id)?.value || "NURTURE") : null, recycle_note: result === "RECYCLE" ? reason : null, next_action_at: result === "RECYCLE" ? rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-risk-next-at]", item.id)?.value || "") : null, responsible: rmsCommercialWorkflow(item).confirmation?.responsible || null }) });
    item.stage = result === "RECYCLE" ? "control_anti_fuga" : "cierre";
    item.rms_phase = item.stage;
    item.risk_review = review?.review || review?.risk_review || { ...(item.risk_review || {}), result, reason, recovery_offer: result === "CLEARED" ? recoveryOffer : "NONE", recovery_benefit_id: result === "CLEARED" ? recoveryBenefitId : null, discount_percent: result === "CLEARED" ? discountPercent : 0, recovery_detail: result === "CLEARED" ? recoveryDetail || null : null };
    rebuildRmsOpportunityIndex(state.rmsMachine?.opportunities || []);
    state.rmsMachineLoaded = true;
    if (result === "RECYCLE") { setView("recycling"); showFeedback("Lead enviado a Reciclaje con el motivo y contexto conservados.", "success", { title: "Riesgos de fuga" }); }
    else { showFeedback("Venta lograda. Continúa el pago y productos en Ventas atribuidas.", "success", { title: "Riesgos de fuga" }); openRmsStation("cierre", { source: "risk-recovery" }); }
  } finally { setButtonLoading(button, false); }
};

// El activo se ve dentro de la estación; no se ofrece un enlace ambiguo al
// validador ni una pestaña vacía. La acción útil es descargar o compartir.
rmsRiskRecoveryResourceMarkup = function rmsRiskRecoveryResourceMarkupFinalAsset(item = {}) {
  const resource = rmsRiskRecoveryResourceFor(item);
  if (!resource?.public_ticket_url) return `<div class="rms-risk-resource-empty"><span class="material-symbols-outlined" aria-hidden="true">qr_code_2_add</span><div><strong>Aún no has generado el activo</strong><small>Selecciona una alternativa autorizada para crear el ticket.</small></div></div>`;
  const label = resource.recovery_offer?.label || resource.benefit?.label || "Beneficio extraordinario";
  const filename = escapeHtml(resource.filename || `ticket-${String(item.id || "qori").slice(0, 8)}.png`);
  if (!resource.qr_image_data_url) return `<article class="rms-risk-resource-ready rms-risk-resource-visual"><div class="rms-risk-ticket-preview"><span class="rms-risk-image-unavailable">La imagen del ticket aún no está disponible. Genera el activo nuevamente.</span></div><div class="rms-risk-resource-copy"><span class="mono-label">ACTIVO LISTO</span><strong>${escapeHtml(label)}</strong><small>Comparte el enlace desde los canales de entrega cuando la imagen esté disponible.</small></div></article>`;
  return `<article class="rms-risk-resource-ready rms-risk-resource-visual"><div class="rms-risk-ticket-preview"><img class="rms-risk-ticket-image" src="${escapeHtml(resource.qr_image_data_url)}" alt="Ticket ${escapeHtml(label)}" loading="lazy"></div><div class="rms-risk-resource-copy"><span class="mono-label">TICKET LISTO PARA COMPARTIR</span><strong>${escapeHtml(label)}</strong><small>Vigente hasta ${escapeHtml(resource.expires_at ? formatDate(resource.expires_at) : "sin vencimiento")}.</small></div><div class="rms-risk-ticket-actions"><a class="ghost-button compact" href="${escapeHtml(resource.qr_image_data_url)}" download="${filename}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar imagen</a></div></article>`;
};

// Valorización: los activos creados se entregan desde la misma compra. La
// historia se separa por venta para no mezclar recompras anteriores del cliente.
function rmsPostSaleSaleActions(item = {}) {
  const saleId = item.state_metadata?.rms_attributed_sale_id || item.state_metadata?.rms_sale_id || "";
  return (state.rmsPostSaleActions || []).filter((action) => (
    String(action.source_type || "") === String(item.source_type || "")
    && String(action.source_id || "") === String(item.source_id || "")
    && (!saleId || String(action.sale_id || "") === String(saleId))
  ));
}

function rmsPostSaleResourceForAction(action = {}) {
  return state.rmsPostSaleGeneratedResources?.[action.id] || null;
}

function rmsPostSaleAssetLabel(action = {}) {
  return ({ REFERRAL: "QR de referidos", REBUY_TICKET: "Ticket de recompra", REWARD_PASS: "Activo de fidelización" })[action.action_type] || "Activo postventa";
}

function rmsPostSaleAssetsMarkup(item = {}) {
  const assets = rmsPostSaleSaleActions(item).filter((action) => action.resource_url || rmsPostSaleResourceForAction(action)?.public_ticket_url);
  if (!assets.length) return `<section class="rms-post-sale-assets rms-post-sale-assets-empty"><header><div><span class="mono-label">ACTIVOS DE ESTA COMPRA</span><h5>Aún no hay QR ni ticket para entregar</h5></div><small>Cuando crees un referido o una recompra, el activo aparecerá aquí para compartirlo.</small></header></section>`;
  return `<section class="rms-post-sale-assets" aria-label="Activos de Valorización de esta compra"><header><div><span class="mono-label">ACTIVOS DE ESTA COMPRA</span><h5>QR y tickets listos para entregar</h5><p>Estos activos pertenecen solo a esta venta atribuida.</p></div><span class="rms-commercial-state is-sale">${assets.length} ${assets.length === 1 ? "activo" : "activos"}</span></header><div class="rms-post-sale-assets-list">${assets.slice(0, 4).map((action) => {
    const resource = rmsPostSaleResourceForAction(action) || {};
    const url = resource.public_ticket_url || action.resource_url || "";
    const referralCapture = action.action_type === "REFERRAL";
    const openLabel = referralCapture ? "Abrir formulario" : "Abrir ticket";
    const image = resource.qr_image_data_url ? `<img src="${escapeHtml(resource.qr_image_data_url)}" alt="${escapeHtml(rmsPostSaleAssetLabel(action))}" loading="lazy">` : `<span class="material-symbols-outlined" aria-hidden="true">qr_code_2</span>`;
    const filename = escapeHtml(resource.filename || `qori-${String(action.id || "activo").slice(0, 8)}.png`);
    return `<article data-rms-post-sale-asset="${escapeHtml(action.id)}"><div class="rms-post-sale-asset-preview">${image}</div><div class="rms-post-sale-asset-copy"><span class="mono-label">${escapeHtml(rmsPostSaleAssetLabel(action))}</span><strong>${escapeHtml(rmsPostSaleActionStatusLabel(action.status))}</strong><small>${escapeHtml(referralCapture ? "Enlace de captura: el referido recibe el ticket al completar sus datos." : (action.result_note || action.content || "Activo listo para compartir."))}</small></div><div class="rms-post-sale-asset-actions"><label class="rms-post-sale-share-consent" title="Confirmar autorización de contacto"><input type="checkbox" style="width:13px!important;min-width:13px!important;max-width:13px!important;height:13px!important;min-height:0!important;max-height:13px!important;margin:0!important;padding:0!important" data-rms-post-sale-share-consent="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">verified_user</span><span>Contacto autorizado</span></label><div><button class="ghost-button compact" type="button" data-rms-post-sale-copy-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span>Copiar enlace</button><button class="ghost-button compact" type="button" data-rms-post-sale-share-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">chat</span>WhatsApp</button>${resource.qr_image_data_url ? `<a class="ghost-button compact" href="${escapeHtml(resource.qr_image_data_url)}" download="${filename}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar QR</a>` : ""}<a class="ghost-button compact" href="${escapeHtml(url)}" target="_blank" rel="noopener"><span class="material-symbols-outlined" aria-hidden="true">open_in_new</span>${escapeHtml(openLabel)}</a></div></div></article>`;
  }).join("")}</div></section>`;
}

const rmsPostSaleStationCardMarkupAssetBase = rmsPostSaleStationCardMarkup;
rmsPostSaleStationCardMarkup = function rmsPostSaleStationCardMarkupAssets(item = {}) {
  const actions = rmsPostSaleSaleActions(item);
  const latest = actions[0] || null;
  const activity = latest ? `${rmsPostSaleActionStatusLabel(latest.status)} · ${rmsPostSaleAssetLabel(latest)}` : "Sin acciones postventa";
  let html = rmsPostSaleStationCardMarkupAssetBase(item);
  html = html.replace(/(<small>Actividad postventa<\/small><strong>)[^<]*(<\/strong><b>)[^<]*(<\/b>)/, `$1${escapeHtml(actions.length === 1 ? "1 acción de esta compra" : `${actions.length} acciones de esta compra`)}$2${escapeHtml(activity)}$3`);
  return html.replace('<section class="rms-refinery-workbench"', `${rmsPostSaleAssetsMarkup(item)}<section class="rms-refinery-workbench"`);
};

const rmsPostSaleStationCardMarkupReferralCaptureBase = rmsPostSaleStationCardMarkup;
rmsPostSaleStationCardMarkup = function rmsPostSaleStationCardMarkupReferralCapture(item = {}) {
  const id = escapeHtml(item.id);
  const referralPanel = `<section class="rms-refinery-panel rms-referral-capture-panel" data-rms-refinery-panel="${id}" data-rms-refinery-panel-key="REFERRAL"><header><span class="mono-label">REFERIDOS · ENLACE DE CAPTURA</span><h5>Entrega un enlace que captura al referido</h5><p>El cliente comparte este QR. Su contacto deja nombre y teléfono o correo; solo después recibe su ticket. El cliente acumula los puntos configurados por registro y por compra.</p></header><div class="rms-sale-form-grid"><label><span>Beneficio para el referido</span><input type="text" data-rms-refinery-referral-benefit="${id}" placeholder="Ej.: 10% en la primera compra"></label><label><span>Canal para compartir el enlace</span><select data-rms-refinery-channel="${id}"><option value="WHATSAPP">WhatsApp</option><option value="EMAIL">Email</option><option value="">Solo generar enlace</option></select></label></div><label class="rms-commercial-note-field"><span>Mensaje que compartirá el cliente</span><textarea rows="2" data-rms-refinery-message="${id}" placeholder="Comparte este enlace: registra tus datos y recibe tu beneficio."></textarea></label><div class="rms-referral-capture-note"><span class="material-symbols-outlined" aria-hidden="true">person_add</span><span><strong>Captura estratégica</strong><small>Los datos se solicitan en el enlace público; aquí no se registra ni se entrega el ticket antes de la captura.</small></span></div></section>`;
  return rmsPostSaleStationCardMarkupReferralCaptureBase(item).replace(
    /<section class="rms-refinery-panel" data-rms-refinery-panel="[^"]+" data-rms-refinery-panel-key="REFERRAL">[\s\S]*?<\/section>\s*(?=<section class="rms-refinery-panel"[^>]+data-rms-refinery-panel-key="LOYALTY")/,
    referralPanel
  );
};

// Valorización: el ticket de recompra tiene que sentirse como una entrega,
// no como otra fila de historial. Esta bandeja conserva los activos por venta
// y prioriza las acciones que el operador necesita para enviarlo.
rmsPostSaleAssetsMarkup = function rmsPostSaleAssetsMarkupDelivery(item = {}) {
  const assets = rmsPostSaleSaleActions(item).filter((action) => action.resource_url || rmsPostSaleResourceForAction(action)?.public_ticket_url);
  if (!assets.length) return `<section class="rms-post-sale-assets rms-post-sale-assets-empty"><header><div><span class="mono-label">ENTREGA DE ACTIVOS</span><h5>Aún no hay ticket para entregar</h5></div><small>Cuando crees una recompra o un referido, aparecerá en esta bandeja de entrega.</small></header></section>`;
  return `<section class="rms-post-sale-assets rms-post-sale-assets-delivery" aria-label="Entrega de QR y tickets de esta compra"><header><div><span class="mono-label">ENTREGA DE ACTIVOS DE ESTA VENTA</span><h5>Tickets y QR listos para enviar</h5><p>Este es el lugar para encontrar, ver y enviar los activos creados; no necesitas buscarlos en el historial.</p></div><span class="rms-commercial-state is-sale">${assets.length} ${assets.length === 1 ? "activo" : "activos"}</span></header><div class="rms-post-sale-assets-list">${assets.slice(0, 4).map((action) => {
    const resource = rmsPostSaleResourceForAction(action) || {};
    const url = resource.public_ticket_url || action.resource_url || "";
    const referralCapture = action.action_type === "REFERRAL";
    const rebuyTicket = action.action_type === "REBUY_TICKET";
    const assetLabel = rmsPostSaleAssetLabel(action);
    const image = resource.qr_image_data_url ? `<img src="${escapeHtml(resource.qr_image_data_url)}" alt="${escapeHtml(assetLabel)}" loading="lazy">` : `<span class="material-symbols-outlined" aria-hidden="true">confirmation_number</span>`;
    const filename = escapeHtml(resource.filename || `qori-${String(action.id || "activo").slice(0, 8)}.png`);
    const assetTitle = rebuyTicket ? (action.result_note || action.content || "Beneficio de recompra") : rmsPostSaleActionStatusLabel(action.status);
    const note = referralCapture
      ? "Enlace de captura: el referido recibe el ticket al completar sus datos."
      : (rebuyTicket
        ? "Listo para entregar. Confirma el contacto y usa uno de los canales de envío de esta tarjeta."
        : (action.result_note || action.content || "Activo listo para compartir."));
    const deliveryGuide = rebuyTicket ? `<p class="rms-post-sale-delivery-hint"><span class="material-symbols-outlined" aria-hidden="true">task_alt</span><span>Confirma el contacto y elige un canal. El cliente abre <b>Ver ticket y QR</b> para redimirlo.</span></p>` : "";
    const standardActions = `<button class="ghost-button compact" type="button" data-rms-post-sale-copy-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span>Copiar enlace</button><button class="ghost-button compact" type="button" data-rms-post-sale-share-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">chat</span>WhatsApp</button>`;
    const rebuyActions = `<button class="solid-button compact" type="button" data-rms-post-sale-share-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">chat</span><span class="rms-post-sale-button-label">Enviar por WhatsApp</span></button><button class="ghost-button compact" type="button" data-rms-post-sale-email-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">mail</span>Enviar por correo</button><button class="ghost-button compact" type="button" data-rms-post-sale-copy-resource="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span>Copiar enlace</button>`;
    return `<article class="${rebuyTicket ? "is-rebuy-ticket" : ""}" data-rms-post-sale-asset="${escapeHtml(action.id)}"><div class="rms-post-sale-asset-preview">${image}</div><div class="rms-post-sale-asset-copy"><span class="mono-label">${escapeHtml(rebuyTicket ? "TICKET DE RECOMPRA · LISTO PARA ENVIAR" : assetLabel)}</span><strong>${escapeHtml(assetTitle)}</strong><small>${escapeHtml(note)}</small>${deliveryGuide}</div><div class="rms-post-sale-asset-actions"><label class="rms-post-sale-share-consent" title="Confirmar autorización de contacto"><input type="checkbox" style="width:13px!important;min-width:13px!important;max-width:13px!important;height:13px!important;min-height:0!important;max-height:13px!important;margin:0!important;padding:0!important" data-rms-post-sale-share-consent="${escapeHtml(action.id)}"><span class="material-symbols-outlined" aria-hidden="true">verified_user</span><span>Contacto autorizado</span></label><div>${rebuyTicket ? rebuyActions : standardActions}${resource.qr_image_data_url ? `<a class="ghost-button compact" href="${escapeHtml(resource.qr_image_data_url)}" download="${filename}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar QR</a>` : ""}<a class="ghost-button compact" href="${escapeHtml(url)}" target="_blank" rel="noopener"><span class="material-symbols-outlined" aria-hidden="true">open_in_new</span>${referralCapture ? "Abrir formulario" : (rebuyTicket ? "Ver ticket y QR" : "Ver activo")}</a></div></div></article>`;
  }).join("")}</div></section>`;
};

function rmsPostSaleActionFromButton(button) {
  const actionId = button?.dataset.rmsPostSaleCopyResource || button?.dataset.rmsPostSaleShareResource || button?.dataset.rmsPostSaleEmailResource || "";
  return (state.rmsPostSaleActions || []).find((action) => String(action.id) === String(actionId)) || null;
}

function rmsPostSaleAssetUrl(action) {
  return rmsPostSaleResourceForAction(action)?.public_ticket_url || action?.resource_url || "";
}

async function copyRmsPostSaleAsset(button) {
  const url = rmsPostSaleAssetUrl(rmsPostSaleActionFromButton(button));
  if (!url) throw new Error("No encontramos el enlace del activo.");
  await navigator.clipboard.writeText(url);
  showFeedback("Enlace del activo copiado. Ya puedes pegarlo en el canal autorizado.", "success", { title: "Valorización Clientes" });
}

function shareRmsPostSaleAsset(button) {
  const action = rmsPostSaleActionFromButton(button);
  const url = rmsPostSaleAssetUrl(action);
  const card = button.closest("[data-rms-station-lead]");
  const customer = rmsOpportunityById(card?.dataset.rmsStationLead || "");
  const consent = card?.querySelector(`[data-rms-post-sale-share-consent="${CSS.escape(action?.id || "")}"]`);
  if (!url) throw new Error("No encontramos el enlace del activo.");
  if (!consent?.checked) {
    showFeedback("Confirma la autorización de contacto antes de preparar el WhatsApp.", "info", { title: "Valorización Clientes" });
    return;
  }
  const phone = String(customer?.phone || "").replace(/\D/g, "");
  if (!phone) {
    showFeedback("Este cliente no tiene un WhatsApp válido registrado. Copia el enlace o usa otro canal autorizado.", "info", { title: "Valorización Clientes" });
    return;
  }
  const label = rmsPostSaleAssetLabel(action);
  const message = `Hola ${customer?.name || ""}, gracias por tu compra. Aquí tienes tu ${label.toLowerCase()}: ${url}`.trim();
  window.open(`https://wa.me/${encodeURIComponent(phone)}?text=${encodeURIComponent(message)}`, "_blank", "noopener");
  showFeedback("WhatsApp preparado con el activo de esta compra.", "success", { title: "Valorización Clientes" });
}

async function emailRmsPostSaleAsset(button) {
  const action = rmsPostSaleActionFromButton(button);
  const card = button.closest("[data-rms-station-lead]");
  const customer = rmsOpportunityById(card?.dataset.rmsStationLead || "");
  const consent = card?.querySelector(`[data-rms-post-sale-share-consent="${CSS.escape(action?.id || "")}"]`);
  if (!consent?.checked) {
    showFeedback("Confirma la autorización de contacto antes de preparar el correo.", "info", { title: "Valorización Clientes" });
    return;
  }
  const email = String(customer?.email || "").trim();
  if (!email) {
    showFeedback("Este cliente no tiene un correo registrado. Usa WhatsApp o copia el enlace.", "info", { title: "Valorización Clientes" });
    return;
  }
  const url = rmsPostSaleAssetUrl(action);
  const name = String(customer?.name || "").trim();
  const subject = "Tu ticket de recompra Qori";
  const message = `Hola${name ? ` ${name}` : ""}, gracias por tu compra. Aquí tienes tu ticket de recompra. Ábrelo y presenta el QR antes de que venza: ${url}`;
  try {
    const route = await portalEmailDeliveryRoute();
    if (route === "external") {
      openExternalEmailDraft({ to: [email], subject, body: message });
      showFeedback("Correo preparado en tu proveedor externo.", "info", { title: "Valorización Clientes" });
    } else if (route === "qori") {
      await sendPortalEmailFromQori({ recipients: [customer], subject, body: message, actionUrl: url, title: `Ticket de recompra · ${name || email}`, metadata: { source_module: "rms_post_sale", post_sale_action_id: action?.id || null } });
      showFeedback("Ticket enviado por correo directamente desde Qori.", "success", { title: "Valorización Clientes" });
    }
  } catch (error) {
    showFeedback(error.message || "No se pudo enviar el ticket por correo.", "error", { title: "Valorización Clientes" });
  }
}

function rmsRiskSelectedOffer(root, item) {
  const value = rmsCommercialNode(root, "[data-rms-risk-recovery-offer]", item.id)?.value || "NONE";
  const benefitId = value.startsWith("BENEFIT:") ? value.slice(8) : null;
  return {
    value,
    offer: benefitId ? "CUSTOM" : value,
    benefitId,
    discount: Number(rmsCommercialNode(root, "[data-rms-risk-discount-percent]", item.id)?.value || 0),
    detail: String(rmsCommercialNode(root, "[data-rms-risk-recovery-detail]", item.id)?.value || "").trim(),
  };
}

async function generateRmsRiskRecoveryResource(item, root, button) {
  const selected = rmsRiskSelectedOffer(root, item);
  if (selected.offer === "NONE") {
    showFeedback("Selecciona una alternativa extraordinaria autorizada antes de generar el ticket.", "info", { title: "Riesgos de fuga" });
    rmsCommercialNode(root, "[data-rms-risk-recovery-offer]", item.id)?.focus();
    return;
  }
  const expirationDays = Number(rmsCommercialNode(root, "[data-rms-risk-expiration-days]", item.id)?.value || 7);
  const fingerprint = [item.source_type || "PLAYER", item.source_id, selected.offer, selected.benefitId || "", selected.discount, selected.detail, expirationDays].join(":");
  setButtonLoading(button, true, "Generando...");
  try {
    const response = await api("/api/business/rms-machine/risk-recovery-resource", {
      method: "POST",
      headers: authHeaders(),
      body: JSON.stringify({
        source_id: item.source_id,
        source_type: item.source_type || "PLAYER",
        lead_id: item.lead_id || null,
        recovery_offer: selected.offer,
        recovery_benefit_id: selected.benefitId,
        discount_percent: selected.discount,
        recovery_detail: selected.detail || null,
        expiration_days: expirationDays,
        idempotency_key: `risk-resource:${fingerprint}`.slice(0, 180),
      }),
    });
    state.rmsRiskGeneratedResources ||= {};
    state.rmsRiskGeneratedResources[item.id] = { ...response.resource, qr_image_data_url: response.ticket?.qr_image_data_url || response.resource?.qr_image_data_url || null, filename: response.ticket?.filename || response.resource?.filename };
    const status = rmsCommercialNode(root, "[data-rms-risk-resource-status]", item.id);
    if (status) status.innerHTML = rmsRiskRecoveryResourceMarkup(item);
    syncRmsRiskRecoveryPhases(root.querySelector(`[data-rms-station-lead="${CSS.escape(item.id)}"]`), item);
    showFeedback(response.duplicate ? "El ticket ya estaba listo; no se descontó otro crédito." : "Ticket y activo extraordinario generados. Ya puedes compartirlos.", "success", { title: "Riesgos de fuga" });
  } finally {
    setButtonLoading(button, false);
  }
}

// El renderizador activo se define por las implementaciones concretas de abajo.

// Convierte el stepper en navegación operativa: cada estado abre su bloque real.
const rmsRiskOperatingFlowMarkupBase = rmsRiskOperatingFlowMarkup;
rmsRiskOperatingFlowMarkup = function rmsRiskOperatingFlowMarkupInteractive(item = {}) {
  let html = rmsRiskOperatingFlowMarkupBase(item);
  html = html.replace(/data-step="(\d+)"/g, 'data-step="$1" data-rms-flow-step="$1" role="button" tabindex="0"');
  return html.replace('</section>', `<div class="rms-risk-response-bridge"><div><span class="mono-label">PASO 3 · RESPUESTA</span><strong>¿Qué respondió el cliente?</strong><small>Abre el resultado, escribe la justificación y envíalo a Ventas atribuidas o Reciclaje.</small></div><button class="solid-button compact" type="button" data-rms-risk-go-response="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">edit_note</span>Registrar respuesta</button></div></section>`);
};

// Nunca uses el validador como sustituto de la imagen: si no hay imagen, se informa y no se navega.
rmsRiskRecoveryResourceMarkup = function rmsRiskRecoveryResourceMarkupImageOnly(item = {}) {
  const resource = rmsRiskRecoveryResourceFor(item);
  if (!resource?.public_ticket_url) return `<div class="rms-risk-resource-empty"><span class="material-symbols-outlined" aria-hidden="true">qr_code_2_add</span><div><strong>Aún no has generado el activo</strong><small>Selecciona una alternativa autorizada para crear el ticket.</small></div></div>`;
  const label = resource.recovery_offer?.label || resource.benefit?.label || "Beneficio extraordinario";
  const filename = escapeHtml(resource.filename || `ticket-${String(item.id || "qori").slice(0, 8)}.png`);
  if (!resource.qr_image_data_url) return `<article class="rms-risk-resource-ready rms-risk-resource-visual"><div class="rms-risk-ticket-preview"><span class="rms-risk-image-unavailable">La imagen del ticket aún no está disponible. Genera el activo nuevamente.</span></div><div class="rms-risk-resource-copy"><span class="mono-label">ACTIVO LISTO</span><strong>${escapeHtml(label)}</strong><small>El enlace público no se mostrará como si fuera la imagen.</small></div></article>`;
  const image = `<img class="rms-risk-ticket-image" src="${escapeHtml(resource.qr_image_data_url)}" alt="Ticket ${escapeHtml(label)}" loading="lazy">`;
  return `<article class="rms-risk-resource-ready rms-risk-resource-visual"><div class="rms-risk-ticket-preview">${image}</div><div class="rms-risk-resource-copy"><span class="mono-label">TICKET LISTO PARA COMPARTIR</span><strong>${escapeHtml(label)}</strong><small>Vigente hasta ${escapeHtml(resource.expires_at ? formatDate(resource.expires_at) : "sin vencimiento")}.</small></div><div class="rms-risk-ticket-actions"><a class="ghost-button compact" href="${escapeHtml(resource.qr_image_data_url)}" target="_blank" rel="noopener"><span class="material-symbols-outlined" aria-hidden="true">visibility</span>Ver imagen</a><a class="ghost-button compact" href="${escapeHtml(resource.qr_image_data_url)}" download="${filename}"><span class="material-symbols-outlined" aria-hidden="true">download</span>Descargar imagen</a></div></article>`;
};

// Reasignación final: la consola nueva prevalece sobre las declaraciones legacy.
rmsRiskValidationStationCardMarkup = function rmsRiskValidationStationCardMarkupFinal(item = {}) {
  const flow = rmsCommercialWorkflow(item);
  const confirmation = flow.confirmation || {};
  const id = escapeHtml(item.id);
  const status = item.active_tickets ? "Beneficio activo" : item.redeemed_tickets ? "Beneficio redimido" : "Sin beneficio activo";
  return `<article class="rms-commercial-work-item rms-risk-work-item rms-risk-recovery-work-item" data-rms-station-lead="${id}">${rmsCommercialLeadAsideMarkup(item, "Riesgos de fuga · decisión final")}<section class="rms-commercial-work-console rms-risk-command-console">${rmsDealProgressMarkup("risk", "Una decisión clara: protege una venta real o conserva el contexto para Reciclaje.")}<header class="rms-commercial-console-head rms-risk-hero"><div><span class="mono-label">ESTACIÓN 07 · RIESGOS DE FUGA</span><h4>Decide en menos de un minuto</h4><p>Revisa las señales, aplica solo una autorización válida y elige el siguiente destino.</p></div><span class="rms-commercial-state is-pending">${escapeHtml(status)}</span></header>${rmsRiskCommandStripMarkup(item, confirmation, status)}<section class="rms-risk-agreement-summary"><span class="material-symbols-outlined" aria-hidden="true">handshake</span><div><strong>${escapeHtml([confirmation.product_name || rmsClassifiedProductName(item) || "Producto por confirmar", confirmation.amount ? money(confirmation.amount) : "Valor por confirmar", confirmation.negotiation?.channel || "Canal por confirmar"].join(" · "))}</strong><small>Elige una sola salida y conserva el contexto del caso.</small></div></section>${rmsRiskRecoveryAvailabilityMarkup()}<section class="rms-commercial-info-block rms-risk-recovery-form"><input type="hidden" data-rms-risk-decision="${id}" value="CLEARED"><div data-rms-risk-sale-panel="${id}"><h5>Si compró: registra la excepción aplicada</h5><div class="rms-sale-form-grid"><label><span>Alternativa de recuperación</span><select data-rms-risk-recovery-offer="${id}">${rmsRiskRecoveryOfferOptions()}</select><small>El generador emite ticket/QR con el tipo válido de Qori.</small></label><label data-rms-risk-discount-wrap="${id}" hidden><span>Descuento aplicado</span><input type="number" min="0.01" max="100" step="0.01" data-rms-risk-discount-percent="${id}" placeholder="0"></label><label class="span-2" data-rms-risk-detail-wrap="${id}" hidden><span>Detalle autorizado</span><input type="text" maxlength="1000" data-rms-risk-recovery-detail="${id}" placeholder="Describe el 2x1 u obsequio autorizado"></label></div><label class="rms-commercial-note-field"><span>Justificación de la venta</span><textarea rows="3" data-rms-risk-reason="${id}" placeholder="Qué aceptó el cliente y qué debe revisar Ventas atribuidas"></textarea></label></div><div data-rms-risk-recycle-panel="${id}" hidden><h5>Si no compró: conserva el caso sin duplicarlo</h5><div class="rms-sale-form-grid"><label><span>Motivo principal</span><select data-rms-risk-recycle-reason="${id}"><option value="BUDGET">Presupuesto</option><option value="TIMING">Momento inadecuado</option><option value="NO_RESPONSE">Sin respuesta</option><option value="WAITING_DECISION">Decisión aplazada</option><option value="NOT_VIABLE_NOW">No es viable ahora</option><option value="OTHER">Otro</option></select></label><label><span>Estrategia si se reactiva</span><select data-rms-risk-recycle-strategy="${id}"><option value="NURTURE">Nutrición comercial</option><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva activación</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option></select></label><label><span>Fecha de revisión <em>Opcional</em></span><input type="datetime-local" data-rms-risk-next-at="${id}"></label></div><label class="rms-commercial-note-field"><span>Por qué no fue viable</span><textarea rows="3" data-rms-risk-reason="${id}" placeholder="Resume qué se intentó y por qué no conviene insistir ahora"></textarea></label></div></section><aside class="rms-negotiation-route-preview" data-rms-risk-preview="${id}"><strong>Siguiente paso: Ventas atribuidas</strong><small>La venta se termina de registrar allí con productos, pago, costos y atribución.</small></aside><div class="rms-commercial-action-row"><small data-rms-risk-help="${id}">Al guardar, el lead saldrá de esta estación y no se creará una copia.</small><button class="solid-button compact" type="button" data-rms-save-risk-decision="${id}"><span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas</button></div></section></article>`;
};

// La imagen ya está visible en el ticket; no mostramos un enlace que abre un recurso vacío.
const rmsRiskRecoveryResourceMarkupDownloadOnlyBase = rmsRiskRecoveryResourceMarkup;
rmsRiskRecoveryResourceMarkup = function rmsRiskRecoveryResourceMarkupDownloadOnly(item = {}) {
  return rmsRiskRecoveryResourceMarkupDownloadOnlyBase(item).replace(/<a[^>]*>\s*<span[^>]*>visibility<\/span>\s*Ver imagen<\/a>/, "");
};

// Inserta la consola de fases directamente en la tarjeta activa; no depende del montaje posterior.
const rmsRiskValidationStationCardMarkupPhasedBase = rmsRiskValidationStationCardMarkup;
rmsRiskValidationStationCardMarkup = function rmsRiskValidationStationCardMarkupPhased(item = {}) {
  let html = rmsRiskValidationStationCardMarkupPhasedBase(item);
  const formMarker = '<section class="rms-commercial-info-block rms-risk-recovery-form">';
  const formIndex = html.indexOf(formMarker);
  const legacyFlowIndex = html.indexOf('<section class="rms-risk-operating-flow');
  if (legacyFlowIndex >= 0 && formIndex > legacyFlowIndex) {
    html = `${html.slice(0, legacyFlowIndex)}${html.slice(formIndex)}`;
  }
  if (html.includes("rms-risk-flow-phased")) return html;
  return html.replace(formMarker, `${rmsRiskOperatingFlowMarkup(item)}${formMarker}`);
};

function rmsRiskShareMessage(item, resource) {
  const name = item.name || item.first_name || "Hola";
  const label = resource?.recovery_offer?.label || resource?.benefit?.label || "beneficio extraordinario";
  return `${name}, preparamos ${label} para ayudarte a completar esta compra. Revisa y redime tu ticket aquí: ${resource.public_ticket_url}`;
}

function requireRmsRiskShare(item, root) {
  const resource = rmsRiskRecoveryResourceFor(item);
  if (!resource?.public_ticket_url) {
    showFeedback("Genera primero el ticket extraordinario.", "info", { title: "Riesgos de fuga" });
    return null;
  }
  if (!rmsCommercialNode(root, "[data-rms-risk-consent]", item.id)?.checked) {
    showFeedback("Confirma la autorización de contacto antes de compartir el beneficio.", "info", { title: "Riesgos de fuga" });
    return null;
  }
  return resource;
}

async function emailRmsRiskRecoveryResource(item, root, button) {
  const resource = requireRmsRiskShare(item, root);
  if (!resource) return;
  if (!String(item.email || "").trim()) {
    showFeedback("Este lead no tiene un email válido registrado.", "info", { title: "Riesgos de fuga" });
    return;
  }
  const message = rmsRiskShareMessage(item, resource);
  setButtonLoading(button, true, "Enviando...");
  try {
    const route = await portalEmailDeliveryRoute();
    if (route === "external") {
      openExternalEmailDraft({ to: [item.email], subject: "Tu beneficio extraordinario está listo", body: message });
      showFeedback("Beneficio preparado en tu proveedor externo. Qori no lo marcará como enviado.", "info", { title: "Riesgos de fuga" });
      return;
    }
    if (route !== "qori") return;
    const created = await api("/api/business/communications", {
      method: "POST", headers: authHeaders(),
      body: JSON.stringify({ title: `Recuperación RMS - ${item.name || item.email}`.slice(0, 180), communication_type: "EMAIL", status: "READY", subject: "Tu beneficio extraordinario está listo", email_body: message, action_url: resource.public_ticket_url, metadata: { source: "rms_risk_recovery", qr_code_id: resource.qr_code_id, source_type: item.source_type, source_id: item.source_id } }),
    });
    const communicationId = created.communication?.id;
    if (!communicationId) throw new Error("No se pudo preparar el email.");
    const delivery = await api(`/api/business/communications/${encodeURIComponent(communicationId)}/send`, { method: "POST", headers: authHeaders(), body: JSON.stringify({ recipients: [{ source_id: item.source_id, source_type: item.source_type || "PLAYER" }], consent_confirmed: true, idempotency_key: crypto.randomUUID() }) });
    if (!Number(delivery?.results?.sent || 0)) throw new Error(delivery?.results?.failure_reasons?.[0]?.message || "El email no pudo entregarse.");
    showFeedback("Beneficio enviado por email y registrado en Comunicaciones.", "success", { title: "Riesgos de fuga" });
  } finally {
    setButtonLoading(button, false);
  }
}

function rmsRiskValidationStationCardMarkup(item = {}) {
  const flow = rmsCommercialWorkflow(item);
  const confirmation = flow.confirmation || {};
  const ticketStatus = item.redeemed_tickets ? "Beneficio redimido" : item.active_tickets ? "Beneficio activo" : item.expired_tickets ? "Beneficio vencido" : "Sin beneficio activo";
  const agreement = [confirmation.product_name || rmsClassifiedProductName(item) || "Producto por confirmar", confirmation.amount ? money(confirmation.amount) : "Valor por confirmar", confirmation.negotiation?.channel || "Canal por confirmar"].join(" · ");
  return `<article class="rms-commercial-work-item rms-risk-work-item rms-risk-recovery-work-item" data-rms-station-lead="${escapeHtml(item.id)}">${rmsCommercialLeadAsideMarkup(item, "Riesgos de fuga · recuperación excepcional")}<section class="rms-commercial-work-console">${rmsDealProgressMarkup("risk", "Usa solo las alternativas autorizadas. El resultado termina en Venta atribuida o Reciclaje.")}<header class="rms-commercial-console-head"><div><span class="mono-label">ESTACIÓN 07 · RIESGOS DE FUGA</span><h4>Recupera o libera el caso</h4><p>Este lead ya agotó la negociación habitual. Registra una alternativa autorizada solo si realmente ayudó a cerrar la venta.</p></div><span class="rms-commercial-state is-pending">Recuperación excepcional</span></header><section class="rms-risk-agreement-summary"><span class="material-symbols-outlined" aria-hidden="true">handshake</span><div><strong>${escapeHtml(agreement)}</strong><small>${escapeHtml([confirmation.responsible && `Responsable: ${confirmation.responsible}`, ticketStatus, item.campaign_name || item.source_detail || "Sin campaña"].filter(Boolean).join(" · "))}</small></div></section>${rmsRiskRecoveryAvailabilityMarkup()}<section class="rms-commercial-info-block rms-risk-recovery-form"><input type="hidden" data-rms-risk-decision="${escapeHtml(item.id)}" value="CLEARED"><div data-rms-risk-sale-panel="${escapeHtml(item.id)}"><h5>Alternativa aplicada y resultado</h5><div class="rms-sale-form-grid"><label><span>Alternativa de recuperación</span><select data-rms-risk-recovery-offer="${escapeHtml(item.id)}">${rmsRiskRecoveryOfferOptions()}</select><small>Solo aparecen las autorizaciones configuradas en Cuenta.</small></label><label data-rms-risk-discount-wrap="${escapeHtml(item.id)}" hidden><span>Descuento aplicado</span><div class="rms-risk-percent-field"><input type="number" min="0.01" max="${escapeHtml(String(rmsRiskRecoveryAuthorizations().discount.max_percent || 100))}" step="0.01" inputmode="decimal" data-rms-risk-discount-percent="${escapeHtml(item.id)}" placeholder="0"><b>%</b></div></label><label class="span-2" data-rms-risk-detail-wrap="${escapeHtml(item.id)}" hidden><span>Detalle de la alternativa</span><input type="text" maxlength="1000" data-rms-risk-recovery-detail="${escapeHtml(item.id)}" placeholder="Describe el 2x1 u obsequio autorizado que aceptó el cliente"></label></div><label class="rms-commercial-note-field"><span>Justificación de la venta</span><textarea rows="3" data-rms-risk-reason="${escapeHtml(item.id)}" placeholder="Qué alternativa se usó, qué aceptó el cliente y qué debe revisar Ventas atribuidas"></textarea></label></div><div data-rms-risk-recycle-panel="${escapeHtml(item.id)}" hidden><h5>Salida a Reciclaje</h5><div class="rms-sale-form-grid"><label><span>Motivo principal</span><select data-rms-risk-recycle-reason="${escapeHtml(item.id)}"><option value="BUDGET">Presupuesto</option><option value="TIMING">Momento inadecuado</option><option value="NO_RESPONSE">Sin respuesta</option><option value="WAITING_DECISION">Decisión aplazada</option><option value="NOT_VIABLE_NOW">No es viable ahora</option><option value="OTHER">Otro</option></select></label><label><span>Estrategia si se reactiva</span><select data-rms-risk-recycle-strategy="${escapeHtml(item.id)}"><option value="NURTURE">Nutrición comercial</option><option value="NEW_CONTACT">Nuevo contacto</option><option value="NEW_PROPOSAL">Nueva propuesta</option><option value="NEW_ACTIVATION">Nueva activación</option><option value="PERMITTED_BENEFIT">Beneficio permitido</option></select></label><label><span>Fecha de revisión <em>Opcional</em></span><input type="datetime-local" data-rms-risk-next-at="${escapeHtml(item.id)}"></label></div><label class="rms-commercial-note-field"><span>Por qué no fue viable</span><textarea rows="3" data-rms-risk-reason="${escapeHtml(item.id)}" placeholder="Resume qué se intentó y por qué no vale la pena seguir insistiendo ahora"></textarea></label></div></section><aside class="rms-negotiation-route-preview" data-rms-risk-preview="${escapeHtml(item.id)}"><strong>Siguiente paso: Ventas atribuidas</strong><small>La venta se termina de registrar allí con productos, pago, costos y atribución.</small></aside><div class="rms-commercial-action-row"><small data-rms-risk-help="${escapeHtml(item.id)}">Registra el resultado real. No hay retornos a Negociación ni seguimientos dentro de esta estación.</small><button class="solid-button compact" type="button" data-rms-save-risk-decision="${escapeHtml(item.id)}"><span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas</button></div></section></article>`;
}

function rmsRiskRecoveryOfferUi(root, id) {
  const offer = rmsCommercialNode(root, "[data-rms-risk-recovery-offer]", id)?.value || "NONE";
  const discount = rmsCommercialNode(root, "[data-rms-risk-discount-wrap]", id);
  const detail = rmsCommercialNode(root, "[data-rms-risk-detail-wrap]", id);
  if (discount) discount.hidden = offer !== "DISCOUNT";
  if (detail) detail.hidden = !["TWO_FOR_ONE", "GIFT"].includes(offer);
}

function activateRmsRiskTab(root, id, tabKey) {
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(id)}"]`);
  if (!card) return;
  const isRecycle = tabKey === "recycle";
  const decision = rmsCommercialNode(root, "[data-rms-risk-decision]", id);
  if (decision) decision.value = isRecycle ? "RECYCLE" : "CLEARED";
  const salePanel = rmsCommercialNode(root, "[data-rms-risk-sale-panel]", id);
  const recyclePanel = rmsCommercialNode(root, "[data-rms-risk-recycle-panel]", id);
  if (salePanel) salePanel.hidden = isRecycle;
  if (recyclePanel) recyclePanel.hidden = !isRecycle;
  card.querySelectorAll(`[data-rms-risk-tab="${CSS.escape(id)}"]`).forEach((button) => {
    const active = button.dataset.rmsRiskTabKey === (isRecycle ? "recycle" : "sale");
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  const preview = rmsCommercialNode(root, "[data-rms-risk-preview]", id);
  const button = rmsCommercialNode(root, "[data-rms-save-risk-decision]", id);
  const help = rmsCommercialNode(root, "[data-rms-risk-help]", id);
  if (isRecycle) {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Reciclaje comercial</strong><small>El caso sale de Riesgos con motivo y estrategia conservados para una reactivación responsable.</small>";
    if (button) button.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">autorenew</span>Enviar a Reciclaje';
    if (help) help.textContent = "Reciclaje conserva la inversión y el contexto; no vuelve automáticamente a Negociación.";
  } else {
    if (preview) preview.innerHTML = "<strong>Siguiente paso: Ventas atribuidas</strong><small>La venta se termina de registrar allí con productos, pago, costos y atribución.</small>";
    if (button) button.innerHTML = '<span class="material-symbols-outlined" aria-hidden="true">paid</span>Enviar a Ventas atribuidas';
    if (help) help.textContent = "Registra solo la concesión excepcional que realmente se aplicó. El pago se confirma en Ventas atribuidas.";
    rmsRiskRecoveryOfferUi(root, id);
  }
  const offer = rmsCommercialNode(root, "[data-rms-risk-recovery-offer]", id);
  if (offer && !offer.dataset.rmsRiskRecoveryBound) {
    offer.dataset.rmsRiskRecoveryBound = "true";
    offer.addEventListener("change", () => rmsRiskRecoveryOfferUi(root, id));
  }
  card.querySelectorAll("[data-rms-open-risk-settings]").forEach((settingsButton) => {
    if (settingsButton.dataset.rmsRiskRecoveryBound) return;
    settingsButton.dataset.rmsRiskRecoveryBound = "true";
    settingsButton.addEventListener("click", () => {
      setView("account");
      window.setTimeout(() => document.getElementById("accountRiskRecoveryAuthorizations")?.scrollIntoView({ behavior: "smooth", block: "center" }), 100);
    });
  });
}

async function saveRmsRiskDecision(item, root) {
  const result = rmsCommercialNode(root, "[data-rms-risk-decision]", item.id)?.value || "CLEARED";
  const reasonNode = rmsCommercialNode(root, "[data-rms-risk-reason]", item.id);
  const recycleReasonNode = rmsCommercialNode(root, "[data-rms-risk-recycle-reason]", item.id);
  const recycleReason = String(recycleReasonNode?.value || "").trim();
  const recycleReasonLabel = recycleReasonNode?.selectedOptions?.[0]?.textContent?.trim() || recycleReason;
  const typedReason = String(reasonNode?.value || "").trim();
  const card = root.querySelector(`[data-rms-station-lead="${CSS.escape(item.id)}"]`);
  const recoveryOfferNode = card?.querySelector(`[data-rms-risk-outcome-offer="${CSS.escape(item.id)}"]`)
    || rmsCommercialNode(root, "[data-rms-risk-recovery-offer]", item.id);
  const recoveryOfferValue = recoveryOfferNode?.value || "NONE";
  const recoveryBenefitId = recoveryOfferValue.startsWith("BENEFIT:") ? recoveryOfferValue.slice(8) : null;
  const selectedBenefit = recoveryBenefitId ? rmsRiskRecoveryAuthorizations().benefits.find((benefit) => benefit.id === recoveryBenefitId) : null;
  const reason = typedReason || (result === "RECYCLE" && recycleReason
    ? `Motivo de reciclaje: ${recycleReasonLabel}`
    : result === "CLEARED" && selectedBenefit
      ? `Beneficio extraordinario aplicado: ${selectedBenefit.label}`
      : "");
  if (!reason) {
    showFeedback(result === "RECYCLE" ? "Explica por qué este caso debe ir a Reciclaje." : "Explica por qué la recuperación logró la venta.", "info", { title: "Riesgos de fuga" });
    return;
  }
  const recoveryOffer = recoveryBenefitId ? "CUSTOM" : recoveryOfferValue;
  const discountPercent = Number(card?.querySelector(`[data-rms-risk-outcome-discount-percent="${CSS.escape(item.id)}"]`)?.value
    || rmsCommercialNode(root, "[data-rms-risk-discount-percent]", item.id)?.value
    || 0);
  const recoveryDetail = String(card?.querySelector(`[data-rms-risk-outcome-detail="${CSS.escape(item.id)}"]`)?.value
    || rmsCommercialNode(root, "[data-rms-risk-recovery-detail]", item.id)?.value
    || "").trim();
  const permissions = rmsRiskRecoveryAuthorizations();
  if (result === "CLEARED" && recoveryOffer === "DISCOUNT" && (!permissions.discount.enabled || discountPercent <= 0 || discountPercent > permissions.discount.max_percent)) {
    showFeedback(`El descuento debe respetar la autorización de Cuenta (máximo ${permissions.discount.max_percent || 0}%).`, "info", { title: "Riesgos de fuga" });
    return;
  }
  if (result === "CLEARED" && ["TWO_FOR_ONE", "GIFT"].includes(recoveryOffer) && !recoveryDetail) {
    showFeedback("Describe la alternativa autorizada que aceptó el cliente.", "info", { title: "Riesgos de fuga" });
    return;
  }
  if (result === "RECYCLE" && !recycleReason) {
    showFeedback("Selecciona el motivo principal para enviar a Reciclaje.", "info", { title: "Riesgos de fuga" });
    return;
  }
  const button = rmsCommercialNode(root, "[data-rms-save-risk-decision]", item.id);
  setButtonLoading(button, true, result === "RECYCLE" ? "Enviando..." : "Confirmando...");
  try {
    const review = await api("/api/business/rms-machine/risk-review", {
      method: "POST", headers: authHeaders(),
      body: JSON.stringify({
        source_id: item.source_id, source_type: item.source_type || "PLAYER", lead_id: item.lead_id || null,
        result, reason,
        recovery_offer: result === "CLEARED" ? recoveryOffer : "NONE",
        recovery_benefit_id: result === "CLEARED" ? recoveryBenefitId : null,
        discount_percent: result === "CLEARED" ? discountPercent : 0,
        recovery_detail: result === "CLEARED" ? recoveryDetail || null : null,
        recycle_reason: result === "RECYCLE" ? recycleReason : null,
        recycle_strategy: result === "RECYCLE" ? (rmsCommercialNode(root, "[data-rms-risk-recycle-strategy]", item.id)?.value || "NURTURE") : null,
        recycle_note: result === "RECYCLE" ? reason : null,
        next_action_at: result === "RECYCLE" ? rmsCommercialLocalToIso(rmsCommercialNode(root, "[data-rms-risk-next-at]", item.id)?.value || "") : null,
        responsible: rmsCommercialWorkflow(item).confirmation?.responsible || null,
      }),
    });
    // El POST ya confirmó la transición. Reflejamos el destino de inmediato y
    // dejamos que la estación de destino haga una sola sincronización ligera.
    // Antes se cargaba RMS aquí y openRmsStation volvía a cargarlo enseguida.
    item.stage = result === "RECYCLE" ? "control_anti_fuga" : "cierre";
    item.rms_phase = item.stage;
    item.risk_review = review?.review || review?.risk_review || {
      ...(item.risk_review || {}),
      result,
      reason,
      recovery_offer: result === "CLEARED" ? recoveryOffer : "NONE",
      recovery_benefit_id: result === "CLEARED" ? recoveryBenefitId : null,
      discount_percent: result === "CLEARED" ? discountPercent : 0,
      recovery_detail: result === "CLEARED" ? recoveryDetail || null : null,
    };
    rebuildRmsOpportunityIndex(state.rmsMachine?.opportunities || []);
    state.rmsMachineLoaded = true;
    if (result === "RECYCLE") {
      setView("recycling");
      showFeedback("Lead enviado a Reciclaje con el motivo, contexto y costo conservados.", "success", { title: "Riesgos de fuga" });
    } else {
      showFeedback("Venta lograda. Ahora termina el registro de pago y productos en Ventas atribuidas.", "success", { title: "Riesgos de fuga" });
      openRmsStation("cierre", { source: "risk-recovery" });
    }
  } finally {
    setButtonLoading(button, false);
  }
}


